window.D=window.D||{};D["mb_14"]={"351":[{"s":"<b>דין המושיט ידו לצנור ברשות הרבים לשתות. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>לא יעמוד אדם ברשות הרבי' ויחבר ידו למזחילה שהוא צנור ארוך מונח לאורך הגג <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>בתוך <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>ג' טפחים סמוך לגג ולקבל המים ממנה שכיון שהוא בתוך ג' סמוך לגג <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>חשוב כגג ואסור בין אם הוא למעלה מעשרה או למטה מעשרה אבל מותר לקלוט <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>מן האויר אפי' אם ידו תוך ג' למזחילה <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>היתה מזחילה בולטת <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>ג' מן הגג וכן סתם צנור <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>שבולט ג' יכול לחבר ידו אליהם ולקבל המים וכגון <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>שאין בהם ד' על ד' והן למטה מעשרה <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אבל אם <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>יש בהן ד' על ד' או <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אפי' אין בהן <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>ד' על ד' והן <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>למעל' <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>מעשרה אסור:","m":["(א) ויחבר ידו - וה\"ה פיו או כלי:","(ב) למזחילה - וכ\"ש לקלוט מים מע\"ג הכותל דאסור:","(ג) בתוך ג' טפחים - פי' המזחילה מונחת סמוך לגג תוך ג' טפחים ואמרינן לבוד ושם גג ע\"ז והוי כמוציא מן הגג לר\"ה ואפילו אין המזחילה רחבה ד' טפחים:","(ד) מן האויר - את המים היורדין מן המזחילה או מן הגג דאויר שלמעלה מיו\"ד מקום פטור הוא ואם הוא למטה מעשרה הוי ר\"ה וידו הלא ג\"כ בר\"ה היא:","(ה) תוך ג' למזחילה - דלא אמרינן בזה לבוד וגם דלא הוי עקירה ממקום ד' על ד':","(ו) היתה מזחילה וכו' - מזחילה נקרא הצינור המונח לאורך הגג וצינור נקרא כשהוא עומד בצד אחד מן הגג וסתמו בולט להלן הרבה כדי שלא יפלו המים על הכותל:","(ז) יכול לחבר ידו - דכיון שבולט ג' תו לא חשיב כגג:","(ח) שאין בהם וכו' - דחשיב מקום פטור:","(ט) יש בהן וכו' - דהוי ככרמלית:","(י) אפילו אין בהם וכו' והן למעלה וכו' - דגזרינן שמא יהיה בהן רחב ד' על ד' והוי רה\"י ואסור:"]}],"352":[{"s":"<b>הקורא בספר ונתגלגל מרשות לרשות. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i> הקורא בספר על האסקופה ונתגלגל ראש האחד מהספר מידו <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>ונשאר ראש השני בידו <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>גוללו אצלו אפי' נתגלגל חוץ לד' אמות <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>ואפילו ברשות הרבים והאסקופה ברשות היחיד <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>משום בזיון כתבי הקדש התירו: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>דרבים דרסי על האסקופ' ודוקא כתבי הקדש אבל בשאר דברי' אסור אפי' לא נפל אלא לכרמלית [המגיד פט\"ו והרשב\"א]:</small>","m":["(א) הקורא בספר - כל ספרים שלהם עשויים בגליון כס\"ת שלנו:","(ב) על האיסקופה - היינו אפילו היתה רה\"י כגון שהיא גבוה עשרה טפחים ורוחב ד\"ט ולפניה הולכת ר\"ה וכדלקמיה והו\"א דנגזור שלא להקל בזה לגלול הספר אצלו משום דלמא נפל מידו כולו ואתי ג\"כ לאתויי אצלו דשם איכא חיוב חטאת בזה קמ\"ל דלא גזרינן בזה משום בזיון כתבי הקודש ואף דמבואר בס\"ב היכא דעומד בראש הגג ולפניה הולך ר\"ה ונתגלגל ראש אחד מן הספר מידו על הארץ דאסור לגול אצלו משום גזירה זו הכא מיירי באסקופה שרבים דורסים עליה כמבואר בהג\"ה ואיכא בזיון טפי לכתבי הקודש לכך הקילו:","(ג) ונתגלגל ראש האחד וכו' - ר\"ל ונח על הארץ דאם מסולק מן הארץ אפילו מעט לא דמי כלל לנפילה וליכא למיגזר משום נפילה:","(ד) אפילו נתגלגל וכו' - ג\"כ מותר לגלול הספר אצלו ולא חיישינן דלמא אתי לאקולי לאתויי הארבע אמות אפילו היכא דנפל כולו מידו דאיכא איסורא דאורייתא:","(ה) אפילו רשות הרבים - ודוקא היכא דצד אחד אוגדו בידו הא אם נפל גם ראש השני לארץ אפילו היכא דנפל לכרמלית ג\"כ אסור לאתויי אצלו ולא התירו בזה משום בזיון כתבי הקודש [ב\"ח ומ\"א]:","(ו) ברשות היחיד - צ\"ל רשות היחיד:","(ז) משום בזיון - דמדאורייתא אם זרק דבר לר\"ה וראש השני בידו מותר להביאו אצלו [דאין כאן הנחה כיון שראש השני בידו ויכול להביאו אצלו וא\"כ במה שמושכו ומגביהו מן הארץ לא נחשב עקירה] אלא דרבנן גזרו שלא יבואו להקל אפילו היכא דנפל לגבי והכא משום בזיון התירו:","(ח) דרבים דרסי - ואיכא בזיון טפי:","(ט) אבל בשאר וכו' - היינו נמי אפילו כשראשו אחד נשאר בידו אסור להביאו אצלו:","(י) אלא לכרמלית - והטעם דגם בזה גזרינן שמא יפול לגמרי על הארץ ואפ\"ה יביאנו אצלו ודע שיש כמה אחרונים שמקילין בזה מ\"מ נראה דבר\"ה שלנו אין להקל דכמה פוסקים סוברין דגם אצלנו יש ר\"ה דאורייתא וכדלעיל בסימן שמ\"ה ס\"ז:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>היה קורא בו <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>על הגג ונתגלגל ראשו האחד מידו עד שלא הגיע <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>לעשרה טפחים התחתונים הקרובים לארץ <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>גוללו אצלו הגיע לעשרה טפחים התחתונים אם הכותל משופע <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i><i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>בענין <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>שנח עליו אסור לגללו אצלו וכדי שלא יעמוד בבזיון הופכה על הכתב ואם אינו משופע כל זמן שלא הגיע לארץ גוללו אצלו:","m":["(יא) על הגג - מיירי בגג שהוא רה\"י היה לפניו ר\"ה אכן כל שלא הגיע לעשרה טפחים התחתונים הוי האויר מקום פטור וע\"כ גללו אצלו:","(יב) גוללו אצלו - ואפילו אם היה כותל הבית משופע ונח עליו או שהיה נח שם ע\"ג זיז בין שהיה הזיז רחב ד' ובין שלא היה ד' ובכל זה מותר לכו\"ע אפילו בשאר דברים שאינם כתבי הקודש כגון שהיה בידו סדין ונתגלגל ראש האחד מידו דלמעלה מעשרה טפחים אין שום חשש משום ר\"ה:","(יג) אם הכותל משופע - ר\"ל דאז הוי כמונח ראש אחד על הארץ וע\"כ אם נקיל בזה יש חשש שמא יפול כולו מידו שם ויבוא ג\"כ לאתויי מר\"ה לרה\"י:","(יד) שנח עליו - ודוקא כשרבים מכתפים עליו הא לאו הכי הוי כרמלית וכיון דאגודו בידו שרי להביאו אצלו בכתבי הקודש לכו\"ע ועיין בביאור הלכה:","(טו) שלא הגיע לארץ - ואפילו יש רק כמלא מחט בינו ובין הארץ כיון שלא נח ממש על הארץ ותלוי באויר לא מיקרי הנחה וגוללו אצלו. ודוקא בכתבי הקודש מקילינן אבל בשאר דברים כל שהגיע לאויר העשרה טפחים שהוא אויר ר\"ה אף שלא נח אסור להביאו אצלו דגזרינן שמא יפול כולו לארץ ויבוא ג\"כ לאתויי אצלו ויש מקילין בזה. וכל זה באויר ר\"ה אבל אם נפל לאויר כרמלית מותר לכו\"ע להביאו אצלו כיון שאוגדו עדיין בידו:","(טז) גוללו אצלו - ובביאור הגר\"א חולק ע\"ז דכל שהגיע תוך ג' סמוך לארץ חשוב כמונח על הארץ ועיין בביאור הלכה:"]}],"353":[{"s":"<b>דיני זיזין ברשות הרבים. ובו ג סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>שני בתים בשני צדי רשות הרבים והם של אדם א' או של שנים <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>ועירבו אם שניהם שוים <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>מותר לזרוק <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>מזה לזה <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>ואם א' גבוה מחבירו <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>אסור לזרוק מזה לזה <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אלא א\"כ הם <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>כלי חרס וכיוצא בהם שאם יפלו ישברו <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>במה דברים אמורים ברשות הרבים עוברת ביניהם אבל אם היתה כרמלית עוברת ביניהם מותר בכל גוונא:","m":["(א) ועירבו - דבלא ערבו הלא אסור לטלטל מרשות לרשות אפילו בלא הפסק רשות הרבים בינתים כלל:","(ב) שוים וכו' - ר\"ל דכיון שהם שוים אין צריך לאמן ידיו לזריקה שלא יפול החפץ למטה:","(ג) מותר לזרוק - ודוקא למעלה מי' דהוי מרה\"י לרשות היחיד דרך מקום פטור אבל למטה מי' אסור:","(ד) גבוה מחבירו - דכיון שגבוה מחבירו צריך לצמצם ידו בזריקה וחיישינן שמא לא יכוין כ\"כ ויפול לארץ ואתי לאתויי:","(ה) כרמלית וכו' - דכיון דאיסור כרמלית אינה אלא מדרבנן לא גזרינן שמא יפול דהוי גזירה לגזירה:","(ו) בכל גווני - היינו אפילו אחד גבוה מחבירו אבל פשוט דדוקא בשערבו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>זיז דהיינו דף הבולט מן הכותל <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>לר\"ה <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>למעלה מעשרה <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ויש בו ד' על ד' <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>וחלון הבית פתוח לו משתמשין עליו אם היו שני זיזים זה למטה מזה והם של שני אנשים אע\"פ ששניהם למעלה מעשרה אם יש בזיז העליון שלפני <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>החלון רוחב ד' על ד' <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>אסור להשתמש עליו מפני שהוא רשות בפני עצמו והזיז שתחתיו רשות אחרת <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>ואוסרין זה על זה ואם אין בעליון ד' וגם אין בתחתון ד' משתמש בשניהם ובכל הכותל עד עשרה טפחים התחתונים היה בתחתון ארבע' ובעליון אין בו ארבע' אינו משתמש בעליון אלא <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>כנגד חלונו בלבד אבל בשאר הזיז שבשני צדי החלון <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>אסור להשתמש מפני זה שתחתיו שחלק רשות לעצמו:","m":["(ז) לר\"ה - נקט לר\"ה לרבותא דאפילו לר\"ה מותר דאין ר\"ה תופס למעלה מעשרה וכ\"ש אם הוא בולט לרשות כרמלית דשרי ועיין בס\"ג דיש חילוק בין ר\"ה לכרמלית לענין ליתן עליו כלים שאין נשברים בנפילתן:","(ח) למעלה מעשרה - ולא מבעי אם היה החלון פתוח לו בסמוך להזיז בתוך ג' טפחים בודאי מותר להשתמש על הזיז מתוך החלון ליתן עליו ולטול ממנו דהוא בכלל חורי רה\"י וכרה\"י דמי אלא אפילו אם היה החלון מופלג ממנו הרבה אעפ\"כ מותר להשתמש על הזיז דכל שהוא למעלה מעשרה חשבינן ליה כמקום פטור ומשמע מסתימת המחבר דאם היה הזיז למטה מעשרה אפילו אם היה חלון הבית פתוח לו בסמוך לו בתוך ג' אפ\"ה אסור להשתמש על הזיז והטעם דכיון שהוא בתוך עשרה נוח גם לבני רה\"ר להשתמש על הזיז ולא הוי בכלל חורי רה\"י כ\"א בכלל כרמלית ואסור להשתמש עליו ליתן עליו וליטול ממנו בין מר\"ה ובין מתוך החלון:","(ט) ויש בו ד' על ד' - לפי מה שפסק המחבר בס\"ג דבכלים שאינם נשברים אסור שמא יפולו ואתי לאתויי מר\"ה וע\"כ הכא מיירי בכלים שישברו ע\"י נפילתן וא\"כ אפילו אין בהזיז ד' על ד' שמצוי שיפלו ממנו ג\"כ מותר להשתמש עליו ויש לומר בדוחק דנקט ד' על ד' משום דמסיים והחלון פתוח לו ובאין בהזיז ד' על ד' א\"צ שיהיה החלון פתוח לו דהוא מקום פטור ובכל גווני מותר להשתמש עליו:","(י) והם של וכו' - אבל של איש אחד שרי כיון שהם של רשות אחד. ואם ערבו יחד אפילו של שני אנשים שרי [פמ\"ג]:","(יא) אסור להשתמש - דוקא בכלים ששבתו בתוך הבית אבל אם שבתו בין השמשות על גבי הזיז מותר לטלטל מזיז לחברו:","(יב) זה על זה - ר\"ל בין העליון ובין התחתון והלבוש מיקל בתחתון. כתב המ\"א בשם המגיד משנה דאפילו אין בתחתון ד' ג\"כ אוסרין אלו על אלו ובלבוש מיקל בזה וכתב בא\"ר שכן הוא ג\"כ בעה\"ק:","(יג) כנגד חלונו - בלבד שהוא כזוית החלון והרחבתו:","(יד) שחלק רשות לעצמו - וממילא אסור להשתמש גם בזיז התחתון שאוסרים זה על זה וכנ\"ל ולדעת הלבוש הנ\"ל הכא בודאי מותר בתחתון:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>כל זיז היוצא על אויר רה\"ר שמותר להשתמש עליו כשהוא משתמש בו אין נותנין עליו ואין נוטלים ממנו אלא כלי חרס וזכוכית וכיוצא בהם שאם יפלו לרשות הרבים ישברו אבל שאר כלים אסורים שמא יפלו לרשות הרבים ויביאם: <small>הגה ודוקא זיז וכיוצא בו אבל אם הוא דבר רחב כגג שהמשתמש עומד שם עם הכלי מותר להשתמש בכל הכלים (ב\"י בשם הריטב\"א) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>ואם היה זיז אחד לבדו יוצא על אויר כרמלית כל שהוא גבוה י' לעולם מותר בין רחב בין קצר ואפילו כלים שאין משתברין שלא גזרו בכרמלית:","m":["(טו) כל זיז וכו' - היינו בין שהוא רחב ד' או לא:","(טז) כל שהוא גבוה יו\"ד - דשם אין אויר כרמלית תופס וכנ\"ל בסימן שמ\"ה סי\"ח ולכן מותר להשתמש עליו דרך החלון אבל למטה מעשרה הוי כמוציא מרשות היחיד לכרמלית:\n"]}],"354":[{"s":"<b>דיני בור ואשפה ברשות הרבים. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>בור ברשות הרבים וחוליא סביבו <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>אם <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>עומד <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>בתוך ד' טפחים לרשות היחיד מותר למלאות ממנו לרשות היחיד אפילו אין החוליא גבוה עשרה <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ואם הוא <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>רחוק ד' מרה\"י <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>אין ממלאים ממנו אלא אם כן תהא <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>החוליא גבוה עשרה:","m":["(א) וחוליא - היינו קרקע סביבות הבור נותן סביבותיו להקיף כמין חומה:","(ב) אם עומד - היינו הבור עצמה:","(ג) בתוך וכו' - דכיון שהוא הפסק פחות מד\"ט בין הבור להכותל לא דרסי בה רבים כלל וע\"כ הוי מקום פטור:","(ד) למלאות ממנו לרה\"י - פי' מאותו צד שהוא סמוך לרה\"י בין שהוא עומד בין הכותל לבור ומוציא המים מהבור ומניחו ברה\"י שאצלו ובין שהוא עומד בבית ומשלשל הדלי לבור דרך חלון הבית וחוזר ומכניסו לבית והטעם בכל זה דמוציא מרה\"י לרה\"י דרך מקום פטור:","(ה) אפילו אין החוליא גבוה עשרה - ר\"ל כ\"א בצירוף הבור אפ\"ה הוי רה\"י דבור וחוליתו מצטרפין לעשרה וה\"ה אם לא היה חוליא כלל והיה הבור בעצמו עמוק עשרה טפחים:","(ו) ואם הוא רחוק וכו' - דהשתא אותו מקום לאו מקום פטור הוא אלא ר\"ה:","(ז) אין ממלאים ממנו - אפילו דרך חלון דקמטלטל מרה\"י לרה\"י דרך אויר ר\"ה ואע\"ג שאגידו בידו אסור:","(ח) אא\"כ תהא וכו' - דאז ממילא הדלי ששואב בו הולך למעלה מעשרה ששם מקום פטור וא\"כ ממלא מרה\"י לרה\"י דרך מקום פטור. ודוקא כשהחלון ג\"כ גבוה יו\"ד טפחים מן הקרקע דלא ראה הדלי כלל אויר ר\"ה והעומד בר\"ה ומשלשל דלי בחבל לתוך הבור עמוק עשרה ורחב ד' וממלא מים ומוציא לר\"ה חייב ואף דעל הדלי אין לחייבו משום שלא הוציא החבל מת\"י כשהורידו לבור עכ\"פ משום המים יש לחייבו דהא עקר המים מרה\"י לר\"ה ואפילו אם סביב הבור לא היה ר\"ה רק כרמלית ג\"כ יש ליזהר מזה דעכ\"פ איסורא איכא. ודלי התלוי בעץ ארוך כמו שעושין לבארות שלנו לשאוב בו והוא תלוי בתוך הבאר או אפילו למעלה מן הבאר נגד אוירו אף שהמים היה בדלי מבעוד יום שלא עקר אותם בשבת מן הבאר אפ\"ה יש ליזהר שלא להוציאו משם להורידו על הארץ שסביב הבאר דהא עכ\"פ עשה הנחה בשבת ואפילו לאוחזו באויר סביב הבאר ג\"כ מסתפק הפמ\"ג אם מותר:","(ט) אשפה בר\"ה וכו' - ואם עומדת בכרמלית עיין בפמ\"ג:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>אשפה ברשות הרבים שגבוה עשרה ורחבה ארבעה אם היא של רבים מותר לזרוק לה מרשות היחיד הקרוב לה: <small>הגה ולא חיישינן שמא יתגלגל מן האשפה לר\"ה ואתי לאתויי דאין דרך לזרוק לאשפה אלא דברים <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>מאוסים (המגיד פ' ט' בשם הרשב\"א) </small> ואם היא של יחיד אסור משום דיחיד עשוי לפנות אשפה שלו ויבואו לשפוך שם כדרכן ונמצאו שופכים בר\"ה:","m":["(י) שגבוה עשרה - דאם לא היתה גבוה עשרה שם כרמלית עליה ואסור לזרוק עליה מרה\"י:","(יא) של רבים - דרבים משליכין שם שופכיהן וזבליהן:","(יב) מותר לזרוק לה - ואפילו אם האשפה מופלגת מן הכותל ד' טפחים ויש על ההפסק שביניהם שם ר\"ה אפ\"ה מותר לזרוק על האשפה מחלון שבבית ורק שיהיה החלון גבוה עשרה מן הארץ כדי שתהיה הזריקה מרה\"י לרה\"י דרך מקום פטור ומה שכתב המחבר הקרוב לה בא לאפוקי אם האשפה רחוק מרה\"י שלא יזרוק על האשפה שעלול ליפול בר\"ה:","(יג) הקרוב לה - ואין צריך עירוב כיון שאין בה דיורין:","(יד) מאוסים - כלומר שאין צריך להם ולא אתי לאתויי אח\"כ אפילו אם יפול:","(טו) כדרכן - שהיו רגילין שם מקודם משא\"כ באשפה של רבים לא ממלכי מעשותה אשפה ולעולם תהיה גבוה עשרה טפחים שהרי כל היום משליכין כולם שופכיהן וזבליהן שם ולא תחסר גבהה:\n"]}],"355":[{"s":"<b>דיני גזוזטרא ובית הכסא. ובו ה סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>גזוזטרא <small> (פירוש דף או בנין בולט מתוך הבתים חוצה) </small> שהיא למעלה מן המים <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>וחלון <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>פתוח לה מן הבית אין ממלאין ממנו אלא אם כן <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>עשה לה <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>מחיצה כל סביבה או יעשה המחיצה <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>סביב הנקב שדולים דרך שם <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>והוא שיהא בו <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ארבעה על ארבעה ואין חילוק בין אם יעשנה למטה מחוברת לה בין אם יעשנה על גבה וכיון שעשה מחיצה <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>מותרין <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>גם <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>לשפוך ממנה <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>וכן ההולך <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>בספינה אינו יכול למלאות אא\"כ יעשה דף ארבעה על ארבעה ועושה בו נקב וממלא דרך שם <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ואינו צריך לעשות לו מחיצות אלא אמרינן כוף הצדדים וגוד אחית מחיצתא <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>שהקילו בספינה מפני שאינו יכול לעשות שם מה שיעשה בבית <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>והני מילי כשהוא <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>בתוך <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>י' טפחים אבל אם דופני הספינה גבוהים עשרה מעל המים מוציא <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>זיז כל שהוא ועושה בו <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>נקב וממלא דרך שם שהרי דרך <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>אויר מקום פטור הוא ממלא וסגי בהיכר זיז <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ומימיו <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>יכול <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>לשפוך על דפני הספינה והם יורדים לים דכיון דלא זרק להו להדיא לים אלא מכחו הם באים כחו בכרמלית לא גזרו: <small>הגה ועיין לקמן סוף סימן שנ\"ז. שני ספינות זו אצל זו אסור לטלטל מזו לזו אלא א\"כ <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>קשורות <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>זו בזו או אא\"כ הם <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>גבוהים מן <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i>המים י' וצריכים לערב ביחד אם הם של שני בני אדם (מרדכי פרק הזורק):</small>","m":["(א) גזוזטרא - פי' דף היוצא מן כותל הבית שהיה סמוך לים או לנהר והיה הדף למעלה מן המים ויש שם נקב באמצעיתו וחלון הבית פתוח לו וכשימלא מים דרך הנקב מטלטל מן המים שהם כרמלית [כדלעיל בסימן שמ\"ה סי\"ד] לרה\"י ע\"כ צריך שיעשה מחיצה גבוה עשרה טפחים כל סביבה דהשתא הוי כל שכנגדה עד למטה רה\"י ואף שהמחיצה תלויה ואינה מגעת למים קל הוא שהקילו במים ואמרינן גוד אחית מחיצתא:","(ב) אין ממלאין ממנו - להכניסו לבית וכן להניחו ע\"ג הגזוזטרא ג\"כ אסור דהגזוזטרא ג\"כ אסור דהגזוזטרא נחשב רה\"י כיון שהחלון פתוח לו וכדלעיל בסימן שמ\"ה סט\"ז:","(ג) או יעשה וכו' - ר\"ל שאין צריך לעשות דוקא סביב כל רוחב הגזוזטרא אלא סגי כשיעשה המחיצות סביב הנקב שהוא רחב ד' על ד' טפחים דכל מחיצה העשויה לפחות מחלל ד' אינה מחיצה:","(ד) למטה מחוברת לה - אע\"פ שרחוק עוד הרבה מן המים וכ\"ש אם עושה המחיצה של עשרה טפחים למטה אצל המים דמהני דאמרינן גוד אסיק מחיצתא עד נגד הגזוזטרא:","(ה) על גבה - דגם בזה אמרינן גוד אחית מחיצתא ויש מן הראשונים שחולקין בזה וס\"ל דדוקא כשעושה המחיצות למטה מן הגזוזטרא אז אמרינן גוד אחית מחיצתא אבל לא כשעושה ע\"ג הגזוזטרא. ולכתחלה בודאי נכון ליזהר בזה:","(ו) לשפוך ממנה - היינו דרך הנקב על הנהר והים דאף שהשופכין ילכו חוץ למחיצת הגזוזטרא אפ\"ה שרי ואפילו אם הוא סמוך לרקק שהוא ר\"ה כמבואר בסימן שמ\"ה מ\"מ כיון שאין כונתו להוציאן לר\"ה שרי ועיין בבה\"ל:","(ז) אינו יכול למלאות - דהמים כרמלית הם והספינה רה\"י:","(ח) ארבעה על ארבעה - טפחים:","(ט) שהקילו בספינה - פי' שבגזוזטרא הנזכר מקודם צריך דוקא מחיצות עשרה טפחים והקולא דאמרינן גוד אחית מחיצתא עד מיא אבל בספינה מקילינן עוד דא\"צ מחיצות כלל אלא אמרינן כוף הצדדים כאילו היה שם מחיצות ואח\"כ אמרינן גוד אחית עד מיא:","(י) כשהוא בתוך י' טפחים - ר\"ל שגובה דופן הספינה הבולט מעל המים היה פחות מעשרה טפחים אבל עומק הספינה בפנימה היה גובה יו\"ד טפחים דהויא רה\"י וע\"כ צריך לעשות מבחוץ דף של ארבעה על ארבעה כמ\"ש [דאם אין עמוק י' טפחים גם בפנימה של הספינה הלא הוי כרמלית ומותר לטלטל מתוכה לים ומים לתוכה בלי שום תקון]:","(יא) גבוהים עשרה וכו' - ר\"ל ונמצא כשהוא ממלא ע\"כ צריך להגביה קצת המים למעלה מדופני הספינה שהיא יותר מי' דהוי מקום פטור וא\"כ הוא מטלטל מכרמלית לרה\"י דרך מקום פטור וע\"כ הקילו חכמים שדי שיוציא זיז כל שהוא חוץ לספינה משום היכר בעלמא:","(יב) ועושה בו נקב - והאחרונים הסכימו דבזיז א\"צ לעשות נקב כיון שאינו אלא להיכר בעלמא ויכול למלאות אפילו שלא במקום הזיז:","(יג) יכול לשפוך וכו' - ר\"ל דאין מחוייב לשפוך שופכיו [דהיינו מי רחיצות כוסות וקערות וכה\"ג] בתוך הדף של ארבע על ארבע שעשהו למלאות המים דרך בו אלא יכול לשפוך על דופני וכו' ובזה אין חילוק בין אם דופן הספינה גבוה י' טפחים מעל המים או לא ואפילו לא היה לו דף מיוחד של ארבע על ארבע וגם לא עשה זיז כלל אפ\"ה שרי לשפוך שופכיו על דופן הספינה ממש כיון דאין כאן אלא כחו:","(יד) על דופני - דאם שופך קצת רחוק מן הדופן הוי זורק מרה\"י לכרמלית ממש אבל זהו דוקא בשאין הדופן גבוה י' מעל המים דאם יש בו גבוה י' ואינו רוצה לשפוך על הדופן כגון שהם סרוחים והריח יכנס לתוך הספינה ורוצה לשפוך מרחוק לכותל שרי אך בלבד שיעשה עכ\"פ זיז להיכר:","(טו) לים - וה\"ה דיכול להניח עצמות וקליפין על ראש הדופן בעביו והם נופלין לים [אחרונים]:","(טז) ועיין לקמן - דשם כתב דלא בכל כרמלית כחו מותר ע\"ש:","(יז) אלא א\"כ קשורות - דכשאינן קשורות אע\"פ שהן סמוכות זו לזו מ\"מ עשויות להתרחק זו מזו ונמצא כרמלית מפסקת ביניהן וחיישינן דילמא נפיל ואתי לאתויי מכרמלית לרה\"י ומטעם זה אפילו שתי הספינות שהם של אדם אחד ג\"כ אסור ויש מתירין אם הם של אדם אחד דלא חיישינן דילמא נפיל וכו' ורק בשהם של שני בני אדם אסורין כשאינן קשורות זו בזו דכיון שעשויין לנוד ולהתרחק זו מזו לא מהני עירוב שיערבו ביניהן. איתא בגמרא דקשורות חשוב אפילו ע\"י חוט ובלבד שיהא חוט חזק שיוכל להעמידן שלא יתפרדו זו מזו:","(יח) זו בזו - וצריך שלא יהא ביניהם ד' טפחים:","(יט) גבוהים מן המים עשרה - דאז מותר אפילו אינם קשורות משום דקמטלטל מרה\"י לרה\"י דרך אויר מקום פטור ואע\"ג דמושיט אסור בדיוטא אחת אפילו למעלה מי' כמ\"ש בסוף סימן שמ\"ז הכא איירי בשתי דיוטות זה כנגד זה דאפילו למטה מי' הוא רק איסור דרבנן ולמעלה שרי לגמרי להושיט או דאיירי בזורק:","(כ) וצריכים לערב - קאי גם על ההיתר דגבוהים עשרה אף כשאינם קשורות ובספר בית מאיר חולק ע\"ז ודעתו דכשאינם קשורות מכיון שעומדים להתפרד אף אם הם גבוהים עשרה אם הם של שני בני אדם אסורים בטלטול מזה לזה ואין עירוב מועיל בהם:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>בית הכסא שעל פני המים מותר על ידי מחיצה תלויה ובלבד שתהא <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>עשויה <i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i>להתיר אבל העשויה לצניעות בית הכסא בלבד לא מהניא <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>ואם עשה דף <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>או קנה <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"13\"></i>פחות מג' שתפול הצואה עליו קודם שתפול למים אין צריך מחיצות דהוי ליה כחו בכרמלית ושרי <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>וה\"ה אם בית הכסא עשוי כך שהצואה נופלת על צידי הכותל ואח\"כ מתגלגלת ונופלת למטה בכרמלית <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>ואם נשבר הדף בשבת מותר משום דגדול כבוד הבריות:","m":["(כא) שעל פני המים - היינו שסמוך לים או לנהר:"]},{"s":"אם בית הכסא בולט חוץ לחומת העיר וצואה נופלת בחפירה שסביב העיר שיש בה יותר מבית סאתים שהוא כרמלית <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>אינו מותר על ידי מחיצה תלויה שלא התירו אותה אלא במים אבל על ידי דף שרי דכחו שרי בכל כרמלית: <small>הגה וי\"א דאם בית הכסא למעלה מעשרה שרי בכל ענין דהא מוציא מרשות היחיד לכרמלית דרך מקום פטור וע\"ל סימן שמ\"ו דיש חולקים וי\"א דאם היה שם צואה מבעוד יום שרי בכל ענין דהא <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i>הצואה הוא מקום <i data-commentator=\"Ba'er Hetev\" data-order=\"14\"></i>פטור דלא דרסי בה רבים (מרדכי פרק הזורק) ועיין לעיל סי' שמ\"ה דיש חולקין וסבירא להו <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i>דאין מקום פטור בכרמלית ולפי מה שנתבאר לעיל סימן שמ\"ה דאין מקום פטור ברשות היחיד לכולי עלמא בית הכסא העומד בין שני בתים אסור לפנות שם אם לא עירבו יחד ולא עשו לו תיקון מבע\"י כמו שנתבאר סעיף ב' דאז שרי דלא הוי אלא כמו חצר שאינה מעורבת כדלקמן סי' שנ\"ו ועסי' שע\"ו ס\"ד (ד\"ע) וכל זה דוקא לכתחלה אבל דיעבד ששכחו ולא ערבו מותר דגדול כבוד הבריות (הגהות מרדכי וד\"ע) הולכי ספינות נהגו לעשות צרכיהן מן המשוטה לים דהואיל והמשוטה אינה גבוה עשרה אע\"פ שרחבה ארבעה אינו אלא כרמלית ומוציא מכרמלית לכרמלית (ב\"י בשם אורחת חיים):</small>","m":["(כב) ע\"י מחיצה תלויה - שגבוה עשרה טפחים אף שאינה מגעת למים וכנ\"ל:","(כג) עשויה להתיר - לפנות שם בשבת כגון שיעשנה למטה סביב לצד המים דמה שנעשית למעלה לצניעות עבידא:","(כד) דף או קנה פחות מג' - היינו שהם פחות מג' סמוך לנקב דהוי לבוד והוי חורי רה\"י דהוא כרה\"י לרה\"י ואע\"ג שנופל משם אח\"כ למטה דהוא כרמלית כחו בכרמלית לא גזרו:","(כה) נשבר הדף בשבת וכו' - ר\"ל שנשבר בשבת גופא שא\"א לתקנו ולכן מותר לפנות שם לאותו שבת:","(כו) שהוא כרמלית - ר\"ל שאף שהחפירה עמוקה י' טפחים כיון שהיא מחזקת יותר מבית סאתים ולא הוקפה לדירה דין כרמלית עליה נמצא מוציא מרה\"י לכרמלית:","(כז) אינו מותר וכו' - אלא בעינן שהמחיצות יגיעו עד הקרקע:","(כח) אבל ע\"י דף - או קנה או שהצואה נופל על צידי הכותל ואח\"כ מתגלגל ונופל בחפירה וכנ\"ל:","(כט) למעלה מעשרה - מקרקעית החפירה והטעם דאויר למעלה מעשרה בכרמלית מקום פטור הוא ונמצא כשהוא נפנה מוציא מרה\"י לכרמלית דרך מקום פטור:","(ל) ועיין לעיל סי' שמ\"ו וכו' - היינו בסוף ס\"א דיש אוסרים להוציא מרה\"י לכרמלית אפילו דרך מקום פטור ועיין בביאור הגר\"א שמאריך בזה ודעתו דאף אי נימא דברשויות דרבנן דרך מקום פטור מותר היינו דוקא בדנח באמצע על המקום פטור אבל לא בדלא נח והכא הלא לא נח באמצע וכעין זה מפקפק הבית מאיר ג\"כ על הי\"א הראשון [עיין בספרו בסי' שמ\"ו וכן בכ\"מ] וכן בספר מאמר מרדכי בסי' שנ\"ג ס\"א דעתו ג\"כ כדעת הגר\"א הנ\"ל ותמה על דעת הי\"א הראשון:","(לא) צואה מבעוד יום - ומיירי שמפנה ממש על הצואה ואע\"פ שנופלת אח\"כ מן הצד שהוא כרמלית שרי:","(לב) הצואה הוא מקום פטור - דהא מסתמא אינה רחבה ד' ואף דבעלמא קיי\"ל דפחות מג\"ט גובה בטל לגבי רשות שהוא עומד בו והצואה מסתמא אינה גבוה ג\"ט שאני הכא דצואה שבבה\"כ בודאי לא דרסי לה רבים וע\"כ אינה בטל לרשות שבצדה והוי מקום פטור:","(לג) ולפי מה וכו' - כאן מתחיל הרמ\"א לבאר דין אחר אודות בהכ\"ס שהיה שייך מקום החפירה שתחתיה לשני אנשים ולא עירבו ביניהם וקאמר דכאן לא שייך ההיתר שכתב מתחלה דהצואה הוי מקום פטור כיון דהרשויות בעצמן רה\"י הם אין מקום פטור ברה\"י:","(לד) אסור לפנות שם - מיירי שמקום מושב בהכ\"ס היה שייך לכל אחד לבדו כי היה מחיצה מפסקת ביניהם אלא שהחפירה שתחתיה היה שייך לשניהם ולכך אסור דמוציא מרשותו לקרקע שותפים דאם גם מקום מושב שייך להשותפים אין כאן הוצאה מרשות לרשות ומותר [בית מאיר וחידושי רע\"א עי\"ש]:","(לה) כמו שנתבאר ס\"ב - היינו תיקון דדף או קנה. אבל תיקון דמחיצה תלויה אינו מועיל הכא עד שיורדת עד למטה:","(לו) כדלקמן סי' שנ\"ז - ס\"ג בהג\"ה דשם מבואר דבחצר שאינה מעורבת לכו\"ע מותר כחו:","(לז) ששכחו ולא עירבו - או שלא היה לו באפשר לעשות תיקון הנזכר [ח\"א]:","(לח) דגדול כבוד הבריות - שהתירו חכמים במקום שאין בו איסור דאורייתא:","(לט) מן המשוטה לים - אבל מן הספינה לים [בלא תיקון הנזכר בס\"ב] לא דהא מוציא מן רה\"י לים שהוא כרמלית ואם א\"א ליה מפני איזה סבה אא\"כ יעשה צרכיו בספינה מותר דגדול כבוד הבריות [א\"ר]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i><i data-commentator=\"Magen Avraham\" data-order=\"16\"></i>מים שאין <i data-commentator=\"Ba'er Hetev\" data-order=\"15\"></i>עמוקים י' טפחים אין להם דין מים להתיר לשפוך בהם במחיצה תלויה: הגה וכל שכן אם יבשו המים אע\"פ שהיו שם עמוקים עשרה (מרדכי):","m":["(מ) מים שאין עמוקים וכו' - קאי על ס\"א ובי\"ת:","(מא) לשפוך בהם - וה\"ה למלאות ע\"י מחיצה תלויה והטעם דכיון שאין בהם י\"ט כיבשה דמיא. ועיין בב\"ח ומ\"א שחולקין ע\"ז וס\"ל דאין לחלק בזה אם לא שרבים מהלכין שם ע\"י הדחק דאז לכו\"ע כקרקע דמיא ועיין בביאור הגר\"א שיישב דעת השו\"ע וכתב דדבר זה תלוי בשיטת הראשונים עי\"ש ומ\"מ אף לדידיה נוכל לסמוך ע\"ד הפוסקים המקילין בזה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>היו שתי גזוזטראות זו למעלה מזו משוכה זו מכנגד זו מעט <i data-commentator=\"Turei Zahav\" data-order=\"7\"></i><i data-commentator=\"Magen Avraham\" data-order=\"17\"></i>ואינה <i data-commentator=\"Ba'er Hetev\" data-order=\"16\"></i>רחוקה מכנגדה ארבעה טפחים בין אם עומדות תוך עשרה זו לזו בין יש ביניהם יותר מגובה עשר אמות <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>עשו לעליונה מחיצה בשותפות משל שניהם ולא עשו לתחתונה כלל שתיהן אסורו' בה עד שיערבו וכל שכן אם עשו שתיהן <i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i>לתחתונ' ששתיהן אסורות עד שיערבו <i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i>אבל כל אחת מהן <i data-commentator=\"Magen Avraham\" data-order=\"18\"></i>שעשתה לבדה בשלה אין האחרת אוסרת עליה אפי' לא עשתה האחרת בשלה <i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"19\"></i>וכן אם עשו <i data-commentator=\"Magen Avraham\" data-order=\"19\"></i>בשתיהן בשותפות משל שניהם אין אחת אוסרת על חברתה:","m":["(מב) היו שתי וכו' - אבאר בקצרה והוא דבית ועליה ע\"ג העומדת אצל הנהר ויש להם לכל אחת גזוזטרא הבולטת לדלות על ידה מים מן הנהר אם היו עושים כ\"א מחיצות סביבה כדין המבואר בס\"א היו שתיהן מותרות בשבת כל אחד לדלות בשלו אפי' אם לא ערבו יחד ואם תקנו שתיהן בשותפות רק גזוזטרא אחת כדין בין לעליונה בין לתחתונה נחשבין כשני אנשים הדרין בחצר אחת ואסורין שניהם לדלות דרך הגזוזטרא ההיא כיון שרשות שניהם שולטת עליה אם לא שעירבו ביניהן. בד\"א ששתי הגזוזטרא העומדים זה ע\"ג זה אינם רחוקים זה מזה במשך הכותל ד' טפחים שנוח תשמישתיה אבל אם היו רחוקים ד' טפחים א\"כ כשרוצה בעל התחתון להשתמש בגזוזטרא העליונה צריך לזרוק דלי שלו באויר להלאה דרך ד' טפחים ותשמיש מופלג כזה אין חשיב לאסור על חבירו אף כשלא עירבו ביניהן:","(מג) משוכה זו וכו' - ר\"ל אפילו משוכה וכ\"ש אם עומדת זו כנגד זו בשוה:","(מד) ואינה רחוקה וכו' - דברחוקה מכנגדה במשך רוחב הכותל ד' טפחים שוב לא אסרי אהדדי שאינה יכולה להשתמש אלא ע\"י זריקת הדלי באויר מרחוק ואינו חשוב תשמיש לאסור:","(מה) יותר מגובה וכו' - דאגובה לא קפדינן אע\"פ דהוכרח עי\"ז להשתמש בדלי ע\"י זריקה למעלה והיא תשמיש קשה כיון שאינו משתמש דרך אויר ברוחב חשיבא תשמישתיה לאסור:","(מו) וכ\"ש אם עשו שתיהן לתחתונה - שתשמיש זה נוח יותר לעליונה שהוא דרך ירידה:","(מז) אין האחרת וכו' - היינו אפילו רגילה להשתמש בשל חברתה בחול אעפ\"כ אינה אוסרת עליה שבעצם הלא הרשות אין שייך לה אם לא שהתנו ביניהן בפירוש שכל אחד ישתמש בשל חבירו אז צריכין עירוב [פמ\"ג]:","(מח) אפילו לא עשתה וכו' - וכ\"ש אם כ\"א עשתה לעצמה דמותרת כל אחת להשתמש בגזוזטרא שלה בלי עירוב אך י\"א דכל זה דוקא בשמשוכות הגזוזטרות זו מזו ואין צריכין לשמש אחת בחברתה אבל אם העליונה מכוונת ממש נגד התחתונה וכשהיא צריכה לדלות מים יורד הדלי שלה דרך נקב גזוזטרא התחתונה ואין ביניהן אויר של עשרה טפחים בגובה שתיהן אסורות למלאות [רמב\"ם]:","(מט) אם עשו בשתיהן וכו' - ר\"ל דאף דאמרינן לעיל דאם תקנו לאחת בשותפות שתיהן אסורות למלאות שם כשלא עירבו הוא דוקא אם תקנו רק אחת ובשניה לא עשו מחיצה כלל אבל אם עשו תיקון בשתיהן בשותפות מותרים כל אחת בשלה משום דאמרינן דכל אחת סלקה נפשה מחברתה כיון שעשתה לה תיקון בפנ\"ע [ומה שעשתה בשותפות איזה טעם היה להם בדבר] וכ\"ש אם עשו רק באחת בשותפות והשניה עשתה מחיצה להגזוזטרא שלה לבדה בודאי מותר כ\"א למלאות בלי עירוב דבהא בודאי סילקה נפשה מחברתה:\n"]}],"356":[{"s":"<b>דין אמת המים העוברת בחצר. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>אמת המים העוברת בחצר <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>עמוקה עשרה ורחבה ארבעה <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>אין ממלאין ממנה בשבת אלא אם כן עשו לה <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>מחיצה גבוה עשרה בכניסתה וביציאתה <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ויהיה טפח ממנה <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>משוקע במים <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואם היתה המחיצה כולה יורדת בתוך המים צריך שיהי' טפח ממנה יוצא למעל מן המים ואם התחילה לעשות המחיצ' <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>אצל השפה מכל צד ולא חיבר אותם <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>באמצע כדי שיהו המים נכנסים ויוצאים דרך שם <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אם אין ביניהם ג' טפחים שרי דאמרינן לבוד יש ביניהם ג' טפחים אסור: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>ואם הנקבים שהאמה נכנס ויוצא בהם אינם רחבים ג' אפי' מחיצה אינו צריך (ב\"י בשם ריטב\"א):</small>","m":["(א) העוברת בחצר - ודוקא כשהיא עוברת דהיינו שנכנסת לחצר מן צד האחד ויוצאת משם מן צד האחר בנקבים שיש תחת הכתלים אבל אם יש לו בריכת מים בחצירו ואינה נמשכת מבחוץ א\"צ שום תיקון אפילו רחבה ועמוקה הרבה דכל מה שבתוך המחיצות בכלל רה\"י הוא:","(ב) עמוקה עשרה ורחבה ד' - דבשיעור זה נעשו המים רשות לעצמן ושם כרמלית עליהם כשאר ימים ונהרות ולפיכך כשעוברין דרך חצירו אסור למלאות מהן בשבת אבל אם אין עמוקין עשרה או שאינם רחבים ד' מותר למלאות מהן בלי שום תיקון דבטל הוא לגבי רה\"י:","(ג) אא\"כ עשו וכו' - דכיון שמבדילין משאר המים שחוץ לחצר המים שבתוך החצר בטלין לגביה דבעלמא הלא קיי\"ל דכל מה שבתוך המחיצות רה\"י הוא ורק בזה כשמחוברין עם המים שמבחוץ אמרינן דאינם בטילים ונעשו רשות לעצמן משא\"כ כשמבדילן שם רה\"י עליהם ומחיצת החצר גופא אף אם שקוע הרבה במים אינו מועיל בזה דבעינן שיהא נראה שנעשה בשביל המים:","(ד) בכניסתה וביציאתה - ר\"ל במקום כניסת המים לחצר ובמקום יציאת המים מן החצר והכל בפנים על פני רוחב אמת המים:","(ה) משוקע במים - לחלוק בין המים שבחוץ שהם כרמלית למים שבפנים:","(ו) למעלה מן המים - כדי שיהיה ניכרת קצת המחיצה המפסיקתן:","(ז) אצל השפה מכל צד וכו' - פירוש שבצד הכניסה ובצד היציאה עשה מחיצה לרחב האמה אלא שלא עשה מחיצה בצד הכניסה כולה בחתיכה אחת אלא בשתי חתיכות דבאמצע המחיצה הניח מקום פנוי וכן במחיצה של צד היציאה:","(ח) דאמרינן לבוד - ומטעם זה אפילו הניח הרבה חללים ביניהם כגון שעשה המחיצה מקנים ובין כל אחד ואחד היה פחות מג' שרי [ח\"א]:","(ט) אפילו וכו' - דכל מה שפחות משלשה אמרינן לבוד ונראה דבזה אפילו אם מצד השני הוא רחב שלשה אעפ\"כ א\"צ תיקון כיון דמצד אחד הוא כסתום לגמרי וכעין לשון ים העוברת בתוך החצר המבואר לקמיה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>חצר שנפרצה ולשון ים עובר על הפרצה <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>אם אינו במלואו <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ואין בפרצה יותד מי' <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>מותר <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>למלאות ממנו ולהכניס לבית נפרצה במילואה או שיש בפרצה יותר מי' <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>אם נשאר במקום שנפרץ גידודין <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>גבוהים י' והמים מכסים אותו מותר למלאות <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>ממנו <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>בחצר אבל <i data-commentator=\"Be'er HaGolah\" data-label=\"•\" data-order=\"10\"></i>אסור להכניסן לבית אלא אם כן עשו מחיצה גבוה עשרה על המים לא נשאר גידודים <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>אסור אפילו למלאות <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>בחצר:","m":["(י) מותר למלאות ממנה - אע\"פ שהיא עמוקה י' ורחבה ד' ואינו דומה לאמת המים המבואר בס\"א דבכאן כיון שנכנס לשון הים בחצר ואינו יוצא ממנה לצד אחר הוא כבור שבחצר ומחיצות החצר מתירות אותה [דכיון שלא נפרץ יותר מעשר הוא בכלל פתח דהוי כאלו המחיצות קיימין] משא\"כ באמת המים שנכנסת ויוצאת תחת כותלי החצר משני הצדדים חולקת רשות לעצמה והוי כרמלית:","(יא) במילואה - היינו כל כותל החצר שלצד המים:","(יב) גידודין גבוהים י' - דבזה נחשב כאלו המחיצות עדיין קיימות:","(יג) ממנו בחצר - דפעמים שהמים שוקעים והמחיצה ניכרת ולכן אף כשאין המים שוקעים התירו חכמים משא\"כ בבית שהוא רחוק מן המחיצה לעולם אין המחיצה נראית אפילו כשהמים שוקעים:","(יד) גבוה עשרה - ורחבה של המחיצה א\"צ על פני כל הפרצה ורק שיסתום השטח עד שלא ישאר אלא עשר אמות פרוץ דהוא שיעור פתח:","(טו) לא נשאר גדודים וכו' - ר\"ל שלא נשאר גדודים גבוהים עשרה:","(טז) אסור אפילו למלאות - וה\"ה לטלטל בחצר כיון שהוא פרוץ יותר מעשר למקום האסור בד\"א כשאין לשון הים עמוק י' אבל אם הלשון עמוק י' שהמים שטפו קרקעית החצר ונעשה גומא עמוקה י' טפחים דופני הגומא גופא נחשב למחיצה בין המים ובין החצר ומותר לטלטל בחצר אבל אסור למלאות ממנה כיון שאין מחיצה על גבה בינו לבין המים שבחוץ:\n"]}],"357":[{"s":"<b>דיני חצר פחות מד' אמות וביב. ובו ג סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>חצר שפחותה מד' אמות על ד' אמות שהיא סמוכה לרשות הרבים אין שופכין לתוכה מים בשב' בימות החמה שכיון שאין בה ד' אמות אין סאתים מים שאדם עשוי להשתמש בכל יום ראוי ליבלע בה והוי כאילו שופך לרשות הרבים לכך צריך לעשות גומא שתהא חללה מחזקת סאתים: <small>הגה וכל גומא חצי אמה על חצי אמה ברום שלשה חומשי אמה מחזקת סאתים (רמב\"ם) </small> בין אם יעשנה בפנים בחצר או בחוץ אלא שאם יעשנו בחוץ צריך <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>לכסותה בנסרים <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>כדי שתהא <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>מקום פטור ויפלו המים מידו למקום פטור וכיון שיעשה גומא <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>יכול לשפוך בה כל מה שירצה ואם אינה מחזקת סאתים <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>לא ישפוך בה כלל <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואם יש בחצר ארבע על ארבע <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>אפי' הוא <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>אריך <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>וקטין <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>או <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>בימות <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>הגשמים בחצר כל שהוא מותר לשפוך בה כל מה שירצה <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>וחצר ואכסדרה <small> (פי' בית שיש לו ג' דפנות ודופן ד' שמעמידין בו דלת אינה מגופפת כל עיקר אלא ברחבו של בית כלו ופעמים שעושים לה אמה אחת פצים מכאן ואמה אחת פצים מכאן כך פי' הערוך ופצים הוא מעט כותל ישר ושוה) </small> שאין באחד מהם לבד ד' אמות מצטרפין לד' אמות להתיר לשפוך בהם: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>והוא הדין ב' דיוטאות שלפני ב' עליות ועליהם <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>מעזיבה שראוים המים לבלוע בהם אם הם <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>סמוכות זו לזו מצטרפות (ב\"י בשם הר\"ר יונתן): </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>במה דברים אמורים בחצר הסמוכה לר\"ה <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>אבל אם היא סמוכה <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>לכרמלית אפילו היא קטנה הרבה <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>אינה צריכה גומא אפילו בימות החמה <small> (וע\"ל סי' שע\"ז):</small>","m":["(א) חצר וכו' - כלל הדברים הנאמרים בסימן זה הוא כך לפי ששיערו חז\"ל שכל אדם הוא צריך להשתמש בכל יום סאתים מים לרחוץ בהם פניו ידיו ורגליו ושאר ענינים הצריכים לו וכבר נודע דבשבת אסור לשפוך מרה\"י לרשות הרבים או לכרמלית ודרך כל אדם לשפוך שופכין שלו לחצירו הסמוך לביתו שהוא רשותו והוא ג\"כ רה\"י ומוציא מרה\"י לרה\"י ושיערו חז\"ל דסאתים מים נבלעים בקרקע של ד\"א על ד\"א ואינם מטנפים הקרקע של החצר וכיון שכן אין מקפיד עליהם שיצאו לחוץ דוקא ואז אפילו אם יצאו אח\"כ לחוץ לא היתה מחשבתו לכך ובשבת בעינן מלאכת מחשבת ולא הוי כאלו מוציא מרה\"י לר\"ה אבל אם הוא פחות מד\"א על ד\"א דאז הסאתים מים מרובים ואינם נבלעים בקרקע ונעשה החצר רפש וטיט ודעתו קצה בזה בימות החמה שדרך כל אדם להקפיד על חצרו שיהיה נקי ולכך ניחא ליה שיזובו משם לחוץ ואם יצאו לחוץ נתקיים מחשבתו ויש לגזור שמא ישפוך להדיא מרה\"י לר\"ה ולכן צריך לעשות לחצר גומא שהיא מחזקת סאתים ואז כשישפוך לתוך החצר אינו מקפיד עליהם שיצאו לחוץ כיון שאפשר להם לירד ולנוח בגומא ולא יתטנף חצרו וע\"כ אפילו אם יצאו לחוץ לא הוי כמוציא מרה\"י לר\"ה:","(ב) שהיא סמוכה לר\"ה - לאפוקי כשהיא סמוכה לכרמלית וכדלקמיה בסוף הסעיף:","(ג) בימות החמה - שאדם מקפיד על לכלוך חצרו ומסתמא ניחא ליה שיצא לחוץ:","(ד) וכל גומא וכו' - וה\"ה שיכול לשנותה בעמקה וברחבה ורק שיהיה חללה מחזקת סאתים:","(ה) בחוץ - היינו בצד החצר:","(ו) כדי וכו' - וגם כדי שלא יהא תקלה לרבים [ד\"מ]:","(ז) שתהא מקום פטור - דע\"י הכיסוי מסתלק אותו המקום מתשמיש הרבים והנה בגוונא שצייר בהג\"ה בלא הכיסוי הוא ג\"כ מקום פטור דהוא פחות מארבע על ארבע אלא פן יעלה אותו קרקעית העוקה רפש וטיט ויהיה פחות מן ג' טפחים בגובה ותבטל לגבי ר\"ה:","(ח) יכול לשפוך וכו' - ואפי' נתמלאה מע\"ש שופך לתוכה דכיון דמדאורייתא לית איסורא כ\"א בשופך להדיא לר\"ה רק שתקנו חכמים גומא זכר לשבת שלא ישכח וישליכם להדיא לר\"ה וכיון דאיכא הכירא ע\"י עשיית הגומא שרי ומהאי טעמא נמי התירו לשפוך כל מה שירצה אף שהגומא מחזקת רק סאתים ובודאי יצאו הנותרים לחוץ וניחא ליה בזה כדי שלא יתטנף חצרו אפ\"ה שרי דמ\"מ זכור הוא ע\"י עשיית הגומא ולא גזרו ביה:","(ט) כלל - דגזרינן דילמא אתי לשפוך סאתים דהוא שיעור תשמיש אדם ליום:","(י) אריך וקטין - כגון שהוא ארוך ח' אמות ורוחב שתים דמ\"מ יש כאן שיעור לבלוע סאתים:","(יא) בימות הגשמים - שאין אדם מקפיד על לכלוך חצרו ואינו מתכוין שיצאו לחוץ ואי משם אנשים אחרים שיראו צנור מקלח ואתי למישרי גם בימות החמה אמרינן שיתלו יותר שמי גשמים הן ואפילו שלא בשעת הגשמים מתמצים הם מן הגשמים שהיו בהן מקודם:","(יב) מותר לשפוך בה וכו' - ר\"ל אפילו בלא עשיית גומא כלל:","(יג) ב' דיוטאות - היינו שתי זיזין רחבין נגד פתחי העליות [ורוחב כל זיז שתי אמות באורך ארבע אמות נגד העליה] ועל הזיזין יש מעזיבה רכה שראוי לבלוע בה המים הנשפכין עליהן:","(יד) סמוכות זו לזו - ר\"ל בתוך ד' טפחים מצטרפות כאלו היו במקום אחד וא\"כ הוי ד' אמות על ד' אמות ומותר לשפוך עליהן ומשם יורדים לר\"ה להדיא:","(טו) אבל וכו' לכרמלית - דאפילו כשהיא סמוכה לר\"ה אינו אסור רק משום גזירה דילמא אתי לזרוק להדיא לר\"ה ובכרמלית לא שייך זה דאפילו כי יזרוק להדיא ג\"כ ליכא איסורא דאורייתא ועיין לקמן סוף סימן זה דיש חולקין:","(טז) ביב וכו' - הוא חריץ העשוי לקלח שופכין שבחצר לר\"ה:","(יז) ארבע אמות במשך - צ\"ל במשך ארבע אמות ור\"ל שארבע אמות הראשונות הסמוכות להחצר הוא מכוסה והוא רחב ג\"כ ארבע אמות [וה\"ה אם הוא רחב רק שתי אמות ויש בארכו שמונה אמות] דבשיעור זה יש שיעור לבלוע סאתים מים שאדם עשוי להסתפק בכל יום וע\"כ מקילינן ביה לשפוך ע\"פ הביב העומד בחצר כמו בחצר שהוא מחזיק ד\"א על ד\"א וכנ\"ל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i><i data-commentator=\"Turei Zahav\" data-order=\"6\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>ביב שמכוסה ד' אמות במשך ברשות הרבים ויש בו ארבע על ארבע <i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>מותר <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>לשפוך אפי' על פי הביב אפי' בימות החמה אע\"פ שהמים יוצאים מיד מידו לחוץ <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>ובלבד שלא יהא סילון של עץ שאין המים ראוים לבלוע אבל אם עשוי כעין רצפה <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>של אבנים מבליעים ושרי <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>ולהרמב\"ם אפי' היה אורך הביב או הצנור מאה אמה לא ישפוך על פיו בימות החמה אלא שופך חוץ לביב והם יורדים לביב:","m":["(יח) לחוץ - כיון דהוא אינו מכוין דוקא שיצאו לחוץ וע\"כ אפילו כשיצאו לחוץ שרי וכנ\"ל בריש הסעיף:","(יט) שלא יהא וכו' - דאם הביב של עץ הוי כמכוין בהדיא שיצא לחוץ ואפילו מחזיק מאה אמה אסור:","(כ) כעין רצפה של אבנים - מיירי שמרוצף באבנים חלקים קטנים כמו שמרוצף רחובות וחצרות שיש הרבה עפר בין אבן לאבן לבלוע:","(כא) אפילו היה אורך הביב וכו' - ר\"ל שאורך הביב בחצר הוא מאה אמה ובשיעור זה בודאי יבלע המים בקרקע אפ\"ה אסור מפני שהמים יוצאין מכחו לר\"ה [שם ברמב\"ם] ונקטינן להקל כסברא ראשונה (א\"ר):","(כב) או הצנור - צנור מקרי מה שמניחין על הגג וע\"י יורד הקילוח לר\"ה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>במה דברים אמורים כשהמים יוצאים לרשות הרבים אבל אם היו יוצאים לכרמלית <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>מותר לשפוך על פי הביב אפילו בימות החמה: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"8\"></i>וי\"א דאין חילוק בין כרמלית לרשות הרבים (ב\"י בשם תוספות והרא\"ש בפ' כיצד משתתפין) ודוקא כרמלית שהיא תוך העיר <i data-commentator=\"Turei Zahav\" data-order=\"9\"></i>דמחלף ברה\"ר עצמה <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>אפילו בזמן <i data-commentator=\"Be'er HaGolah\" data-label=\"•\" data-order=\"11\"></i>הזה דלית לן <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>רה\"ר אבל <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>כרמלית <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>שהוא מחוץ לעיר או חצר שאינה מעורבת שרי (מרדכי פרק הזורק וסמ\"ג וד\"ע) (תשו' מהר\"מ סימן צ') ועיר המוקפת חומה ולא עירבו בה כחצר שאינה מעורבת דמי (מרדכי ס\"פ הדר ותה\"ד סימן ע\"ג וע\"ד) ואם הצנור למעלה מעשרה שעוברים המים דרך מקום פטור לכרמלית יש להקל (מהרי\"ל) וכן עיקר:</small>","m":["(כג) במה דברים אמורים וכו' - זהו סיום דברי הרמב\"ם וגם לדידן נ\"מ בזה דהיינו אם הביב היה של עץ שאינו עשוי ליבלע בו המים ובודאי יצאו לחוץ בר\"ה דזה אסור אפי' לדעה ראשונה אבל כשהיא סמוכה לכרמלית מותר אפילו בשל עץ והטעם בכל זה כיון דאינו שופך בהדיא לכרמלית רק שהוא בא מכחו ס\"ל דכחו בכרמלית לא גזרו:","(כד) וי\"א דאין חילוק וכו' - אף דאנן נקטינן לדינא דאפילו כשהמים יוצאים לר\"ה מותר בביב וכמו שכתבנו בסקכ\"א מ\"מ נ\"מ מי\"א הזה לענין סילון של עץ וכמ\"ש בסקכ\"ג או כשהביב אין מכוסה ד' אמות בהכרמלית דלהשו\"ע מותר ולהי\"א אסור וגם נ\"מ לענין חצר קטנה שאין בה ד\"א על ד\"א דסתם המחבר לעיל בסוף סעיף א' דבסמוכה לכרמלית מותר ולהי\"א הזה אסור [ומה שנרשם בהג\"ה ב\"י בשם תוס' והרא\"ש לא נזכר בתוס' ורא\"ש לענין ביב כלל דהם פוסקים בביב להקל אפילו בסמוכה לר\"ה רק לפי דבריהם נשמעו גם לענינינו]:","(כה) אפילו בזה\"ז דלית וכו' - ר\"ל לדעת הסוברים דבעינן דוקא ס' רבוא בוקעין בו וזה אינו מצוי מ\"מ גזרינן אטו עיר גדולה שיזדמן שיהיה ס' רבוא [מ\"א]:","(כו) או חצר שאינה מעורבת - ר\"ל דהחצר שבו הביב [או חצר קטנה שאין בו ד' על ד'] סמוך לחצר שאינה מעורבת וכששופך המים ירד לאותה חצר שרי לכו\"ע כיון דלא זריק להדיא אלא כחו לא גזרו בזה ושרי לשפוך אפילו ע\"פ הביב:","(כז) כחצר שאינה מעורבת דמי - כיון דבאמת יש לה מחיצות אלא שמחוסרת עירוב:","(כח) ואם הצנור וכו' - ר\"ל שצנור המקלח מים בכרמלית הוא למעלה מעשרה וא\"כ עובר המים דרך מקום פטור מותר לשפוך אפילו במתכוין שירדו המים לכרמלית והיינו אפילו לדעת המחמירים לעיל בסימן שמ\"ו סוף ס\"א דרך מקום פטור הכא דלא זריק להו ממש אלא כחו יש להקל [הגר\"א]:","(כט) וכן עיקר - עיין בפמ\"ג שמצדד דאכל הג\"ה קאי ואף אראש דבריו:"]}],"358":[{"s":"<b>דין איזה מקומות נקראים מוקפים לדירה. ובו יד סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>כל היקף שלא הוקף לדירה כגון גנות ופרדסים <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>ובורגנין שאינם עשוים אלא לשמור בתוכן אסרו חכמים לטלטל בתוכה יותר מד' אמות <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>אם הוא יותר <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>מסאתים אבל אם היא סאתים שהוא שיעור ע' אמה וד' טפחים על ע' אמה וד' טפחים מותר לטלטל בכולו בין שהוא מרובע בין שהוא עגול <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>או <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>אריך <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>וקטין <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ובלבד שלא יהא אורכו יותר משנים ברחבו <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>אמה אחת ואם הוקף לדירה <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אפי' יש בה כמה מילין מותר לטלטל בכולו: <small>הגה ועיין לקמן סי' ת\"א דין סתם עיירות אי מוקפות לדירה וי\"א דסתם קרפיפות שלנו מקרי מוקפות לדירה דרגילים לפתוח פתח תחילה ואח\"כ להקיף (מרדכי פרק עושין פסין) וי\"א עוד דכל קרפף שהוא <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>סמוך לביתו מקרי היקף לדירה כי דעתיה עלויה (הגהות אשירי פ\"ב דעירובין) ויש חולקין בזה (ב\"י בשם תוס'):</small>","m":["(א) לדירה - דירת אדם ותשמישיו:","(ב) כגון גנות ופרדסים - שמקיפים אותם רק לשמור את הפירות והזרעים שבתוכן וה\"ה קרפף שהוא היקף גדול חוץ לעיר להכניס שם עצים לאוצר:","(ג) ובורגנין - סוכת שומרים שבשדות:","(ד) שאינן עשויין וכו' - ר\"ל אע\"ג דסוכה זו נעשית לישיבת השומר מ\"מ כיון שאין דירתם שם מחמת עצמן אלא לשמור האויר שלפניהן אין זו דירה חשובה מחמת עצמה והרי זו כהיקף של גנות ופרדסים ואפי' היא מקורה בגג נמי לא מיחשבה דירה ועיין ביאור הלכה בסימן שס\"ב מ\"ש בזה:","(ה) אסרו חכמים וכו' - דאע\"ג דמן התורה כל המוקף מחיצות גבוהות עשרה אע\"פ שהיא רחבה כמה כורים הוא רה\"י גמור ומותר לטלטל בכולו מ\"מ חכמים אסרו בהיקף גדול יותר מב\"ס שלא הוקף לדירה שהוא דומה קצת לר\"ה ולכרמלית שלא לטלטל בה ביותר מד\"א כמו בר\"ה ובכרמלית:","(ו) שהוא שיעור ע' וכו' - דבית סאה הוא נ' על נ' דהיינו בין כולו אלפים וחמש מאות אמה באמה רוחב ובית סאתים הוא ה' אלפים אמה באמה רוחב וכשתעשה מזה שדה מרובעת הוא בערך שיעור ע' אמה וד' טפחים אורך על ע' אמה וד' טפחים רוחב:","(ז) וד' טפחים - ומעט יותר כשיעור אצבע בערך ולא חשו להזכירו מפני שהוא מועט ואעפ\"כ יכול לחשבו בחשבון וכל שליכא יותר על ע' אמה וד' טפחים ואותו משהו מותר לטלטל ועיין בקיצור ש\"ע שכתב דלפי אמות שלנו שהם גדולים הוא נ\"ג על נ\"ג:","(ח) מותר לטלטל בכולו - וסמכו חכמים בשיעור זה אשיעורא של חצר המשכן שהיה ב\"ס בכולו והיו מטלטלים בו:","(ט) בין שהוא מרובע - והכלל בזה דכל דליכא יותר מה' אלפים בתשבורת לית לן בה בין שהמקום עגול או מרובע או שאר צורות וכדלקמיה:","(י) או אריך וקטין - כגון שהיה ארוך ק' ורוחב נ' שהוא עולה כמרובה של ע' וד\"ט:","(יא) ובלבד שלא יהא ארכו וכו' - דהיינו שלא יהא עכ\"פ ארכו יותר ממאה אמה דכל שהוא שטח גדול אף באורך לחוד מיחלפי בר\"ה וכרמלית ובמאה אמה לא רצו לגזור מפני שמצינו בחצר המשכן שארכו מאה ורחבו חמשים:","(יב) אמה אחת - אבל בפחות מאמה לא גזרו וכ\"ז בדוקא אם היה עכ\"פ בית סאתים בין כולה אבל אם בין כולה ליכא ב\"ס לא קפדינן בזה ואפילו היה ארכו הרבה יותר ממאה אמה נמי מותר לטלטל בכולה כל שמוקף מחיצות:","(יג) אי מוקפות - פי' היכא שיש חומה סביב לעיר ומבואר שם דמן הסתם אמרי' דהוקף לדירה דאין דרך להקיף אלא אחר שבנו הבתים מתחלה והוי בנוי ולבסוף הוקף דמהני וכדלקמן:","(יד) דסתם קרפיפות וכו' - פי' ופתח הבית פתוחה להם:","(טו) דרגילים - כוונת הרמ\"א במקום שאין אדם זוכר אם הקרפיפות נבנו קודם הבתים או לאחר הבתים ולשם תשמיש דירה ובזה כתב דרוב קרפיפות שלנו הוקפו אחר בנין הבתים לתשמישי הבתים ודבר פשוט הוא דלאו כללא הוא בכל מקום ובכ\"ז ויש לראות בזה בזמננו לפי מנהג המקומות:","(טז) סמוך לביתו - וכל שהוא סמוך לעיר מיקרי סמוך לביתו לדיעה זו:","(יז) דעתיה עילויה - ופשוט דאף לדעה זו דוקא בשבנה הבית ואח\"כ הקיף וקמ\"ל דאע\"ג דלא פתח ליה אפ\"ה כיון שהיא סמוכה לעיר הרבה דעתיה עילויה להשתמש בה תדיר ומסתמא הוקפה לדירה:","(יח) וי\"ח בזה - ולדעה זו אפי' בסמוכה ממש לביתו כל שלא פתח ולבסוף הוקף לא מהני והסכימו האחרונים להלכה כדעה זו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ומה נקרא מוקף לדירה זה <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>שבנה בו בית <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>דירה או שפתח לו פתח מביתו ואח\"כ הקיפו <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ואם היה מוקף שלא לשם דירה א\"צ לפרוץ כולו אלא יפרוץ בו פרצה ביותר מעשרה ונמצא בית פתוח בו בלא היקף ויחזור ויגדור הפרצה כולו <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>או אמה היתיר' על עשר אמות והעשר אמות פתח הן והרי הוא פתוח ולבסוף הוקף <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>ואם פרץ אמה וגדרה וחזר ופרץ אמה אצל מה שגדר וחזר ועשה כן עד <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>שהשלימו לעשרה מותר: <small> (עיין ת\"ש): הגה ואם קשה עליו לפרוץ הכותל י\"א דיכול להניח עפר אצל הכותל משני צדדיה עד שיתמעט הכותל מגובה עשר ורוחב העפר רחב מעשר אמות באורך הכותל וארבע רוחב ואם <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>אין בגובה העפר <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>עשר א\"כ הוי כאלו פרץ שם הכותל שלא נשאר שם גבוה עשר למעלה מן העפר דהוי כקרקעות הקרפף ואף אם <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>חוזר ולוקח משם אח\"כ העפר הואיל ובטלו שם שבת אחת ויש חולקים דעפר לא הוי ביטול אא\"כ אין עתיד לפנותו לעולם (תה\"ד סי' ע\"ה הרא\"ש פ\"ק דסוכה):</small>","m":["(יט) ואח\"כ הקיפו - קאי גם אבנה בו בית דרישא וכלומר דבין שבנה בית באותו מקום ואח\"כ הקיפו לאותו מקום ונמצא הבית באמצעיתא ובין שבנה בית אצל אותו מקום ופתח לו פתח ואח\"כ הקיפו דבכ\"ז נחשב מוקף לשם דירה דלשם תשמיש דירה הקיפו אבל היכא דהקיפו מתחלה ואח\"כ בנה בו בית או אפילו בנה מתחלה ואח\"כ הקיף אחורי הבית אלא דלא היה פתח בבית לצאת משם למקום המוקף מיקרי הקיף שלא לשם דירה דמוכח דלא עשאו לתשמיש תדיר לבית. ודע דאם חשב בפירוש בשעה שהקיף למקום הזה שיבנה בו בית אח\"כ והקרפף הזה יהא כמו חצר או בשבית בנה מתחלה ואח\"כ הקיף בסוף הבית וחשב בשעת ההיקף שיפתח אח\"כ פתח בבית לאותו צד כדי שיכול להשתמש בהיקף לצרכי הבית אפשר שיש להקל ולומר דמיקרי מוקף לדירה שהרי הקיף אותו לשם דירה:","(כ) ואם היה מוקף וכו' - ורוצה להקיפו לשם דירה כצ\"ל וכן הוא במחבר שבעולת שבת וכן הוא בטור והכוונה שרוצה להשתמש עתה בהיקף הזה בקביעות אלא שאינו מועיל דבעינן שיהיו המחיצות עשויות לשם זה:","(כא) יפרוץ בו - ואינו צריך לפרוץ כל גובה הכותל עד למטה אלא כל שלא נשאר בגובה י' טפחים סגי דהפחות מי' טפחים בגובה לא מיקרי מחיצה:","(כב) ביותר מעשרה - ואם היה מכבר פרוץ עשרה דיו דיפרוץ מעט יותר וסגי:","(כג) ונמצא בית פתוח - דכיון דנפרץ כ\"כ נתבטלו כל המחיצות ואפילו זה שהוא עומד עדיין הרי הוא כאלו נסתר:","(כד) ויחזור ויגדור - לשם כוונת דירה:","(כה) הפרצה כולה - וה\"ה אם עושה צורת הפתח דשוב אינו פרצה:","(כו) או אמה היתירה - ואם לא פרץ אמה רק מעט צריך לגדור אותו מעט וסגי:","(כז) עד שהשלימו - ליותר מעשרה כצ\"ל:","(כח) מותר - ולא אמרינן כיון דלא פרץ עשרה בבת אחת ולא גדר בבת אחת לא הוי היקף לשם דירה אלא כיון דהשתא מיהא הוי החידוש של היקף ביותר מעשר חשיב היקף לשם דירה:","(כט) י\"א דיכול וכו' - ומיירי כשהכותל הוא פחות מעשרים טפחים בגובה דבכותל עשרים או יותר לא מהני האי תקנה וכמו שיתבאר לקמיה:","(ל) משני צדדים - כדי שיתבטל המחיצה שהרי יש דריסת הרגל מקרקע הקרפף לחוץ לקרפף:","(לא) עד שיתמעט וכו' - והוי כפרוץ במקום הזה וא\"כ יכול עתה לבנות שם בית דירה או לפתוח שם פתח מדירתו אם לא היה שם פתוח לקרפף מכבר ואח\"כ כשיפנה העפר דמי כמו הקיף אחר שפתח מתחלה:","(לב) רוחב - צ\"ל רוחב ד' והטעם דבפחות מארבעה אינו ראוי לעמוד עליו ולהתעכב:","(לג) באורך הכותל - צ\"ל באורך יותר מעשר דאז לא יחשב פתח אלא פרצה וכנ\"ל:","(לד) ואם אין בגובה - ר\"ל דכל תקנה זו אינו אלא בשכל גובה הכותל הוא פחות מעשרים טפחים דאז יכול לעשות תל משני צדדיו בגובה פחות מעשרה טפחים דבשיעור כזה אפשר עוד לדרוס ולהלוך עליו ומעתה צריך לחשוב גובה הכותל רק מתל ולמעלה דהתל חשיב כקרקעית הקרפף וכיון שלא נשאר בכותל מסוף התל ולמעלה עשרה טפחים הו\"ל כותל כפרוץ משני צדדיו שהרי אין בו עשרה לא מבחוץ ולא מבפנים:","(לה) ואף אם חוזר וכו' - הלשון מגומגם שהרי בע\"כ צריך ליטלו כדי שיוחזרו המחיצות למקומם [דאל\"כ אסור לטלטל בה ואפילו בפחות מבית סאתים] ועיין בא\"ר בשם מלבושי יו\"ט שכתב שצ\"ל ואף שחוזר וכו' ור\"ל ואף שחוזר ולוקח העפר כדי שיתגלו המחיצות מחדש לשם דירה מ\"מ לא אמרינן משום זה שהעפר לא נתבטל מעולם כלל משום שדעתו היה לחזור ולפנותם כיון דעכ\"פ ביטלם לשבת אחת:","(לו) הואיל ובטלו שם שבת אחת - היינו בפיו [הגר\"א בביאורו]:","(לז) דעפר לא הוי בטול - פי' באופן כזה שדעתו לפנותו:","(לח) אלא אם כן אין עתיד - וצריך לבטלו בפירוש לעולם ועיין באחרונים שדעתם להורות כסברא קמא להקל ועיין בביאור הלכה שהגר\"א חולק על עיקר דין זה ולפי המבואר בס\"ו יש עצה שלא יצטרך לפרוץ הכותל דהיינו שיעשה מחיצה שהיא גבוה י\"ט באורך יותר מעשר אמות ורחוקה ממנה ג\"ט אך כ\"ז אינו מועיל ג\"כ רק בעת שעומדת המחיצה אבל לא לאחר שנפלה דיחזור לאיסורו דהא הכותל הראשון לא הוקפה לדירה וכדלקמן סעיף י\"ד:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>תל גבוה עשרה דינו כקרפף:","m":["(לט) תל גבוה עשרה - טפחים ואפילו אינו זקוף בגובה הרבה אלא כל שמתלקט העשרה טפחים מתוך ד\"א הוי מחיצה גמורה:","(מ) דינו כקרפף - דעד סאתים מותר לטלטל בכולו דכאלו מוקף מחיצות דמי וביותר מסאתים אסור לטלטל דהוא מחיצה הנעשית מאליה ולא הוקף לשם דירה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>קרפף יותר מסאתים שנטע בו אילנות למעט אוירו <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>לא הוי <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>מיעוט <small> (אפילו יש בהן גבוה עשרה ורחב ארבעה) (המגיד פי\"ו) </small> והוא הדין לחופר בו בור:","m":["(מא) למעט אוירו - שלא יהיה שטחו יותר מסאתים ויהא מותר לטלטל בו:","(מב) לא הוי מיעוט - שדרך לעשות כן בקרפיפות ליהנות בהן ולישב תחתיהן בצל וא\"א למעט ולהכשיר אלא בדברים שאין דרך הקרפיפות בכך:","(מג) אפילו יש בהן גבוה עשרה וכו' - דחולקין בכל מקום רשות לעצמן ונעשו רה\"י אפ\"ה אינו ממעט כיון שהוא מתשמישי הקרפף:","(מד) לחופר בו בור - של מים ואפילו עמוק עשרה טפחים ורוחב ד' ואע\"ג דמקום חללו אינו מקום הילוך מ\"מ נמדד בשיעור סאתים דהוא נמי מתשמישי קרפף הוא כאילנות וכן אם עשה בור בגינה ג\"כ אינו ממעט דתשמיש הגינה הוא להשקותו ודבר אחר שאינו צורך הגינה ממעטו ופשוט דדבר המיטלטל אינו ממעט לעולם:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>בנה בו עמוד ונתמעט בכך אם הוא רחב ג' טפחים הוי מיעוט:","m":["(מה) עמוד - בין באמצע בין סמוך לכותלי הקרפף:","(מו) רחב ג' טפחים - וגבוה עשרה:","(מז) הוי מיעוט - אבל בפחות מעשרה ורוחב ג' לא חשיב והוי כמי שאינו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>בנה מחיצה באורך עשר לפני מחיצה הראשונה לבטלה שתהיה כמו שאינה <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>ויהיה מוקף לדירה על ידי השניי' אם הרחיקה מהראשונה שלשה טפחים מותר:","m":["(מח) באורך - יותר מעשר כצ\"ל ומיירי דגובהה היה ג\"כ עשר:","(מט) לפני מחיצה - לפנים בקרפף:","(נ) שתהיה כמו שאינה - והוי כאילו נפרץ במחיצה הישנה כל אורך הזה שמתבטל כל המחיצות בשביל פרצה זו כדלעיל בסעיף ב':","(נא) ויהיה מוקף לדירה - ומיירי שפתח לו פתח קודם שבנה מחיצה החדשה:","(נב) ג' טפחים מותר - דהו\"ל היקף חדש לשם דירה אבל אם קירב הכותל החדש בתוך ג' להכותל הישן לא מהני דתו לא נחשב ככותל חדש אלא כמו שמוסיף בבנין על כותל הראשון לשם דירה דלא מהני וכ\"ז בשלא נתמעט הקרפף משיעור יותר מבית סאתים ע\"י כותל החדש אבל אם נתמעט הקרפף משיעורו בודאי מותר אפילו קירב בתוך ג\"ט שהרי אפילו בטח טיט על הכותל מהני כמבואר בס\"ז:"]},{"s":"טח טיט על מחיצות הראשונות למעט אוירו ונתמעט אם הטיט עבה <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>שאם תנטל מחיצה הראשונה ראויה לעמוד בפני עצמה הוי מיעוט ואם לאו לא הוי מיעוט:","m":["(נג) למעט אוירו - שלא יהיה שטחו יותר מבית סאתים ויהא מותר לטלטל בו:","(נד) הוי מיעוט - ואפילו לא טח אלא באחד מכתלי הקרפף ואפילו במקצתו סגי ומ\"מ נראה שתהיה עכ\"פ גובה הטיח עשרה מקרקע ולמעלה ורחבה שלשה ואי לא\"ה לא חשיב וכההיא דעמוד בסעיף ה' ועיין בה\"ל:","(נה) לא הוי מיעוט - דכמי שאינה דמיא ויש חולקים ע\"ז דכל שיכולה לעמוד עם הכותל ממעט ויש להקל לעת הצורך וכ\"ז אם נתמעט השיעור עי\"ז מבפנים אבל אם לא נתמעט השיעור בודאי אסור ואפילו כיון בטיח הזה לשם דירה אף שעשהו עב כ\"כ שיכול לעמוד בפני עצמו דהוי כמחיצה ע\"ג מחיצה כמבואר בס\"ו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>בנה מחיצות על הראשונה להקיפו על ידם לדירה אינו מועיל <i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>ואם נבלעו התחתונות ונשארו העליונות מאליהם ניתר על ידם אבל תל יותר מסאתים ועשה מחיצות אפי' על שפתו לדירה מועיל שהרי דר באויר מחיצות שעשה עתה:","m":["(נו) אינו מועיל - דלא מהני ליה לקרפף ולא מידי שהרי בלא זה מוקף כבר:","(נז) ואם נבלעו התחתונות - שהיה העפר רך ותחוח ונחבט הכותל עד שלא נשאר בה עשרה טפחים בגובה:","(נח) ניתר על ידם - שהרי נעשו לשם דירה מתחילתן אלא שלא יכלו להתיר עד עתה שהיו שלא לצורך אבל עתה שבלא הם ליכא עשרה בגובה מחיצה הישנה שפיר מהני ליה לקרפף:","(נט) ועשה מחיצות - לדור ולהשתמש על התל:","(ס) אפי' על שפתו - ר\"ל דלא מיבעיא אם הרחיק משפת התל ג' טפחים דבודאי מועיל וכמבואר בס\"ו:","(סא) מועיל - ואע\"ג דבלא מחיצות אלו הרי יש בגובה התל עשרה ויותר והרי הוא מוקף מאליו אעפ\"כ שרי דכיון דאינו דר למטה בעמק אלא על התל בגובה למעלה הרי אדרבה מהני ליה רק מחיצות עליונות ותחתונות לא מהני ליה ולא מידי וכדמסיים שהרי דר וכו':","(סב) באויר מחיצות - ולא בעינן שיעשה כמה מחיצות אלא כיון שבנה מחיצה אחת לשם דירה סגי ושארי שלש מחיצות נחשב ע\"י התל גופא שהוא גבוה עשרה טפחים וכדלעיל בס\"ג ואפילו אותה מחיצה לא בעינן שיעשנה ע\"פ כל רוחב התל אלא כיון שעשאה באורך עשר ומעט יותר לשם דירה סגי וכדלעיל בסעיף וי\"ו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>קרפף יותר מסאתים שהוקף לדירה ונטע רובו אילנות אפילו אינם נטועים שורות שורות אינם מבטלים הדירה אבל אם נזרע רובו הזרעים מבטלים הדירה אפי' אין בהם <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>אלא <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"8\"></i>סאתים <i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i>נזרע מיעוטו <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>אם אין בו אלא סאתים מותר יותר מסאתים <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>אסור:","m":["(סג) ונטע רובו - ה\"ה כולו:","(סד) שורות שורות - אלא מעורבין:","(סה) אינם מבטלים הדירה - דעבידי אינשי לנטוע אילנות בחצירות כדי להסתופף בצלן:","(סו) הזרעים מבטלים הדירה - דבזרעונים לא דיירי אנשי והוי ליה גינה ואסור לטלטל אף בשאינו נזרע דבטל לה לגבי רובו וכזרע כולו דמיא:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i><i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>מי שיש לו <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>גנה בחצירו אם הוא רוב החצר אפילו אין בה אלא בית סאתים לא יטלטל <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>ממנו ומן החצר <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i><i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>לבית ואם הוא יותר מסאתים לא יטלטל בה ובחצר אלא בד' אמות ואם היא מיעוט החצר מה שיש בה יותר מסאתים <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>אוסר כל <i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i>החצר ואם יש בה סאתים או פחות <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>אסור להוציא <i data-commentator=\"Ba'er Hetev\" data-order=\"13\"></i><i data-commentator=\"Magen Avraham\" data-order=\"14\"></i>ממנה לבית:","m":["(סז) אפילו אין בהם וכו' - ר\"ל בשטח מקום הזריעה ובית סאתים אינו צריך להיקף דירה אפ\"ה אסור דכיון דמיעוט בטיל לגבי רוב הרי הוא כאלו כולו נזרע ובכולו הא איכא יותר מבית סאתים:","(סח) אלא סאתים - וה\"ה פחות כיון שהם הרוב וביחד עם המיעוט יש יותר מבית סאתים:","(סט) נזרע מיעוט - נראה דה\"ה מחצה על מחצה:","(ע) אם אין בו - ר\"ל במקום הזרוע:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"19\"></i>קרפף יותר מבית סאתים שהוקף לדירה ונכנסו בו מים <i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"20\"></i>אם ראוים לשתיה אין מבטלין הדירה אפילו אם המקום שנתפשטו שם יותר מסאתים ואפילו הם עמוקים הרבה ואם אינם ראוים לשתיה דינם כזרעים <i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"21\"></i>והוא שיהא בעמקם <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i>עשרה <i data-commentator=\"Ba'er Hetev\" data-order=\"14\"></i>טפחים:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ת\" data-order=\"22\"></i>קרפף בית שלשה סאין וקירה ממנה בית סאה מותר <i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"23\"></i><i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>אפילו אם הקירוי משופע:","m":["(עא) מותר - דאין כח במיעוט לבטל הרוב שהוקף לדירה והמיעוט עצמו ג\"כ מותר דלו יהא דלגבי דידיה נתבטל המחיצות שהוקפו לדירה ג\"כ לאו מידי הוא דהא בית סאתים לא צריך היקף לדירה:","(עב) יותר מסאתים אסור - לטלטל בכולו דהמיעוט אסור כיון שיש בו יותר מבית סאתים אינו ניתר בלא היקף לדירה וזרעים מבטלים מחיצה של דירה ורוב הקרפף ג\"כ נאסר מפני שהוא פתוח ופרוץ לזרעים שהוא מקום אסור:","(עג) מי שיש לו גינה וכו' - אף שכבר נתבאר כ\"ז בסעיף הקודם לענין קרפף מ\"מ חזר המחבר ושנה דין זה לענין חצר לאשמועינן דכשם שזרעים מבטלי מחיצות של קרפף שהוקפו לדירה כמו כן מבטלי מחיצות של חצר ולא אמרינן דחצר חשיבא טפי ולא מתבטל בשביל זרעים ועוד הוסיף לבאר בסעיף זה לענין טלטול מן החצר לבית וכמו שנבאר:","(עד) אפילו אין בה - ר\"ל בכל החצר:","(עה) אלא בית סאתים - וה\"ה פחות:","(עו) לא יטלטל וכו' - דבחצר בעצמו בודאי מותר לטלטל בכולו אפילו במקום הזרעים דאף שזרעים מבטל מחיצות של דירה בזה שאין בה אלא סאתים הרי לא בעינן היקף לדירה:","(עז) ממנה ומן החצר - דכיון דנתבטל היקף של דירה הרי כל החצר כקרפף דעלמא שאסור לטלטל ממנו לבית וכן מן הבית לתוכה ואפילו בקרפף פחות מבית סאתים ואפילו הן של אדם אחד:","(עח) ואם הוא יותר וכו' - ר\"ל כל החצר:","(עט) אלא בד\"א - כדין כרמלית כיון דבין כולה יש יותר מבית סאתים ורוב הזרעים ביטל שם דירה מחצר וכנ\"ל בס\"ט:","(פ) מה שיש וכו' - ר\"ל אם יש במקום הזרוע:","(פא) אוסר כל החצר - אף דחצר רוב לגבי גינה ולא נבטל ממנו שם דירה ע\"י הזרעים אבל עכ\"פ נבטל היקף דירה לגבי זרעים עצמם ואסור לטלטל שם כיון שהם יותר מבית סאתים ומשום זה אסור גם בשאר החצר דנפרץ הוא למקום הזרעים שהוא מקום אסור:","(פב) אסור להוציא וכו' - דבמקום הזרעים גופא מותר לטלטל וכמ\"ש בס\"ט אלא דעכ\"פ אסור להוציא ממנה לבית כדין קרפף שאין מוקף לדירה שאין מטלטלים ממנו לבית:","(פג) ממנה - ומשמע מזה דעכ\"פ מחלק החצר שרי לטלטל לבית אף כשיש שיעור בית סאתים כדין כל חצר שמוציאין ממנו לבית ויש אוסרים בזה להוציא אף מחצר לבית דאע\"ג דבחצר וגינה מותר לטלטל מ\"מ לענין כלי הבית מקרי גינה מקום האסור שהרי אסור להוציא ממנה לבית וממילא נאסר גם החצר לענין זה משום שהוא פרוץ ופתוח לגינה. והיכי שהזרעים פחות מן בית סאתים בודאי אין להחמיר לטלטל מן החצר לבית ויש מקילין בכגון זה לטלטל אף מן חלק הגינה גופא לבית וה\"ה מן הבית לגינה ויש לסמוך ע\"ז במקום הדחק. וכל המוזכר בכאן הוא בשאין מחיצה בין החצר למקום הזרעים ואם יש מחיצה אין חלק אחד שייך לחבירו כלל וא\"כ חלק החצר דינו כחצר ומותר לטלטל בכולו וממנו לבית ומקום הנזרע הוא נידון לעצמו ואם חלק הנזרע הוא יותר מבית סאתים דינו ככרמלית ואסור לטלטל אף בתוכו וכ\"ש להוציא ממנו לחצר או להיפך דחצר דינו כרה\"י גמור ואם הוא רק ב\"ס או פחות מותר לטלטל בכולו וכן ממנו לחצר ומחצר לו חוץ כלים ששבתו בבית אסור להוציא מן החצר לגינה ע\"כ ראוי שלא לאכול או לשתות בגינה בשבת דא\"א ליזהר בזה וכ\"ש באם הוא יותר מב\"ס דאסור בטלטול יותר מד\"א:","(פד) ונכנסו בו מים - ומיירי שהמים קוו וקיימי בתוך הקרפף:","(פה) אם ראויים לשתיה - ר\"ל לשתית אדם ויש מקילין אף בשראוים לכביסה וכדומה:","(פו) אין מבטלין הדירה - דאין לך דירה מעולה מזו:","(פז) יותר מסאתים - ולא אמרינן דבור גדול כהאי אין דרך לעשות דשפיר מצוי דאדם עושה בריכה גדולה של מים לתשמישו ומבואר בטור דלאו דוקא יותר מסאתים אלא אפילו נתמלא כל החצר נמי שרי:","(פח) ואם אינם ראוים לשתיה - ולאידך סברא דלעיל דוקא בשאינם ראוים לא לשתיה ולא לכביסה כגון שהיו עכורים מאד:","(פט) דינם כזרעים - משמע מלשון זה דהוא ממש כזרעים ולכן אם נתפשטו ברובו כולו אסור אפילו אין בהם סאתים ואם במיעוטו אם יש בהם יותר מב\"ס כולו אסור וכדלעיל בזרעים וכתבו האחרונים דכ\"ז דוקא כשאין עמוק י\"ט בשפתו וגם אין מתלקט י\"ט בתוך הילוך ד\"א דאם עמוק י\"ט בשפתו או עכ\"פ מתלקט י' בתוך הילוך ד\"א כותלי המים עצמן נעשו מחיצה בין מקום המים לשאר החצר ואין אסור אלא מקום המים עצמו ועיין בה\"ל:","(צ) והוא שיהא בעמקם י\"ט - דפחות מי\"ט הו\"ל כטיט ורפש בעלמא שאין חולקין רשות לעצמן:","(צא) מותר - שפי תקרה יורד וסותם והוי כאלו מחיצה מפסקת בין הסאה המקורה לבית סאתים שאינה מקורה ונמצא שאין שם אלא בית סאתים:","(צב) ואפילו אם הקירוי משופע - כעין גגין שלנו שפיה באלכסון וקמ\"ל שגם בפי תקרה כזו יורד וסותם ואף דלקמן בסימן שס\"א ס\"ב סתם המחבר דהיכא דפי התקרה בשיפוע לא אמרינן פי התקרה יורד וסותם חילקו האחרונים דשאני הכא דמן התורה רה\"י גמור הוא לכו\"ע שהרי מוקף ד' מחיצות אלא שחכמים גזרו בקרפף יותר מבית סאתים ולהכי הקילו בפי תקרה אף שפיה בשיפוע משא\"כ התם דנפרץ מחיצה לא אמרינן יורד וסותם אלא א\"כ פיה שוה:"]},{"s":"קרפף <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"24\"></i>בית סאתים מצומצם וחצר שנפרצו במילואה זה לזה <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"15\"></i>הקרפף אסור מפני שמקום המחיצה מייתרו ונעשה יותר על סאתים:","m":["(צג) מצומצם - ולא היה מוקף לדירה:","(צד) שנפרצו במילואה זה לזה וכו' - הלשון מגומגם דבאמת אם שניהם נפרצו במילואם גם החצר אסור שהרי הוא פתוח ופרוץ לקרפף שנאסר אלא מיירי שהיה החצר רחב מהקרפף ונשארו גפופים מהצדדין וע\"כ החצר מותר דלא נפרץ במילואו להקרפף וגם מיירי שפרצת החצר לא היה יותר מעשר אמות דביותר מעשר אפילו נשארו גפופין שניהם אסורין דשוב לא מיקרי פתח אלא פרצה:","(צה) שמקום המחיצה מייתרו - דאויר החצר אינו עושהו יותר על בית סאתים משום שהוא אויר המותר רק מקום שהיה המחיצה שאינו בכלל החצר נצטרף עתה עם הקרפף ועושהו יותר על בית סאתים:","(צו) ונעשה יותר על סאתים - ומיירי שכותלי הקרפף נכנסין בתוך חלל החצר מבפנים או שהיו כותלי החצר שבצד זה ובצד זה יתירים על רוחב הקרפף ד' אמות ואם לאו אין זה נקרא נפרץ במילואו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"25\"></i>קרפף יותר מבית סאתים שלא הוקף לדירה ופתח בו פתח ועשה מחיצה לפניו יותר מעשרה והותר ע\"י מחיצה שעל ידיה בטלה מחיצה ראשונה שלא היתה לשם דירה ואח\"כ נפלה מחיצה אחרונה חוזר לאיסורו:","m":["(צז) ופתח בו פתח וכו' - הלשון מגומגם קצת ובמקור הדברים מבואר ביותר שהסמיך ג' כתלים בסוף כותל ביתו וכותל ביתו היה הכותל הרביעי ובו עשה פתח וזהו שכתב המחבר ופתח בו פתח אלא שלא פתח הפתח רק אחר ההקפה של הכתלים דלא מהני כמבואר לעיל ולהכי עשה בקרפף מחיצה חדשה דהשתא הוי ההקפה לאחר הפתיחה ומבואר שם עוד דגם במחיצה החדשה עשה פתח כדי שיכול לילך ולהשתמש בפנים הקרפף וכן הוא גם כונת המחבר:","(צח) ועשה מחיצה לפניו - בפנים והרחיק לכה\"פ מכותל הבית ג' טפחים כדלעיל בסעיף ו':","(צט) יותר מעשרה - וכשיטת המחבר בסעיף ו' דמהני בשיעור זה ועיי\"ש מה שכתבנו בביאור הלכה:","(ק) ואח\"כ נפלה - וה\"ה אם הפילה בידים כדי לסמוך על המחיצה הראשונה ג\"כ לא מהני:","(קא) חוזר לאיסורו - ולא אמרינן כיון שהקרפף הותר פעם אחת אינו חוזר לאיסורו. כתבו הפוסקים דאם אחד מצדי הקרפף הוא כותל של בית והיה פתח ולבסוף הוקף ונפל הכותל אע\"ג דנשארו כותלי גוואי שבבית והם סותמים הקרפף אעפ\"כ נאסר הקרפף שהרי מחיצות הפנימיות לחדרים הפנימים נעשו ולא ליעשות כותל לקרפף ולא דמי למחיצות חיצוניות שלזה ולזה נעשו:\n"]}],"359":[{"s":"<b>דין רחבה שאחורי הבתים. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>רחבה שאחורי הבתים <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>יתירה על בית סאתים ולא הוקפה לדירה אין מטלטלין בה אלא בד' אמות ואם פתח לה פתח מביתו ואחר כך הקיפה <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אפילו אם יש גורן בינה לבית הוי היקף לדירה: <small>הגה ומה שאין אנו נזהרין לטלטל בחצירות שאחורי הבתים משום דבזמן הזה סתמן מוקפין לדירה כמו שנתבאר לעיל גבי קרפף: (ד\"ע)</small>","m":["(א) רחבה שאחורי הבתים - דרכן היה להניח שטח מקום פנוי לפני הבתים ואחורי הבתים אותו שלפני הבתים קרוי חצר ואותו שלאחורי הבתים קרוי בשם רחבה והיה דרכן להקיפן במחיצות והנה אותו חלק הקרוי בשם חצר בודאי הוקפה לדירה שדרך לעשות שם כל תשמישי הבית וע\"כ אפילו אם הוא יתר מבית סאתים ואפילו עשרה כורין מותר לטלטל בכולו ואף מהבית לתוכו [אם הוא דחד גברא או של שנים וערבו יחד] דרשות אחד הוא אכן רחבה מסתמא לא הוקפה לדירה שאין דרכן להשתמש שם תשמישי הבית כ\"כ וע\"כ דינו כקרפף לענין יתר מבית סאתים [קרפף הוא מה שעושין רחוק מהעיר מקום מוקף מחיצות להניח שם עצים וכה\"ג] ועתה נבאר דברי השו\"ע רחבה שאחורי וכו' והיינו שהקיף השטח הפנוי הזה בשלש מחיצות והסמיך אותם לכותל ביתו:","(ב) ולא הוקפה לדירה - שלא פתח בהכותל פתח להרחבה קודם שהקיפה:","(ג) אלא בד' אמות - כדין שאר קרפף שלא הוקף לדירה וכדעיל בסימן שנ\"ח ס\"א וכ\"ש שאסור לטלטל ממנה לבית אבל אם אין בהקיפה רק סאתים אין לה דין קרפף ומותר לטלטל ממנה אפילו לבית לפי שאינה רשות מחולקת מן הבית לגמרי כמו קרפף אע\"פ שלא הוקף לדירה:","(ד) אפילו אם יש גורן וכו' - ר\"ל אפילו אם היה גורן אחורי ביתו קודם שהוקף השלש מחיצות אין אומרים שבשביל הגורן נפתח פתח בכותל הבית ואין כאן פתח לרחבה אלא סתמא נפתח לרחבה והרי היא מוקף לדירה ומותר לטלטל בכולה ואפילו ממנה לביתו:","(ה) בחצרות שאחורי הבתים - היינו רחבה דלעיל:"]}],"360":[{"s":"<b>היקף מחיצות לשבת. ובו ג סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>יחיד ששבת בבקעה והקיף <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>מחיצות <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>גרועות כגון <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>שתי בלא ערב או ערב בלא שתי <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>עד סאתים מותר לטלטל בכולו מסאתים ואילך אין מטלטלין בו אלא בארבע <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>וכן הדין <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>אם הם <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>שנים ואם הם שלשה ישראלים חשובים כשיירא <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ומותר לטלטל בכולו אפילו הוא גדול הרבה <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ובלבד שלא יקיפו יותר מכדי צרכם שלא ישאר בית סאתים פנוי שאין צריכים לו לתשמיש אבל אם נשאר בית סאתים פנוי אין מטלטלין בכל המוקף אלא בד' אמות <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>במה דברים אמורים כשהקיפו יותר על שש סאין <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>אבל אם לא הקיפו יותר על שש <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>סאין אף על פי שיש סאתים פנוי כיון שהן שלשה מותר: <small>הגה עכו\"ם אינו מצטרף לשיירא וי\"א דה\"ה קטן אינו מצטרף. (רמב\"ם פרק י\"א):</small>","m":["(א) יחיד ששבת בבקעה - ה\"ה דאפילו במקום ישוב ג\"כ מותר עד סאתים וכדלקמן בסימן שס\"ב ס\"ה ונקט בקעה לאשמועינן דאפילו בבקעה שאין מצוי לו ממה לעשות מחיצות מעולות אפ\"ה החמירו רבנן ואסרו אם הוא מחזיק יותר מסאתים:","(ב) כגון שתי וכו' - היינו כגון שנעץ קנים בקרקע פחות פחות מג\"ט זה אצל זה ומ\"מ מיירי שתקועים בארץ בחוזק שלא ינידם הרוח דאל\"ה לא נחשב למחיצה כלל כמש\"כ בסימן שס\"ב ס\"א:","(ג) או ערב בלא שתי - כגון שהקיף כמה חבלים זה למעלה מזה ואין בין חבל לחבל ג\"ט ועיין בספר גאון יעקב שהביא משם הרשב\"א והריטב\"א דה\"ה בעומד מרובה על הפרוץ ג\"כ מחיצה גרועה מקרי כמו בשתי בלא ערב אבל שארי פוסקים לא הזכירו ד\"ז וכן בירושלמי לא משמע הכי ע\"ש:","(ד) עד סאתים - ועד בכלל אבל יותר מסאתים לא אפילו הוא צריך לתשמישיו:","(ה) מסאתים ואילך - ר\"ל שההיקף היה מחזיק יותר מב\"ס החמירו רבנן ואסרו לטלטל בו כמו בשאר כרמלית ומ\"מ לא נחשב ככרמלית גמור שיהא מותר להוציא ממנו לכרמלית אחר דבאמת רה\"י גמור הוא ע\"י לבוד אלא שהחמירו בו חז\"ל לכתחלה משום דהוי מחיצה גרועה. ובמחיצות גמורות מותר לטלטל בכולה אפילו היה מחזיק יותר מב\"ס הרבה דהוקפו לדירה שהרי הקיפם לדור בהם בשבת ואפילו הוא רק על שבת אחת [אחרונים]:","(ו) וכן הדין אם הם שנים - ר\"ל דגם בזה אין נותנים לשניהם ביחד רק עד בית סאתים:","(ז) בכל המוקף - דחשבינן לכל המחיצה כאילו אינה:","(ח) כשהקיפו יותר על שש וכו' - דשש סאין הוא לג' אנשים לכ\"א בית סאתים והם הקיפו יותר כגון שבע ולא הוצרכו אלא לחמש ונשאר סאתים פנוי וע\"כ אסור אבל אם לא הקיפו יותר על שש וכו' כיון דשש הוא השיעור לג' אנשים לכ\"א ב\"ס לא מחמרינן אפילו נשאר ב\"ס פנוי ועיין בט\"ז וא\"ר וכ\"כ בספר גאון יעקב שכל הראשונים חולקין ע\"ז ודעתם דאף בפחות משש כל שיש סאתים פנוי אסור:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>היו שלשה והקיפו כל צרכם ומת א' בשבת מותרים בכל השבת כיון שנכנס השבת בהיתר היו שנים והקיפו יותר מסאתים ונתוספו עליהם בשבת אסורים כיון שנכנס שבת באיסור:","m":["(ט) בכל השבת - ר\"ל דוקא לאותה שבת אבל לשבת אחרת אסור:","(י) אסורים - ר\"ל לאותה שבת הואיל ובתחלת כניסת השבת לא היו אלא שנים אבל לשבת אחרת מותר:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>היו ג' והקיפו כל אחד לעצמו זה בצד זה ועירבו יחד אם החיצונים רחבים והאמצעי קצר שנמצא האמצעי פרוץ במילואו לחיצונים והחיצונים שיש להם גפופים עודפים עליו מכל צד נותנים להם כל צרכם באמצעו אפילו אם הוא גדול הרבה שאנו רואים כאלו כולם דרים בתוכו והרי יש שלשה ביחד <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>ואף בחיצונים נותנים להם כל צרכם דכיון שנעשו שיירא באמצע הוי ליה אינך כחצר לאמצעי <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>ויש אומרים שהחיצונים אינם מותרים אלא עד סאתים ואם אחד מהם יותר מסאתים <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>גם האמצעי אסור שהרי הוא פרוץ במילואו ואם החיצונים פרוצים במילואם לאמצעי והאמצעי <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>מגופף ויחיד בכל אחד אין נותנין לכל אחד אלא בית סאתים ואם א' מהחיצונים יותר מבית סאתים הוא לבדו אסור ואם האמצעי יותר מבית סאתים גם החיצונים אסורים שהרי הם פרוצים למקום האסור להם <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>אבל אם א' בכל א' מהחיצונים ושנים באמצעי או שנים בכל א' מהחיצונים וא' באמצעי <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>נותנין לשנים <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>החיצונים כל צרכם דחשיבי כל מה שבאמצעי כאלו הוא בחיצונים <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>במה דברים אמורים כשאינם פתוחים זה לזה ביותר מעשרה דאם כן הוי ליה פירצה <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>וגם המגופפין אסורין <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>וכל זה בשכותלי קטנה נכנסין לגדולה וכשכותלי קטנה מופלגים ג' טפחים מכותלי אורך הגדולה דאז אוסרת הגדולה על הקטנה <small> (ועיין לעיל סימן שע\"ד סעיף ג') </small> דאם לא כן הוי ליה נראה מבחוץ ושוה מבפנים ונדון משום לחי וכולם חשובין מגופפין וכאלו אין א' מהם נפרץ לחבירו ואין נותנין להם באחד מהם אלא מבית סאתים:","m":["(יא) והקיפו כל אחד וכו' - פי' שהקיפו במחיצה גרועה שתי בלא ערב או ערב בלא שתי:","(יב) והאמצעי קצר - כזה:","(יג) גדול הרבה - יותר מבית סאתים:","(יד) שאנו רואים וכו' - שהרי אין מחיצה לחצוץ בינו לבינם כיון שנפרץ להם במילואו:","(טו) וי\"א וכו' - והלכה כדעה קמייתא ומ\"מ לכתחלה אין כדאי להקל:","(טז) אלא עד סאתים - שהרי הם אינם רשות אחד זה עם זה מפני גיפופיהם המפסיקים ביניהם להאמצעי:","(יז) גם האמצעי אסור וכו' - אבל החיצון השני שכנגדו שרי שהרי אינו פרוץ במלואו להאמצעי [אחרונים]:","(יח) פרוצים במילואם וכו' - כזה שהאמצעי רחב מן שתי החיצונים:","(יט) אלא בית סאתים - דהחיצונים אינם יכולים להצטרף עם האמצעי דנחשוב כאלו כולם דרים בו שהרי יש בו גיפופין המפסיקין ואינו פרוץ במילואו להם ואף שהוא יכול להצטרף עם כל אחד מהחיצונים מטעם שהם פרוצים לו במילואו ונחשב כאלו הוא דר ברשותם וכנ\"ל מ\"מ אין בכל אחד מהם אלא שנים:","(כ) הוא לבדו אסור - ולא האמצעי שהרי הוא מגופף ואינו פרוץ לו וכ\"ש החיצון השני שהוא רחוק ממנו:","(כא) דחשיבי וכו' - וכמו שביארנו הטעם לעיל בסקי\"ד:","(כב) כאלו הוא בחיצונים - ר\"ל עם כל אחד מהחיצונים אבל האמצעי אין נותנים לו רק בית סאתים וכל זה הוא רק לדעת הי\"א אבל לדעה הראשונה כשם שהחיצונים נעשים שם חצר לאמצעי כן בעניננו נעשה האמצעי כחצר לחיצונות ושרי גם בו כל צרכו:","(כג) הו\"ל פרצה וגם המגופפין וכו' - קאי אהא דאיתא לעיל כשהאמצעי מגופף והיה בחיצון יותר מסאתים דהוא נאסר והמגופף מותר וע\"ז קאמר דאם היה הפרצה יותר מעשר נתבטל שם המחיצה מהמגופף וממילא גם המגופף אסור. ועיין בה\"ל:","(כד) וכל זה כשכתלי וכו' - קאי אהא דכתב לעיל אבל אם אחד בכ\"א מהחיצונים וכו':","(כה) נכנסים לגדולה - וכמו שציירנו בתוך הציור:","(כו) מופלגים - ר\"ל שיש בין קצה כותלי הקטנה עד כותלי הגדולה ג\"ט:","(כז) דאז אוסרת הגדולה על הקטנה - תיבות אלו עד תיבות ס\"ג מוקף בתוך השו\"ע של עולת שבת ונכון הוא ומ\"מ בדוחק יש ליישב גם בלי היקף ור\"ל כמו דקי\"ל לקמן בסימן שע\"ד ס\"ג לענין חצר קטנה שנפרצה לגדולה דאימתי הגדולה אוסרת על הקטנה רק באופן זה כן הוא הדין בעניננו:","(כח) נראה מבחוץ ושוה מבפנים - היינו דכשעומד בתוך הגדולה נראה שנשארו קצת כותל בסוף הקטנה ואף דכשעומד בתוך הקטנה אין הגיפופים נראים מ\"מ הוי כאלו יש גיפופים גם להקטנה ואי אין בין כותלי הגדולה לבין כותלי הקטנה רק פחות מג\"ט אז אמרינן לבוד והרי הוא כסתום עד קצה כותלי הקטנה וא\"כ הרי גיפופים נראים מבחוץ ומהני אף לקטנה:","(כט) ונידון משום לחי - לחי אין שייך לעניננו אלא דר\"ל דכמו לענין לחי קיי\"ל דאף דשוה מבפנים כיון שנראה מבחוץ נידון משום לחי כן לעניננו אף דהעומד בתוך הקטנה נראה כפרוץ במילואו מ\"מ להעומד בתוך הגדולה נראה הגיפופין חשבינן אותם גם להקטנה:\n"]}],"361":[{"s":"<b>דין גג הסמוך לרשות הרבים. ובו ב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>גג הסמוך לרשות הרבים <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>בתוך י' טפחים <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>ולמעלה <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>מעשרה לחצר הואיל ורבים <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>משתמשין בו הרי זה כרה\"ר ואסור לבעל הגג להשתמש בו מחצירו עד שיעשה לו <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>סולם קבוע מחצירו <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>איזהו סולם קבוע כל שקבעו שם בין לחול בין לשבת:","m":["(א) בתוך עשרה טפחים - דהיינו שלצד ר\"ה אינו גבוה י\"ט ולצד החצר הוא גבוה י\"ט דאלו לא היה גבוה י\"ט אף לצד החצר לא היה מהני סולם כלל דהוי ר\"ה גמור כשרבים מכתפים עליו וכשאין מכתפים עליו הוי עכ\"פ כרמלית אבל השתא כיון דמצד החצר הוא גבוה י\"ט יש על הגג תורת רה\"י ומותר להשתמש עליו כשיש לו סולם קבוע לעלות בו מחצרו לגגו דבזה גלי דעתו דמסלק לגגו מן בני ר\"ה ואין שייך רק לו ואם מצד ר\"ה גבוה י\"ט א\"צ סולם. ואם הגג נמוך פחות מעשרה טפחים מכל צד ובתוכו עמוק י\"ט כגון שחקק הקרקע בתוכו והשלימו לי\"ט דעת המ\"א דא\"צ סולם דאין שם כרמלית עליו כלל דהוא רה\"י גמור ורבים מאחרונים חולקין עליו ודעתם דמדרבנן שם כרמלית ע\"ג מלמעלה כיון שהוא נמוך מי\"ט מכל צד וצריך סולם להתירו ובפרט כשרבים מכתפין עליו אפשר דהוא ר\"ה גמור עי\"ז ואפילו סולם לא מהני להתירו:","(ב) משתמשין בו - שמניחין כובעים וכלים קטנים על הגג:","(ג) הרי זה כר\"ה - לאו כר\"ה ממש דאי הכי לא היה מהני סולם אלא ר\"ל כעין ר\"ה:","(ד) מחצירו - אבל בגג מותר לטלטל בכולו:","(ה) כל שקבעו שם וכו' - היינו שעומד שם הסולם תמיד אבל אם לפעמים מסלק ליה הרי הוא כמאן דליתא:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>חצר שנפרצה במילואה או ביותר מי' לר\"ה מקום מחיצה נידון כצידי רשות הרבים שהוא כרמלית (כמו) שהוא החצר <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ואם נפרץ בקרן זויות אפילו <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>בפחות מי' אסור וכן בית שנפרץ בקרן זוית אפי' בפחות מי' ונפרץ גם הקירוי עד שישאר באלכסון אסור <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אבל פירצה שאינה בקרן זוית אמרינן בה פי תקרה יורד וסותם אפילו ביותר מי' <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>והוא שלא יהא פי תקרה משופע דליכא פה: <small>הגה וי\"א דבעינן ג\"כ <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>ברוחב הקירוי ארבעה טפחים (תוס' והרא\"ש פרק כיצד משתתפים וסמ\"ג וטור) ואמרי' פי תקרה יורד וסותם אפי' בב' מחיצות אם יש כאן ב' מחיצות שלימות דבוקות זו בזו אבל זו כנגד זו לא: (טור)</small>","m":["(ו) מקום מחיצה נידון כצידי ר\"ה - צידי ר\"ה בעלמא נקרא כשמעמידין אבנים גדולות או שנועצין יתדות סמוך לכותל שלא יזיקוהו קרונות וההוא אויר שביניהם נקרא צידי ר\"ה ודינו ככרמלית ואסור לטלטל מתוכו לר\"ה וקמ\"ל דאף בעניננו אף דליכא שום הפסק בין החצר לר\"ה ועיילי ביה רבים להדיא ודרסי ליה אפ\"ה אין דינו רק כצידי ר\"ה ושם כרמלית עליה ואסור לטלטל ממקום זה לחוץ שהוא ר\"ה ואם כרמלית סמוך לחצר מותר דמכרמלית לכרמלית קמטלטל. ובר\"ה שלנו יש להחמיר:","(ז) כמו שהוא החצר - ר\"ל כמו שהחצר גופא שם כרמלית עליה מחמת שהוא פרוץ ברוח רביעית כן הוא ג\"כ מקום המחיצה ונמצינו למידין מלשון זה שני דברים אחד דבחצר זה אסור לטלטל כ\"א בתוך ד\"א שנית דממקום המחיצה לתוך החצר מותר לטלטל בתוך ד\"א דתרוייהו שם כרמלית עלה וכדלעיל בסימן שמ\"ו ס\"ב וג':","(ח) ואם נפרץ בקרן זוית - ר\"ל שהפרצה אכלה בשתי הכתלים של החצר בסופן זה אצל זה. ומשמע בגמרא דאם הפרצה נעשה בשאר מקומות של הכתלים אפילו היו בשתי כתלים כל שאין בכל פרצה יותר מעשר אמות שרי וע\"ש בתוספות דדוקא אם היה העומד מרובה על הפרוץ הא לא\"ה אסור כשהפרצה הוא בשתי כתלים וכ\"כ הרשב\"א בעבודת הקודש:","(ט) בפחות מעשרה וכו' - דלא נוכל לכנות הפרצה ההיא בשם פתח דפתחא בקרן זוית לא עבדי אינשי ודוקא לענין פרצה אמרינן כן אבל אם עשה צורת פתח וכ\"ש אם עשה שתי מזוזות ומשקוף ממש בודאי שם פתח עליה ושרי:","(י) אסור - ומסתברא דאם היה הפרצה פחות מאמה אין להחמיר [פמ\"ג] אכן בעה\"ק להרשב\"א מצאתי דמשלשה טפחים ועד ארבעה צריכה שני לחיים ואם היה ארבעה אין לה הכשר עד שימעטנה מארבע וכו' ע\"ש:","(יא) וכן בית וכו' - כלומר דלא תימא שאני בית דאע\"פ דאין להתיר מחמת פתח מפני שהוא בקרן זוית מ\"מ איכא משום פי תקרה שעל גבו יורד וסותם קמ\"ל דפעמים ליכא משום פי תקרה ומפרש היכי דמי:","(יב) עד שנשאר באלכסון אסור - דבזה שאין הקירוי שוה לא אמרינן פי תקרה יורד וסותם:","(יג) אפילו ביותר מעשרה - ואפילו אם היה זה ג\"כ במלוא כל הכותל שלא נשארו גיפופין כלל והנה בדברי המחבר לא נתבאר אם דוקא בדופן אחד כשהוא פרוץ אמרינן פי תקרה יורד וסותם או אפילו בשתי דפנות משום דלא פסיקא ליה ד\"ז כדמשמע בב\"י אכן הרמ\"א בהגהתו העתיק לדינא דברי הטור דסתם כשיטת הפוסקים דס\"ל דאפילו פרוץ שתי מחיצות אמרינן פי תקרה יורד וסותם וכדלקמיה:","(יד) שלא וכו' משופע - ר\"ל דלא אמרינן דיורד וסותם רק כשהתקרה חלק אבל לא כשהוא משופע כעין גגין שלנו שעומדים בשיפוע אם לא היה תקרה תחתיה:","(טו) וי\"א וכו' - וכן הלכה כמו שכתבתי בבה\"ל:","(טז) דבעינן וכו' ארבעה טפחים - ר\"ל דאז אמרינן פי תקרה יורד וסותם ולא דמי לקורת מבוי בעלמא דסגי בטפח דקורת מבוי אינו אלא להכירא בעלמא אבל כל היכי דבעינן מחיצה אז צריך שיהא בה דוקא ד' טפחים ואז אמרינן פ\"ת יורד וסותם:","(יז) אם יש כאן ב' מחיצות שלימות - פי' והמחיצות הנסתרים נשאר עליהם הקירוי שלא נסתר עמהם:","(יח) זו כנגד זו לא - דאז הלא נראה מפולש ואין פי תקרה מועיל לזה:"]}],"362":[{"s":"<b>איזה מחיצה קרויה מחיצה לטלטל. ובו יב סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>כל מחיצה שלא נעשית לדור בתוכה אלא לצניעות או לשמור מה שיתנו בתוכה <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>או לישב בה כדי <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>לשמור השדות היא מחיצה <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>לטלטל מה שבתוכה אבל אינה מחיצה לעשות מה שבתוכה מוקף לדירה אם הוא יותר מב' סאתים <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>הילכך אילן שענפיו יורדין למטה אם אינם גבוהים שלשה מן הארץ <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>ועיקרן במקום שמחוברים לאילן הוא גבוה עשרה חשיב מחיצה ומותר לטלטל בכולו <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>והוא שימלא האויר שבין הענפים בעצים או בקש ויקשור הענפים שלא ינידם הרוח שכל מחיצה שאינה יכולה לעמוד ברוח מצויה אינה מחיצה <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ודוקא עד בית סאתים אבל יותר מבית סאתים לא <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אפי' נטעו לכך כיון <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>שאינו עשוי לדור בתוכו אלא להסתופף בצלו לשמור השדות:","m":["(א) אלא לצניעות - כגון מחיצה שעושין לנוח שם לשעה חוצב אבנים והבנאים ושאוכלין ועומדים שם לשעה בהצנע דאין זה מחיצת דירה אלא מחיצת הצניעות:","(ב) או לשמור מה שבתוכה - שעשויה להניח שם פירות וכלים וכיוצא בהן ועיין בה\"ל:","(ג) היא מחיצה לטלטל וכו' - ר\"ל שע\"י היקף המחיצה מותר לטלטל בכל תוך שטח המחיצה אם איננה יותר מב\"ס ומש\"כ הלכך אילן וכו' כונתו על מה שסיים לבסוף אבל יותר מבית סאתים וכו':","(ד) אינם גבוהים שלשה וכו' - דהוי כלבוד לארץ:","(ה) הוא גבוה וכו' - וה\"ה אם אין גבוהין עשרה טפחים במקום שמחוברין לאילן אלא שבאמצע גבוהין י\"ט שעשויה כקשת אך בין כך ובין כך צ\"ל ג\"כ רחב ד\"ט במקום שגבוהין י\"ט דאם הוא רחב ד\"ט רק במקום נמוך מזה הו\"ל כרמלית:","(ו) ומותר לטלטל בכולו - היינו אפילו במקום שאין גבוה י' טפחים דהו\"ל חורי רה\"י וכרה\"י דמי וכנ\"ל בסי' שמ\"ה ס\"ד:","(ז) והוא שימלא וכו' - היינו דע\"י המילוי מתחזק המחיצה שלא תתנדנד ע\"י הרוח ואפ\"ה בעינן ג\"כ קשירת הענפים בארץ בשביל זה:","(ח) אבל יותר וכו' - כגון שהיה ענפיו ארוכין מאוד או שהיו הרבה אילנות סמוכין זה לזה:","(ט) אפילו נטעו לכך - להסתופף בצלו:","(י) שאינו עשוי לדור - ואם מילא הקש לשם דירה ממש אפילו לא נטע האילן לכך אם רוב הדופן מן הקש הוי מוקף לדירה [מ\"א וש\"א ועיין בתו\"ש]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>תל שגבוה חמשה והשלימו לעשרה שעשה עליו מחיצה גבוה חמשה חשיבה מחיצה לטלטל ולכל דבר:","m":["(יא) תל שגבוה חמשה - טפחים מן הארץ וה\"ה חריץ שעמוק ה' טפחים ועשה על שפת החריץ מחיצה גובה חמשה מצטרפין להחשב מחיצה של עשרה טפחים:","(יב) שעשה עליו - היינו על שפת התל:","(יג) חשיבה מחיצה - שמצטרף גובה התל להמחיצה להשלים העשרה טפחים:","(יד) לטלטל - דתוך המחיצות מחשב כרה\"י גמור שיהא מותר לטלטל בתוכה:","(טו) ולכל דבר - היינו גם לענין הפסק שני חצירות כמבואר לקמן סימן שע\"ב סעיף ו':"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>מחיצה העומדת מאליה דהיינו שלא נעשית לשם מחיצה כשירה <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i><i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>מחיצה שנעשית בשבת כשרה והני מילי שנעשית בשבת <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>בשוגג אבל במזיד הויא מחיצה להחמיר לחייב הזורק מרשות הרבים לתוכה אבל לא להתיר לטלטל בתוכה <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>והני מילי שלא היה שם מחיצה תחלה אבל היתה שם והסירה וחזרה ונעשית אפי' במזיד חזרה להתירה הראשון כגון שנים או שלשה שהקיפו במחצלאות סביבותיהם ברשות הרבים והבדילו גם ביניהם במחצלאות ועירבו יחד מותרים לטלטל מזה לזה נגללו המחצלאות נאסרו חזרו ונתפרשו אפי' במזיד חזרו להתירן הראשון:","m":["(טז) כשירה - ואפילו לא סמכו עליה מע\"ש:","(יז) בשבת כשרה - ואפילו לא נעשית ג\"כ לשם מחיצה [גמרא]:","(יח) בשוגג - היינו שלא ידע שהיום שבת או שהיה שגגת מלאכה. ואם צוה ראובן לשמעון לעשות מחיצה כדי לטלטל בה או שידע ששמעון עושה בשבילו והיה ניחא ליה שתעשה כדי שיוכל לטלטל בה משמע מלשון הרמב\"ם דשוב אסור לראובן לטלטל בה אף ששמעון עשאה בשגגה דלדידיה נחשב כמזיד:","(יט) אבל לא להתיר וכו' - משום קנס ואסור גם לכל אדם לטלטל ע\"י זו המחיצה באותו שבת:","(כ) שלא היתה שם וכו' - וה\"ה כשהיתה ונסתרה קודם שבת [מ\"א ותו\"ש]:","(כא) והסירה - לרבותא נקט וכ\"ש כשהוסרה ממילא:","(כב) כגון שנים וכו' - היה יכול לצייר בפשיטות באיש אחד שהיה לו מחיצה גמורה שעל ידה היה המקום רה\"י והסירה בשבת וחזרה ועשאה אלא בא לאשמועינן בשנים ושלשה אנשים דאפילו העירוב שביניהן לא נתבטל ומותרין לטלטל מזה לזה כשחזרו ונפרסו המחצלאות:","(כג) שהקיפו במחצלאות - ר\"ל בחול ותקנו אותם באופן שלא ינידם הרוח כנ\"ל בס\"א ועי\"ז נעשית שם רה\"י:","(כד) ועירבו יחד - דאף שהמחצלת מפסיק ביניהם אפ\"ה כיון שיכולין להשתמש זה עם זה דרך המחצלת דינו כאלו יש כותל ופתח או חלון ביניהם שהרשות בידן לערב יחד [הרא\"ש]:","(כה) נגללו המחצלאות - שסביבותיהן ונתבטלו המחיצות:","(כו) אפילו במזיד וכו' - ודעת רוב הפוסקים דבמחיצה שנעשה על ידה בשבת רה\"י לא אמרינן דחזר להתירו הראשון כשנעשה במזיד רק אם בלא\"ה היה אותו המקום רה\"י שהיה מוקף מחיצות ועשה מחיצה באמצע שעל ידה נתחלקו הדיורין וערבו כ\"א בפני עצמה וכשנפלה אותה מחיצה נאסרו לטלטל מפני שאוסרין זה על זה אז אם חזר ועשאה אפילו במזיד אף דבעשיתו עבר על איסור תורה מ\"מ חזר להתירו הראשון כיון שבלא\"ה הוא ג\"כ רה\"י ואינה באה רק לחלק הדיורין וגם בזה דוקא כשכבר היתה שם המחיצה אלא שנפלה אבל אם לא היתה שם מחיצה ועשאה בשבת אף שהוא רק לחלק דיורין אסור:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>ספינה מותר לטלטל בכולה אפילו היא יותר מבית סאתים דחשיב' מוקפת לדירה <small> (וע\"ל סי' שס\"ו וסוף סימן שפ\"ב) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>כפאה לדור תחתיה הוי רה\"י <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>אף עליה כפאה לזופתה <i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i><i data-commentator=\"Magen Avraham\" data-order=\"7\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>אין מטלטלין בה אלא בד' אמות אם היא יותר מסאתים:","m":["(כז) וע\"ל סימן שס\"ו - סעיף ב' בהג\"ה:","(כח) אף עליה - דאמרינן גוד אסיק מחיצתא ואפילו היא יותר מבית סאתים ג\"כ מותר לטלטל שם דכיון דלמטה מוקף לדירה חשבינן כאלו למעלה ג\"כ מוקף לדירה:","(כט) אלא בד' אמות - דבזה שכפאה לזופתה ביטל מחיצותיה מתורת דירה ולכן אף תחתיה אין מטלטלין בה אלא בד\"א כיון שהיא יותר מב\"ס וכ\"ש למעלה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>בכל עושים מחיצה בכלים ובאוכפות בין <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>של ערב לבד כגון של חבלים או של שתי לבד כגון קנים נעוצים בארץ ומותרים עד סאתים אפי' ליחיד בישוב ובלבד שלא יהא בין חבל לחבירו ובין קנה לחבירו ג\"ט <i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i>ואפי' בבעלי חיים ובלבד <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>שיהו <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i>כפותים <i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"19\"></i>ואפי' באנשים שעומדים זה אצל זה <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>בפחות מג' <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"20\"></i>ואפי' כשהם <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>מהלכים חשובים מחיצה וביניהם רה\"י <i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"21\"></i><i data-commentator=\"Magen Avraham\" data-order=\"11\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>והוא שלא ידעו שהועמדו לשם מחיצה ואפילו <i data-commentator=\"Be'er HaGolah\" data-label=\"ת\" data-order=\"22\"></i>אחד מהם יודע אסור ואפי' אם לא הודיעם שעושה מחיצות עתה <i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"23\"></i>אם קרוב הדבר שידעו כגון שעשה מהם מחיצה פעם אחת <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>לא יעשה מהם <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>מחיצה <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>עוד:","m":["(ל) בכלים ובאוכפות - אף שהם עתידים לינטל אחר השבת:","(לא) כגון של חבלים - המתוחים על יתדות התקועות בארץ:","(לב) עד סאתים - ולא יותר אפילו אם הקיף לדור ולהשתמש שם כיון שהיא מחיצה גרועה שתי בלא ערב וערב בלא שתי ועיין לעיל סימן ש\"ס בבה\"ל:","(לג) אפילו ליחיד בישוב - ר\"ל אף שבישוב יכול להשיג ממה לעשות מחיצה טובה אפ\"ה מקילינן בה עד ב\"ס וכ\"ש כשהוא בבקעה:","(לד) ובלבד שלא יהא בין חבל וכו' - ולפ\"ז יכול לעשות מחיצה של עשרה טפחים בארבעה חבלים ואם בשלשה חבלים מחזיק עוביין יותר מטפח יכול לעשות מחיצה ע\"י ג' חבלים כגון שמניח חבל התחתון בפחות משלשה סמוך לארץ וכן ממנו לחבל השני וכן ממנו להשלישי ובצירוף עוביין יהיה עשרה טפחים [ש\"ס]:","(לה) ובין קנה לחבירו וכו' - ולא אמרינן בזה שפרוץ מרובה על העומד דלבוד כסתום דמיא:","(לו) ובלבד שיהו כפותים - היינו שהוא כופתה מבע\"י ומניחה ואז מותר לטלטל עי\"ז בשבת והטעם דבעינן כפיתה אחד שלא יברחו וגם דאל\"ה יהיה הפסק בין חלל שבין רגלי הבהמה להארץ אבל כשהיא כפותה שוכבת בגופה על הקרקע ומיירי שיש עשרה טפחים בגובה אף כשהיא שוכבת:","(לז) בפחות משלשה - עיין בבה\"ל:","(לח) חשובים מחיצה וביניהם רה\"י - וכגון שהיו מוקפים מארבעה רוחות ומחיצה גמורה היא ומועלת אפילו בר\"ה ועיין לקמן ס\"ז בהג\"ה. וה\"ה דמחיצה כזו הוי הפסק לענין לדבר ד\"ת נגד מקום שאינו נקי [אחרונים]:","(לט) והוא שלא ידעו וכו' - אף דבמחיצה כזו אין בה משום בנין בשבת מ\"מ אסור כשידעו כדי שלא יבואו לזלזל באיסור שבת. ואפילו בדיעבד אסור ודינו כמחיצה הנעשית במזיד בס\"ג:","(מ) לא יעשה מהם - ואם אדם אחר רשאי לעשות מהם מחיצה הוי ספק דשמא ירגישו בזה [מ\"א בשם הב\"י] ובא\"ר מיקל בזה:","(מא) מחיצה עוד - ואפילו בשבת אחרת דמאחר שקרוב שירגישו הו\"ל כמעמיד מתחלה לדעת ולא דמי לסעיף ו' דהתם מתחלה לא היה לו לחוש שידע ואפילו בפעם הראשון אם לא היה לו אנשים כדי צרכו והעמידן במקום אחד ואח\"כ אמר להם שילכו והוא הולך ביניהם אסור שקרוב הדבר שירגישו ומה דאמרינן דגם כשהם מהלכין מותר הוא כשמהלכין מעצמן או שיש סיעה גדולה של אנשים שהולכין ואין ניכר מה שהוא הולך ביניהם:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"24\"></i>אם באו מתחילה שלא לדעת אע\"פ שאחר כך הרגישו אין לחוש:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"25\"></i>יש מי שאומר <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i>שלא יעמיד אותם אדם שהוא רוצה להשתמש במחיצה זו אלא יעמיד אותם אחר שלא לדעתו: <small>הגה ואין לעשות מחיצה של בני אדם רק בשעת הצורך ובשעת הדחק ואם שכח דבר אחד ברשות הרבים יותר עדיף להוליך שם <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i>תינוקות שיביאו הדבר בלא מחיצה מלעשות מחיצה של בני אדם ושיביאנו גדול (ב\"י בשם שבולי הלקט וסמ\"ג וס\"ה):</small>","m":["(מב) שלא יעמיד אותם וכו' - שכשם שצריך שלא ידעו האנשים שמעמידים אותם למחיצה כך צריך שלא ידע האיש שמעמידים בשבילו בשעה שמעמידים אותם אבל לאחר שכבר הועמדו לכו\"ע לא איכפת כלל במה שידע וכדלעיל בס\"ו:","(מג) אלא יעמיד אותם אחר - והרשב\"א חולק ע\"ז ודעתו שגם הוא בעצמו מותר להעמידם ואין קפידא רק על האנשים בעצמן שעומדין למחיצה שלא ידעו שהועמדו לזה ועיין בא\"ר שכתב שכן הוא ג\"כ משמעות שארי פוסקים וכן עיקר:","(מד) להוליך שם תינוקות - והוא שאין התינוק יודע שחפץ זה הוא של אביו ולהנאת עצמו הוא מתכוין בהבאתו אותו שסבור שמצא חפץ בר\"ה אבל אם יודע שחפץ זה הוא של אביו הרי הוא מתכוין מן הסתם בהבאתו בשביל אביו וצריך כל אדם למחות בתינוק זה שלא יביאנו וכ\"ש שלא יוליכנו שמה כדי שיביאנו וה\"ה אם החפץ הוא של אדם אחר והתינוק יודעו ומכירו ויביאנו אליו וכ\"ז באחרים אבל אביו מצווה לחנכו ולגעור בו ולהפרישו כשרואהו מחלל שבת אפי' להנאת עצמו ואפילו באיסורי ד\"ס כמ\"ש בסימן שמ\"ג וכ\"ש שלא יוליכנו שמה כדי שיביאנו אפילו אין החפץ שלו [אחרונים]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"26\"></i>פרוץ מרובה על העומד אסור <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"27\"></i>אלא אם כן כל פרצה מהם פחותה מג' טפחים:","m":["(מה) מרובה - אפי' שתי מחיצות שלמות [וגם הדופן שבה הלחי או הצוה\"פ עשויה כדין] ובמחיצה השלישית היה הפרוץ מרובה נחשב אותה המחיצה כמאן דליתיה ואפילו כנגד העומד נחשב כפרוץ ונמצא שאין לו בס\"ה כ\"א ג' מחיצות אבל כשעומד מרובה מותר וי\"א שאפילו העומד אינו מרובה מצ\"א רק משני הצדדים מצטרפים אהדדי ומתבטל הפרוץ לגביה ואפילו אם העומד גופא שבשני הצדדים אינו במילואו אלא יש בכל אחד ג\"כ פרצה אלא שהעומד רבה עליו נחשב עי\"ז כאלו כולו עומד ומתבטל הפרוץ שבאמצע כגון שהיה שטח הרוח רוחב חמשה עשר אמה ונשאר בקצה הכותל אמה ונפרץ אמה ונשאר עומד שני אמות ואצלו פרצה גדולה של שבעה אמות ואצלו עומד שני אמות ועוד פרצה אמה ועוד פס אמה בקצה השני של הכותל נחשב זה כאלו עומד מרובה על הפרוץ:","(מו) פחותה וכו' - דהוי לבוד וכעומד דמי וע\"כ אפילו אם בלא זה היה שם פרצה גדולה כגון שמחזיק שטח אותו הרוח י\"א אמה והיה שם פרצה של חמשה אמות במקום אחד ובששה אמות הנותרים היה בכולן פרצות קטנות של פחות פחות מג\"ט חשבינן אותן הפרצות כאלו הן סתומות ונמצא שהעומד מרובה:","(מז) משלשה טפחים - ואף דבפרוץ כעומד מבואר בס\"ט דעד עשר אמות נחשב לפתח בפרוץ מרובה אפילו ע\"י פרצות של ג\"ט ג\"כ אסור משום דהעומד מתבטל לגביה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"28\"></i>פרוץ כעומד מותר <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i>בין בשתי בין בערב <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"29\"></i>ובלבד שלא יהא במקום א' פרוץ יותר מעשר אבל עד עשר אמות מותר מפני שהיא כפתח:","m":["(מח) פרוץ כעומד מותר - דלא צריך שיהא העומד מרובה על הפרוץ אפילו אם שוין הם ג\"כ מותר כיון שאין הפרוץ מרובה ואפילו כנגד הפרוץ מותר לטלטל דיש ע\"ז דין מחיצה שלמה:","(מט) בין בשתי - שעומד ע\"ג קרקע בגובה ויש חללים רחבים בתוך המחיצה עד שהפרוץ הוא שוה לעומד:","(נ) בין בערב - דע דכל מחיצה צריך שלא יהיה בתחתיתו חלל שלשה טפחים [דאם היה בו חלל ג\"ט אפילו למעלה עשה השבעה טפחים בלא שום חלל דנמצא שהעומד מרובה על הפרוץ או שהיה למעלה עשרה טפחים שלמים ג\"כ לא מהני דהו\"ל מחיצה שהגדיים בוקעין תחתיה] וכן אם המחיצה היה למטה גובה ששה טפחים והרחיק שלשה טפחים שלמים והעמיד למעלה עוד פס והשלימו לעשרה טפחים ג\"כ לא מהני אף שהעומד מרובה על הפרוץ דאתי אויר של חלל ג\"ט שתחת הפס ואויר שלמעלה מן הפס עד לרקיע ומבטלי ליה להפס שבאמצע וכן אם עשה למטה בתחתיתו ג\"ט וכן למעלה ג\"ט ובאמצע נשאר רוחב ד\"ט חלל אף שבס\"ה יש עומד של ששה טפחים ומרובה הוא על החלל שבינתים לא הוי מחיצה דאתי אוירא דלמעלה והאויר ד\"ט שבאמצע ומבטלי ליה להשלשה טפחים אבל אם עשה למעלה ארבעה טפחים ובתחתיתו שלשה טפחים ובאמצע נשאר ג\"ט חלל בזה לא אמרינן דהאוירין מבטלי ליה להארבעה טפחים עומד שלמעלה שאחרי שהוא מרובה על האויר שתחתיו אין יכול האויר לבטלו דאדרבה האויר בטיל לגביה וכאלו סתום כולו דמיא והנה בזה הציור שציירנו העומד מרובה על הפרוץ ופרוץ כעומד לא משכחת לה בערב כמו שכתבנו בבה\"ל והנה לשון זה של המחבר הוא נובע מלשון הטור ונראה דהטור לאו דוקא נקט פרוץ כעומד לענין ערב ומשום שתי נקטיה ותדע דבפסקי הרא\"ש לא כתב שם רק דעומד מרובה על הפרוץ מתיר בערב ועיין בבה\"ל:","(נא) שלא יהא וכו' - דעי\"ז נחשב כל הכותל כאלו אינו ואפילו העומד מרובה על הפרוץ:","(נב) אבל עד עשר - ועד בכלל:","(נג) אפילו וכו' - דשוב אין נחשב המקום ההוא לפרצה:","(נד) מותר - ואפילו כשכל הארבעה רוחות היה בהן פרצות כאלו:","(נה) ע\"ג מותר - לטלטל בתוכן דכדפנות שיש בהן פתחים חשיבי:","(נו) והנ\"מ בחצר וכו' - ר\"ל שנפלו כותליה ועשה שם קונדסין בצורת פתחים ומפני שיש בהם דיורין דרך להיות שם פתחים הרבה לכך התירו:","(נז) ע\"י צורת הפתח - לאפוקי אם היה ההיקף כתיקונו אלא שיש בה פרצות יותר מעשר מהני צורת הפתח אפילו בבקעה בארבעה רוחותיה אפילו אם היה הפרוץ מרובה על העומד:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"30\"></i>אם עשה צורת פתח אפי' לפירצה יתירה מעשר מותר <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"31\"></i>ואפי' לא נעץ אלא ארבע קונדיסין בארבע רוחות ועשה צורת פתח על גביהן מותר <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"32\"></i>והני מילי בחצר ומבוי שיש בהם דיורין אבל בבקעה לא מהני בשכל הרוחות על ידי צורת פתח <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"33\"></i><i data-commentator=\"Magen Avraham\" data-order=\"17\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>ולהרמב\"ם אין צורת הפתח מועיל לפרצה יותר מעשר אלא אם כן עומד מרובה על הפרוץ <small> (אז מהני אפי' בבקעה בכל הרוחות) (ב\"י בשם סמ\"ג וסמ\"ק):</small>","m":["(נח) לפרצה יותר מעשר - אבל בעשר מועיל אפילו פרוץ מרובה על העומד ואפילו בבקעה ואפילו כל הד' רוחות ע\"י צורת הפתח ופעמים מועיל אפילו בפרצה יותר מעשר כגון ברוח שלישי של מבוי מהני צורת הפתח ואפילו לדופן כולו כשהוא מפולש כיון ששתי דפנות שלימות וכדלקמן בסימן שס\"ד ס\"א:","(נט) אא\"כ עומד וכו' - ונכון לחוש לדברי הרמב\"ם שגם דעת הסמ\"ג והסמ\"ק הוא כן:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"34\"></i>מהו צורת פתח <i data-commentator=\"Magen Avraham\" data-order=\"18\"></i>קנה מכאן <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>וקנה מכאן וקנה על גביהן <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"35\"></i>אפי' אינו נוגע בהן אלא שיש ביניהם כמה אמות ובלבד שיהא גובה הקנים שמכאן ומכאן י\"ט <i data-commentator=\"Magen Avraham\" data-order=\"19\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"36\"></i>ויהיו <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>מכוונים כנגד קנה <i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"37\"></i>העליון ואם חיבר הקנה העליון לשני הקנים או לא' מהן <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i><i data-commentator=\"Magen Avraham\" data-order=\"20\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>מן הצד לא מהני <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"38\"></i>וצריך שיהיו הקנים שבצדדים חזקים לקבל דלת כל שהוא אפילו של קש או של קנים <i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"39\"></i>אבל קנה שעל גביהן סגי בכל שהוא <i data-commentator=\"Magen Avraham\" data-order=\"21\"></i>ואפילו גמי מהני:","m":["(ס) קנה מכאן וכו' - אפילו אחד גבוה מחבירו הרבה והקנה העליון מונח בשיפוע:","(סא) וקנה על גביהן - וה\"ה ע\"י חבלים:","(סב) אפילו אינו נוגע בהן - דאמרינן גוד אסיק והקנים עולים עד החבל וכגון שהחבל קשור למעלה לאיזה דבר:","(סג) ויהיו מכוונים וכו' - ר\"ל ששני הקנים יהיו מכוונים ממש נגד הקנה העליון ולא מרוחק ממנו אפילו כל שהוא ואפילו אם קנה אחד לא היה מכוון כנגדו אלא רחוק כל שהוא פסול והטעם דאפילו אם נימא גוד אסיק הלא יהיה הקנה העליון מן הצד ולא מהני וכדלקמיה. ואם שני הקנים שלמטה אינם מכוונים זה כנגד זה צריך לצמצם שקנה עליון שעל גבן יהיה ג\"כ באלכסון מכוון נגד שני הקנים שתחתיו:","(סד) מן הצד - פי' שלא נתן העליון על שני הקנים העומדים אלא חברו להם מן הצד לפי שאינו דומה לפתח שהמשקוף ניתן על שתי המזוזות. ודע דמה שמקיל הט\"ז אפילו עשאו מן הצד אם עשאו בגובה הקנה בשוה עם הקנה ממש שאין הקנה העומד בולט למעלה מן החבל כל האחרונים חולקין עליו וס\"ל דבעינן שיהיה החבל ע\"ג הקנים ממש. ואם הקנה שלמעלה תחוב בין קנה לקנה שנחקק קצת בקנים כעין שעושין האומנים והקנים עודפין למעלה על גב הקנה שמונח ביניהם מסתפק הפמ\"ג ומצדד בזה להחמיר אבל אם אין הקנים עודפין למעלה אלא שחקק רק מעט באמצעיתן להניח החבל בתוכו שיהא מונח בטוב ולא ישתלשל למטה שפיר דמי דמיקרי זה על גבו. וכן אם נועץ מסמר בראש הקנה וקושר בו החבל ש\"ד דהא מונח מלמעלה נגד הקנה. ואם כרך החוט סביב הקנה מן הצד עד שבכריכתו העלהו על ראשי הקנים ג\"כ כשר. אם יכול לסמוך על הטעליגראף במקום צוה\"פ עיין בתשו' מאמר מרדכי סימן ל\"א ובתשובת שואל ומשיב מהד\"ק ח\"ב סי' פ\"ו ופ\"ח ובתשובת בית שלמה ח\"א סימן מ\"א:","(סה) לא מהני - ואם העמיד קנה אחר תחת איזה מקום שהיה מן הצד כשר ומ\"מ יש לשלוף קנה הפסול מפני הרואים:","(סו) גמי - ומ\"מ אותו גמי צריך שלא ינטל ע\"י רוח וכתב בספר מחצית השקל דמ\"מ קיל קנה שעל גבן מקנה שבצדדים דאותן שבצדדים צריך ליזהר שלא ינידם הרוח [וכמו שכתב המ\"א בסימן שס\"ג סק\"ד] כיון דהם משום מחיצה ומחיצה שהרוח מנידה לא מיקרי מחיצה אבל הקנה שעל גבן נהי דצריך ליזהר שלא ינטל ע\"י הרוח אבל אי הרוח ינידו אין בכך כלום דעיקר המחיצה תלוי בשני הקנים העומדים מן הצד ויש מאחרונים שמחמירין בזה ולדידהו בשעושין העירוב ע\"י חבל צריך למתחו בחזקה כדי שלא ינידו הרוח:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"40\"></i>כיפה <small> (פי' שער העשוי ככיפה. רש\"י) </small> אם יש ברגליה דהיינו קודם שהתחיל להתעגל י' טפחים מותרת משום צורת פתח:","m":["(סז) קודם שהתחיל להתעגל - ר\"ל דלא מצרפינן מקום העיגול לגובה יו\"ד טפחים שצריך להיות צוה\"פ:"]}],"363":[{"s":"<b>דיני מבוי ולחי. ובו לו סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מקום <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>שיש לו ג' מחיצות אסרו חכמים לטלטל בו עד שיעשה שום תיקון ברביעית:","m":["(א) מקום שיש לו ג' מחיצות - היינו כגון מבוי שפתוח לרוח רביעית או חצר שנפרץ אחד מכתליו ובין שפתוח לכרמלית או לר\"ה:","(ב) אסרו חכמים לטלטל בו - שיעור ד' אמות וטעם שאסרוהו דכיון שרוח רביעית פתוח לגמרי דומה קצת לר\"ה ואי נתיר בזה יבואו לטלטל גם בר\"ה ועיין בבה\"ל:","(ג) שום תיקון ברביעית - היינו כמבואר לקמן בסעיף ב' וג' לכל אחד כדינו:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>חצר שנפרץ במילואו עד עשר אמות ניתר בפס רחב ד' טפחים שיעמידנו מצד א' במקום הפרוץ ואם ירצה לתקנו בשני צידי הפרצה <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>די בשני פסין של שני משהויין <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>והוא הדין לנשתייר מהם כותל רביעי בנוי בשיעור ארבעה טפחים במקום א' או אם נשתייר מהשני צדדים <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i><i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>טפח מכאן וטפח מכאן וכל זה בגובה עשרה טפחים <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ואפילו אם <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>אין בפרצה ד' טפחים כיון שהוא במילואו צריך תיקון עד שיהא בה פחות מג' <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ואם יש בפרצה יותר מעשר אמות אפילו אינה במילואו צריך לתקנה בצורת פתח:","m":["(ד) שנפרץ - ר\"ל למקום האסור לה:","(ה) במילואו - כלומר כל הכותל:","(ו) עד עשר אמות - ועד בכלל דאף דבעלמא קי\"ל דאם נפרץ הכותל עשר אמות נחשב הפרצה כפתח הכא שכל הכותל נחסר לא נוכל לחשוב זה המקום לפתח:","(ז) במקום אחד - היינו בראש הכותל:","(ח) טפח מכאן וכו' - לאו דוקא טפח אלא די בשני משהויין וכנ\"ל במעמיד פסין לכתחלה וכמו שכתב בב\"י ועיין בבה\"ל:","(ט) בגובה עשרה טפחים - וא\"צ שיהיה שוה בגובה לשאר הכתלים מיהו בפחות מזה אין עליו שם מחיצה כלל:","(י) כיון שהוא במילואו - האי במילואו לאו דוקא דאפילו אם נשתייר מהכותל ב' או ג' טפחים כל שהוא מיעוט לגבי הפרוץ צריך תיקון אלא אתי לאפוקי היכי דהעומד מרובה דבזה קי\"ל דרובו ככולו והוי כסתום ואע\"פ שאינו מחזיק ד' טפחים כל שהוא משהו יותר מהפרוץ סגי:","(יא) עד שיהא בה פחות מג' - פי' שיתקן הפרצה במקצת ולא ישתייר אלא פחות מג' דאז הוי כלבוד וכ\"ש אם הפרצה לא היה אלא פחות מג' דאין צריך שום תקון מטעם זה:","(יב) אפילו אינה במילואה - האי לישנא לאו דוקא דאפילו העומד מרובה על הפרוץ ג\"כ אסור דכאלו נפרץ כל הכותל דמי. וצוה\"פ מהני אפילו כשהיא במילואה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>מבוי שיש לו ג' מחיצות ופרוץ בצד רביעי התירו בלחי <small> (פי' תרגום הקרש האחד לוחא חדא) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>שעביו ורחבו <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>כל שהוא שיעמידנו בפתח המבוי ויהיה גבהו י\"ט ומכל דבר שיעשנה כשר <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>אפילו מבעלי חיים <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>ובלבד שיקשרנו שם בחבלים לכותלי המבוי ביתדות שיוצאים מן הכתלים בענין שאינו יכול לרבוץ כדי שלא יתמעט גבהו מי' טפחים: <small>ואפילו <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>קשר שם אדם נמי הוי לחי (א\"ז):</small>","m":["(יג) התירו בלחי - ואף דבחצר בעינן דוקא פס רחב ד' טפחים הכא הקילו חכמים והטעם שכל שהוא עשוי יותר לדירה ולתשמישי הצנע צריך מחיצות יותר גמורות ולפיכך החצרות שדרכן של בעלי בתים להשתמש בהן יותר בתשמישי הצנע ולאכול צריכות מחיצותיהן להיות יותר גמורות שיהיה שם רה\"י עליהן מהמבואות שאין משתמשין בהן בתשמישי הצנע ולפיכך די במבוי בלחי ועיין לקמן סכ\"ו שזהו דוקא כשאין רחב פתחו יותר מעשר אמות ועוד פרטים עי\"ש:","(יד) כל שהוא - אפילו פחות מאצבע (אחרונים):","(טו) בפתח המבוי - עיין לקמן סל\"א:","(טז) י' טפחים - מרווחים ולא מצומצמים [חידושי רע\"א] ועשרה טפחים מהני אפילו למבוי שגבוה עשרים אמה:","(יז) ואפילו קשר וכו' - ומיירי שלא הודיעו שהעמידו לשם לחי א\"כ בודאי ילך לו שלא יעמוד שם כל היום לכן בעינן דוקא קשר ויש מחמירין אפילו בהודיעו שמא ישכח וילך משם:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>אם יש קצת כותל ברוח רביעית עולה משום לחי ובלבד שיהא בו רוחב טפח:","m":["(יח) אם יש קצת כותל וכו' - אף דלא נעשה לשם לחי קי\"ל דלחי העומד מאליו ג\"כ כשר וכדלקמן בסי\"א ע\"ש:","(יט) רוחב טפח - עיין בבה\"ל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>לחי דאי נשיב ביה זיקא <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>לא מצי <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>קאי לא חשיב לחי:","m":["(כ) לחי דאי נשיב וכו' - וה\"ה כשעושין צוה\"פ דלא עדיף ממחיצה שאינה יכולה לעמוד ברוח מצויה שאינה מחיצה [תו\"ש וש\"א] ואפילו אין הרוח מפילו לארץ אלא מנידו כמ\"ש בסי' שס\"ב ס\"א:","(כא) לא חשיב לחי - נ\"ל דאם הלחי למטה אינו מתנענע כגון שקבוע במסמר או שקשור היטב להכותל ומחמת זה אינו מתנענע עד משך גבוה עשרה טפחים ורק למעלה הוא מתנענע ע\"י הרוח מפני רוב גובהו כשר דדל מה שלמעלה נשאר ג\"כ שיעור לחי:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>צריך שלא יהא הלחי <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>רחוק מן הכותל ג' טפחים:","m":["(כב) צריך שלא יהא - י\"א שהטעם משום דאתי אוירא דהאי גיסא ודהאי גיסא ומבטלין ליה ולפ\"ז אם הלחי היה רחב יותר מג\"ט כשר אף שהלחי היה רחוק ג\"ט מן הכותל דהא הוי עומד מרובה על הפרוץ שבצדו ובכגון זה לא אמרינן אתי אוירא ומבטל ליה ויש אומרים דבכל גווני צריך להיות הלחי בתוך ג\"ט לכותל ויש להחמיר:","(כג) הלחי - והיכי שקובע צורת הפתח למבוי דעת הרבה מהפוסקים שא\"צ לדקדק שיהא בתוך ג\"ט לכותל דצוה\"פ מחיצה גמורה היא ויש פוסקים דס\"ל דאין חילוק בין צוה\"פ ללחי לענין זה ובשעת הדחק יש לסמוך להקל. ואם יש ארבעה טפחים בין צוה\"פ להכותל דעת הח\"א דצריך להעמיד לחי אצל הכותל ולדידי צ\"ע גם בזה כמו שביררתי בבה\"ל ולכתחלה בודאי נכון לחוש להחמיר אפילו ברחוק ג' טפחים מן הכותל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>לחי <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>אפילו שברים ושברי שברים כשרים בו: <small>הגה <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>ולכן עושין לחי <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"3\"></i>מסיד טחוי בכותל ובלבד שיזהר שלא יתמחה יותר משלש לארץ: (תה\"ד סי' ט\"ו):</small>","m":["(כד) לחי אפילו שברים וכו' - ר\"ל מדובקים ובלבד שיוכל לעמוד ברוח מצויה [לבוש]. ולאפוקי קורה דבעינן דוקא שתהיה חזקה כדי לקבל אריח וכדלקמן בסי\"ז:","(כה) כשרים בו - וה\"ה אבנים היוצאים מן הכותל ומובדלים זו מזו פחות מג\"ט הוי לחי ממש והא שיהא בין כולן גבוה עשרה טפחים:","(כו) ולכן עושין לחי וכו' - דלא גרע משברי שברים דמותר בלחי וה\"ה לענין צוה\"פ דבעינן שיעשה לחיים מכאן ומכאן אם ירא שיפילם הרוח מותר לעשותן ע\"י סיד מחוי בכותל מכאן ומכאן והקנה שלמעלה יהיה מכוון על גביהן. ומ\"מ בעינן שיהי בו ממשות קצת עכ\"פ כחוט אבל מראה סיד לבד או רושם בנתר שקורין קריי\"ד או שאר צבע לא מהני [ט\"ז וש\"א]:","(כז) שלא יתמחה יותר וכו' - היינו ע\"י כלבים וחזירים שרגילים להתחכך בכתלים ומוחקין מן הכתלים את מיחוי הסיד הסמוך לארץ ואז לא מהני שוב לא ללחי ולא לצוה\"פ:","(כח) יותר משלש לארץ - האי לישנא לאו דוקא דאפילו נמחה רק שלש בצמצום ג\"כ בטל ממנו שם לחי וכדלקמיה בסעיף יו\"ד:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>לחי שעשאו <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i><i data-commentator=\"Magen Avraham\" data-order=\"7\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>מעצי אשירה כשר:","m":["(כט) לחי שעשאו וכו' - בגמרא איתא דעושין לחי אשרה ומשמע אפילו לכתחלה. ואין להקשות נהי דבלחי כיון דאין צריך שיעור לא שייך בזה כתותי מיכתת שיעוריה וכדלקמיה מ\"מ הא אסור בהנאה י\"ל כיון דהלחי אינו אלא לצורך מחיצה ובה גופא לא משתמש במידי לא חשיב הנאה מה שנהנה על ידה היתר טלטול [בית מאיר ע\"ש]:","(ל) כשר - הטעם משום דכיון דלחי א\"צ שיעור דבכל שהוא סגי וכדלעיל בס\"ג אפי' מעצי אשרה מהני אע\"ג דעצי אשרה עומד לשריפה וכמאן דשרוף דמי ומכתת כתות שיעוריה מ\"מ הא לא בעי שיעור ואע\"ג דהא מ\"מ בעי עכ\"פ שיעור בגובהו י' טפחים כיון דיכול לעשותו קו דק מאוד של כל שהוא לא החמירו חכמים בשיעור זוטא כי האי ועוד תירצו בזה דבלחי אפילו היה נשרף העץ לאפר והיה מגבל לאפר ומדבק לכותל ג\"כ חשיב לחי ובלבד שלא יהא ניטל ברוח ולכן אין נפסל מחמת שעומד לשריפה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i><i data-commentator=\"Turei Zahav\" data-order=\"6\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>בין שנראית בליטת הלחי לעומדים בתוך המבוי <i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i>ואינה נראית לעומדים בחוץ <i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"19\"></i>בין שנראית לעומדים בחוץ <small>נגד חלל המבוי (תוס' והרא\"ש פ\"ק דעירובין) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"20\"></i>ואינה נראית לעומדים בפנים כשר:","m":["(לא) ואינה נראית לעומדים בחוץ - כגון שהעמיד הלחי רחבו לצד ארכו של מבוי ולא משך קצה רחבו קימעא כלפי חוץ אלא השוה חודו החיצון לעובי כותל המבוי ודומה כמי שמוסיף על עובי הכותל ואינו נראה מבחוץ כלחי אבל חודו הפנימי נראה לעומדים שם בפנים כזה /במקור מופיע ציור/:","(לב) נגד חלל המבוי - כגון שנתן כל הלחי לחוץ המבוי וחודו הפנימי עומד אצל עובי הכותל אבל לא העמידו בשוה לשפת עובי הכותל של צד תוך המבוי דא\"כ לא היה נראה כלחי אלא כמוסיף על הכותל אף להעומדים בר\"ה אלא הרחיקו מזוית עובי הכותל של צד פנים והעמידו לשפת עובי של צד אחורי המבוי דעי\"ז ניכר להעומדים בחוץ בר\"ה נגד חלל המבוי שהוא לחי כזה /במקור מופיע ציור/:","(לג) לעומדים בפנים - ר\"ל לאותן העומדים תוך המבוי אין הלחי נראית שאין עשויה בפנים:","(לד) הרחיק מהכותל שלש - אע\"ג דכבר שנאו בס\"ו חזר ושנאו לאשמועינן שהוא לעיכובא:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"21\"></i>הרחיקו מהכותל שלש או שהגביהו מהארץ שלש פסול <i data-commentator=\"Be'er HaGolah\" data-label=\"ת\" data-order=\"22\"></i>ואם הגביהו פחות משלש אע\"פ שאין בו אלא שבע ומשהו כשר:","m":["(לה) או שהגביהו מהארץ שלש - היינו אף דאית בלחי עשרה טפחים והטעם דלא עדיפא ממחיצה שנטולה שלשה טפחים מן הארץ דפסולה משום דהוי מחיצה שהגדיים בוקעין תחתיה דלא שמה מחיצה:","(לו) כשר - מטעם לבוד והוי כמלא זה המקום הפנוי:"]},{"s":"<i data-commentator=\"Magen Avraham\" data-order=\"8\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"23\"></i>אפילו לא עשאו לשם לחי אלא שנזדמן לו שם מאליו כשר <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"24\"></i>ובלבד שיסמכו עליו מערב שבת אבל לא סמכו עליו מערב שבת כגון שהיה שם לחי אחר ונפל בשבת ובאים עכשיו לסמוך על זה לא: <small> (אבל לא היה שם לחי אחר מערב שבת <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>כאלו סמכו עליו דמי) (ב\"י בשם רש\"י והגהות אשירי והמגיד פי\"ו):</small>","m":["(לז) שנזדמן לו שם מאליו - כגון שיצא בליטה מכותל המבוי בראשו בשיעור משך גבוה עשרה טפחים או שהועמד שם לאיזה ענין ואפילו לא קבעו הוא בעצמו אלא מעולם הוא שם ג\"כ כשר דלחי משום מחיצה ומחיצה העומדת מאליה כשרה:","(לח) כגון שהיה שם לחי אחר וכו' - דהו\"ל כאלו אמר ע\"ז אני סומך ולא ע\"ז והו\"ל האי כאלו אדחי מתורת לחי [א\"ז]:","(לט) כאלו סמכו עליו - ר\"ל אע\"פ שלא סמכו עליו בפירוש אכן אם בפירוש לא סמכו עליו כגון שלא טלטלו בשבת שעברה ע\"י לחי זו ולא היה שם לחי אחר אינו מועיל לשבת הבאה עד שיסמכו עליו מע\"ש בפירוש:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"25\"></i>לחי העומד מאליו אפי' סמכו עליו מערב שבת אם המבוי רחב יותר משמונה אמות <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"26\"></i><i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>אם הלחי בולט לתוכו <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>ד' אמות אינו נדון משום לחי וצריך לחי אחר להתירו <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"27\"></i>ויעמידנו ברוח שכנגדו <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"28\"></i>ואם ירצה להעמידו אצלו יעשנו <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"29\"></i>מעט עב או דק יותר מהבליטה כדי שיהא ניכר שהוא לשם לחי: <small>הגה ואם <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>העמידו לשם לחי דאית ליה קלא שתקנו לחי למבוי זה אפי' רחב ארבע אמות הוי לחי:</small>","m":["(מ) לחי העומד וכו' - שיעור דבריו כך הוא דהא דכתב בסי\"א דלחי העומד מאליו וסמכו עליו מהני דוקא אם הלחי אינו בולט לרחבו של מבוי ד\"א אבל אם הוא בולט ויוצא מכותל הבית לרחבו של מבוי ד\"א אז נפק ליה מתורת לחי [משום שיש בו שיעור הכשר של אורך מבוי שהוא בד\"א וכדלקמיה בסכ\"ו] ושם כותל מבוי עליה וצריך לחי אחר לפתח המבוי להתירו אם לא שהמבוי אינו מחזיק רחבו רק ח' אמות דאז מותר בלא לחי אחר דהוי עומד כפרוץ וחשיב המבוי כסתום מכל הצדדין וכנ\"ל בסימן שס\"ב ס\"ט:","(מא) מאיליו - דאם העמידו לשם לחי אפילו רחב ד' אמות הוי לחי כמו שכתב בהג\"ה:","(מב) ד' אמות - דד\"א הוי שיעור כותל מבוי וליכא הכירא כלל דהוא לחי אבל עד ד' אמות נוכל לחשבו ללחי והוא דסמכו עליו מע\"ש וכנ\"ל בסי\"א:","(מג) אפילו רחב ד\"א - וה\"ה יותר מזה והטעם דמשום דריבה בפתח המבוי בסתימתו לא גרע מלחי דעלמא [רש\"י]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"30\"></i><i data-commentator=\"Turei Zahav\" data-order=\"8\"></i><i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>לחי המושך עם דפנו של מבוי שהעמיד חודו כנגד עובי הכותל דשוה מבפנים ונראה מבחוץ שאין חודו של לחי מכס' כל עובי הדופן פחות <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"31\"></i>מד' אמות נידון משום לחי ומשתמש <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>עם חודו הפנימי ד' אמות נידון משום מבוי <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i>ואסור להשתמש בכל המבוי שהרי אין כאן לחי:","m":["(מד) המושך עם דפנו וכו' - לאורך המבוי:","(מה) שאין חודו של לחי מכסה וכו' - אלא קצר ממנו ונמשך להלאה לצד אחורי המבוי וכמו שציירנו לעיל בס\"ט במ\"ב:","(מו) עם חודו הפנימי - ר\"ל שמותר ע\"י הלחי להשתמש בכל המבוי עד חודו הפנימי של הלחי ולא יותר דאף דקי\"ל בסימן שס\"ה ס\"ד דבין הלחיים מותר להשתמש הכא שאני דהא הצד השני קצר מזה שאין דופן כנגד הלחי:","(מז) ד\"א נידון משום מבוי - דכיון דהוא ד\"א שהוא בעלמא שיעור אורך מבוי יוצא מתורת לחי ונחשב לכותל מבוי וכן מבוי שעשה לאורך המבוי לפנים לחיים קטנים הרבה רצופים בפחות מג\"ט זה אצל זה במשך ארבע אמות אינו ניתר המבוי בזה דכיון שהם בפחות מג\"ט זה מזה חשובים כולם כלחי אחד שמחזיק ד' אמות ברחבו ויוצא מתורת לחי ונחשב ככותל ואין לחי למבוי זה. ומ\"מ אם הלחי הראשון שעומד בקצה המבוי אינו עומד בשוה עם קצה המבוי אלא נמשך קצת מן המבוי ולפנים נידון משום לחי כיון שנראה מבחוץ:","(מח) ואסור להשתמש - דזה אסור אפילו הועמד לשם לחי ואינו דומה להנ\"ל בסי\"ב דמתירין שם כשהעמידו לשם לחי דהתם הלא העמיד הבליטה לרוחב המבוי ונסתם עי\"ז פתיחתה וע\"כ לא גרע מלחי משהו משא\"כ הכא דהעמידו לארכו ומחזי כמוסיף עוד על הכותל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"32\"></i>עוד יש הכשר אחר למבוי הפרוץ ברוח רביעית בקורה שיניחנה על ראש המבוי וצריך שיניחנה על כותל המבוי <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"33\"></i>אבל אם נעץ שתי יתדות אצל המבוי בחוץ אפילו בסמוך לו והניח' עליהם פסול:","m":["(מט) בקורה - שעי\"ז יהיה היכר שלא יבואו להחליף ולטלטל בר\"ה גמורה וגם שלא יבואו לטלטל ממנו ולחוץ:","(נ) על ראש המבוי - ר\"ל בקצה המבוי ואם העמידו באמצע המבוי עיין לקמן בסל\"ב:","(נא) אבל אם נעץ וכו' - היינו שתחב שני יתדות בשני הכתלים מזה ומזה לצד ר\"ה ומש\"כ אפילו בסמוך לו היינו שהיתדות היו קצרות מאוד וממילא כשהניח הקורה עליהם היה סמוך להכתלים בלא שום הפסק בינתים אפ\"ה פסול והטעם דקורה ע\"ג כתלים בעינן שאין נראית שבא להכשיר המבוי אלא כשהוא תוך חללו של מבוי שאין דרך שום תקרה ושום קורה לתתה אלא ע\"ג הכתלים ולא מבחוץ ודוקא קורה אבל לחי לא בעינן תוך חללו של מבוי אלא אפילו חוץ לחלל המבוי וכעין ההיא דסי\"ג הנ\"ל וטעמא דמלתא דלחי אפילו עומד בחוץ ניכר שבא להכשיר המבוי משא\"כ בקורה וכנ\"ל:","(נב) פסול - ואם נעץ שתי יתדות בקרקע סמוך לכותלי המבוי מזה ומזה מבחוץ והניח הקורה עליהן כשר מטעם לחי [עו\"ש וא\"ר וש\"א]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"34\"></i><i data-commentator=\"Turei Zahav\" data-order=\"9\"></i>וצריך שיניחנה כדי להתיר המבוי אבל אם לא נעשית לשם כך אפילו סמכה עליה <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i>מערב שבת פסולה:","m":["(נג) אבל אם לא וכו' - כאותו שנותנין קורה מכותל לכותל לחזק הכתלים וכל כה\"ג:","(נד) אפילו סמכו עליה וכו' - ואף דבלחי קי\"ל בסי\"ב דאם סמכו עליו מע\"ש מהני אפילו בעומד מאליו שאני התם דלחי משום מחיצה ומחיצה העומדת מאליה ג\"כ הוי מחיצה אבל קורה משום היכר וכשלא הונחה לשם כך לא הוי היכר ועיין בפמ\"ג שמצדד דאפילו היה הקורה רחבה ד' טפחים ג\"כ לא מהני ועיין בה\"ל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"35\"></i>קורה זה שאמרנו צריכה שיעור <i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"36\"></i>ולפיכך אם עשאה מעצי אשרה פסולה דכיון דלשריפה קיימא כתותי מכתת שיעורה:","m":["(נה) צריכה שיעור - וכדלקמיה בסי\"ז:","(נו) ולפיכך וכו' - וה\"ה לכל דבר שצריך שיעור כגון מה שנזכר לעיל בס\"ב פס של ד' טפחים בצד א' או טפח מכאן וטפח מכאן:","(נז) מעצי אשרה - שעבדה ישראל שאין לה ביטול או אפילו של עכו\"ם וקצצה ישראל [דאי קצצה עכו\"ם הלא נתבטלה ממילא וכדאיתא ביו\"ד סימן קמ\"ו ס\"ו] ונטלה לזכות בה דעי\"ז נעשה עכו\"ם של ישראל דאין לה ביטול ולפיכך אמרינן דכתותיה מכתת אבל אם לא נטל הישראל לזכות בה הו\"ל עכו\"ם של נכרי דיש לה ביטול וכיון דיש לה ביטול לא אמרינן ביה כתותי מכתת אפילו קודם שנתבטל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"37\"></i>שיעור הקורה רחבה טפח ועביה כל שהוא רק שתהא חזקה <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i>כדי לקבל אריח שהוא חצי לבנה של ג\"ט <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"38\"></i>ואם היא רחבה ד\"ט א\"צ להיות חזקה לקבל אריח:","m":["(נח) רחבה טפח - ואף שצריכה שיעור לקבל עליה אריח שהוא רחב טפח ומחצה יוכל לחבר כרביע טפח ממנו בטיט בכאן ורביע טפח ממנו בכאן [גמרא]:","(נט) לקבל אריח וכו' - ר\"ל אריחים שכל אחד מהם מחזקת בארכו ג' טפחים וברחבו טפח ומחצה שוכבים עליה בכל ארכה כשיעור רוחב פתח אותו המבוי [ומ\"מ אם היה רוחב פתח המבוי עשר אמות א\"צ שתהא ראויה לקבל אריחים לכל ארכה ממש אלא דיה אם תקבל אריחים באורך ט' אמות ושני משהויין שהן י\"ח אריחים לאורכן לפי שקורת ט' אמות ושתי משהויין מתרת במבוי של רוחב עשר אמות מדין לבוד דהיינו שלא תגיע פחות מג' טפחים לכותל זה ופחות מג\"ט לכותל זה כדלקמיה בסכ\"א] והטעם שצריכה לקבלת אריחים שאל\"כ לא יהיה בה היכר כ\"כ שסבורים בני ר\"ה שלפי שעה הניחו שם אבל כשהיא בריאה וחזקה לקבל בנין כזה ניכר לכל שלקביעות בנין הונחה לשם:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"39\"></i>מעמידים דהיינו אם היא נסמכת על יתדות היוצאות מן הכותל <i data-commentator=\"Turei Zahav\" data-order=\"10\"></i>שאין ברחבן טפח ולא בארכן שלש <i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"40\"></i>יש אומרים <i data-commentator=\"Turei Zahav\" data-order=\"11\"></i>שצריך שיהיו חזקים לקבלם ולקבל חצי לבנה <i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"41\"></i>וי\"א שאין צריך שיהיו חזקים אלא כדי לקבלה בלבד:","m":["(ס) שאין ברחבן טפח וכו' - דאל\"ה היו המעמידין בעצמן תורת קורה עליהם וגם לא היה בארכן שלש כדי שתהיה הקורה לבוד להכותל וכמבואר הכל בסכ\"ה:","(סא) ולקבל חצי לבנה - וכפי המבואר בסעיף י\"ז:","(סב) אלא כדי לקבלה - דהא אין נותנין אריח עליה ובקורה הוא דבעינן קביעות כי היכי דתהוי הכירא מעליא אבל מעמידיה לא תלי הכירא בדידהו [רש\"י] ולכתחלה נכון להחמיר כדעה הראשונה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"42\"></i>אם היתה הקורה עגולה צריך שיהיה בהקיפה ג' טפחים שאז יש ברחבה טפח:","m":["(סג) הקורה עגולה וכו' - ואף דהשתא כשהיא עגולה אינה יכולה לקבל עליה אריח אפ\"ה כשרה דחשבינן אותה כאלו היתה מתחלקת לשנים [רש\"י]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"43\"></i>היתה עקומה ועקמימותה נוטה חוץ למבוי או למעלה מעשרים או למטה מעשרה רואים כל שאלו ינטל העקמימות ואין בין זה לזה שלשה כשרה ואם לאו פסולה:","m":["(סד) נוטה חוץ למבוי וכו' - דכל אלו דברים שפוסלים בקורה:","(סה) רואים כל שאלו ינטל וכו' - והטעם דאמרינן לבוד:","(סו) ואם לאו פסולה - היינו דוקא באופן זה שקצת קורה העקומה הוא חוץ לשיעור הכשר מבוי אבל אם היא כולה בתוך המבוי כדין אפילו אם העיקום הוא הרבה יותר מג' טפחים כשרה דאמרינן רואין כאלו היתה פשוטה [כן מוכח מסתימת לשון הרמב\"ם בפי\"ז הלכה כ\"ו ע\"ש וכן משארי הראשונים אמנם בספר גאון יעקב וכן בחידושי אה\"ע מפקפקין בזה עי\"ש]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ת\" data-order=\"44\"></i>היתה יוצאה מכותל זה <i data-commentator=\"Magen Avraham\" data-order=\"17\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>ואינה נוגעת בכותל זה כגון שסמכה על עמודים וכן שתי קורות א' יוצא מכותל זה וא' יוצא מכותל זה ופגעו זו בזו באמצע המבוי אם אין ביניהם שלשה כשרה יש ביניהם שלשה פסולה:","m":["(סז) ואינה נוגעת וכו' - ואפילו מרוחקת משני הכתלים כה\"ג כגון שנעץ עץ באמצע המבוי והניח קורה עליה אמרינן לבוד משני רוחות:","(סח) פסולה - אלא יביא קורה אחרת או יראה למלא הריוח ההוא בחתיכת קורה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"45\"></i>הניח שתי קורות זו בצד זו לא בזו לקבל אריח ולא בזו לקבל אריח אם יש בשתיהן כדי לקבל אריח לרחבו דהיינו טפח <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"46\"></i>ואין בין זו לזו שלשה טפחים אינו צריך להביא קורה אחרת ואם לאו צריך להביא קורה אחרת <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"47\"></i>ויש אומרים שצריך שיהו קרובות זו לזו <i data-commentator=\"Turei Zahav\" data-order=\"12\"></i><i data-commentator=\"Magen Avraham\" data-order=\"18\"></i>בתוך טפח:","m":["(סט) דהיינו טפח - ר\"ל שיהיו שניהן רחבין ביחד טפח:","(ע) ואין בין זל\"ז ג\"ט - חשבינן להו כאלו סמוכות זו לזו מטעם לבוד:"]},{"s":"היתה אחת למעלה ואחת למטה <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"48\"></i>רואים את העליונה כאלו היא למט' ואת התחתונ' כאלו היא למעל' ובלבד שלא תהא העליונה למעלה מעשרים ולא תחתונה למטה מעשרה <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"49\"></i>ולא יהי' ביניהם ג' טפחים לא בגובה ולא במשך כשרואין אותם שירדה זו ועלתה זו בכוונ' עד שיעשו זו בצד זו <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"50\"></i><i data-commentator=\"Magen Avraham\" data-order=\"19\"></i>ויש פוסלים:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"51\"></i>פירס על הקורה מחצלת ואינה נוגעת עד הקרקע אם גבוה מהארץ ג\"ט פסול' שהרי כיסה הקורה ואינה נראית ובטלה מהיות קורה ומחיצה גם כן אינה כיון שגבוה מהארץ שלשה <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"52\"></i>אבל אם הניח קורה רחבה <i data-commentator=\"Magen Avraham\" data-order=\"20\"></i>ונמשכת קצת <i data-commentator=\"Turei Zahav\" data-order=\"13\"></i>למטה מי' כשרה:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"53\"></i>נעץ שתי יתדות עקומות על שני כתלי המבוי ועקמימותיה נוטה לתוך המבוי ונתן הקורה עליהם ואין ביתידות טפח שהוא שיעור קורה להיות נחשבים כקורה אם אינם גבוהים מכתלי המבוי שלש' ואין בנטייתם שלשה <i data-commentator=\"Magen Avraham\" data-order=\"21\"></i>כשרה שאנו רואים כאלו הם על כתלי המבוי ואם יש בגבהן או בנטייתן שלשה פסולה:","m":[]},{"s":"הא דמבוי ניתר בלחי או קורה <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"54\"></i>דוקא בשאינו נמוך פחות מי\"ט <i data-commentator=\"Magen Avraham\" data-order=\"22\"></i><i data-commentator=\"Turei Zahav\" data-order=\"14\"></i>מרווחים <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"55\"></i>ולא יהא רחבו יותר מעשר אמות מצומצמות <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"56\"></i>ושיהא ארכו ד' אמות מרווחות או יותר אבל אם חסר א' מכל אלו אין לו תקנה <i data-commentator=\"Magen Avraham\" data-order=\"23\"></i>אלא בצורת פתח <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"57\"></i>ואם היה בגובה חללו יותר מעשרים אמה מצומצמות <i data-commentator=\"Turei Zahav\" data-order=\"15\"></i>אינו ניתר בקורה <i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"58\"></i>אבל ניתר הוא בלחי ואם רוצה להכשירו בקורה צריך <i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"59\"></i>שיעשה בה ציור וכיור <small> (פי' ציור אחד בכותל מן הסיד או על שמי קורה) </small> שעל ידי כך הכל מסתכלים בה ואם היה <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"60\"></i>גבוה יותר מעשרים ובנה בנין תחת הקורה למעטו מעשרים די <i data-commentator=\"Magen Avraham\" data-order=\"24\"></i>בבנין רחב טפח ברוחב הקורה אבל אם אינו גבוה י' וחוקק בו להשלימו לי' <i data-commentator=\"Turei Zahav\" data-order=\"16\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"61\"></i>צריך לחוק ד' אמות לתוך המבוי על פני כל רחבו. <i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"62\"></i>אין מבוי ניתר בלחי או קורה עד שיהיו פתוחים לתוכו <i data-commentator=\"Magen Avraham\" data-order=\"25\"></i>שני חצרות ולכל חצר <i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"63\"></i>שני בתים <small> (ואפי' כל החצרות פתוחות זו לזו) <i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"64\"></i>(רא\"ש ומרדכי והטור) <i data-commentator=\"Turei Zahav\" data-order=\"17\"></i><i data-commentator=\"Magen Avraham\" data-order=\"26\"></i>ויש חולקים בזה (ב\"י בשם הרי\"ף והרמב\"ם) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"65\"></i>ושלא יהא בכל פתח מאלו פחות מד\"ט ושיהיו דיורים אוכלים בכל בית שמקום הפת גורם ואפי' היה הבית <i data-commentator=\"Be'er HaGolah\" data-label=\"ת\" data-order=\"66\"></i>הא' לאב והב' לבן אע\"פ שהבן מקבל פרס משלחן אביו ואוכל בביתו הרי הם נידונים כשנים <i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"67\"></i>ואפילו צדו א' עכו\"ם וא' ישראל מהני עוד צריך <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"68\"></i>שיהא ארכו יותר על רחבו ואם חסר א' מאלו <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"69\"></i>אינו ניתר אלא בפס ארבע או שני פסין שני משהויין או צורת פתח: <small>הגה וי\"א דנוהגין האידנא לתקן כל המבואות בצורות הפתח דכל המבואות שלנו <i data-commentator=\"Turei Zahav\" data-order=\"18\"></i>יש להם <i data-commentator=\"Magen Avraham\" data-order=\"27\"></i>דין חצרות (ת\"ה סי' ע\"ד) והמנהג הפשוט במדינות אלו לתקנן על ידי חבל הקשור לרחבו של מבוי ודין חבל זה אינו קורה שהרי אין רחבו טפח ולא מהני אלא מטעם צורת הפתח דמהני למעלה אפי' בגמי כדלעיל סוף סי' שס\"ב <i data-commentator=\"Turei Zahav\" data-order=\"19\"></i>ועל כן יש ליזהר להעמיד <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"7\"></i>תחת החבל <i data-commentator=\"Magen Avraham\" data-order=\"28\"></i>שני קנים גבוהים י' מכוונים תחת החבל ואז מהני אפי' במבוי מפולש בתורת צורת פתח או אפי' בחצר ובכל מקום שצורת הפתח מהני וכמו שנתבאר לעיל ס\"ס שס\"ב: (ד\"ע)</small>","m":["(עא) וי\"א וכו' - ס\"ל דלא שייך כאן להתיר משום לבוד דהא בעינן שיהיה הקורה ראויה לקבל אריח לרחבה וכשהן פרודות הרבה אין יכולת לקבל אריח עליהן:","(עב) בתוך טפח - דהא האריח לרחבו היא מחזקת טפח ומחצה וצריך שיהיה עכ\"פ נסמך ממנו כרבע טפח על קורה זו וכרבע על השניה וא\"כ לא ישאר פירוד ביניהן אלא כשיעור טפח ולא יותר:","(עג) היתה וכו' - כאן בא להוסיף רבותא על סעיף הקודם דאפילו אם לא היו שתי הקורות שאין בכל אחת לקבל אריח עומדות בשוה אלא אחת גבוהה מחברתה עד ג' טפחים ג\"כ כשירה דאמרינן רואין וכו':","(עד) ואת התחתונה וכו' - ר\"ל או את התחתונה [רש\"י]:","(עה) ובלבד וכו' מעשרים - דאם היא למעלה מעשרים אז אפילו התחתונה סמוכה לה בתוך ג' טפחים לא אמרינן כאלו היא למטה מעשרים כיון דעתה עומדת במקום פסול וכן אם התחתונה למטה מיו\"ד והעליונה סמוכה לה בתוך ג' טפחים לא אמרינן רואין את התחתונה כאלו היתה עומדת בשוה עם העליונה כיון דעכשיו אין בה הכשר קורה:","(עו) בכוונה - ר\"ל מכוונת והיינו דאפילו אם נחשוב שכבר עלתה זו למטה קצת והתחתונה עלתה למעלה קצת עד שנעשו זו כנגד זו בשוה לא יהיו אז מרוחקין רק פחות מג' טפחים דאז שייך לומר לבוד וכנ\"ל בסעיף הקודם בדעה ראשונה:","(עז) ויש פוסלין - משום דס\"ל דלא אמרינן רואין את העליונה וכו' ואע\"ג דלקמן בהל' סוכה בסימן תרל\"א פסק המחבר בפשיטות בס\"ה דאם הסיכוך הוא מבולבל ואחד למעלה ואחד למטה דאם אין ביניהם ג\"ט דאמרינן לבוד שאני הכא דבעינן שיהו ראויין לקבל אריח ובאחד למעלה ואחד למטה אין ראויין לקבל אריח [עו\"ש] והיינו דאפילו אם גבוהות טפח אחד מחבירו ג\"כ לא מהני ואפילו אם עומדות בשוה ממש ס\"ל להדעה זו כדעה שניה הנ\"ל דבעינן דוקא שיהא סמוכות אחד לחבירו לא יותר מטפח וכתב בא\"ר דיש להחמיר כדעה זו:","(עח) מחצלת - שרצה ליפות כח ההיתר ופירס עליה מחצלת וגם קשרה לכותל שלא תנידה הרוח כדי שיהיה עליה שם מחיצה ג\"כ:","(עט) פסולה - אפילו אם המחצלת בעצמה גבוהה עשרה:","(פ) ואינה נראית - א\"כ לית כאן היכר:","(פא) קורה רחבה - ר\"ל שהיא רחבה עשרה טפחים והו\"א כיון שהיא רחבה כ\"כ שם מחיצה עליה ולא שם קורה ומחיצה כשרה אינה דהא גבוה מן הארץ הרבה וכמו במחצלת קמ\"ל דכשרה דמפני גדלותה לא נתבטל מינה שם קורה ומחצלת שאני דכיסה את הקורה ואינה ניכרת:","(פב) ונמשכת קצת למטה מעשרה - כמה אחרונים נתקשו בדבריו דמשמע מלשונו דבא לאשמעינן דאפילו קצת מהקורה הרחבה נכנס בתוך עשרה טפחים התחתונים של המבוי ג\"כ כשר דאמרינן רואין את המקצת הזה כאלו אינו והקורה עומדת רק למעלה מעשרה כדין הכשר קורה המבואר בסכ\"ו אבל באמה זה אינו דאם היה נכנס קצת מרוחב הקורה בתוך האויר של יו\"ד התחתונים פסולה דבעינן שיהא החלל של המבוי עד הקורה עשרה טפחים דוקא:","(פג) עקומות על שני וכו' - ר\"ל דהיו עומדות היתדות על שני הצדדים בשיפוע וראשיהם בולטות למעלה מגובה הכתלים:","(פד) ונתן הקורה עליהם - ר\"ל ויש כאן שני ריעותות אחת דאינה מונחת הקורה על הכותל ממש ורק באויר מלמעלה על היתדות שנית דהקורה קצרה מאורך השטח שבין שני הכתלים:","(פה) ואין ביתידות טפח - דאי הוי היתדות רחב טפח לא איכפת לן במה שהקורה עצמה קצרה דהלא היתדות עצמן נחשבין כקורה:","(פו) כשרה וכו' - דבמה שאין גבוהים היתדות מכותלי המבוי ג' טפחים אמרינן חבוט רמי והיינו כאלו הקורה נחבט ונשפל אצל הכתלים ואף שעדיין קצר היא כיון שאין בנטייתן של היתדות שלשה וא\"כ הקורה אינה רחוקה ג' טפחים מהכתלים אמרינן לבוד:","(פז) פסולה - דבשיעור שלשה לא אמרינן חבוט בקורה ולא לבוד:","(פח) כשאינו נמוך - ר\"ל שאם הקרקע שבמבוי אינו נמוך מבפנים נגד הכתלים שיעור עשרה טפחים נחשב כאלו אין למבוי מחיצות דאין מחיצה פחותה מעשרה:","(פט) מרווחים - ובסיפא מצומצמות דאזלינן לחומרא בכל מקום לענין זה. ושיעור מרווחים יותר על מצומצמות הוא חצי אצבע לאמה:","(צ) יותר מעשר - דאם הוא יותר מעשר אין עליו שם פתח ולא מהני לזה לחי וקורה:","(צא) מצומצמות - ר\"ל שמודדין לכל אמה את הששה טפחים מצומצמות וכן בסיפא לענין אורך המבוי דבעינן ד\"א מרווחות נמי הכי הוא דמודדין טפחיו מרווחים וא\"כ יתוסף על ד\"א שני אצבעות וכנ\"ל:","(צב) ארכו ד' אמות וכו' - דבפחות משיעור זה לא חשובה כמבוי אלא כחצר:","(צג) אלא בצורת הפתח - היינו דאפילו היה נמוך פחות מעשרה טפחים ג\"כ מהני צוה\"פ וכן ברחב מעשר אמות או שלא היה ארכו ד\"א אבל הרבה אחרונים הסכימו לדינא דאם היה חלל המבוי נמוך פחות מעשרה טפחים לא מהני צורת הפתח דאפילו מחיצה לא מהני כל שאינו גבוה יו\"ד וכ\"ש צוה\"פ בעלמא. אכן אם חלל המבוי היה גבוה עשרה טפחים ורק במקום פתח המבוי היה נמוך מעשרה בזה מהני צוה\"פ והוא שהיה עשוי כדין דהיינו שהיו הקנים גבוהין יו\"ד טפחים [הגר\"א]. ודע עוד דאם לא היה ארכו ד\"א דעת כמה פוסקים דדינו כחצר וע\"כ ניתר ג\"כ בפס ארבעה מצד אחד או שני פסין של משהויין משני הצדדין וכן סתם המחבר בעצמו לקמן בסל\"ב והמחבר שכתב אלא בצוה\"פ לאו דוקא נקט:","(צד) בגובה חללו וכו' - אבל אם גובה חללה של המבוי עד הקורה אינו אלא עשרים מצומצמות אע\"פ שהקורה היא למעלה מעשרים כשרה:","(צה) אינו ניתר בקורה - דקורה משום היכר ולמעלה מעשרים אין היכר דלא שלטא ביה עינא אבל לחי שהוא סמוך לקרקע וסגי בגובה י\"ט א\"כ מה מזיק מה שהוא גבוה הרבה:","(צו) למעטו מכ' - וה\"ה דיכול להשפיל את הקורה גופא ולהניחה בתוך חלל המבוי על יתדות היוצאים מן הכתלים למטה מכ':","(צז) בבנין רחב טפח - וה\"ה עפר כשיעור זה וצריך ליזהר כשנדרס ברגלים שלא יתמעט מכשיעור ברחבו וה\"ה לענין גובהו שלא יתמעט ויהיה יותר מעשרים:","(צח) ברוחב הקורה - דשיעורו טפח וכנ\"ל בסי\"ז. והטעם דמהני רוחב טפח דהא קיי\"ל מותר להשתמש תחת הקורה והעומד על אותו מקום יוכל לראות את הקורה דהא על אותו המקום אינו גבוה יותר מעשרים ואית ביה משום הכירא:","(צט) צריך לחוק ד\"א - והא דלעיל סגי בטפח שאני הכא דבפחות מעשרה טפחים לא מקרי דופן כלל וצריך לשויה דופן ולכך צריך דוקא כשיעור משך המבוי דהוא ד\"א וכנ\"ל בריש הסעיף אבל התם מקרי דופן אלא שהוא גבוה יותר מעשרים אמות ולהכי סגי בטפח כשיעור רוחב הקירה (רש\"י):","(ק) לתוך המבוי - ואם חקק בפחות מזה צריך דוקא פס ד' או שני פסין שני משהויין כדין חצר וכנ\"ל סוף ד\"ה אלא:","(קא) על פני כל רחבו - דאם ישאר הפסק בין החקיקה ובין הכתלים לא יוכלו הכתלים להצטרף להן וכאין כתלים להמבוי דמי. אכן אם ההפסק בין החקיקה ובין הכתלים הוא רק פחות מג' טפחים י\"ל דמהני [פמ\"ג]:","(קב) שני חצרות - הטעם בזה משום דהא דהתירו במבוי בלחי וקורה מחמת דיש בו ריבוי דיורין ואין משתמשין בו בהצנע כ\"כ לפיכך סגי בתיקון כזה משא\"כ בחצר שאין מצוי בו דיורין כ\"כ משתמשין בו בהצנע טפי לכך צריך הכשר טפי שני פסין או פס ד\"ט ולכך ה\"נ במבוי שאין בו שני חצרות פתוחין דיוריהן מועטין ועושין בו תשמישי הצנע ולכן לא סגי בלחי וקורה:","(קג) ויש חולקין - דכיון דיכולין לערב יחד דרך הפתחים נחשבו כחצר אחת וה\"ה בבתים הפתוחים זה לזה וכתבו האחרונים דכיון שהוא מלתא דרבנן נקטינן לקולא:","(קד) ואוכל בביתו - לאפוקי אם דרך אכילתו בבית האב:","(קה) שיהא ארכו וכו' - שכן דרך המבוי להיות:","(קו) יותר על רחבו - אפילו משהו [וארכו מקרי דרך כניסתו למבוי ומה שאינו דרך כניסתו מקרי רוחב] דאם ארכו כרחבו הו\"ל כחצר וכדלקמיה:","(קז) אחד מאלו - קאי על כל מה שמבואר כאן מן אין מבוי ניתר וכו' וכן הדין לענין כשלא היה אורך המבוי ד\"א:","(קח) אינו ניתר וכו' - דדינו כחצר וע\"כ צריך לזה פס ד' טפחים וכו' וכדלעיל בס\"ב:","(קט) או צורת פתח - וזה מהני אפילו ברחב מעשר וכדלעיל בס\"ב:","(קי) כל המבואות וכו' - בין סתום מצד אחד בין מפולש משני הצדדין בין רחב עד עשר אמות בין יותר מעשר אמות:","(קיא) דכל המבואות שלנו וכו' - היינו משום דבמבואותינו אין בתים וחצרות פתוחות לתוכו ולכן אין ניתר בלחי וקורה כדין היתר מבוי ואף דבחצר סגי בשני לחיים משני הצדדים בלא צוה\"פ מ\"מ משום דלפעמים המבוי מפולש משני צדדין ואז בודאי צריך להחמיר בו שיצטריך צוה\"פ אף באין בתים וחצרות פתוחות לתוכו מחמת שבראשה פתוח לר\"ה או לכרמלית או שלפעמים רחב יותר מעשר דבזה אפילו בחצר צריך מדינא צוה\"פ וכנ\"ל בס\"ב לכן הנהיגו תמיד לעשות צוה\"פ. והנה לצד השני של מבוי אם אין רחב יותר מעשר אמות יש דעות בין האחרונים דדעת הרבה מהם דשם סגי עכ\"פ בשני לחיים משני הצדדים ולא בעי צוה\"פ וטעמם דממ\"נ אם דינו כמבוי מפולש הלא גם בו קי\"ל לקמן בסימן שס\"ד דא\"צ צוה\"פ רק מצד אחד ובצד השני סגי בלחי אחד או קורה ואם דינו כחצר וכנ\"ל הלא עכ\"פ די בשני לחיים ויש מאחרונים שמצדדין דמצד המנהג יש לעשות בכל צד צוה\"פ. ובודאי צריך לכתחלה ליזהר בזה אך במקום הדחק שנפסק החבל שע\"ג הלחיים בשבת או כל כה\"ג נראה דיש לסמוך עליהם להקל היכא שאין רחב יותר מעשר אמות אף דהוא פרוץ במילואו. והנה במבואות שלנו הנ\"ל שאין בתים וחצרות פתוחות לתוכו אם הוא מבוי עקום יש דעות בין האחרונים אם צריך לעשות תיקון בעקמימותו כדין המבואר לקמן בסימן שס\"ד ס\"ג דיש לומר כיון דמעיקר הדין יש לו דין חצר אין צריך שום תיקון שם ודי במה שעושה התיקון בשני ראשיו ויש מחמירין בזה והמנהג להקל ודע עוד דהא דמבואר דבעיירות שלנו צריך צוה\"פ היינו בעיירות שאינן מוקפות חומה או שמוקפין חומה והחומה נפרצה לר\"ה או לכרמלית ביותר מעשר אמות אבל כשמוקף חומה והחומה לא נפרצה רק שצריך לתקן ולחלק בין מקום שהיהודים דרים שם ובין מקום שהעו\"ג דרים שם כדי שלא יאסרו על היהודים לטלטל אין צריך לעשות שם צוה\"פ רק די בפס רחב ד' טפחים או שני פסין של שני משהויין כשנפרץ שם במלואו ואינו רחב שם יותר מעשר אמות במקום שרוצה לעשות התיקון (אף שהמבוי באמצע רחב יותר מעשר אמות) כי העיר הזו יש לה דין חצר לגמרי. וכשלא עשה שום תיקון בין יהודי לעו\"ג ג\"כ הדין כאן כמו בחצר דמותר לטלטל בכלים ששבתו בתוכו אבל לא לבית ולא מבית לחצר:","(קיב) תחת החבל וכו' - וכיון שהקנים שלמטה גבוהין עשרה טפחים א\"צ עוד קנים למעלה לקשור החבל בהן אלא יכול לקשור החבל נגדן אפילו בגג למעלה מזה ומזה וכדקי\"ל לעיל בסוף סימן שס\"ב דהקנה של מעלה א\"צ ליגע בקנים שלמטה. גם הא דמבואר לעיל בסוף סימן שס\"ב דאין לקשור הקנה של מעלה או החבל מן הצד של הקנים רק למעלה על גביהן הכא כשקושר החבל למעלה על הגג באיזה קנה לא שייך לדקדק באופן הקשירה אם ע\"ג או מצדו כל שהקנים שלמטה מכוונים תחת החבל כשר. אם יש גג שמפסיק בין גובה החבל להקנים שלמטה לא הוי צוה\"פ בזה כיון שהגג מפסיק בין החבל להקנים ואין עושין צוה\"פ בענין זה אלא צריך שיפתח נקב גדול בגג למעלה נגד הקנים בענין שיהיו הקנים מכוונים תחת החבל בלי הפסק:","(קיג) שני קנים - על הארץ אבל כותלי המבוי אין נחשבין במקום הקנים. ואם איכא עמוד בכותל בולט נידון משום קנה אם סמך עליו מע\"ש דלא גרע מלחי בסי\"א. וה\"ה כשיוצאים מהכותל חיפופים פחות פחות מג\"ט עד פחות מג\"ט סמוך לארץ יש לסמוך עליהם מע\"ש לשם קנים של צוה\"פ ובלבד שיהיו מגולים למעלה תחת החבל ויש מחמירין בחיפופים כאלה שאינם עשויים דרך מזוזת הפתח ולא חשיב פתח. אם מעמיד הקנים בתוך הבית או בתוך גדר המוקף מד' רוחותיו לאו כלום הוא ואפילו אם קנה אחד העמיד שם ג\"כ לא מהני:","(קיד) מכוונים תחת החבל - ואם משהו יוצא מן הצד פסול:","(קטו) בתורת צורת פתח - ר\"ל ומהני אפילו ביותר מעשר אמות:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"70\"></i>חצר שארכו יותר על רחבו דינו כמבוי וניתר בלחי או קורה: <small>הגה אע\"פ שאין חצירות ובתים פתוחין לתוכו הואיל ואינו קרוב לר\"ה אלא פתוח למבוי והמבוי פתוח לר\"ה: (ב\"י בשם תשובת מהרי\"א בשם סמ\"ק):</small>","m":["(קטז) שארכו יותר על רחבו - אפילו משהו [גמרא] וארכו מקרי דרך כניסתו. ואינו נידון משום חצר אלא אם ארכו ורחבו שוה או שרחבה יתר על ארכה [המ\"מ]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"71\"></i>מבוי <i data-commentator=\"Magen Avraham\" data-order=\"29\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>שאין ברחבו ג\"ט אינו צריך שום תיקון שהוא כסתום <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"72\"></i>וי\"א דכל שאין בו ד\"ט אין צריך שום תיקון:","m":["(קיז) שאין ברחבו ג' טפחים - וכתבו המפרשים דאם אין בפתחו רוחב ג' א\"צ תיקון אע\"פ שבתוכו רחב הרבה, וכן להי\"א דס\"ל דבעינן דוקא רוחב ד' ג\"כ מיירי שהיה רוחב ד' בכל הכתלים אבל היכי שמתקצר סמוך לפתחו א\"צ תיקון אפילו תוכו רחב הרבה. והנה מהמחבר משמע דס\"ל לעיקר כדעה ראשונה דהיכי שרחב ג' צריך תיקון ועיין בד\"מ שחולק ודעתו דנוכל להקל בזה כדעה אחרונה עי\"ש ולענ\"ד נראה דאף אם נחמיר כדעה ראשונה דהיכא שרחב ג' צריך תיקון היינו דוקא היכא שמבפנים היה עכ\"פ רחב ד' אלא שמתקצר בפתחו כנ\"ל אבל היכי שבכולו אינו רחב ד' בודאי יש להקל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"73\"></i><i data-commentator=\"Magen Avraham\" data-order=\"30\"></i>מבוי שצדו אחד כלה לים וצדו אח' כלה לאשפה של רבים <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"74\"></i>אין צריך כלום שאשפה של רבים אינה עשויה להתפנות ואין חוששין <i data-commentator=\"Turei Zahav\" data-order=\"20\"></i>שמא יעלה <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"9\"></i>הים <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>שירטון <small> (פי' יובש כעין אי שנדחו המים ממנו שנעשה ראוי לזריעה): הגה ויש חולקים וסוברים דחיישינן שמא <i data-commentator=\"Magen Avraham\" data-order=\"31\"></i>יעלה שירטון ואין כאן מחיצה (הרא\"ש ורש\"י וטור והמגיד):</small>","m":["(קיח) כלה לים - ר\"ל שהיה להמבוי שני צדדים מבתים וחצרות ושני ראשיה שממזרח וממערב אחד היה כלה לים ואחד היה כלה לאשפה שגבוה יו\"ד טפחים מן הקרקע ועל כן אינו צריך כלום שגם הים נחשב למחיצה שעמוק יו\"ד טפחים בשפתו והמים אינם מבטלין המחיצה כמש\"כ סימן שנ\"ו וכתב המ\"א דהכא מיירי במקום שאין הספינות עוברות שם לנמל דאל\"ה אתו רבים ומבטלי מחיצתא אבל כמה אחרונים פליגי ע\"ז וס\"ל דאפילו כשהספינות עוברות שם לא נתבטל עי\"ז שם מחיצה משפת הים. [אכן כשראש אחד מן המבוי כלה לנהר ויש גשר עליו שמהלכין בו רבים לעבר השני משמע מכמה אחרונים דע\"י הגשר מתבטל המחיצה וצריך לעשות צורת הפתח במקום הגשר]. וכל זה דוקא כששפת הים או הנהר היה עמוק עשרה טפחים אבל אם שפת הים והנהר משופע והולך אם כשהולך השיפוע ד' אמות עדיין אינו גבוה יו\"ד טפחים אינה מחיצה דכקרקע שוה דמי:","(קיט) אינה עשויה להתפנות - שהרי כל היום משליכין שופכיהן וזבליהן שם ולא תחסר גובהה אבל אשפה דיחיד אע\"ג דהשתא גבוה יו\"ד טפחים למחר ינקנה ויחסר גבהותה ואם נתיר עתה לטלטל יטלטל גם אח\"כ כשיחסר גבהותה:","(קכ) ואין חוששין וכו' - ר\"ל שגם אין חוששין שמא יתקלקל המחיצה שלצד הים ונמצא שאין למבוי מחיצה רביעית:","(קכא) יעלה הים שרטון - שכן דרך הים שמעלה חול ואבנים אצל שפתו ומתקצר ונעשה קרקע ברוחב פרסה ובטלי המחיצות ומטלטלי נמי במבואות כדמעיקרא [וכ\"ז כשאין מדרון אלא במקום המים בלבד אבל אם יש על שפתו מדרון המתלקט עשרה טפחים מתוך ד' אמות ה\"ז נחשב למחיצה בכל ענין] והסכימו האחרונים להחמיר כדעה זו ודוקא בימים אבל בנהרות לא חיישינן שיעלה שירטון ונחשב שפת הנהר למחיצה כשיש בגובהו יו\"ד טפחים [אכן הנהרות שדרכן להתייבש בקיץ וכשמתיבשין אין במדרון שלהם גבוה יו\"ד טפחים מתוך ד\"א יש לאסור בלא תיקון אפילו כשלא נתייבש דחיישינן שיתייבש ולאו אדעתיה] ועכ\"פ בעינן שיהא הנהר סמוך ממש לראש המבוי אבל אם הוא רחוק מהבתים יותר מעשר אמות צריך תיקון דאותו מקום הוי פרוץ ואם נקרשין בימות הגשמים בטלה אז המחיצה ואסור לטלטל ויש מאחרונים שסוברין דלא נתבטל המחיצה ע\"י הקרישה. ואם שפת הנהר גבוה ומתלקט עשרה טפחים מתוך ארבע אמות עד מקום הקרישה בודאי יש להקל:","(קכב) ואין כאן מחיצה - וע\"כ צריך תיקון כשאר מבוי הפרוץ ברוח רביעית בצורת הפתח או בלחי או בקורה. עיר שמוקף סביבה חריץ שעמוק עשרה טפחים ורחבה ארבעה טפחים הוי כמוקף חומה סביבה וא\"צ שום תיקון ואם יש גשר ע\"ג החריץ שהולכין דרך שם למבואות העיר נתבאר למעלה שצריך לעשות שם תיקון:","(קכג) שצדו אחד ארוך - ונמשך כותלו לר\"ה יותר מכותל השני:","(קכד) אפילו אין צד וכו' ארבע אמות - וה\"ה אפילו פחות מזה ג\"כ אין מניח אלא כנגד הקצר דוקא ולא באלכסון והטעם דקורה משום היכר עשויה כדי דלא ליתי למיחלף בר\"ה ובאלכסון לא הוי היכר והיינו דאם יניחו באלכסון וישתמש בצד הארוך נגד הארוך שאין דופן כנגדו הרואה זה יאמר שמותר להשתמש בר\"ה לפי שאין אותו עודף דומה שיהא מן המבוי וזהו הטעם דהתיר אח\"כ בשו\"ע להניח הקורה בתוך המבוי באלכסון ששם לא יבואו עי\"ז לטעות להתיר להשתמש בר\"ה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"75\"></i>מבוי <i data-commentator=\"Magen Avraham\" data-order=\"32\"></i>שצדו א' ארוך וא' קצר אפי' אין צד הארוך עודף על הקצר ד' אמות אינו מניח הקורה <i data-commentator=\"Turei Zahav\" data-order=\"21\"></i>אלא כנגד הקצר <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"76\"></i>אבל אם ירצה יעשה שם צורת פתח באלכסון <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"77\"></i>ותוך המבוי יכול להניח הקורה באלכסון ומשתמש בקצר כנגד הקצר ובארוך כנגד הארוך:","m":["(קכה) יעשה שם צו\"פ באלכסון - וישתמש בקצר כנגד קצר ובארוך כנגד הארוך והטעם דצו\"פ הוי כמו מחיצה גמורה ומחיצה גמורה בודאי מהני אפילו באלכסון ואפילו היה רחב פתח המבוי יותר מעשר אמות ג\"כ מותר ע\"י צוה\"פ כדלעיל בריש סכ\"ו אבל אם יעמיד לחי אחד אצל הארוך ולחי אחד אצל הקצר אינן מועילים להשתמש באלכסון ואפילו לא היה האלכסון יותר מעשר אמות שאף שהלחי אינו משום היכר בלבד אלא משום מחיצה מ\"מ לחי שבצד הארוך אינו מועיל להתיר להשתמש אצלו הואיל ואין שם מחיצה כנגדו ואינו מותר להשתמש אלא נגד הלחי שעומד בצד הקצר שהוא מתיר רק נכחו ביושר. אמנם זהו דוקא במבוי שמותר בלחי אחד אבל בחצר שצריך שני פסין או במבואות שלנו שיש להן דין חצרות אפילו עד מקום הקצר ג\"כ אינו מותר להשתמש אחרי שלא נוכל לצרף אליו הלחי האחר שאינו עומד נגדו וע\"כ צריך ליזהר במקום שמעמיד שני לחיים שיעמידם בשוה זה נגד זה ולא באלכסון [ח\"א] ובצורת הפתח מהני אפילו באלכסון וכנ\"ל. כתב בחידושי הרשב\"א דצוה\"פ מהני אפילו היה צד אחד עודף על חבירו ד' אמות ויותר דהוא כמו מחיצה גמורה:","(קכו) יכול להניח וכו' - עיין בט\"ז שמצדד דדוקא אם באלכסון אינו יותר מעשר אמות דאל\"ה אסור ועיין בבה\"ל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"78\"></i>העמיד לחי באמצע המבוי <i data-commentator=\"Turei Zahav\" data-order=\"22\"></i>אם יש חצר מתחלתו ולחוץ ועשו גם החיצונים לחי לראש המבוי אוסרים אלו על אלו עד שיערבו יחד ואם אין שם חצר או שיש חצר <i data-commentator=\"Magen Avraham\" data-order=\"33\"></i>ולא עשו החיצונים לחי לראש המבוי שמן הלחי ולפנים מותרים ממנו ולחוץ אסורים <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"79\"></i><i data-commentator=\"Turei Zahav\" data-order=\"23\"></i>אבל אם עשו <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>באמצע <i data-commentator=\"Magen Avraham\" data-order=\"34\"></i>שני פסים או פס ארבעה אם אינו רחב יותר מעשרה או שעשו צורת פתח אם הוא רחב יותר מי' אפי' אם יש חצר מהתיקון ולחוץ ועשו גם החיצונים תיקון לראש המבוי כל אחד יכול לערב ויהיה מותר בחלקו:","m":["(קכז) עד שיערבו יחד - ר\"ל שישתתפו יחד. וטעם הדבר דהנה דרך המבואות לאחר שתקנום בלחי או קורה להשתתף כל הדרים במבוי יחד [דכשלא ישתתפו יהיו אסורים להוציא מהחצרות למבוי] וכיון שההרגל כן הוא שוב אסורים בני מבוי ליחלק לחצאין ולעשות כל אחד שיתוף בפ\"ע דאסרי הני אהני משום דהוי כמבוי ששכח אחד מן החצרות ולא נשתתפה בו דאסרה אכולה:","(קכח) ולא עשו וכו' - דכיון שלא עשו לחי ואין יכולין לטלטל במבוי א\"כ אינם ראוים להשתתף יחד לכן אין בכחן לאסור על הפנימית ואפילו יש להם דריסת הרגל עליהם [פמ\"ג]:","(קכט) ממנו ולחוץ אסורים - דחשבינן כאלו המבוי הותחל מן הלחי ולפנים:","(קל) אבל אם עשו באמצע וכו' - בזה מתחלקים הרשויות מהדדי והוי כאלו מחיצה ביניהם ואין יכולין לאסור אלו על אלו ודוקא כשאין להם דריסת הרגל זה על זה כגון שיש להם פתח אחר אבל בלא\"ה אפילו דלת לא מהני:","(קלא) שני פסים - של משהויין משהו מכאן ומשהו מכאן. ואפילו חצר יכולין לחלק בכה\"ג עיר המוקפת חומה וננעלו הפתחים בלילה ופתח אחד אין ננעל ומ\"מ הוי כלחי ע\"י פתח ההוא אין מערבין אותה לחצאין אבל אם נפרץ פרצה בטל הכשרה [ועיין סי' שס\"ה ס\"ב ע\"י איזה פרצה בטל ההכשר] של העיר ויכולין לערב חציה ולהניח חציה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"80\"></i>זה שהכשרנו להעמיד לחי באמצע המבוי הוא הדין להעמיד קורה באמצע המבוי <i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"81\"></i>וכל זה ביש באותו חצר מבוי המוכשר תורת מבוי שלא יהא ארכו פחות מד' אמות ושיהא ארכו יתר על רחבו ושיהיו בתים וחצרות פתוחים לתוכו הא לאו הכי צריך פס משהו מכאן ופס משהו מכאן או פס ארבעה בצד אחד:","m":["(קלב) וכל זה ביש וכו' - האי וכל זה קאי אמה שהכשרנו בהעמיד לחי באמצע המבוי כשלא עשו לחי בראש המבוי וקאמר דהוא דוקא שבחצי המבוי זה לבד ג\"כ יש עליו שם מבוי דיש לו כל התנאים הצריך לזה [וכדמסיים השו\"ע וכמ\"ש לעיל בסכ\"ו] הא לא\"ה יש לו דין חצר וצריך פס משהו וכו' וכדלעיל בס\"ב ולא קאי השו\"ע באם עשו גם לחי בחוץ וערבו יחד דע\"ז לא צריך שבאותו חצי המבוי יהיו לו כל הפרטים דמצטרף כל המבוי ביחד לזה [פמ\"ג] וע\"ש מה שכתב עוד בזה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"82\"></i>מבוי שהוא רחב כ' אמות עושה <i data-commentator=\"Magen Avraham\" data-order=\"35\"></i>פס רחב ד' אמות <i data-commentator=\"Turei Zahav\" data-order=\"24\"></i>ומעמידו באמצע וחשוב כל צד מצדי הפס כמבוי בפני עצמו כיון שאורך הפס ד' אמות ויתן קורה בראשו <i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"83\"></i>וצריך ליזהר שתהא הקורה מונחת על הפס או תוך ג\"ט וצריך שיהא בכל מבוי משני אלו שהפס מפסיק ביניהם בתים וחצרות פתוחים לתוכו <i data-commentator=\"Turei Zahav\" data-order=\"25\"></i>וכל תנאי <small> (מבוי) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"84\"></i><i data-commentator=\"Turei Zahav\" data-order=\"26\"></i>ומה <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i>שמן הפס עד כותל האמצעי של מבוי יש לו דין מבוי עקום שהרי אלו שני המבואות מתעקמים ובאמצע פתוחים בשני ראשיהן לרשות הרבים: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"36\"></i>ויש אומרים דאין לו דין מבוי עקום אא\"כ יש מן הפס עד כותל האמצעי יותר מעשר אמות (הרא\"ש ור' ירוחם וטור):</small>","m":["(קלג) שהוא רחב כ' אמות - ומיירי שאינו רוצה לעשות צוה\"פ בפתח המבוי דזה מהני אפילו רוחב המבוי כמה כדלעיל בסוף סכ\"ו:","(קלד) רחב ד\"א - ובפחות מכאן לא מהני אע\"פ שכל צד הוא פחות מיו\"ד דאתי אוירא דהאי גיסא ודהאי גיסא ומבטל ליה משא\"כ כשעושהו רחב ד\"א כשיעור משך כותל מבוי וכנ\"ל בסכ\"ו אין אויר שמכאן ומכאן יכול לבטלו שאין אויר יכול לבטל כותל מבוי. ומש\"כ ומעמידו באמצע היינו לארכו של מבוי:","(קלה) כיון שאורך וכו' - וצריך ג\"כ שלא יהיה הפס נמוך מעשרה טפחים וכדין כותל של מבוי וכנ\"ל בסכ\"ו:","(קלו) בראשו - היינו שיגיע מכותל אחד של מבוי עד הכותל שכנגדו כדי להתיר שני הצדדים וה\"ה שיכול לתקנן ע\"י לחיים לחי מכאן ולחי מכאן או לחי באחד וקורה באחד [היינו שראש אחד על כותל המבוי וראשו השני על הפס] כשאר מבואות:","(קלז) מונחת על הפס וכו' - לאפוקי אם הפס נמוך אף שהקורה מגעת מכותל זה עד הכותל שכנגדו לא מהני דהרי ע\"י הפס נחשב כשני מבואות דהוא חשוב ככותל וא\"כ כל מבוי אין הקורה שלו מונח רק על כותל אחד:","(קלח) או תוך וכו' - דהוי כלבוד:","(קלט) וכל תנאי מבוי - המבואר לעיל בסכ\"ו דלא\"ה דינו כחצר ואין קורה מועיל בו אלא שני לחיים של משהו בשני צדיו כמבואר לעיל בס\"ב:","(קמ) ומה שמן הפס וכו' - ר\"ל חוץ תיקון הקורה שעושה בפתח המבוי צריך לעשות עוד תקון בסוף אורך הפס כדין מבוי עקום המבואר בסימן שס\"ד סוף ס\"ג ואפי' אין שם עשר אמות מן סוף אורך הפס עד כותל האמצעי:","(קמא) מתעקמים ובאמצע פתוחים - צ\"ל מתעקמים באמצע ופתוחים:","(קמב) בשני ראשיהן לר\"ה - וע\"כ צריך לעשות צוה\"פ בסוף אורך הפס עד כותל האמצעי כנגדו ודמי כמו שהיה עושה פס לאורך כל המבוי:","(קמג) דאין לו דין מבוי עקום וכו' - דאע\"ג דמבואר לקמן בסימן שס\"ד במבוי עקום שעשוי כמין חי\"ת אפילו אין מפתיחת עקמימותו עד כותל האמצעי עשר אמות נמי צריך שם תיקון שאני התם דהוא עקום ממש אבל הכא יש לומר שע\"י הפס נעשים כשני מבואות שמחולקים לגמרי עד סופם ואף דאין הפס מגיע עד כותל האמצעי מ\"מ כיון דאין מן סוף הפס עד כותל שכנגדו יותר מיו\"ד אמות נחשב כפתח ודמי כשני מבואות שמחולקים לגמרי אלא שיש פתח מאחד לחבירו משא\"כ ביותר מעשר אמות א\"א לומר דהוי כפתח וע\"כ דינו כמבוי עקום ולדינא הסכימו האחרונים דהעיקר כסברא הראשונה ועיין בבה\"ל:","(קמד) יותר מעשר אמות - כצ\"ל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"85\"></i>עוד אפשר לעשות תיקון אחר למבוי שהוא רחב כ' אמות שירחיק ב' אמות מהכותל <i data-commentator=\"Turei Zahav\" data-order=\"27\"></i>ויעשה <i data-commentator=\"Magen Avraham\" data-order=\"37\"></i>פס רחב שלש אמות ויעשה כן גם בצד השני וישאר פתח רחב עשר אמות או ירחיק אמה ויעשה פס אמה ומחצה וירחיק אמה ויעשה פס אמה ומחצה וכן יעשה בצד השני <i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"86\"></i>או ירחיק שתי אמות ושני טפחים ויעשה פס שתי אמות וד' טפחים וכן יעשה בצד השני וכן כל כיוצא בזה ובלבד שהפס יהא יתר על האויר שבינו לכותל דאם לא כן אתי אוירא דהאי גיסא ודהאי גיסא ומבטל ליה וצריך ליזהר <i data-commentator=\"Magen Avraham\" data-order=\"38\"></i>דלא לשביק פתחא רבא ועייל בזוטא שאם <i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"87\"></i>עשה כן בטל תיקון המבוי אלא אם עשה צורת פתח לזוטא:","m":["(קמה) ויעשה פס רחב ג\"א - דנעשה עי\"ז עומד מרובה על הפרוץ שבצדו ונחשב כסתום ואע\"ג דבעלמא קי\"ל דפרוץ כעומד נמי שרי כמבואר בשס\"ב ס\"ט שאני הכא דהוא פרוץ גם מצד השני ובכגון זה דשוין אמרינן אתי אוירא דהאי גיסא ודהאי גיסא ומבטל ליה:","(קמו) וישאר פתח רחב עשר אמות - ומ\"מ צריך לחי או קורה להתיר המבוי דלא עדיף משאר מבואות דעלמא. ונותן הקורה רק על שטח העשר אמות [וכן כשעושה הלחי יעמידו בראש העשר אמות] דמן הפסין ולהלן עד הכתלים ניתרין בלא\"ה משום עומד מרובה על הפרוץ:","(קמז) וכן כל כיו\"ב - דהיינו שירחיק ארבע אמות מהכותל ויעשה פס של שש אמות [רש\"י]:","(קמח) וצריך ליזהר וכו' - אבל מן הסתם אין חוששין שמא ילכו בקטן ויניחו הגדול שחזקה אין אדם מניח פתח גדול ונכנס בקטן:","(קמט) שאם עשה כן וכו' - ר\"ל שעי\"ז יתבטל תורת פתח מן הגדול ובטל הלחי או הקורה המתוקן בו ונמצא מבוי זה בלא תיקון:","(קנ) לזוטא - עיין בחידושי רע\"א שמתמה מאי מהני במה דעושה צוה\"פ לזוטא אחרי שנתבטל תורת פתח מן הגדול והנכון כמו שכתב בספר תפארת שמואל שט\"ס הוא וצ\"ל לרבא והשתא אתי שפיר דאחרי שנעשה צוה\"פ לא נתבטל שם פתח ממנו אף אם לא ילכו בו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ת\" data-order=\"88\"></i>פס זה שאמרנו שעושה כן למעט רוחב המבוי א\"צ שיהא פס א' שלם אלא בקנה קנה פחות מג' סגי דפחות מג' כשלם דמי:","m":["(קנא) כשלם דמי - ר\"ל וע\"כ אין שייך לומר בזה אתי אוירא דהאי גיסא ודהאי גיסא ומבטל ליה:","(קנב) ומדרון לר\"ה - שהיה קרקע המבוי גבוה מקרקע ר\"ה והוצרך לשפע אצל פתחו לצד ר\"ה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"89\"></i>מבוי ששוה מתוכו ומדרון <small> (פי' מקום משופע) </small> לרה\"ר או ששוה לרה\"ר ומדרון לתוכו אם הולך ומתלקט מעט מעט עד שמגביה י' <i data-commentator=\"Turei Zahav\" data-order=\"28\"></i>מתוך ד' אמות הרי הוא כאלו זקוף כולו וא\"צ שום תיקון <i data-commentator=\"Magen Avraham\" data-order=\"39\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"12\"></i><small> (ובזה התל <i data-commentator=\"Magen Avraham\" data-order=\"40\"></i>הוי כמחיצה) (ב\"י) <i data-commentator=\"Be'er HaGolah\" data-label=\"•\" data-order=\"90\"></i>:</small>","m":["(קנג) או ששוה לר\"ה וכו' - שהיה ר\"ה גבוה מקרקע המבוי וכניסת המבוי נמי מן הפתח ולפנים גבוה כקרקע ר\"ה ברוחב אמה או חצי אמה ואח\"כ הוא נעשה מדרון לצד דופן האמצעי:","(קנד) שמגביה עשרה וכו' - ר\"ל שאם השיפוע ארכה ד' אמות אז כבר הוגבה הקרקע למעלה עשרה טפחים הוי כמחיצה אבל אם מתלקט יו\"ד מתוך ה' אמות כמאן דליתא דמיא וכשאר קרקע דמיא דניחא תשמישתיה להילוך:","(קנה) ואינו צריך שום תיקון - דאותו גובה שבצד הפתח הו\"ל מחיצה אע\"פ שהוא משפע והולך וזהו שמסיים רמ\"א ובזה התל וכו':","(קנו) ובזה התל וכו' - ואם כל העיר מוקפת תל ואח\"כ בנו בה בתים אסור דלא הוי מוקף לדירה וכמש\"כ סימן שנ\"ח ס\"ב וע\"ש ס\"ח דאפילו בנה מחיצות גבוה יו\"ד על התל לא מהני ואם התל היה פחות מיו\"ד טפחים והשלים עד יו\"ד טפחים מהני דזה ההיקף הוי מוקף לדירה דנעשה אחר שנבנה העיר. וע\"כ יכול לתקן אפילו אם היה התל סביב העיר כולו דהיינו שיפחות מהתל בשטח יותר מעשר אמות ברוחב עד שלא יהיה בגובה עשרה טפחים דבזה חשוב כפרצה ואח\"כ ישלים זה השיעור ובזה מהני וכדלעיל בסימן שנ\"ח ס\"ב ע\"ש:","(קנז) כמחיצה - ואם יש סביב העיר חריץ עמוק יו\"ד טפחים ורוחב ד' טפחים דהוי כמחיצה ונסתם החריץ ע\"י עפר וצרורות אם אין הסתימה עולה ביותר מעשר אמות הרי הוא כפתח ואינו אוסר אבל אם הוא יותר מעשר אמות הרי הוא כפרצה:\n"]}],"364":[{"s":"<b>דין מבוי המפולש ועשוי כנדל. ובו ה סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i> מבוי המפולש בשני ראשיו לרה\"ר או צד א' לרה\"ר וצדו השני לכרמלית <small>הגה או שני ראשיו פתוחין לכרמלית (ריב\"ש סימן ת\"ה) </small> <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>צריך צורת הפתח מכאן ולחי או קורה מכאן <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אבל אם צדו א' פתוח לרה\"ר וצדו השני לחצר שאינה מעורבת אין צריך אלא לחי <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>או קורה בשני ראשיו: <small>הגה וכל זה יש לו תנאים המבוארים לעיל סי' שס\"ג סכ\"ז בדין מבוי אבל אם אינו רק בחצר צריך תיקון חצר <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>משני צדדיו:</small>","m":["(א) מבוי המפולש וכו' - ומיירי שאותו המבוי לא היה ברחבו שיעור ר\"ה ועיין לעיל סימן שמ\"ה ס\"ח וטי\"ת ובמ\"ב שם:","(ב) צריך צורת הפתח וכו' - והטעם דע\"י צורת הפתח נעשה כסתום במחיצה מההוא צד והוי כמבוי סתום מג' צדדין וסגי בצד השני בלחי או קורה:","(ג) וצדו השני לחצר וכו' - דכיון דהחצר יש לו מחיצות הרי אין המבוי מפולש וא\"צ צורת הפתח אלא לחי או קורה כדי לחלק בין דיורי החצר למבוי שלא יאסרו אלו על אלו ויש מחמירין דדוקא לחי לצד החצר בעינן ולא קורה וכ\"ז כשהחצר אינה רגילה במבוי זה כגון שיש לה פתח למבוי אחר אבל אם היא רגילה בו מכבר אפילו צורת הפתח ודלתות אינן מועילות להתיר שם אם לא נשתתפה מבוי זה עם שארי החצרות הפתוחות לו ואם נשתתפה בו א\"צ לערב כלל כמ\"ש בסימן שפ\"ז:","(ד) אבל אם אינו וכו' - ר\"ל כשאין להמבוי תנאין המבוארים לעיל ממילא דינו רק כחצר וע\"כ אפילו אם היה מפולש משני צדדין לר\"ה ורבים נכנסין דרך אותו החצר לר\"ה אין צריך רק תיקון חצר משני צדדין דהיינו מכל צד שני פסין או פס רוחב ד':"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>רשות הרבים עצמה אינה ניתרת אלא בדלתות <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>והוא שננעלות בלילה <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ויש אומרים אע\"פ שאינן ננעלות אבל צריך שיהו ראויות לינעל שאם משוקעות בעפר מפנה אותן ומתקנן שיהיו ראויות לינעל ואחר שעשה לה תיקון דלתות חשיבא כולה כחצר אחד ואין מבואותיה צריכים תיקון:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>מבוי עקום <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>כמין דלי\"ת דינו כאילו היה <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"1\"></i>מפולש בעקמימות וצריך צורת פתח בעקמימותו ובשני ראשיו לכל א' לחי או קורה או צורת פתח בכל א' משני ראשיו ולחי או קורה בעקמימות <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>ואם עשוי כמין <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>חי\"ת צריך צורת פתח בשני עקמימותו ולחי או קורה בשני ראשיו:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>מבואות הפתוחי' אלו לאלו ואין העיקום של א' מהם נוטה לרה\"ר כיון שפתיחת המבוי החיצון לר\"ה הרי אותו מבוי שפתוח אליו בעקמימותו חשיב כפתוח לרשות הרבים וכן מבוי הפתוח לאותו מבוי וכן כולם:","m":["(ה) ר\"ה עצמה - דהיינו רחובות ושווקים הרחבים ט\"ז אמה ומפולשים משער לשער וכדלעיל בסימן שמ\"ה ס\"ו ועי\"ש בס\"ח וטי\"ת דיש עוד מיני ר\"ה:","(ו) אלא בדלתות - מכאן ומכאן דעי\"ז נעשית כחצר של רבים אבל צורת הפתח לא מהני [אפילו אם יעשהו משני צדדיו] ויש פוסקים דס\"ל דסגי בדלת מצד אחד כשננעלת בלילה דאין זה ר\"ה כיון שמונע רבים מלעבור משער לשער וסגי מצד השני בלחי או קורה וכמו בעלמא היכא שיש ג' מחיצות שלימות:","(ז) שננעלות בלילה - שעי\"ז נתבטל ממנה שם ר\"ה שאינה דומה לדגלי מדבר שהיה פתוח כל שעה:","(ח) וי\"א וכו' - מדהעתיק המחבר דעה ראשונה בסתמא ודעה השניה בשם י\"א משמע דדעתו כדעה הראשונה. והנה מדברי השו\"ע מוכח דאין מערבין ר\"ה כ\"א בדלתות. ובעיירות שלנו שמנהג העולם לתקן ע\"י צורת הפתח אף שרחובותיה רחבין הרבה ומפולשין משער לשער וגם פעמים רבות הולך דרך המלך תוך העיר ומדינא הוי ר\"ה גמור עי\"ז וכדלעיל בסימן שמ\"ה וע\"כ דסומכין על הי\"א שבסימן שמ\"ה דר\"ה לא הוי אא\"כ ששים רבוא בוקעין בו וזה אין מצוי [פמ\"ג] אמנם באמת הרבה ראשונים חולקין על הי\"א הנ\"ל כמו שכתבנו שם בסימן שמ\"ה וע\"כ אף דאין למחות לאחרים הנוהגין להקל ע\"י צורת הפתח שכן נהגו מעולם ע\"פ דעת הפוסקים המקילין בזה מ\"מ כל בעל נפש יחמיר לעצמו שלא לטלטל ע\"י צורת הפתח לבד ועיין בביאור הלכה:","(ט) עקום כמין דלי\"ת - והיה פתוח משני ראשיו לר\"ה או לכרמלית:","(י) כאלו היה מפולש - אחרי שעוברין מצד זה לצד זה לר\"ה:","(יא) בעקמימותו - דהפילוש שהוא מפולש לחבירו דומה כאלו מפולש לר\"ה ולכרמלית אותו מקום וע\"כ צריך לעשות שם בעקמימות צוה\"פ וכדמסיים:","(יב) ולחי או קורה בעקמימות - ואין להקשות מאי גריעה זה מאלו היה מפולש משני צדדיו ביושר דהיה די בצוה\"פ מצד אחד ולחי או קורה בקצה השני די\"ל דכיון דהפילוש שבאמצע נראה משני הצדדים צריך לסתמו שלא יראה לא מצד זה ולא מצד זה. והנה במבואות שלנו שיש להם דין חצרות כמבואר לעיל בסימן שס\"ג סכ\"ו ע\"כ דעת כמה אחרונים דאף אם הם עקומות ומפולשות משני צדדיהן לר\"ה א\"צ שום תיקון בעקמימות כמ\"ש לעיל בסימן הנ\"ל במ\"ב ס\"ק קי\"א ע\"ש ונוכל לסמוך ע\"ז להקל כמו שביררנו בה\"ל:","(יג) בשני עקמימותיו - דחשבינן לכל עקמימות כאלו הוא מפולש אחרי שבם עוברין מצד זה לצד זה לר\"ה. וה\"ה שיכול לעשות שני צורות הפתח בשני ראשיו ושני לחיים בשני עקמימות:","(יד) הפתוחים אלו לאלו - ר\"ל אף דדין מבוי עקום הוא בשני מבואות שראשיהן פתוחות לר\"ה דוקא וכאן יש הרבה מבואות קטנים שנכנסות אלו באלו ואלו באלו ואין בהם פילוש לר\"ה אפ\"ה כיון שקצה מבוי האחרון פתוח לר\"ה וכן תחלת מבוי הראשון חשובות כולם כמפולשין וצריך תיקון בכל עקמומית של כל אחד מהן:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>מבוי העשוי <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>כנדל דהיינו <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>מבוי גדול שהרבה מבואות קטנים פתוחים לו וראשי השניים פתוחים לרה\"ר <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>אפילו אין פתחי הקטנים שמכאן ומכאן מכוונים זה כנגד זה עושה לכל א' במקום פתיחתו למבוי גדול צורת פתח ובראשו השני הפתוח לרה\"ר לחי או קורה <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>ובמבוי הגדול אם הוא מפולש עושה צורת פתח מצד א' ומצד השני לחי או קורה ואם הוא סתום עושה לחי או קורה בראשו:","m":["(טו) העשוי כנדל - הוא שרץ שיש לו רגלים הרבה משני צדדיו ואינם מכוונים זה כנגד זה כן הוא מבוי זה שפתוחין לו מבואות קטנים הרבה משני צדדיו זה שלא כנגד זה:","(טז) וראשי השניים - צ\"ל וראשם השניה והיינו שכל אחד ואחד מהמבואות הקטנות שראשו אחד פתוח למבוי הגדול ראשו השניה פתוח לר\"ה וה\"ה לכרמלית:","(יז) אפילו אין וכו' - מלשון המחבר משמע דגם במכוונים הפתחים של מבואות הקטנות זה כנגד זה ג\"כ צריך תיקון במקום פתיחתן למבוי הגדול ואין לחשבן כמבוי אחד ארוך מפולש ביושר דהא מ\"מ כל אחד כמבוי עקום הוא עם הגדול:","(יח) עושה לכל אחד וכו' - היינו בכל מבואות הקטנות שמצד זה וכן מצד השני וה\"ה אם ליכא מבואות קטנות אלא מצד אחד של מבוי הגדול ג\"כ צריך תיקון זה:","(יט) במקום פתיחתו וכו' - אזיל לטעמיה שפסק לעיל דמבוי עקום צריך תיקון במקום עקמימותו והכא כל אחת מהמבואות הקטנות בכלל מבוי עקום הוא שנכנס ממנה למבוי הגדול וממנו יוצא לר\"ה:"]}],"365":[{"s":"<b>דין מבוי שנפרץ. ובו ח סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מבוי שנפרץ בו פירצה <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>מצידו <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>כלפי ראשו <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>אם נשאר <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>עומד בראשו פס רחב ארבעה טפחים מותר והוא שלא תהא הפרצה יתר על י' ואם לא נשאר פס ד' <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>אסור אלא אם כן היתה הפרצה פחות מג\"ט:","m":["(א) מצדו כלפי ראשו - פי' המבוי היה מתוקן בלחי או בקורה ונפרץ אחד מהכתלים שבצד ארכו כלפי ראשו סמוך ללחי או לקורה:","(ב) אם נשאר וכו' ארבעה טפחים - שעדיין נשאר שיעור חשוב במבוי לכן לא בטיל הפתח הגדול ואע\"ג דבעלמא שיעור אורך מבוי לא פחות מד\"א וכנ\"ל בסימן שס\"ג סכ\"ו היינו אם נעשה מבוי בתחלה אבל כאן שכבר היה מבוי אלא שנסתר די בארבעה טפחים שנשאר ממנו:","(ג) והוא וכו' עשר - אמות דעד שיעור זה הוא בכלל פתח יתר מכאן חשוב פרצה וצריך לסתום או לעשות צוה\"פ במקום הזה [ריטב\"א]:","(ד) אסור אלא אם כן וכו' - דאע\"ג דבפחות מיו\"ד אמות מקרי פתח הכא חיישינן דלמא שבקי בני המבוי פתח המבוי וילכו בפתח זו לקצר דרכם ובטל ליה תיקון דלחי או קורה שהם צריכין להיות בפתח המבוי והוא אין שם פתח מבוי עליו:","(ה) פחות מג\"ט - דחשוב כסתום:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>נפרץ מצדו <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>שלא כלפי ראשו שיעורו בעשרה אפי' לא נשתייר מן הכותל ביסוד כלום <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>והוא <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>דלא <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"2\"></i>בקעי בה רבים <small> (אבל אי בקעי בה רבים אפילו לא נפרץ רק ד\"ט צריך לתקנו שם) (הרי\"ף והרא\"ש וטור):</small>","m":["(ו) נפרץ מצדו - היינו דלא נפרץ סמוך לראשו אלא בפנים ממנו וא\"כ קשה דהיינו דינא דס\"א דנשתייר פס ד' טפחים ולמה להמחבר למיהדר ולמיתני ותירצו האחרונים דסעיף זה אינו אלא פרטו ופירושו של הדין הראשון דכל שנשאר פס ד' בראשו הוי נפרץ שלא כלפי ראשו ומשום סיפא נקטיה והוי כאלו אמר בס\"ב דהא דאמרינן בס\"א דאם נשאר פס ד' מותר עד יו\"ד אמות היינו אפילו לא נשאר מן הכותל ביסוד כלום ומיהו לא שרי אלא היכי דלא בקעי בה רבים:","(ז) שלא כלפי ראשו - וה\"ה כשנפרץ בראשו ממש כגון שהמבוי סתום משלשה רוחות וקצת מרוח רביעית ותיקון המבוי היה ע\"י לחי או קורה [שהיה מונח ממקום הסתימה עד הכותל שכנגדו] ונעשה פרצה במקום הסתימה שרי עד עשר אמות כל שעומד הנשאר מרובה על הפרוץ וי\"א דהכא שיש פרצה ברוח רביעית בעינן שיהיה מונח הקורה דוקא על כותלי המבוי מקצה אל הקצה אבל רוב האחרונים הסכימו דמה שמונח על מקום העומד הנשאר כאלו היה מונח על כותל המבוי דגם זה שייך להמבוי ומה שיש פרצה בינתיים נתבטל לגבי העומד וה\"ה אם עושה שם לחי די וא\"צ לחי סמוך לבית:","(ח) אפילו לא נשתייר וכו' - ר\"ל ואין עיכוב לעבור דרך אותו מקום אפ\"ה לא גזרינן משום דלמא שבקי פתחא רבא ועיילי דרך אותו מקום ובטל פתח הגדול:","(ט) דלא בקעי בה רבים - פי' שהיה מקום מטונף או מקולקל בטיט ואין דרך רבים לעבור באותה מחיצה וכ\"ש אם נשתיירו מן הכותל ביסוד ג' או ד' טפחים גובה ע\"פ כל הפרצה דזה בודאי מעכב הילוך בני אדם:","(י) אבל אי בקעי וכו' - דשוב אינו נקרא פתח רק דרך הרבים [לבוש] והנה בס\"ג מבואר דלענין חצר תמיד שיעור פרצתו בעשרה אפילו בקעי בה רבים ומסתפק המ\"א דלפי מה דמבואר בסימן שס\"ג סכ\"ו בהג\"ה דמבואות שלנו דין חצרות יש להם אפשר דגם לענין זה דין חצרות יש להם וה\"ה בעיר המוקפת חומה ונפרץ בחומתה פרצה בד' טפחים ובקעי בה רבים אם גם לענין זה יש לה דין חצר וסיים דיש להחמיר ועיין בספר בית מאיר שהאריך בזה וסיים דמדינא נוהג כל אלו הדינים במבואות שלנו:","(יא) צריך לתקנו שם - היינו שימעטנו מד' טפחים או שיעשה שם צוה\"פ:","(יב) מבוי וכו' - מפני שסעיף זה יש בו הרבה פרטים לכן אקדים הקדמה קצרה והוא. ידוע מסימן שס\"ד דמבוי המפולש לר\"ה חמור משאינו מפולש דצריך בו צורת הפתח מצד אחד. ויבואר בסעיף זה אם מפסיק חצר בין קצה המבוי לר\"ה ונפרץ החצר משני צדדיו כעשר אמות [ונשארו גיפופין מכאן ומכאן] דנמצא העומד במבוי רואה ר\"ה כנגדו דלא היה לחצר דופן אחר כ\"א דופן המבוי הנכנס בתוכו מהו דינו של המבוי וחצר אם מותר לטלטל בם אולי נידון המבוי מחמת זה כמפולש לר\"ה [ויבואר בו שיש חילוק אם פרצת החצר שלצד ר\"ה מכוון כנגד פרצת החצר שלצד המבוי אז נידון כמפולש ואי לא לא] וגם הלא אנשי החצר יכולין לאסור עליו אם לא ערבו יחד ואיך הדין לענין חצר הלא פרוץ לר\"ה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>מבוי שנפרץ במילואו לחצר ונפרץ החצר מצד השני לרה\"ר אם לא עירבו בני חצר עם בני המבוי <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>חצר מותר <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ואפי' נפרץ נגד פרצת המבוי <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>ואפילו בקעי בה רבים ובלבד שלא יהא יותר מעשר ומבוי אסור אפי' אינו כנגד פרצת החצר דכיון שלא עירבו עם המבוי אוסרת עליו <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>וכגון <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>שנכנסו כתלי המבוי בחצר בענין שאין הגיפופין שנשארו בחצר נראין <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>למי שעומד במבוי <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>אבל אם נראים עולים לו משום לחי <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>ומותר ואם עירבו בני החצר עם בני המבוי והפרצה שבמבוי לחצר <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>אינה <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>מצד החצר ופרצת החצר מצד השני אינן מכוונות כנגד פרצת המבוי והחצר של רבים גם המבוי מותר אבל אם לא עירבו או אפילו עירבו <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>ופרצת החצר למבוי <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i><i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>מצדו או אפילו באמצע החצר ופרצת החצר מצד השני כנגדה <i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>או אפי' אינה כנגדה <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>והחצר הוא <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>של <i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>יחיד אסור <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>ואם נפרץ לרחבה פחותה מסאתים או יותר על סאתים והוקף לדירה דינו כאלו נפרץ לחצר אבל אם יתירה על סאתים ולא הוקפה לדירה הוי כאלו נפרץ לכרמלית וצריך תיקון:","m":["(יג) שנפרץ במילואו - לאפוקי כשנשארו בו גיפופין נידון כלחי ואין יכול החצר לאסור עליו אף כשלא ערבו יחד:","(יד) אם לא ערבו וכו' - נקט לא ערבו לרבותא דאפילו בזה דבמבוי אסור לטלטל וכדלקמיה אפי' הכי בחצר מותר ואין המבוי יכול לאסור עליו:","(טו) חצר מותר - דהפרצות שיש בכתליו לצד המבוי ולצד ר\"ה כיון שאין בהם יותר מעשר אמות הוו כפתחים ובני המבוי ג\"כ אין יכולים לאסור עליו כיון שאין להמבוי דריסת הרגל על החצר:","(טז) אפילו נפרץ נגד וכו' - ור\"ל אף דלגבי מבוי איתא לקמיה דאם היה פרצתה מכוונת נגד פרצת החצר חשבינן ליה כמפולש לר\"ה ואסור בכל גווני מ\"מ לענין חצר לא מחמרינן בזה:","(יז) ואפילו בקעי בה רבים - אע\"ג דלעיל במבוי פוסל בקעי רבים כאן לענין חצר לא משגחינן בבקעי רבים:","(יח) ובלבד וכו' - ר\"ל בין הפרצה שלצד ר\"ה ובין הפרצה שלצד המבוי דאז חשיבי כפתחים אבל אם היה הפרצה יותר מעשר אמות חשוב פרצה גמורה והרי נפרץ למקום האסור לה ואינו ניתר אלא בצורת הפתח וכדלעיל בסימן שס\"ג ס\"ב:","(יט) אפילו אינו כנגד - ר\"ל אפילו אם הפרצה שלצד ר\"ה לא היה מכוון נגד פרצת החצר שכנגדו וא\"כ אין אנו יכולים לאסור לטלטל במבוי משום מפולש לר\"ה אפילו הכי אסור מטעם חסרון העירוב וכמו שמפרש והולך ואסור אפילו לא בקעי רבים מר\"ה למבוי דרך החצר:","(כ) שנכנסו כתלי המבוי בחצר - היינו שקצה כותלי אורך המבוי נכנסין להלן בתוך החצר ועי\"ז נראו גיפופי החצר מכאן ומכאן שהם רק כותלי החצר משו\"ה לא נוכל לצרף הגיפופין להמבוי אבל אם לא נכנסו לפנים חשבינן הגיפופים גם להמבוי ונחשבין כלחיים מכאן ומכאן ושוב אין החצר יכול לאסור עליו:","(כא) אינו מצד החצר - אלא באמצע החצר דאלו היה כן שכותל המבוי שוה באורך כותל החצר אפילו מצד אחד נראה כמבוי ארוך ומושך עד ר\"ה שכנגדו ומפולש ואסור:","(כב) מצד השני כנגדה - דעי\"ז נידון המבוי כמפולש ונמשך עד ר\"ה שכנגדו:","(כג) של יחיד אסור - דשמא ימלך ויבנה בתים ברוחב החצר העודף על המבוי והו\"ל מבוי נפרץ מצדו של חצר ואסור וכנ\"ל:","(כד) כאלו נפרץ לכרמלית - וע\"כ אפילו אם אין נכנסין כותלי המבוי בפנים בתוך הרחבה והגיפופין נראין מבחוץ אפ\"ה אסור לטלטל בתוך המבוי דהשתא לרחבה גופא לא מהני הגיפופין להיות מותר לטלטל בה דהא כרמלית היא איך יועיל זה להמבוי. מבוי שפתוח רוח רביעית שלו לצד הנהר אם שפת הנהר שאצל הבתים הוא עמוק יו\"ד טפחים או עכ\"פ הוא משופע כ\"כ שבתוך שיפוע ד\"א עולה לשיעור יו\"ד טפחים א\"כ נחשב המדרון הזה למחיצה וא\"צ שום תיקון דמיא לא מבטלי מחיצתא אבל אם מצד העיר אין משופע כ\"כ אע\"פ שמצד השני של הנהר הוא עמוק עשרה אם הוא רחב יותר מעשר אמות בין הבתים למקום הזה פשיטא דאסור שהרי יש פרצה המפסקת בין המחיצה להבתים ואפילו בפחות משיעור זה אפשר ג\"כ שיש לאסור שלא יעלה על דעתם שההיתר הוא מפני השפה שמעבר הנהר שמתלקט יו\"ד טפחים מתוך ד\"א ויבואו להתיר אף במפולש לגמרי בלי שום תיקון ועיין בבה\"ל שביארנו שבמקום הצורך יש להקל בזה:","(כה) וכנגד הלחי - ר\"ל בין שתיקון המבוי בקורה או בלחי מותר להשתמש כנגדם מיהו יש פוסקים דסוברים דוקא כשזה המקום שכנגד הלחי לא היה בו כשיעור ד' טפחים על ד' טפחים דאז בטל לגבי פנים ומותר להשתמש תחתיו וכן להכניס משם לפנים אבל כשיש בזה השטח דע\"ד וכש\"כ יותר נחשב זה המקום ככרמלית לענין שאסור לטלטל בו רק תוך ד' אמות וכן להוציא ממנו לר\"ה או להכניס לרה\"י אסור ויש פוסקים שאין מחלקים בזה וסוברים דאפילו יש בו דע\"ד ג\"כ בטל לגבי פנים:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i><i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>מותר להשתמש תחת הקורה <i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i>כנגד הלחי <i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"19\"></i>והני מילי בפתוח לרה\"ר <i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"20\"></i><i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>אבל בפתוח לכרמלית אסור בין תחת הקורה ובין כנגד הלחי מפני שמצטרף לכרמלית שאצלו שמצא מין את מינו וניעור:","m":["(כו) אבל בפתוח לכרמלית וכו' - אע\"ג דבעלמא כרמלית קיל מרה\"ר מ\"מ לענין זה אמרינן מצא מין את מינו וניעור פי' דכרמלית שבין לחיים אף אם לא היה בו שיעור כרמלית מתחלה שלא היה דע\"ד טפחים מצא מין את מינו שחוצה לו וניעור משנתו ונתחזק להצטרף לכרמלית שבצדו ושם כרמלית עליו ואסור להשתמש תחתיו וגם להכניסו לפנים משא\"כ בפתוח לר\"ה שהוא אין מינו כלל אין מצטרף עמו ובטל לגבי פנים:","(כז) בין תחת הקורה - ובספר א\"ר מצדד להקל להשתמש תחת הקורה אפילו פתוח לכרמלית וכן פסק בספר אבן העוזר ובפרט אם הקורה רחבה ד' טפחים ובריאה לקבל מעזיבה בודאי מותר אפילו פתוח לכרמלית דפי תקרה יורד וסותם וחשיבא מחיצה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"21\"></i>אע\"פ שמותר להשתמש תחת הקורה <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>לא ישב אדם בראש המבוי וחפץ בידו שמא יתגלגל החפץ מידו לרה\"ר ויביאנו אליו כיון שאין היכר בינו לרה\"ר <i data-commentator=\"Be'er HaGolah\" data-label=\"ת\" data-order=\"22\"></i>אבל על פתח החצר מותר בין פתוח לרה\"ר בין פתוח לכרמלית שיש בו הכירא:","m":["(כח) אע\"פ שמותר להשתמש וכו' - ר\"ל דדוקא על צד המקרה וההזדמן מותר לטלטל שם חפציו לעת הצורך אבל לא ישב שם בקביעות וחפץ בידו וכו' [מאמר מרדכי]:","(כט) תחת הקורה - וה\"ה שלא ישב אצל הלחי [גמרא] ואפשר דכשיש בו צורת הפתח שרי דמקרי הכירא ומיהו בצוה\"פ שלנו שגבוה מאוד בודאי אסור דלית הכירא ואפילו אם המבוי פתוח לכרמלית דהוא רק חששא במלתא דרבנן ג\"כ אסור דשכיחא לאיתשולי [מ\"א ומא\"מ]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"23\"></i>נשים היושבות על פתח המבוי וכדיהן בידן אין ממחין בידן <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>דכיון דמידי דרבנן הוא מוטב שיהיו שוגגות ולא מזידות:","m":["(ל) דמידי דרבנן הוא - ואפילו במידי דאורייתא אי ידעינן שלא ישמעו לנו אין לומר להם אם לא דבר שמפורש בקרא בהדיא כדלקמן בסימן תר\"ח ס\"ב ע\"ש:","(לא) שנטלו קורותיו או לחייו - ר\"ל לחי או קורה שלו דאין במבוי אלא קורה אחד ולחי אחד וה\"ה כשניטל צוה\"פ לפי מנהגנו שאנו עושין צוה\"פ:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"24\"></i>מבוי שנפלו קורותיו או לחייו בשבת <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"25\"></i>אף על פי שהותר למקצת שבת <i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>אסור משם ואילך בין פתוח לרה\"ר בין פתוח לכרמלית <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"26\"></i>ויש מי שאומר דהני מילי בעיר שאינה מוקפת חומ' <i data-commentator=\"Turei Zahav\" data-order=\"8\"></i>אבל בעיר <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>מוקפת חומה מותר: <small>הגה ויש לסמוך על זה להתיר וכל זה שהיה ראוי לעמוד כל השבת <i data-commentator=\"Turei Zahav\" data-order=\"9\"></i>אבל אם היה <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>עומד לסתור מע\"ש אסור לאחר שנסתר ואם ספק אם נסתר מע\"ש או לא אזלינן לקולא: (תה\"ד סימן ע\"ג):</small>","m":["(לב) אסור משם ואילך - לטלטל אלא בתוך ד\"א וכן אסור להוציא מבית לשם ולא אמרינן כאן שבת הואיל והותרה הותרה כמו בסימן ש\"ס ס\"ב הואיל וליתנהו למחיצות:","(לג) מוקפת חומה מותר - דהרי ע\"י החומה הויא כל העיר רה\"י גמור ותיקון המבוי לא היה אלא כדי לסלק דיורי הנכרים מעליהן ולכן אף שנסתר תיקון המבוי בשבת מותר דהוי כשתי חצירות שלא עירבו יחד ונפל כותל המפסיק ביניהן דאמרינן שבת הואיל והותרה הותרה משום דמחיצות החיצונות קיימות וה\"נ בכהאי גוונא. וכתב הט\"ז דוקא ישבה ולבסוף הוקפה בסתם עיירות שלנו דאז הוי רה\"י אבל אם הוקפה ולבסוף ישבה דיש עליה דין כרמלית מדרבנן ועשו תיקון במבוי להתיר הטלטול ונפל התיקון אסור דהרי מיחסרא מחיצתא ופתוח לכרמלית:","(לד) עומד ליסתר - כגון במקומות שמצויים נכרים שמקלקלים אותם בליל שבת וקרוב לודאי הוא שיקלקלוהו:","(לה) ואם ספק וכו' - אאין עומד לסתור קאי:","(לו) אזלינן לקולא - דמוקמינן ליה אחזקתיה והשתא הוא דנשבר [ב\"י]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"27\"></i>מבוי שנשתתפו בו ונשברה הקורה אותו חצר שהעירוב מונח בו וחצרות <i data-commentator=\"Turei Zahav\" data-order=\"10\"></i>הפתוחות לו מותרות אבל חצרות שאין פתוחות לאותו חצר <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"5\"></i>אסורות:","m":["(לז) שנשתתפו בו - ר\"ל שעשו רק שיתופי מבואות ולא עשו עירובי חצרות כל אחד בפני עצמו בחצרו ואעפ\"כ מהני כדקי\"ל לקמן בסימן שפ\"ז דסומכין על שיתוף במקום עירוב:","(לח) הפתוחות לו - ר\"ל שיש פתח או חלון שיכולין לטלטל ולהביא מזו לזו שלא דרך המבוי:","(לט) שאין פתוחות וכו' - ר\"ל אפילו העומדות בצד חצר זו כיון שאין להם פתח או חלון לאותו חצר אסורות דליתא לעירוב גבייהו ולא מצי לאתויי להעירוב דרך המבוי כיון שנשברה הקורה. ודוקא כשנשבר תיקון המבוי בחול אבל נשבר בשבת שרי לטלטל בכל החצרות כיון שהעירוב היה קיים בין השמשות ואפילו מחצר לחצר שרי בין דרך פתחים שביניהם בין דרך חורין דכיון שהותר במקצת שבת הותר לכל השבת וכדלקמן בריש סימן שע\"ד ורק דרך המבוי אסור לטלטל:","(מ) אסורות - דע דאותן חצרות האסורות לטלטל אפילו בבית אחד אסור מחדר לחדר אם בכל חדר דר אדם אחד בפ\"ע ואין לחבירו תפיסת יד בהן כמו שמוכח סי' ש\"ע ס' ב' וג'. וצריך להזהיר ע\"ז במקומות שאין להם תיקון מבואות בעיר דאף בבית אחד לא יטלטלו שני שכנים הדרים בשני חדרים אם לא שעשו עירובי חצרות ביניהם וכן צריך להזהיר במקומות שיש שם לחי או קורה או צוה\"פ ונשבר התיקון באותו מבוי של ביהכ\"נ [שמונח שם העירוב וכה\"ג] אם נשבר בחול שלא יטלטלו שוב בכל המבואות אפילו יש להם תיקון בפ\"ע אא\"כ הוא בענין שיכולין להביא העירוב אצלן מביהכ\"נ. ודע עוד דבמקום שאין עושין תיקון מבואות בעיר צריך ליזהר שלא יעשו עירובי חצרות אא\"כ יש עכ\"פ באותו חצר שני בתים [וכן ה\"ה שני בתים זה נגד זה ופירהויז ביניהם או שני חדרים הפתוחים לבית אחד] או בחצר הסמוכה להם בענין שיכולין להביא העירוב אצלם דרך פתח או חלון בשבת וכתבו האחרונים דבאופן זה שלא עשו תיקון למבואות לא יניחו העירוב בביהכ\"נ כנהוג רק באחד הבתים ואם לא עשו כן אסור לטלטל אפילו בחצר בהכ\"נ על סמך העירוב שמונח בבית הכנסת:"]}],"366":[{"s":"<b>דין עירוב לחצר שהרבה בני אדם דרים בו. ובו טו סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>חצר שהרבה בתים פתוחים לתוכו אסרו חכמים לטלטל <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>מבתיהם <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>לחצר עד שיערבו דהיינו שגובים פת מכל בית ובית ונותנים אותו בא' מבתי החצרות שע\"י כך אנו רואים כאלו כולם דרים באותו בית וכאלו כל החצר מיוחד לאותו בית:","m":["(א) שהרבה בתים - של אנשים מיוחדים:","(ב) מבתיהם לחצר - וה\"ה מבית לבית בתוך החצר או בתוך המבוי אף שהמבוי מתוקן בלחי וקורה וטעם בכל זה דגזרו שלא להוציא מרשותו לרשות חבירו כדי דלא ליתי לאפוקי מרה\"י לר\"ה ובחצר גופא מותר לטלטל בכולו ואפילו מחצר לחצר נמי מותר דלא גזרו בזה רבנן וכדלקמן בסימן שע\"ב:","(ג) שע\"י כך וכו' - דעיקר דירתו של אדם במקום שפתו שם:","(ד) וכאלו כל החצר - וכמו שהסביר הרמב\"ם וז\"ל שיתערבו במאכל אחד שמניחין אותו מע\"ש כלומר שכולנו מעורבין ואוכל אחד לכולנו ואין כל אחד ממנו חולק רשות מחבירו אלא כשם שיד כולנו שוה במקום זה שנשאר לכולנו כך יד כולנו שוה בכל מקום שאחז כ\"א לעצמו והרי כולנו רשות אחד ובמעשה הזה לא יבואו לטעות ולדמות שמותר להוציא ולהכניס מרה\"י לר\"ה עכ\"ל:","(ה) יושבי אוהלים וכו' - כגון שוכני מדבריות וכדומה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>יושבי אהלים או סוכות או מחנה שהקיפוהו מחיצה אין מטלטלין מאהל לאהל עד שיערבו כולם אבל <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>שיירא שהקיפוה מחיצה אין צריכים לערב לפי שכולם מעורבים ואין אותם אהלים קבועים להם: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>בתים שבספינה צריכים עירוב אע\"פ שיש לספינה <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>מחיצות ואם אין לספינה מחיצות <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>אסור <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>לטלטל בספינה רק בארבע אמות (ב\"י בשם שבולי לקט) (ועיין לקמן סוף סי' שפ\"ב וסי' ת\"ה סעיף ז'):</small>","m":["(ו) או מחנה - מקום חנייה של אנשי חיילות ע\"פ השדה שקורין בלשוננו לאגע\"ר ועיין בה\"ל:","(ז) שהקיפוהו מחיצה - ר\"ל שהיה מחיצה גבוה עשרה טפחים מקפת סביב האוהלים והסוכות:","(ח) אין מטלטלין מאהל לאהל - וה\"ה מאוהל לחצר דהיינו לאותו שטח שהוא בתוך המחיצה:","(ט) עד שיערבו - ומאותו טעם שכתבנו לעיל בס\"א:","(י) אבל שיירא - אורחת אנשים ההולכות דרך מדבר:","(יא) שהקיפוה מחיצה - ויש להם בתוך ההיקף אוהלים לכל אחד בפ\"ע:","(יב) לפי שכולם וכו' - פי' דכיון שאין אותם אוהלים קבועים להם לדירה רק דרך ארעי בשעה שעומדים לפוש מעמידים אוהלים לא מיקרי חילוק דירות וכמו שכולם מעורבים בבית אחד דמי ועיין בבה\"ל. ועיין בביאור הגר\"א שהביא בשם מפרשים שחולקים ע\"ז ודעתם דאוהלים שבשיירא צריכים עירוב ושבמחנה פטורים מעירוב אך שיירא לא מיקרי רק כשהוא פחות מעשרה ומעשרה ולמעלה נכללים בשם מחנה:","(יג) בתים וכו' - ששייכים לאנשים מיוחדים והטעם דלא גרע מיושבי אוהלים וכו' שצריכין עירובי חצרות שאף כאן הבתים קבועים להם לכל משך נסיעתם על הים ועיין במ\"א וא\"ר דדוקא כשיש בה איזה בתים השייכים לישראלים אבל אם אין בספינה רק בית אחד ושארי אנשים שוכנים בספינה עצמה א\"צ עירוב כלל ומותר להוציא מן הבית לספינה ועיין בה\"ל:","(יד) צריכין עירוב - ועי\"ז יהיה מותר לטלטל מבית לבית ומבתים לספינה ובלא עירוב אסור בכל זה אבל בספינה עצמה מותר לטלטל בכולה כמו בחצר. וכן אותם ספינות שאין להם בתים אלא שרויים בספינה הרי הם כשרויים בחצר אחת שמותרים לטלטל בכולה בלי עירוב:","(טו) שיש לספינה מחיצות - של עשרה טפחים ודינה כרשות היחיד:","(טז) ואם וכו' מחיצות - של עשרה טפחים ומודדין מקרקעיתה ואע\"פ שיש איזה טפחים במים:","(יז) אסור לטלטל בספינה - דהויא כרמלית ובאופן זה מותר לטלטל מן הים לתוכה ומתוכה לתוך הים דמותר לטלטל מכרמלית לכרמלית. כתב מ\"א דאם יש בתים בספינה והספינה עצמה אין לה מחיצות של עשרה טפחים אסור להוציא מן הבתים לספינה דמרה\"י לכרמלית קמפיק ועיין בבה\"ל מה שהבאתי עוד בשם מ\"א:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>הבית שמניחים בו העירוב <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>א\"צ ליתן <i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>פת <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ואין צריך שיהיה בעירוב שוה פרוטה <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ואין מניחין אותו בחצר אלא בבית שראוי לדיר' לאפוקי <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>בית שער אכסדר' ומרפסת <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>וצריך שיהא בו <i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i><i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>ד' אמות על ד' אמות <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>ואפילו הוא של קטן <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>ואם רגילים ליתנו תמיד בבית ידוע <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>אין להם <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>לשנותו <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>וליתנו בבית <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>אחר מפני דרכי שלום <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>ואפי' <i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>קטן יכול לגבות העירוב ולקבצו: <small>הגה והמנהג בזמן הזה <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>להניח העירוב בבית <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>הכנסת וכן נהגו הקדמונים ונראה לי הטעם דעירובין שלנו יש להם דין שתוף ואין צריך להניח <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>בבית דירה וע' לקמן סי' שפ\"ו ושפ\"ז:</small>","m":["(יח) א\"צ ליתן פת - שהרי אין העירוב אלא שיחשוב כאלו כולן דרין שם והרי הוא דר שם:","(יט) ואין צריך וכו' פרוטה - לאפוקי ממ\"ד בגמרא עירוב משום קנין שבעה\"ב מקנה להם ביתו עבור הפת ולפ\"ז היה צריך שיהא בפת עכ\"פ שוה פרוטה דליחשב ממון קמ\"ל דלאו משום קנין הוא אלא שיתוף דירה בעלמא הוא ומזה הטעם ג\"כ צריך ליתן דוקא פת ולא סגי בד\"א כגון כלי וכי\"ב שאינו מאכל דעיקר דירת אדם הוא במקום פתו כ\"ז מתבאר בש\"ס:","(כ) לאפוקי בית שער וכו' - דאע\"ג שעשויין כעין בתים מ\"מ הואיל והן דריסת הרגל לכל בני החצר לא חשיבי דירה:","(כא) מרפסת - מקום גבוה בחצר ובו מדרגות עולים בהם לעליות וזה המקום גבוה מוקף בבנין ודרין בו:","(כב) ד\"א על ד\"א - דאז הוא ראוי לדירה ואם הוא רחב יותר מד' אלא שהוא קצר בארכו ויש בו לרבע ד' על די יש דיעות בין הפוסקים אי מקרי דירה לפיכך מן הנכון להניח לכתחלה בבית אחר יותר גדול ועיין בה\"ל:","(כג) ואפילו הוא של קטן - פי' שהבית שמניחים בו העירוב הוא של קטן וקמ\"ל דלא תימא דצריך להקנות להם ביתו וקטן לאו בר אקנויי הוא קמ\"ל דלא משום קנין היא אלא משום דירה וע\"כ מותר להניח אפילו בבית קטן:","(כד) רגילים ליתנו תמיד - לאפוקי אם לא הורגלו עדיין לזה הבית אין להקפיד אם משנין לבית אחר:","(כה) אין להם לשנותו וכו' - ואפילו יש להם קצת טעם בדבר אם לא דיש להם טעמא רבא דאז מותרין לשנותו:","(כו) וליתנו בבית אחר - ואפילו מת הבעה\"ב. ואפילו השני נותן מעות לבני החצר להניח בביתו ואפילו הוא ת\"ח והראשון ע\"ה. אם בתחלת הנתינה התנו לשנות מותר לשנות [כנה\"ג] ויש מאחרונים שמפקפקין בזה:","(כז) מפני דרכי שלום - ענין דרכי שלום בכאן הוא משום חשד [גמרא] ופירש\"י הואיל והורגל העירוב בתוך אותו הבית אם באת לשנות את מקומו הנכנסין לאותו הבית ולא יראו שם העירוב יחשדו לבני החצר שמטלטלין בלי עירוב ובתוספות פירשו דחשדא הוא שיחשדו לבעה\"ב זה שגונב פת מן העירוב ולכך הוציאו אותו ממנו לבית אחר ומתוך כך יבוא לידי מחלוקת עמהם ולפירש\"י בודאי יש להחמיר אפילו מכר בית לאחר שלא לשנות מקום העירוב אכן לפירוש התוספות אפשר לומר דעל הלוקח לא יבוא לידי חשד ע\"י הוצאת העירוב מביתו אחרי שמעולם לא היה העירוב בידו והנה כ\"ז בעירוב שדרכו להניח אותו בבית בחנם וככי\"ב אבל דבר שצריכין ליתן מעות לזה יכולין לשנותו ליתן לאחר ואפילו אם להשני צריך ליתן ג\"כ מעות. ובכל גונא אם עברו ונתנו בבית אחר אין מחוייבין להוציא משם ומיהו אם הנותן רוצה לחזור וליתנו במקום שהיה רגיל מתחלה הרשות בידו ומ\"מ צ\"ע למעשה [מ\"א בשם כנה\"ג]:","(כח) ואפילו קטן - והכל מטעם הנ\"ל שאינו משום קנין שיהא צריך בר דעת להקנות ואע\"פ שאין במעשה קטן כלום מ\"מ העירוב נעשה ממילא כשהונח בבית ומ\"מ ע\"י עכו\"ם אסור לקבצו לכתחלה דחשוד לגנוב ולהחליף טוב ברע:","(כט) ונ\"ל הטעם וכו' - ר\"ל אע\"פ שבהכ\"נ אינו ראוי לדירה מפני קדושתו שהרי הדירה הוא מקום האכילה ואסור לאכול בביהכ\"נ אם לא הלומדים שם כמ\"ש בסימן קנ\"א מ\"מ יש לקיים המנהג כמו שמסיים שעירובין שלנו יש להם דין שיתופי מבואות דהיינו שכל החצרות והבתים שבמבוי משתתפין יחד בעירוב זה ושיתופי מבואות א\"צ להניחו כלל בבית דירה רק שיהא במקום המשתמר לבד כמ\"ש בסימן שפ\"ו:","(ל) וא\"צ להניח בבית דירה - ולפ\"ז שאין בהכ\"נ נחשב לבית דירה חשבינן ליה רק כחצר השותפין ומותר לטלטל ממנה לחצר אחרת בלי ע\"ח דכל החצרות רשות אחת כמבואר בסימן שע\"ב:","(לא) בכלי אחד - שהרי עירוב שמו שיהיו מעורבים יחד ואם מניחו בשני כלים נראה שהם מופלגים ומחולקים זה מזה. ונראה לכאורה דדוקא אם כ\"א נותן חלק בעירוב אבל אם אחד מזכה בעד כולם יכול ליתנו בשני כלים אכן מדלא הזכירו הפוסקים ד\"ז משמע דס\"ל דלא פלוג רבנן במלתייהו וצ\"ע:","(לב) נתמלא האחד - ר\"ל שבזה לא היה החילוק לשני כלים ברצונו אכן אם ידע מתחלה שהכלי לא יכיל בתוכו את כל העירוב והיה לו כלי אחר גדול מכלי זה שתוכל להכיל כל העירוב יש מאחרונים שמחמירין דהוי כחולק לכתחלה את העירוב לשנים:","(לג) בבית אחד - דעכ\"פ היו שניהם ברשות אחת אבל לא בשני בתים. ואפילו אם אחד מזכה בהעירוב משלו בשביל כולם ג\"כ יש ליזהר בזה וע\"כ העירוב שמניחין בביהכ\"נ בעד כל העיר יש ליזהר שלא להניחו רק בבית הכנסת אחת ויבחרו לזה הביהכ\"נ היותר גדולה שבעיר [ש\"ת בשם הח\"צ]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>צריך ליתן כל העירוב <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>בכלי א' ואם חלקו ונתנו בשני כלים אינו עירוב אלא אם נתמלא הא' ואז מותר <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>והוא שיהיו שני הכלים בבית א':","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>צריך שלא יקפיד שום א' מהם על עירובו אם יאכלנו חבירו ואם מקפיד אינו עירוב לכך <i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>צריך ליזהר שלא לערב בדבר שתיקן לצורך השבת:","m":["(לד) שלא יקפיד - ג\"כ מטעם דעירוב שמו שיהיו מעורבין ומרוצין בו שלא ימחה אחד בחבירו ויהיה שותפותן נוחה ועריבה:","(לה) שום אחד מהם - וה\"ה כשאחד מזכה לכולם צריך ג\"כ להתרצות כשיבואו מבני החבורה לאכול ממנו שלא להקפיד עליהם:","(לו) שתיקן לצורך השבת - שהרי אם יבקש חבירו ממנו לא יתן לו. ואמנם אם פועל בעצמו בפירוש שאם ירצה אחד מבני העיר ששייכים להעירוב לאכול ממנו שלא יקפיד עליו מסתברא דמותר לערב בו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i> אין מערבין <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i><i data-commentator=\"Magen Avraham\" data-order=\"11\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i>בפרוסה אפי' היא גדולה הרבה אבל בשלימה אפי' קטנה מאוד מערבין ובלבד שיהא בהם כל כך שיהא בהם <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>כשיעור <i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i>ומיהו אם ניטל ממנו <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>כדי <i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i>חלת נחתום שהוא א' ממ\"ח מערבין בה <i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i>אפי' לא היתה טבולה לחלה <i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"19\"></i>ואם נפרסה וחיברה בקיסם שהכניס הקצה הא' בתוך הפת והקצה השני בתוך הפרוסה אם אינו ניכר שנפרסה מערבים בה: <small>הגה ויש שפירשו הא דאין מערבין רק בפת שלם היינו שכל העירוב ביחד יהיה פת שלם ולכן נהגו לקבוץ מכל בית ובית מעט קמח ועושין חלה אחת שלימה ומערבין בה (המגיד והגהות הראב\"ד פ\"א מהל' עירובין) וכן המנהג פשוט בכל מדינות אלו וצריך ליזהר שיהא בחלה כשיעור המפורש לקמן סי' שס\"ח סעיף ג' ואע\"פ שנשתייר מן הקמח ולא נעשה מכולו חלה אפ\"ה הוי עירוב דלא גרע מאילו אחד מזכה לכולם <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>ואדעתא דהכי נתנו קמחם מתחלה כן נראה לי:</small>","m":["(לז) בפרוסה - משום איבה שיבואו לידי מחלוקת שיאמר אני נותן שלימה ואתה פרוסה ואפילו ירצו כולם ליתן פרוסה חיישינן שיחזור הדבר לקלקולו ועיין בפמ\"ג דמסתפק לומר דאפשר דאפילו בדיעבד לא מהני העירוב כשעשאו בפרוסה ואם עשאו מתחלה בשלימה ואח\"כ לשבת אחרת נפחתה ונשתייר ממנה מעט עיין לקמן בסימן שס\"ח ס\"ד ע\"ש:","(לח) כדי חלת - פי' אפילו אינו שלם שרי שהשכנים סוברים שניטל חלה מן הפת:","(לט) ואם נפרסה וכו' - ר\"ל שנפרס מן הככר מעט:","(מ) אם אינו ניכר וכו' - הטעם אע\"ג דבאמת אינה שלמה מ\"מ כיון דאינו ניכר לא יבוא לידי מחלוקת:","(מא) היינו שכל העירוב ביחד וכו' - ר\"ל דבזה ג\"כ מקיים מה שתקנו חז\"ל לע\"ח שיהיה בפת שלם דוקא אבל גם הם מודים דיכול כ\"א ליתן פת שלם ואפילו אם הככר של זה גדול משל חבירו ג\"כ מותר וכן מודים ג\"כ לדעה ראשונה דאין מערבין בפרוסה אפילו אם יתנו כולם פרוסות שוות:","(מב) מכל בית ובית מעט קמח - וה\"ה כשנותנים מעות לקנות בהם קמח ואפילו אם לא נתנו איזה בע\"ב ג\"כ אין קפידא בדבר וכדמסיים לבסוף דכל אחד נותן קמחו לעירוב בשביל כולם:","(מג) וצריך ליזהר וכו' - אשמועינן דאף שמצטרפין יחד להביא פת שלמה למצות עירוב וס\"ד דזה חשוב טפי ולא בעי שיעור קמ\"ל:","(מד) ואע\"פ וכו' - ר\"ל וא\"כ יש בני אדם שאין להם חלק בפת העירוב וא\"כ יאסרו אלו על אלו:","(מה) דלא גרע וכו' ואדעתא דהכי וכו' - ר\"ל אף הכא כשנתן כ\"א מבע\"ב מעט קמח להשמש בשביל כולם נתן ואע\"פ שהנותן עירוב בעד חבירו צריך לזכות לו ע\"י אחר כמו שיתבאר לקמיה בס\"ט מ\"מ כאן כשנותן כ\"א קמחו להשמש לערב בו אנו חושבין כאלו נותנים לו שיזכה בו בשביל כולם ואין השמש צריך לזכות להם ע\"י אחר או ע\"י עצמו בפירוש ויש מי שאומר שאם לא זיכה השמש להם ע\"י אחר או ע\"י עצמו בפירוש אינו עירוב ונכון לחוש לדבריו לכתחלה [ובפרט אם השמש עשהו מקמח שלו בודאי צריך לזכות להקהל ע\"י אחר] וכן נוהגין שהשמש נותן העירוב להרב בערב פסח שיזכה בו בשביל כל הקהל ואם חשכה ליל יו\"ט ראשון ולא זיכה אין לזכות אלא על תנאי דהיינו שיאמר אם היום חול אני מזכהו לכל העיר ואם קודש אין בדברי כלום וכן יאמר למחר בליל יו\"ט שני. וכ\"ז אם היו\"ט היה סמוך לשבת דאם יש ימי חול בינתיים ימתין מלזכות עד ע\"ש ואם שכח גם בע\"ש מלזכות עד שחשכה סומכין על הפוסקים הנ\"ל דס\"ל דמותר לטלטל אף בלי זיכוי כיון שכבר נגבה בשביל כולם [אחרונים]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"20\"></i>אם אחד מזכה לכולם יכול לערב בפרוסה:","m":["(מו) יכול לערב בפרוסה - דלא שייך כאן כלל משום איבה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"21\"></i>מערבין בפת אורז ועדשים אבל לא בפת דוחן:","m":["(מז) בפת אורז ועדשים - שדרך העולם לאפותו ולאכלו משא\"כ בדוחן ועיין לעיל סימן ר\"ח סקכ\"ה במ\"ב מה הוא אורז ודוחן:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ת\" data-order=\"22\"></i>אם א' מבני החצר רוצה ליתן פת בשביל כולם שפיר דמי ובלבד שיזכנו להם על ידי אחר וכשזוכה בו <i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"23\"></i>צריך להגביהו <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>מן הקרקע טפח <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"24\"></i>וצריך לזכות לכל בני החצר או המבוי ולכל מי שיתוסף מיום זה ואילך <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"25\"></i><i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>וי\"א שאע\"פ שלא יזכה בפירוש למתוספים עליהם לב ב\"ד מתנה עליהם <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"26\"></i>ואם נתוספו דיורין לאחר שנתמעט העירוב מן השיעור <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i>צריך להוסיף <i data-commentator=\"Ba'er Hetev\" data-order=\"13\"></i>מחמתן:","m":["(מח) בשביל כולם - אפילו שלא בפניהם:","(מט) ובלבד שיזכנו להם ע\"י אחר - דעל ידי עצמו אינו יכול לזכות להם שכל זמן שהוא בידו לא יצא מרשותו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"27\"></i>כשמזכה להם ע\"י אחר לא יזכה על ידי בנו ובתו הקטנים <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"28\"></i>אפילו אם אינם סמוכים על שלחנו ולא ע\"י עבדו ושפחתו הכנענים אבל מזכה הוא ע\"י בנו ובתו הגדולים <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i>אפי' סמוכים על שלחנו וע\"י עבדו ושפחתו העברים אפי' הם <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i>קטנים <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"29\"></i><i data-commentator=\"Magen Avraham\" data-order=\"17\"></i>וע\"י אשתו אף על פי שהוא מעלה לה מזונו' ואפילו אין לה בית בחצר <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"30\"></i>ויש אומרים שאינו מזכה ע\"י בנו ובתו הסמוכים על שלחנו אפילו הם גדולים ולא ע\"י בתו אפילו אינה סמוכה על שלחנו כל זמן שלא בגרה <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"31\"></i>ולא ע\"י אשתו שמעלה לה מזונות או שאמר לה צאי מעשה ידיך במזונותיך <i data-commentator=\"Magen Avraham\" data-order=\"18\"></i>ואפי' יש לה בית בחצר אבל מזכה ע\"י בנו שאינו סמוך על שלחנו אפי' הוא קטן וע\"י בתו שבגרה ואינה סמוכה על שלחנו וע\"י אשתו <i data-commentator=\"Magen Avraham\" data-order=\"19\"></i>שאינה מעלה לה מזונות אפילו אין לה בית בחצר <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"32\"></i>ולכתחלה טוב לחוש לדברי שניהם היכא דאפשר: <small>הגה ובדיעבד סומכין על דברי המיקל בעירוב וכן גדול שיש לו אשה אע\"פ שסמוך על שלחן אביו מזכה על ידו (הגהות אשירי והגהות סמ\"ג וכל בו) אפילו לכתחלה ואינו צריך להודיע לאותם שזיכה להם קודם השבת אלא אם מודיעם בשבת מותר לטלטל. (כל בו):</small>","m":["(נ) ע\"י אחר - דהיינו שיאמר לו קבל פת זה וזכה בה לכל בני החצר והוא יחשוב בהגבהתו בשביל כולם ואף שהם לא עשאוהו שליח לזה זכין לאדם שלא בפניו והוי כשלוחם:","(נא) טפח - ואפילו לדעת האומרים בח\"מ סי' קצ\"ח ס\"ד בהג\"ה דהגבהה אינו קונה בפחות מג\"ט הכא בעירוב שהוא מדרבנן הקילו וסגי בהגבהה טפח. כתב הט\"ז דה\"ה אם הניחו להעירוב על ידו התלויה באויר צריך שיגביה ידו טפח ועיין בבה\"ל:","(נב) ולכל מי שיתוסף מיום זה ואילך - דאל\"כ לפעמים שיתוספו עליהם דיורים ויאסרו עליהם עד שיוסיפו עליהם אבל כשמכוין עליהם מתחלה ל\"ל בה דהא שיעור שתי סעודות מהני אפילו לאלף וכדלקמן בסימן שס\"ח:","(נג) וי\"א שאע\"פ וכו' - הלשון מקוצר דמעיקר הדין בודאי אינו כן אלא דבזמנינו יש לסמוך ע\"ז מאחר דאנו נוהגין להניח עירוב על כל השנה מסתמא אנו מכוונין גם על אנשים שמתוספים במשך השנה וכן הוא הלשון באמת בב\"י וכן כונת המחבר בכאן:","(נד) צריך להוסיף מחמתן - דשמא לא אמרו חכמים דשיורו בכל שהוא (כמבואר בסימן שס\"ח) אלא באותן שהיו בתחלת הנחת העירוב וזכו אז אבל אלו שלא היו בתחלת הנחתו לא זכו אז ורק הם זוכין בשעה שיתוספו וכיון דבשעה זו כבר נפחת משיעורו א\"כ א\"א להם לזכות ומטעם זה לא מהני אף אם יתנה בפירוש ולכל מי שיתוספו ואין שום עצה רק שצריך לשמור שיהיה בו תמיד שיעור שתי סעודות:","(נה) ע\"י בנו ובתו הקטנים - מפני שידן כידו וא\"כ לא יצא הדבר מרשותו:","(נו) ולא ע\"י עבדו וכו' - ג\"כ מפני שיד עבד כיד רבו ולא יצא מרשותו עדיין:","(נז) אפילו הם סמוכין - ואע\"ג דבאופן זה מציאתן לאביהן כמבואר בח\"מ סימן ר\"ע זה אינו אלא משום איבה שלא ימנע מהן מזונות אם תהיה מציאתן לעצמן אבל בנידון דידן שהאב רוצה לזכות ע\"י לאחרים שפיר זוכים דכיון דגדולים הם יש להם יד בפ\"ע:","(נח) אפילו הם קטנים - ואע\"ג שאין קטן זוכה לאחרים בכל מקום הכא בעירוב שהוא מדרבנן בעלמא הקילו בעבדו ושפחתו ומ\"מ לא רצו להקל אלא בעבדו ושפחתו אבל לא בבניו הקטנים וכדלעיל משום דידן ממש כידו:","(נט) וע\"י אשתו - דכשנותן לה אחר מתנה ע\"מ שאין לבעלה רשות בה מהני הרי דיש לה יד לזכות לעצמה ה\"ה דיכול לזכות על ידה לאחרים:","(ס) ואפילו אין לה בית - נקט האי לישנא לאפוקי ממ\"ד בגמרא דדוקא היכא דיש לה לעצמה בית בחצרה שאוכלת שם אז אמרינן מיגו דמהני הזכיה בעירוב בשביל ביתה מהני נמי לזכות לאחרים בעירוב בשביל בתיהם:","(סא) ויש אומרים וכו' - סבירא להו דדמיא עירוב לענין מציאה דכל היכא דס\"ל לענין מציאה דאין לו יד בפ\"ע ושייך לאביהן או באשה שמוצאת מציאה ושייך לבעלה ה\"ה לענין עירוב אין להם יד בפ\"ע ועדיין לא יצא מרשותו:","(סב) על ידי בנו ובתו וכו' - ר\"ל לאחר שבגרה דיוצאת לכל דבר לרשותה אפ\"ה כיון שסמוכה על שולחנו ומציאתה לאביה גם לענין עירוב אין לה יד לעצמה:","(סג) כל זמן שלא בגרה - דאז שייך מציאתה לאביה:","(סד) שמעלה לה מזונות - דאז מציאתה לבעלה:","(סה) או שאמר לה צאי וכו' - ומיירי במספקת מעשה ידיה למזונות דאי אין מספקת למזונות אין מציאתה לבעלה:","(סו) ואפילו יש לה בית - ר\"ל ואוכלת שם המזונות שנותן לה בעלה וס\"ד דמיגו דזכיא לעצמה בעירוב זה בשביל ביתה תזכה בעירוב גם לאחרים קמ\"ל דלא והטעם דבאמת לעצמה אין צריכה עירוב כלל דנמשכת אחר בעלה כדלקמן בסימן ש\"ע ס\"ו וליכא מיגו:","(סז) אפילו הוא קטן - כיון דלענין מציאה יש לו יד לזכות לעצמו כשאינו סמוך על שולחן אביו:","(סח) שבגרה ואינה סמוכה - ר\"ל דוקא באופן זה ולא כדעה הראשונה דס\"ל דכשבגרה אפילו בסמוכה מזכה על ידה וכן בע\"י אשתו דוקא היכא שאין מעלה לה מזונות דאז מציאתה לעצמה ולא לבעלה:","(סט) על דברי המיקל בעירוב - ר\"ל בין קטן ואין סמוך על שולחנו או גדול אף שסמוך וכן בע\"י אשתו אע\"פ שמעלה לה מזונות:","(ע) שיש לו אשה וכו' - שעושה הכל ע\"ד עצמו ולא ע\"ד אביו:","(עא) ואינו צריך להודיע - דזכין לאדם שלא בפניו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"33\"></i>בני חבורה שהיו מסובין לאכול וקדש עליהם היום הפת שעל השלחן סומכין עליה משום עירוב <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"34\"></i>והוא שמסובין בבית שהוא מקום <i data-commentator=\"Ba'er Hetev\" data-order=\"14\"></i>הראוי להניח שם עירוב אבל בחצר לא <small> (וה\"ה אם יש להם פת בשותפות בא' מן הבתים סומכין עליו משום עירוב):</small>","m":["(עב) בני חבורה וכו' - אשמועינן בזה שני דברים אחד אע\"ג שלא הניחו לכתחילה לשם עירוב גם דאפילו אותו הפת לא היה מתחלה של כולם כ\"א של בעה\"ב לבד שזימנן לסעוד משלו ולא הקנה להן אותו פת בפירוש אפ\"ה כיון שזימנן לאכול עמו ויכולין לאכול לדעתם הרי הוא כאלו נשתתפו בו עמו ויש להם בו זכות וע\"כ אם הוא קיים עד לאחר בין השמשות סומכין עליו משום עירוב:","(עג) הפת שעל השולחן וכו' - לכאורה בעינן שיהיה אז עדיין אצלם פת אחד שלם וכנ\"ל בסעיף וי\"ו או אפשר כיון דלא הביאו פתם אלא בעה\"ב זימנן לסעוד משלו דינו דומה להא דס\"ז וכן משמע בתו\"ש אבל באמת יש לחלק ביניהם וצ\"ע:","(עד) אבל בחצר לא - דחצר לאו בר דירה הוא:","(עה) וה\"ה אם יש להם וכו' - דין זה הוא זו ואצ\"ל זו ובתו\"ש כתב דקמ\"ל דסומכין עליו בחזקת שהוא קיים אע\"פ שאין יודעין בעצמן משום דמוקמינן ליה אחזקתיה:","(עו) סומכין עליו משום עירוב - ומשום שיתופי מבואות יכולין לסמוך אף כשמונח באחד מן החצרות [גמרא]:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"35\"></i>אפוטרופוס של קטן יכול לערב בעדו:","m":["(עז) יכול לערב בעדו - אפילו משל הקטן שלא מדעתו מפני שהוא לו כבן בית שיכול לערב משל בעה\"ב שלא מדעתו כמו שיתבאר בסימן שס\"ז:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"36\"></i>מצוה לחזור אחר עירובי חצרות:","m":["(עח) אחר עירובי חצרות - כדי שלא יבואו לטלטל באיסור:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"37\"></i><i data-commentator=\"Magen Avraham\" data-order=\"20\"></i>מברך על מצות <i data-commentator=\"Ba'er Hetev\" data-order=\"15\"></i>עירוב:","m":["(עט) על מצות עירוב - ואפילו אדם אחר שאינו דר באותה העיר ורוצה לשבות שם בשבת יכול לברך ברכה זו דהא אלו לא עירבו היה גם הוא אסור לטלטל וא\"כ גם הוא שייך להעירוב ועיין מה שכתבנו עוד בזה בבה\"ל. אם מניח עירובי תבשילין וע\"ח בזמן אחד מברך ברכה אחת על שתיהן דהיינו על מצות עירובין. ואומר הנוסח בהדין עירובא על כל אחד ואחד כפי נוסחו ובח\"א כלל ק\"ב כתב שיאמר על מצות עירובי תבשילין ועירובי חצרות ואומר בדין יהא שרא לן לאפויי וכו' ולטלטל מבית לחצר וכו':","(פ) בשעה וכו' - מפני שכל המצות מברך עליהם עובר לעשייתן ולפי מה שכתב הרמ\"א לעיל בס\"ו דהמנהג לקבץ קמח מבתי העיר אין לברך בשעת קיבוץ דהוי עובר דעובר כ\"ז שלא נאפה הפת:","(פא) שמקבץ וכו' - הב\"י והב\"ח כתבו בסימן שצ\"ה דצריך לברך בשעה שמתחיל לקבץ ולא כשנגמר הקיבוץ דאז כבר נגמר המצוה והאחרונים הסכימו דיוכל לכתחלה לברך אחר שכבר נגמר הקיבוץ והטעם משום דס\"ל דאחר שנתקבץ צריך לכתחלה לזכות לכל בני העיר כמו שכתבנו לעיל בסקמ\"ה ומקרי עדיין עובר לעשייתן כשהוא קודם הזיכוי ומ\"מ בדיעבד אפילו כבר זיכה ג\"כ יוכל לברך דעיקר קניית עירוב חל בעת כניסת השבת ומקרי בכל גווני עובר לעשייתן ובפרט אם לא הונח העירוב עדיין במקומו בודאי שייך לברך דלא נגמר עדיין המצוה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"38\"></i> אימתי מברך בשעה שמקבץ אותו מבני החצר או בשעה שמזכה להם ואומר <i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"39\"></i>בהדין עירובא יהא שרי לן לאפוקי ולעיולי מן הבתים לחצר ומן החצר לבתים ומבית לבית לכל הבתים שבחצר <i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"40\"></i>ואם גבו העירוב <i data-commentator=\"Magen Avraham\" data-order=\"21\"></i>ולא ברכו עליו אין הברכה מעכבת ומותרים לטלטל:","m":["(פב) בשעה שמזכה להם - פי' שמערב משלו ונותן לאחרים ואומר לו שאחר שיברך יגביהנו כדי שיזכה בשביל אנשי העיר ועיין בבה\"ל שהבאנו דהמברך אחר הזיכוי יש לו ג\"כ על מי לסמוך:","(פג) לכל הבתים שבחצר - ולא הזכיר מבוי משום דכאן איירי שלא ניתקן המבואות בעירובין כדין וכל חצר מתקן ע\"ח רק להתיר הטלטול בחצר אבל במקום שניתקן המבואות המנהג שעושין ע\"ח ושיתופי מבואות כחדא כמבואר בסימן שפ\"ז וע\"כ צריך להוסיף בו שריותא דמבוי וזה נוסחו בהדין עירובא יהא שרא לנא לאפוקי ולעיולי מן הבתים לחצר ומחצר לבתים ומבית לבית ומחצר לחצר ומגג לגג ומבתים וחצרות למבוי וממבוי לכל הבתים והחצרות שבעיר הזו לנו ולכל הדרים בעיר הזאת ולכל מי שיתוסף בה. ואם מערב לכל שבתות השנה יסיים לכל שבתות השנה ולכל ימים טובים [אחרונים]:","(פד) ולא ברכו עליו - וה\"ה אפילו אם הנוסח בהדין עירובא ג\"כ לא אמרו עליו כיון שמשותפין בעירוב סגי בזה:"]}],"367":[{"s":"<b>אם אשה יכולה לערב. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>אשתו של אדם מערבת לו שלא מדעתו אפי' אם מיחה בה שלא לערב ואפי' אין רגיל לערב עמהם וה\"מ כשאוסר עליהם כגון שאין הבית פתוח אלא לאותו חצר <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אבל אם הוא פתוח לשתי חצרות באחת רגיל לצאת ולבא תדיר שאוסר עליהם ובאחת אינו רגיל לצאת ולבא ברגיל שאוסר מערבת שלא מדעתו אפי' אינו רגיל לערב וכשאינו רגיל לצאת ולבא נמי אע\"פ שאינו אוסר אם רגיל לערב עמהם מערבת שלא לדעתו אבל אם אינו אוסר וגם אינו רגיל לערב עמהם אינה מערבת שלא לדעתו <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>וכל זמן שלא מיחה בה בפירוש אפי' אם אינו רגיל לערב עמהם ואינו אוסר מערבת שלא בידיעתו דמסתמא ניחא ליה <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אבל <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>אינה יכולה <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>לזכות משלו לאחרים שלא בידיעתו <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ואם אין הבעל והאשה בעיר יכולים <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>בני הבית לערב שלא בידיעתו אם אין הבית פתוח אלא <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>לחצר א' ואפילו אם היה פתוח לשתי חצרות אם הוא רגיל לערב לאחת מהם מערבין עליו אבל אם אינו רגיל לא <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>אבל בני החצר אין יכולים ליקח פתו מביתו לערב שלא מדעת <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אחד מבני הבית אפילו רגיל עמהם ואוסר עליהם <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>וי\"א דאין אשתו מערבת אלא שלא בידיעתו אבל אם אומר שאינו רוצה לערב עמהם לא <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>ואם הוא רגיל לערב עמהם ועכשיו אינו רוצה <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>בני חצר נכנסים לתוך ביתו ונוטלים ממנו בע\"כ ואם אינו רגיל אינם יכולים ליטול ממנו בע\"כ <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>אבל כופין אותו בב\"ד לערב עמהם או בית דין יורדים לנכסיו: <small>הגה מי שאינו רגיל לערב ועירב עם בני חצר וחזר מעירובו צריך לחזור ולזכות אבל אם רגיל לערב <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>הוי עירוב בעל כרחו [הרא\"ש פרק הדר]:</small>","m":["(א) אשתו של אדם וכו' - מפני שאשתו כגופו והקילו אפילו כשמיחה בה משום שחששו חז\"ל שמא יתכוין להקניט את הדרים לאסור עליהם:","(ב) מערבת לו - משלו:","(ג) כשאוסר עליהם - החצר אם לא יערב עמהם:","(ד) ברגיל שאוסר וכו' - כדלקמן בסי' שפ\"ו ס\"ט ע\"ש:","(ה) רגיל לערב וכו' שלא לדעתו - היינו אפילו כשמיחה בה והטעם משום דרכי שלום כיון שעד עתה היה דרכו ליתן חלק בעירוב לכן חל העירוב בכל גווני ומותר אח\"כ לטלטל כלים ששבתו בביתו למבוי זה:","(ו) אבל אינה יכולה וכו' - היינו אפילו לבני חצר שאוסר עליהם ורגיל לערב עמהם:","(ז) לזכות משלו וכו' - וממזונותי' יכולה לזכות שהיא שלה:","(ח) שלא בידיעתו - פי' שאין הבעל יודע מזה:","(ט) יכולים בני הבית וכו' שלא בידיעתו - ואם ידעו ממנו שאינו רוצה אע\"פ שלא מיחה בם בפירוש אין יכולים לערב:","(י) לחצר אחד - דזכות היא לו ובודאי לא יקפיד עליהם אבל אם הוא פתוח לשתי חצרות אין יכולים לערב עליו שלא בידיעתו כי איננו זכות לו ודאי כי שמא לא יחפוץ לערב עם חצר זו אלא עם זו אם לא כדמסיים המחבר:","(יא) רגיל לערב וכו' - דמסתמא גם עתה דעתו לזה:","(יב) שלא מדעת אחד מבני הבית וכו' - ר\"ל שלא בידיעת אחד מבני בית דאי היה בידיעתם היה מותר כ\"ז שלא שמעו מבעה\"ב שאינו רוצה בעירוב ועיין בבה\"ל שהבאנו בשם כמה אחרונים שפוסקין דבני החצר יכולין ליקח פתו שלא בידיעתו [כ\"ז שאין יודעין שהוא מוחה בדבר] ואפילו שלא בידיעת ב\"ב:","(יג) אבל אם אומר שאינו רוצה וכו' - אפילו אם אין הבית פתוח אלא לחצר אחד שאוסר עליהם ע\"י מניעתו את העירוב:","(יד) לערב עמהם לא - ואפילו אם אמר כן לאחר שעירבה נתבטל עירובה למפרע:","(טו) בני חצר וכו' - וה\"ה אשתו ומיירי שע\"י מניעתו את העירוב אוסר עליהם:","(טז) אבל היו כופין אותו בב\"ד - ר\"ל אע\"פ שהן בעצמן אין יכולין לעשות דינא לנפשייהו ב\"ד היו כופין אותו שיערב עמהן כדי שלא יאסור עליהן. ודין זה דב\"ד כופין הוא לכו\"ע אף לדעה ראשונה:","(יז) יורדין לנכסיו - ועושין שיתוף:","(יח) וחזר מעירובו - היינו שאמר חוזרני בי מן העירוב ואיני רוצה לערב ולהשתתף עוד עמכם:","(יט) צריך לחזור ולזכות - דבטל עירובו ושיתופו הקודם אף שעדיין הפת מונח במקומו וע\"כ אם ירצה להיות עוד שותף עמהם צריך להשתתף מחדש ועיין בה\"ל:","(כ) הוי עירוב בע\"כ - ר\"ל שאינו יכול לחזור ולבטל עירובו וכדלעיל דהיכא שהוא רגיל לערב עמהם באים בני החצר ונוטלין ממנו בע\"כ וכ\"ש הכא שהפת כבר מונח בידם ואף לדעה הראשונה דס\"ל דבלא דעת אשתו אין בני החצר יכולין ליקח ממנו בע\"כ הכא קילא מפני שהפת כבר מונח תחת ידם:\n"]}],"368":[{"s":"<b>דין אם אחר שעירבו נתקלקל העירוב. ובו ה סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>עירבו ואח\"כ <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>נתקלקל העירוב ובא א' מבני החצר <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>לחזור ולתקנו <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אם בא לערב ממין הראשון אפי כלה א\"צ להודיע <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ואפי' מערב עליהם משלהם ואם בא לערב ממין אחר אם כלה הראשון צריך להודיע להם אם מערב משלהם ואם משלו א\"צ להודיעם כלל ואם לא כלה הראשון אלא נתמעט אע\"פ שמערב משלהם א\"צ להודיעם:","m":["(א) לחזור ולתקנו - זה מיירי בשבת ראשון ונתקלקל קודם שנכנס השבת דאלו נתקלקל אחר שכבר נכנס השבת א\"צ שום תיקון לשבת זו אפילו כבר כלה ונאבד לגמרי. ולענין שבת שניה אף דאם כבר כלה לגמרי צריך לערב מחדש הלא עכ\"פ בנשתייר אפילו כל שהוא א\"צ שום תיקון כיון דהיה שיעור עירוב בבין השמשות של שבת ראשונה כמ\"ש בס\"ד ומה זה דקאמר בסוף הסעיף ואם לא כלה וכו' אע\"פ שמערב משלהם וכו' אלא ודאי כדכתבנו דנתקלקל קודם שנכנס השבת ראשונה:","(ב) א\"צ להודיע - לשאלם אם יתרצו לזה דמוקמינן אחזקתיה דודאי יתרצו כולם ממין זה כמו שנתרצו מתחלה [לבוש]:","(ג) ממין אחר - כגון שהיה מתחלה פת חטים ועכשיו רוצה לערב מפת שעורים:","(ד) צריך להודיע להם - לשאלם דכיון שכבר כלה המין הראשון הו\"ל כמערב לכתחלה וכתב במאמר מרדכי דדוקא בבית הפתוח לשתי חצרות דלא ידעינן בהי ניחא ליה אבל בפתוח לחצר אחד זכות הוא לו וא\"צ דעתו וכ\"כ שארי אחרונים:","(ה) ואם משלו אינו צריך להודיעם - לפי שבודאי יתרצו שיערב עליהם בכל המינים שירצה כיון שהם אינם נותנים כלום וכבר נתרצו לערב יחד:","(ו) אלא נתמעט - משיעור המפורש לקמן בס\"ג ומיירי שנתמעט קודם שנכנס השבת כמש\"כ בסק\"א:","(ז) א\"צ להודיעם - דבודאי יתרצו להשלים העירוב:","(ח) ניתוספו דיורים וכו' - שלא היו בעת הנחת העירוב:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>נתוספו דיורים בחצר אם הבית פתוח לשתי חצרות <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>צריך להודיעם מפני שאולי אינם רוצים לערב עם אלו:","m":["(ט) אם הבית וכו' - אקדים הקדמה קצרה והוא. קי\"ל דמערבין עירובי חצרות שלא מדעת דזכות הוא וזכין לאדם שלא בפניו ומ\"מ אם יש בחצר בית הפתוח לשתי חצרות אין מערבין בשבילו שלא בידיעתו דשמא אינו חפץ כלל לערב בחצר זו עם אנשים אלו אלא בחצר אחרת וקאמר המחבר דזה הדין שייך ג\"כ בניתוספו דיורין בחצר דהוספה זו ג\"כ כתחלת עירוב הוא וצריך לעשות עירוב דוקא בידיעתם אבל שלא בידיעתם לא ואפילו אם מערב עתה משלו [מ\"א ועו\"ש] ויש מקילין שיכול לערב משלו בכל גווני. ודע עוד דהא דקי\"ל דמערבין ע\"ח שלא לדעת ג\"כ יש דיעות בין הפוסקים יש פוסקים דסברי דדוקא אם מערב משלו ויש פוסקים דסברי דיוכל לערב אפילו משלהם בלא דעתם דמסתמא מתרצים לזה ועיין במש\"כ לעיל בסימן שס\"ז בביאור הלכה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>כמה הוא שיעור העירוב בתחלתו בזמן שהם שמונה עשרה או פחות שיעורו כגרוגרות לכל א' ואם הם יותר משמונ' עשרה אפילו הם אלף או יותר שיעורו מזון שתי סעודות שהם שמונ' עשרה גרוגרות <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>שהם כששה ביצים <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>וי\"א שהם כשמונה ביצים:","m":["(י) ואם הם יותר וכו' - ר\"ל דשיעור שמנה עשר גרוגרות הוא שיעור היותר גדול שהוא שיעור שתי סעודות ובשיעור הזה די אפילו לאלף ומה שכתב שיעורו שתי סעודות ר\"ל שיעורו ג\"כ שתי סעודות:","(יא) שהם כששה ביצים - היינו בקליפתן:","(יב) וי\"א שהם כשמונה ביצים - ולכתחלה נכון לנהוג כן ובדיעבד די כששה ביצים:"]},{"s":" <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>נתמעט מכשיעורו <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>אחר שנכנס שבת ראשונ' ונשתייר בו <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>אפי' כל שהוא כשר אף <i data-commentator=\"Eshel Avraham\" data-label=\"א\" data-order=\"1\"></i>לשאר שבתות:","m":["(יג) מכשיעורו - גרוגרת לכל אחד או שתי סעודות למרובין:","(יד) אחר שנכנס - דאלו נתמעט קודם שקידש עליו היום הו\"ל כתחלת עירוב אף שכבר הניחו לשם עירוב וכדלעיל בריש הסימן:","(טו) כשר - דלא צריכא שיעור אלא בתחלה ובין בע\"ח ובין בשיתופי מבואות:","(טז) אף לשאר וכו' - דאלו לשבת זה כשר אפילו לא נשתייר כלל כיון שהיה העירוב קיים בין השמשות. ועיין במ\"א שכתב דדינא דנשתייר כשר הוא רק בזמן הש\"ס שהיו עושין עירובי חצרות ושיתופי מבואות כ\"א בפני עצמו משא\"כ לדידן דנהגינן לעשות שיתוף ועירוב ביחד וכמבואר בסימן שפ\"ז פסול לשבת שניה אם אין בו שיעור עירוב ועיין בבה\"ל שיש חולקין בזה ולכתחלה בודאי צריך ליזהר להוסיף עד כשיעור:","(יז) שבתות - ואף שקי\"ל לעיל בסימן שס\"ו ס\"ו שאין מערבין בפרוסה היינו כשהיתה פרוסה בשעה שהניחה לשם עירוב משא\"כ הכא שנפרסה אח\"כ לית לן בה ומ\"מ יש מחמירין בשנפרסה קודם בין השמשות כיון שיש שהות עדיין להניח ככר אחר שלם:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>אם נתעפש פת העירוב ונפסל מלאכול הרי הוא כמו שכלה לגמרי וצריך לערב מחדש: <small>הגה ולכן נהגו לעשות העירוב חלת מצה שאינה ממהרת להתעפש [כל בו ב\"י סי' שנ\"ד] ועוד דיכולים לשמרה בימי הפסח ויכולים לשמור העירוב כל השנה [דעת עצמו] <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>וזה <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>טוב יותר מלערב כל שבת ושבת שלא ישכחו מלערב מיהו אם רוצים לערב כל ע\"ש ולאכול העירוב כל שבת הרשות בידם וע' לקמן סי' שצ\"ד:</small>","m":["(יח) אם נתעפש וכו' - וה\"ה כשהתליע בתולעים קטנים (שקורין מילבין) [אחרונים]:","(יט) ונפסל מלאכול - היינו כשנתעפש כולו:","(כ) מחדש - ואם ראה ד\"ז בשבת ואינו ידוע לו מתי נתעפש אם קודם שבת או בשבת תלינן לקולא ואמרינן דמקרוב נתעפש ובהמ\"ש היה ראוי לאכול וכבסימן שצ\"ד:","(כא) טוב יותר וכו' - והאחרונים כתבו דיותר טוב לערב כל ע\"ש כי רוב פעמים מצה של עירוב מתקלקלת ומתעפשת מאורך הזמן וגם מצוי ליפול בו תולעים [שקורין מילבין] מאורך הזמן ואינה ראויה לאכילה והרי היא כמו שכלתה לגמרי וכנ\"ל והרוצה לעשות עצהיו\"ט יערב משלו בכל ע\"ש ויזכהו לכל הקהל ע\"י אחר ובזה אין חשש אם יתקלקל העירוב שבבהכ\"נ ולא יברך על שלו כיון שיש עירוב בבהכ\"נ ושמא הוא כשר והברכות אין מעכבות:","(כב) ולאכול העירוב כל שבת - משום דהואיל ואיתעביד ביה מצוה חדא יתעבד ביה מצוה אחריתא:"]}],"369":[{"s":"<b>באיזה אופן מקנין העירוב. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>הנותן מעות לנחתום ואמר לו אם יבואו בני חצר לקנו' ממך ככר לעירוב זכה לי בעירוב שיהא לי חלק עמהם בשביל מעה זו <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>אינו עירוב אפילו <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>עירב החנוני [לכל האחרים] <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>וזכה גם לזה עמהם <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>אבל אם אמר לו <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>ערב לי קנה עירוב ואפילו אם אמר זכה לי <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אם <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>נתן לו כלי בתור' קנין שיקנה לו בו קנה עירוב <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>וכן אם זיכה לו הנחתום <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>ע\"י אחר <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>או שקנה במעה שנתן לו לחם מן השוק קנה עירוב <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>ואם נתן <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>מעה <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>לבעל הבי' ואמר לו זכה לי בעירוב קנה עירוב:","m":["(א) אפילו עירב החנוני - ר\"ל ע\"י זיכוי שזיכה להן ע\"י אחרים כדלעיל בסימן שס\"ו ס\"ט:","(ב) וזכה גם לזה - ר\"ל בכלל כל בני החצר ולא פרט שמו בהדיא והטעם דמסתמא לא כוון ליתן לו במתנת חנם כמו לאחרים אלא בשביל מעות שנתן לו ומעות אינן קונות נמצא שאין לו חלק בעירוב:","(ג) ערב לי וכו' - גם בכאן מיירי שזיכה לו הנחתום בכלל עם אחרים וכמו למעלה והטעם דהכא מהני משום דכיון דאמר ערב לי הרי עשאו שליח לערב לו באופן שיועיל והוי כאלו אמר לו בהדיא שיזכה לו במתנת חנם כמו לאחרים:","(ד) אם נתן לו כלי וכו' - דדוקא מעות אינן קונות עד שימשוך החפץ אבל אם מקנה לו כלי הוי חליפין וכיון שזכה זה בכלי זכה זה בפת ששייך להעירוב כמ\"ש בהרבה מקומות:","(ה) וכן אם זיכה לו הנחתום - ר\"ל שפרט שמו בהדיא ולא בסתמא עם אחרים וע\"כ אף דמעות אינן קונות מ\"מ הרי יש לו חלק בעירוב מטעם דזכין לו לאדם שלא בפניו ובזה מיושב דלא יסתור למה שכתב בראש הסעיף דזיכוי לא מהני:","(ו) ע\"י אחר - ויש מאחרונים שחולקין ע\"ז וס\"ל דכיון דנתן מעות אפשר דלא ניחא ליה לקבל בתורת מתנה ובמעות הלא אינו קונה:","(ז) או שקנה וכו' - דנעשה בזה כשלוחו וקנה זה את הלחם ונמצא שיש לו חלק בעירוב:","(ח) מעה לבעה\"ב וכו' - גם בכאן מיירי שמזכה לו בע\"ה בכלל עם אחרים במתנה והטעם דמהני הכא לפי שאין דרך בעה\"ב למכור משלו ולדעת שיקנה לו במעותיו אמר לו וכאלו אמר לו ערב לי שעשאו שליח דמיא וע\"כ אפילו אם לקח מככרו וזיכה לו עם כל אנשי החצר ג\"כ מהני:"]}],"370":[{"s":"<b>דיני שתוף בערוב. ובו ח סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>הדר <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>בבי' שער אכסדרה ומרפס' שבחצר אינו אוסר על בני החצר <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>שאינם חשובים דירה אבל הדר בבי' התבן בבי' העצים בבי' הבקר ובבי' האוצרו' אוסר:","m":["(א) הדר בבית שער וכו' - לא שנא של רבים ולא שנא של יחיד ואע\"פ שיש לו להבית שער ארבע מחיצות וגם הוא מקורה אפ\"ה כיון שעוברים דרך שם אינו חשוב דירה ועיין לקמן בס\"ז:","(ב) ומרפסת - פירושה מבואר לקמן בסימן שע\"ה:","(ג) אינו אוסר וכו' - אם לא נתן חלק בעירוב:","(ד) שאינם חשובים דירה - וה\"ה סוכת החג בחג ג\"כ לא חשיבה דירה לאסור. בית שאין בו ד\"א על ד\"א אינו אוסר דלא חשיבא דירה:","(ה) אבל הדר וכו' - דחשובים דירה ואע\"פ שעשוים מקנים וכיו\"ב ומבואר לקמן בס\"ה דאם אוכל שם אע\"פ שאינו ישן ושוכב שם מקרי דירה דמקום פיתא גורם:","(ו) אוסר - עד שיתן חלקו בעירוב:","(ז) והשאילן וכו' - ודוקא כשהשאילן לזמן מרובה אבל אם השאילן לפי שעה אין אוסר עליו בכל ענין [עבוה\"ק]:","(ח) מחמת כבדן - אף שאין נעשה מוקצה ע\"י הכובד מ\"מ כיון שיש טורח לפנותן אין דרך ליטלן בשבת:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>בעל הבי' שיש לו הרבה בתים בחצר והשאילן או השכירן לאחרים ויש לו בכל א' מהם דברים <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>שאינם ניטלים בשב' <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>מחמ' <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>כבדן או מחמ' איסור שהם דברים שאסור לטלטלם אפי' לצורך מקומו אין הדרים בהם אוסרים עליו <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>לפי שנעשו כולם כאורחים אצלו לפיכך גם הם מותרים להוציא מבתיהם לחצר אע\"פ שלא נתנו עירוב <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>ואם אין הבתים שלו לא קנויות ולא שכירות אע\"פ שיש לו בהם דברים שאסור לטלטלם אוסרים זה על זה: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>ויש אומרים דכל זה כשאין דיורים בחצר אלא הם אבל כשיש דיורים אחרים <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>ומוליכים ערובן אצלן <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>צריכים כל אחד לערב (הר\"ר יהונתן פרק כיצד משתתפין) אחד ששכר בית מן העכו\"ם והשכיר אחד מן הבירה לחבירו אם מתחלה לא שכרה אדעתא דהכי הוה ליה כאלו כל הבירה שלו והשכיר אחד מן הבתים לחבירו אבל אם <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>שכרה מתחלה אדעתא דהכי הוה ליה שני בתים ולא מהני אע\"פ שיש לאחד מהם תפיסת יד בבית חבירו (מהרי\"ק שורש מ\"א):</small>","m":["(ט) שאסור לטלטלם אפילו וכו' - דאם היה מותר לטלטלן לצורך גופן ומקומן אפשר שיצטרך בעה\"ב להשתמש בהם בשבת או להוציאן מביתו מחמת איזה סיבה ולא ישאר לו שם תפיסת יד:","(י) שנעשו כולם כאורחים - כיון שלא סילק עצמו מבתים אלו מכל וכל ודוקא כשמונח שם חפציו אבל כ\"ז שאין מונח שם אף שיש לו רשות להניח שם לא מהני:","(יא) אצלו - ומיירי כשיש לו רשות להניח שם ואפילו אין לו רשות להניח בכל הבית רק בפינה אחת אבל אם אין לו רשות לזה כלל רק שהניח לשם בדרך מקרה ואין מקפידין עליו בזה לא נעשו עי\"ז כאורחים אצלו ואוסרין עליו:","(יב) ואם אין הבתים שלו וכו' - ר\"ל דדינא דלעיל מיירי שהבתים שלו בעצם או שהוא שכור או שהוא שאול אצלו והוא השכירן או השאילן לאחר דבזה אמרינן דהוא נעשה כאורח אצלו אבל אם אין הבית שייך לו כלל אלא שניהם הם שכנים בחצר וכל אחד יש לו בית בפ\"ע ואחד יש לו רשות בבית חבירו להניח שם חפציו והניח שם לא נעשה הוא כבעה\"ב עליו והשכנגדו כאורח אצלו:","(יג) דכל זה וכו' - ר\"ל אימתי מועיל תפיסת יד שיש לבעה\"ב בזמן שאין עמהם דיורין אחרים בחצר אלא הוא ואותן האנשים שהשאיל ושהשכיר להן [או אפילו יש עוד דיורים בחצר אלא שאותן דיורין מביאין עירובן ומניחין אותו בבית בעה\"ב זה או באחד מבתים השאולין שיש לבעה\"ב תפיסת יד בהן ואז א\"צ כלל ליתן לעירוב פת לפי שכל בתים אלו הם כבית אחת ובית שהעירוב מונח בו א\"צ ליתן פת] אבל כשיש עוד דיורין אחרים בחצר ומניחים העירוב שלא בבית בע\"ב זה אלא בבתי שארי דיורין דבזה הלא הבעה\"ב בלא\"ה צריך ליתן חלק בעירוב לא מהני בזה תפיסת יד לפטור השוכרים מליתן חלק בעירוב דמיגו דשארי דיורים אסרי אבעה\"ב הנך שדרים בביתו נמי אסרי עליו עד שיתנו חלק בעירוב:","(יד) אחד מן הבירה - היינו חדר אחד מן הבירה:","(טו) אדעתא דהכי - ר\"ל בשעה ששכר מן העכו\"ם לא כיון לשכור בעדו ובעד חבירו:","(טז) אבל וכו' אדעתא דהכי - ר\"ל דמתחלת שכירות כוון לשכור גם בעד חבירו ונתרצה אתו לדור יחדו אשתכח דהאי שוכר מן העכו\"ם שליחותו דחבריה קעביד ושניהם שוין בבית זה:","(יז) ולא מהני - וכנ\"ל בדברי המחבר דאם אין הבתים שלו וכו':"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>חמש חבורות ששבתו בטרקלין וחלקוהו במחיצות <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>אם עוברים כולם זה על זה שאין פתח לחצר אלא החיצון וכולם עוברים דרך עליו אין צריכים ליתן בעירוב <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>אלא שנים הפנימיים וכל האחרים חשובים כבית שער להם ואם היה <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>לכל א' פתח פתוח לחצר: <small>הגה <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>או שאין <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>עוברים זה על זה רק כל אחד יש לו פתח פתוח לבית שער שלפניהם והבית שער פתוח לחצר (ב\"י) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>אם המחיצות מגיעות לתקרה בתוך ג\"ט דהוי כל א' חדר בפני עצמו <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>אפילו הן של יריעות <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>אם בני החצר נותנים העירוב בא' משאר בתי החצר <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>צריך כל אחת ואחת מחבורות שבטרקלין ליתן עירוב אבל אם נתנו העירוב בזה הטרקלין אין צריכין ליתן עירוב כלל שכולם דרים בבית זה ובית שמניחים בו העירוב אין צריך ליתן עירוב וכן אם אין דיורין אחרים בחצר אינם צריכים עירוב חלקוהו במחיצות שאין נוגעות לתקר' <small> (אפי') </small> אם בני החצר נותנים עירובן בא' משאר בתי החצר די בעירוב א' לכל החמש חבורות: <small>הגה אם מקצתן עשו מחיצות ומקצתן לא עשו אותן שעשו הם מחולקים ואותם שלא עשו <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>הם כמשותפין. (המגיד פרק ד') </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>ואם היו דיורין בעליות ממש אפילו נתנו בני החצר העירוב בטרקלין צריכה כל חבורה וחבורה לתת עירוב <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>אבל מי שיש לו <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>מלמד או סופר בביתו וכן תלמידים הלומדים בפני הרב ודרים בביתו כל א' בחדרו <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>אפילו יש לכל א' פתח פתוח <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>לחצר ואוכל וישן בחדרו אינם אוסרים:","m":["(יח) ששבתו בטרקלין - ר\"ל שדירתם בטרקלין:","(יט) אלא שנים הפנימים - דאף דהשני הוא ג\"כ בית שער לראשון שהראשון עובר דרך עליו מ\"מ לא מקרי בית שער לפטרו מן העירוב דבית שער דיחיד [דהיינו שרק יחיד עובר דרך עליו] לא מקרי בית שער כדלקמן בס\"ז וע\"כ כל אחד ואחד מהן חייב בעירוב ומיירי באופן שהמחיצות שביניהן מגיעות לתקרה ואי אין המחיצות מגיעות לתקרה נחשבין שנים כבית אחד ואין צריכין ליתן רק עירוב אחד בין שניהן אם יש עמהן עוד דיורין בחצר:","(כ) ואם היה לכ\"א - ר\"ל שאינם עוברים זה ע\"ז רק שיש לכ\"א מחדרו פתח פתוח לחצר:","(כא) או שאין עוברין וכו' - ר\"ל דהמחבר צייר אינם עוברים בגווני שהיה לכ\"א מחדרו פתח לחצר והרמ\"א מוסיף דאפילו כל הפתחים לא היו פתוחים לחצר אלא שהיו פתוחים כ\"א בפני עצמו להבית שער שהיה נגד כל החדרים ובבית שער היה פתח אחד שממנו יוצאים לחצר ואשמעינן דלא תימא כיון שכולם יוצאים לחצר דרך פתח אחד דהיינו פתח של בית שער מקרי מחוברים כולם וכעוברים זה ע\"ז דמי קמ\"ל דלא משגחינן בזה כיון שאינם עוברים זה על זה. ולפ\"ז בבתים שלנו שדרים כמה שכנים בבית וכ\"א בחדרים מיוחדים אע\"פ שעוברים לחוץ דרך הבית שלפניהם שהוא להם כבית שער מ\"מ חייבים כולם בעירוב ולפיכך אם נתקלקל העירוב של עיר אסורים לטלטל כ\"א מחדרו לחדר חבירו [אם לא שיש לבעה\"ב תפיסת יד בחדריהם כגון דברים שאינם ניטלין וכו' וכדעיל בס\"ב שאז נחשב כאלו כל הבית והחדרים שלו והם רק כאורחים אצלו וא\"צ לעירוב] ולענין טלטול מחדר לבית עיין לקמן בסעיף זיי\"ן ועיין בבה\"ט ובבה\"ל מה שכתבנו בזה:","(כב) בתוך ג\"ט - דהוי לבוד וכסתום עד למעלה דמי:","(כג) של יריעות - אכן באופן שקשורות היטב מלמטה שלא ינידם הרוח וכדלעיל בסי' שס\"ב ס\"א [אחרונים]:","(כד) צריך כל אחת ואחת וכו' - דכיון דאסרו הנך דיורין שבחצר אם לא עירבו אסרי נמי הנך שבטרקלין כיון שהמחיצות שבהן מחולקות אף שהן מחיצות גרועות:","(כה) אין צריכין וכו' - ומיירי במחיצות עראי כעין מחיצות של יריעות דאלו חלקוהו במחיצות גמורות כגון של נסרים וכדומה בוודאי אין נ\"מ בין עירוב בא אצלן וכו' ובין יש דיורין אחרים בחצר או אין דיורין דבכולהו צריכין ליתן חלק בעירוב וכדמסיים המחבר בסוף אם היו דיורין בעליות ממש וכו':","(כו) שכולם דרין בבית זה - היינו אף שהעירוב מונח בחדר אחד דמי כמאן שהעירוב היה מונח אצל כולם דהתקרה מחברן לבית אחד כיון שתחתיו הם מחיצות גרועות:","(כז) במחיצות שאין נוגעות לתקרה - אפי' הם מחיצות קבועות של נסרים ואבנים ואפילו גבוהות יותר מעשרה:","(כח) די בעירוב א' וכו' - דכבית אחד דמי:","(כט) עשו מחיצות - המגיעות לתקרה:","(ל) הם כמשותפין - פי' ואז כולם נותנין עירוב א':","(לא) בעליות ממש - כבר כתבנו דה\"ה כשנתחלקו החבורות ע\"י מחיצות קבועות כגון של נסרים וכדומה כיון שהם מגיעות לתקרה:","(לב) צריכה כל חבורה וכו' - ואפי' כשאין דיורין אחרים בחצר צריכין לעשות עירובי חצרות:","(לג) אבל מי שיש לו וכו' - הטעם כיון שכולם משתמשין בשל בעה\"ב באפיה ובישול ובכל דבר חשיבי כולהו כאלו אוכלים וישנים במקום אחד ואע\"פ שיש להם פתח לצד חצר נקראים ע\"ש בע\"ה ועוד דאין משאיל להם רשותו לאסור עליו. וכ\"ז בשהיה שאול להם אבל אם היה מקום החדרים קנוי או מושכר להם או אפילו בשאול רק שמשתמשין כל אחד בפ\"ע בחדרו אוסרין דדוקא בצירוף שני הטעמים ביחד מקילינן. וכ\"ז בשלא היה לבעה\"ב אצלם תפיסת יד דאל\"ה מותר בכל גווני וכנ\"ל בס\"ב:","(לד) פתח פתוח לחצר - והו\"א דיכול לאסור על בני החצר כשלא עירבו:","(לה) אינם אוסרים - על אנשי החצר ולא זה על זה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>אנשי חצר שהיו כולם אוכלים על שלחן אחד אע\"פ שכל א' יש לו בית בפני עצמו אינם צריכים עירוב מפני שהם כאנשי בית א' ואם הוצרכו לעשות עירוב עם אנשי חצר אחרת עירוב אחד (לכולן) ופת אחד בלבד מוליכין לאותו מקום שמערבין עמו ואם היה עירוב בא אצלם אינם צריכים לתת עירוב כדין בית שמניחים בו עירוב שכל אלו הבתים כבית אחת הם חשובים: <small>הגה וכן אם הרבה בעלי בתים אוכלים בחדר אחד כל אחד על שלחנו אע\"פ שכל א' ישן בחדר בפני עצמו עירוב א' לכולם <i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>הואיל ואין מחיצה מפסקת בין מקום אכילתן הוי כחמשה ששבתו בטרקלין וכו' ואע\"פ שפורסין לפעמים וילון לפניהם לצניעות לא מיקרי מחיצה הואיל ולא הוי שם <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>בקביעות (ר' ירוחם חט\"ו):</small>","m":["(לו) אוכלים על שלחן אחד - אע\"פ שכל אחד אוכל משלו [ב\"י]:","(לז) יש לו בית בפ\"ע - ללינה ולשאר תשמישין וכדלקמיה:","(לח) עירוב אחד לכולן - ואיזה מהם שירצה יכול ליתן הפת וא\"צ לזכות דשליחותא דכולהו קעביד:","(לט) וכן וכו' - כ\"א על שולחנו. הרמ\"א הוסיף דלאו דוקא על שולחן אחד דה\"ה על שולחנות מיוחדות הואיל שהם בבית אחת:","(מ) הוי כחמשה ששבתו בטרקלין - וע\"כ אפילו היתה שם מחיצה אלא שאין מגיע לתקרה או לסמוך לה בתוך ג\"ט הוי כאלו אינה [כן איתא בב\"י]:","(מא) בקביעות - דאין פורסין אותה אלא כשעושה דבר צניעות:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>מי שאוכל במקום א' וישן במקום אחר מקום אכילתו הוא העיקר ושם הוא אוסר <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>הילכך האחים שאוכלים בבית אביהם וישנים בבתיהם אינם אוסרים ואם נותן להם <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>פרס ואוכלים בבתיהם אוסרים <i data-commentator=\"Turei Zahav\" data-order=\"8\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i>והני מילי כשנותנים בני שאר החצר עירובן במקום אח' אבל אם היו בני שאר החצר נותנים העירוב בא' מבתים אלו או שאין עמהם דיורים בחצר אינם צריכים לערב:","m":["(מב) וישן במקום אחר - ר\"ל בחצר אחר:","(מג) אינם אוסרים - פי' לא במקום השינה כשלא עירבו עם שאר אנשי החצר ולא במקום האכילה שהם נגררים אחר אביהן ויוצאים בעירובו:","(מד) פרס - פי' שהם מקבלים הוצאה מבית אביהן ואין חילוק בין כשמקבלים לחם או מעות [אחרונים]:","(מה) אוסרים - על אחרים וה\"ה זה ע\"ז כשלא עירבו ואפילו הם דרים בחצר אחת עם אביהם הואיל ואינם אוכלים על שולחנו ממש:","(מו) וה\"מ כשנותנין וכו' - פי' אימתי אמרינן שקבלת פרס אינו מועיל כשחוץ מן האחין ואביהן היו עוד דיורין בחצר והוזקקו לעירוב והניחו אותו אצל אחד מהדיורין דאז אמרינן כשם ששארי דיורין אסרי זה ע\"ז אם לא היו מערבין אינהו נמי אסרי אהדדי אבל כשאין עמהם דיורין אחרים בחצר הם בעצמן אין מזקיקין לעירוב [דהואיל שמקבלין עכ\"פ פרס מאביהן האב מחברן ומצרפן להיות כאיש אחד] וכן כשנתנו בני החצר עירובן אצל אחד מהאחין אמרינן הואיל דהוא פטור מליתן חלק בעירוב משום בית שמניחין בו עירוב גם שאר אחיו נמי פטורין ומטעם הנ\"ל:","(מז) באחד מבתים אלו - ר\"ל או אצל אב או אצל אחין:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i>מי שיש לו חמשה נשים וחמש' עבדים מקבלים ממנו פרס וכל א' אוכל בביתו וכן <i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"19\"></i>תלמיד המקבל פרס מרבו ואוכל בביתו אינם אוסרים זה על זה אם אין עמהם דיורין בחצר או אם העירוב בא אצלם:","m":["(מח) חמשה נשים וכו' - דהם נמי נמשכין אחר בעליהן ואדוניהן:","(מט) עבדים - וה\"ה משרתים:","(נ) אם אין וכו' - וכמו אצל אחין בס\"ה. ודוקא בכל אלו מועיל פרס לפי שהן נמשכין אחריהן אבל באדם דעלמא המקבל פרס מחבירו אין מועיל כלל:","(נא) צריכין ליתן בעירוב - שהם לבדם תורת בית עליהם ואוסרים לטלטל בחצר וכן לטלטל מזה לזה וכן מהם לבתים שלפניהם ואע\"ג דהשני הוי בית שער לפנימי שעובר דרך עליו לא מתבטל מתורת בית עי\"ז כיון דהוי רק בית שער ליחיד:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"20\"></i>עשרה בתים זה לפנים מזה וכולם עוברים זה לזה ויוצאים דרך החיצון לחצר <i data-commentator=\"Turei Zahav\" data-order=\"9\"></i><i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>שנים הפנימיים לבד צריכים ליתן בעירוב והשאר פטורים שחשובים כולם כבית שער:","m":["(נב) שחשובים כולם וכו' - שכל אחד מהם הוא בית שער לכל הפנימים ממנו ואינו חשיב דירה כיון שרבים עוברים עליו ולפ\"ז בבית שיש בתוכו שני חדרים ומושכרים לשני בני אדם ובבית שלפני החדרים דר בו בעה\"ב בעצמו ועוברים דרך עליו הם בעצמם חייבים ליתן בעירוב ובעה\"ב בעצמו פטור שהוא כבית שער להם:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"21\"></i>המתארח בחצר אפי' נתארח בבית בפני עצמו אם לא נתארח דרך קבע <i data-commentator=\"Turei Zahav\" data-order=\"10\"></i>אלא <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>לשלשים יום או פחות אינו אוסר על בני החצר והוא והם מותרים בין בביתו בין בביתם: <small>הגה ואפילו אם האורחים רבים ובעל הבית א' ודוקא בדאיכא בעל הבית א' קבוע דאז האורחים בטלים לגביה אבל אורחים ביחד <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i><i data-commentator=\"Sha'arei Teshuvah\" data-order=\"11\"></i>אוסרים זע\"ז מיד [תה\"ד סי' ע\"ו מגמ' סוף דף ע'] ועיין לקמן ס\"ס שצ\"א: [ועכו\"ם המתארח ע\"ל סי' שפ\"ד]:</small>","m":["(נג) המתארח בחצר - אפילו היה הדירה בשכירות:","(נד) בבית בפני עצמו - שאוכל וישן שם ונקט בפ\"ע דאם היה ביחד עם בעה\"ב אפילו בקבע אינו אוסר כשלא עירב:","(נה) אלא לשלושים יום - וביותר משלשים אפילו אם היה רק בשאילה לבד תו מקרי קבע ויצא מכלל אורח ואוסר. ומסתברא דאם קבע עצמו לכתחלה יותר משלשים אוסר מיד. כתב הט\"ז דביותר משלשים דאסרינן דוקא במתארח במקום שאין קהל אבל במקום שיש קהל ועושין ע\"ח בע\"פ כדרכנו אז פטור גם בזה כי לב ב\"ד מתנה על כל הדיורים שיתוספו וכמו שמבואר בסימן שס\"ו ס\"ט עי\"ש. ומ\"מ טוב במקום שיש ירידים שרגילין לבוא אורחין ולהשתהות שם יותר משלשים יום שיתנו הקהל בפירוש בשעה שעושין העירוב דהוא לכל מי שיתוסף בעיר הזאת:","(נו) אינו אוסר וכו' - י\"א שאפילו רגיל לבוא שם כמה פעמים להתארח ויש מי שמחמיר בזה וכמו לענין עכו\"ם בסי' שפ\"ד ס\"א עי\"ש:","(נז) ואפילו אם האורחים רבים וכו' - נמי בטלים לגבי בעה\"ב ונעשים כאנשי ביתו:","(נח) אבל אורחים ביחד - ר\"ל שלא היו שם רק אורחים בחצר ומיירי בשיש לכל אחד חדר מיוחד לאכילה כמ\"ש ס\"ג:","(נט) אוסרים וכו' - דכיון דליכא כאן קבוע שיהיו נטפלים לגביה הוו כשאר בע\"ב ומיירי בשאותו חצר היה חצר יחידי אבל כשנתארחו בעיר ויש שם עוד חצרות של ישראל והעיר עשויה בתיקון מבואות כדין בטילי הני אורחים לגבי שאר בע\"ב קבועים שבעיר דעיר שעשויה בתיקון מבואות כדין היא חשובה כולה כחצר אחת וכנ\"ל:","(ס) זה על זה - ואם הוא במקום עכו\"ם צריכים לשכור גם רשותו [מ\"א]:","(סא) מיד - היינו אפילו אם שבתו רק שבת אחת [אחרונים]:"]}],"371":[{"s":"<b>כשאחד מבני חצר נפרד משם או מת. ובו ו סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>א' מבני חצר <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>שהניח ביתו והלך ושבת בחצר אחר' אפי' היתה סמוכה לחצרו <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אם הסיח מלבו ואין דעתו לחזור לביתו בשב' הרי זה אינו אוסר עליהם <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>במה דברים אמורים בישראל אבל בעכו\"ם אפי' הלך לשבו' בעיר אחר' אוסר עליהם עד שישכרו ממנו מקומו <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>אם היא קרוב <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>מהלך יום א' שהרי אפשר שיבא בשב' אבל אם רחוק יותר אינו אוסר <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>וי\"א שגם עכו\"ם אם הלך לשבו' בחצר אחר' אינו אוסר <small>[וכן נראה עיקר] [ואם בא העכו\"ם בשבת ע\"ל סי' שפ\"ג]:</small>","m":["(א) אחד מבני חצר וכו' - והטעם דדירה בלא בעלים לא שמה דירה ואינה אוסרת בחצר אף שלא נתנה חלק בעירוב:","(ב) שהניח ביתו והלך וכו' - מיירי שהלך עם כל ב\"ב משם ומבעוד יום ויש מקילין אפילו כשהלך בשבת אם לא חזר בו ביום:","(ג) אוסר עליהם - אפילו עירבו ביניהם:","(ד) אם רחוק יותר וכו' - ואע\"ג דברחוק נמי איכא למיחש שהלך בחול עד סמוך לכאן ויבוא בשבת מ\"מ לא חיישינן להכי:","(ה) שגם עכו\"ם וכו' - עיין בט\"ז שכתב דאם העכו\"ם רגיל לחזור לביתו באותו יום אסור לכו\"ע וכאן מיירי דהלך לדעת לשבות שם כל היום:","(ו) בחצר אחרת - עיין בה\"ל שביארנו בשם כמה פוסקים דאין להקל כ\"א בעיר אחרת ולא בחצר אחרת:","(ז) אינו אוסר - כמו בישראל שהלך לשבות במקום אחר והסיח לבו מדירתו שחשבינן כאלו אינו דר שם באותו שבת:","(ח) אינו אוסר - דכיון דבעת שהלך לא היה דעתו לחזור בשבת א\"כ כבר הסיח דירתו מלב והו\"ל שבת שהותרה ושוב לא תאסר אבל גבי עכו\"ם קי\"ל דאם בא בשבת אוסר דלא שייך גבי עכו\"ם לומר שכבר הסיח דעתו שזה אינו אלא בישראל שבמקום ששובת בכניסת שבת שהוא לו יום מנוחה מסתמא דעתו אז שלא לעקור ומה שבא אח\"כ רוח אחרת היתה לו משא\"כ גבי עכו\"ם כשבא הוכיח סופו על תחלתו ואמרינן שכבר בבין השמשות היה דעתו לבוא ואף אם יאמר שהסיח דעתו מתחלה לא מפיו אנו חיין:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>ישראל בן חצר זו שהלך לשבו' <i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>בחצר אחר' ואין דעתו לחזור בשב' ואח\"כ נמלך בשב' וחזר <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>אינו אוסר:","m":[]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>א' מן <i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>השוק שהי' לו בית בחצר ומת והניח רשותו לא' מבני החצר אם מת מבעוד יום אין הזוכה אוסר <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>שהעירוב שמערב על ביתו מתיר גם מה שירש ואם מת <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>משחשיכה אוסר אע\"פ שעירב הזוכה עמהם אינו מועיל למה שירש אח\"כ בשב':","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>א' מן החצר שמת בשב' <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>אם עירב אפי' ירשו א' מבני השוק אינו אוסר ואם לא עירב אם ירשו א' מן השוק <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>כל זמן שאינו בא לדור עמהם אינו אוסר <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>בא לדור בשב' בבית מורישו אוסר ואם יורשו א' מבני החצר אם עירב היורש <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>והיה דר עם המוריש בבי' אינו אוסר אע\"פ שלא עירב המוריש ואם לא היה דר עם המוריש אלא בבי' אחר שבחצר אוסר <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>אע\"פ שעירב היורש כיון שלא עירב המוריש ואם מבעוד יום מת ויורשו אחד מן השוק הרי זה אוסר <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>והוא שבא היורש בבי' מורישו בשב':","m":["(ט) אחד מן השוק וכו' - מיירי בשלא עירב על הבית שיש לו בחצר וה\"ה אם היה דר בחצר ולא עירב אלא דנקט אחד מן השוק דסתמא דמלתא כן הוא דכשהוא דר בשוק אינו מערב על הבית שיש לו בחצר:","(י) אין הזוכה אוסר - בין שנכנס לדור בה או לא:","(יא) שהעירוב וכו' - אפילו אם עירב על ביתו קודם שמת מורישו שהעיקר קניית העירוב בין השמשות ואז כבר היה הבית שלו:","(יב) אוסר - אפילו אם לא בא היורש לדור באותו בית מ\"מ מקרי דירה בבעלים כיון שהוא דר באותה חצר:","(יג) אע\"פ שעירב וכו' - על ביתו שיש לו בחצר זו:","(יד) אינו מועיל וכו' - כיון דבעת ביה\"ש שהוא אז זמן קניית העירוב לא היה הבית שלו אין חל העירוב על בית זה:","(טו) אחד מן החצר וכו' - וה\"ה אם היה המוריש אחד מן השוק תלוי ג\"כ בעירב ולא עירב אלא סתמא דמלתא כשהוא דר בשוק אינו מערב על הבית שיש לו בחצר להכי נקט המחבר אחד מן החצר שמת וכו':","(טז) שמת בשבת - ר\"ל ולא הניח ב\"ב בבית וא\"כ כיון שמת בטל העירוב וירשו אחד מן השוק ובא לדור שם בשבת והוא הלא לא הניח עירוב מבע\"י אפ\"ה אינו אוסר על בני החצר דכיון שהותר ביהש\"מ בעירוב המוריש הותר לכל השבת:","(יז) ואם לא עירב - ג\"ז מיירי שאין לו ב\"ב שם:","(יח) אינו אוסר - אף דנאסר בתחלת השבת מחמת המוריש שלא עירב עם בני החצר מ\"מ כשמת ונשאר הבית בלא דיורין לא חשיבא לאסור:","(יט) אוסר - כיון דיש עתה בעלים לדירה אוסר על בני החצר עד שיבטל רשותו וכדלקמן בסי' ש\"פ:","(כ) אע\"פ שלא עירב המוריש - שבני ביתו של אדם מערבין לו שלא מדעתו:","(כא) ואם וכו' עם המוריש - אף דגם עתה לא בא לדור בבית שירש מ\"מ כיון דיש לו בית באותו חצר שדר בו וראוי לו להשתמש גם באותו בית שירש חשבינן כאלו נכנס לדור בו והוי דירה בבעלים:","(כב) אע\"פ שעירב היורש - לאותו בית שדר בו:","(כג) ואם מבע\"י מת - כאן לא חילק בין עירב ללא עירב דאפילו עירב כיון שמת מבע\"י בטל עירובו והוי כלא עירב:","(כד) וירשו אחד מן השוק - דאלו אם ירשו אחד מבני החצר חל העירוב שמניח בשביל ביתו שדר בו גם על בית זה:","(כה) והוא שבא וכו' - לדור בה והו\"ל דירה בבעלים והוא הלא לא עירב:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"5\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>ישראל <i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>וגר שהיו דרים בחצר ומת הגר מבעוד יום והחזיק ישראל אחר בנכסיו אפי' לא החזיק עד <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>שחשיכה אוסר עד שיבטל רשותו כשאר יורש מת משחשיכה אין המחזיק אוסר שבהיתר הראשון עומד:","m":["(כו) ישראל וגר שהיו דרים וכו' - מיירי כשעירבו ביחד ולכך אינו אוסר אלא כשמת הגר מבע\"י שבטל העירוב שלו:","(כז) והחזיק ישראל אחר בנכסיו - דאלו החזיק אותו ישראל הדר שם בכל גווני מותר דהרי הוא נשאר יחיד בחצרו וה\"ה כשלא החזיק אדם כלל בחצר זה בשבת זו דמותר דהרי אין לה בעלים:","(כח) אפילו לא החזיק וכו' - ר\"ל אע\"פ שבכניסת השבת כ\"ז שלא נכנס ישראל זה בביתו של גר היתה דירה בלא בעלים ולא היתה אוסרת אפ\"ה אין אומרים בה שבת כיון שהותרה הותרה הואיל והיתה ראויה להחזיק בה מבעוד יום והיה ההיתר תלוי ועומד שלא היה ברור שתהא מותרת כל השבת:","(כט) עד שחשיכה - ר\"ל ונכנס ג\"כ לדור בה:","(ל) כשאר יורש - ר\"ל דחשבינן הזוכה בנכסי הגר כיורש בנכסי אביו דמהני כשמבטל רשות כדאיתא בסימן שפ\"א ס\"ו עי\"ש:","(לא) משחשיכה אין המחזיק אוסר וכו' - ר\"ל כיון שבכניסת השבת היה מותר מחמת עירובו של גר אף דכשמת בטל עירובו אמרינן כיון שהותרה הותרה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>א' מבני חצר שהיה גוסס אף על פי שאינו יכול לחיות בו ביום אוסר עד שיזכו לו בפת <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>ויערבו עליו וכן קטן אוסר אע\"פ שאינו יכול לאכול כזית אבל האורח אינו אוסר כמו שנתבאר בסי' ש\"ע:","m":["(לב) אע\"פ שאינו יכול וכו' - וסד\"א דנחשב כאלו מת והו\"ל דירה בלא בעלים קמ\"ל דכל זמן שהוא חי הרי הוא כחי לכל דבריו:","(לג) ויערבו עליו - כתב מ\"א דאם מת בשבת אוסר כיון שאין העירוב ראוי להתקיים כל השבת דרוב גוססין למיתה עכ\"ל והנה אם היה דר עמו אחד באותו בית פשיטא דאינו מתבטל העירוב ואם ירשו אחד מן השוק ואינו בא לדור שם בשבת ונשאר הבית בלא בעלים לאותו שבת ג\"כ פשיטא דמותר כדלעיל בריש סעיף ד' אך המ\"א מיירי שירשו אחד מן השוק ובא לדור שם בשבת או שירשו אחד מבני החצר שדר בבית אחר והטעם בכ\"ז דהעירוב שהונח בעד הגוסס הרי לא היה ראוי להתקיים כל השבת דהרי חזינן שמת בשבת ולא שייך בזה לומר הואיל והותר הותר. ולפ\"ז לכאורה אף אם אחד עירב באותו ע\"ש בעד כל החצר וממילא גם הגוסס בכלל ואח\"כ מת הגוסס באותה שבת ג\"כ חלק העירוב שנתנו בעד זה הגוסס מתבטל אכן אם העירוב הונח בשבת העבר וא\"כ חל העירוב פ\"א אף שבשבת זו כשנעשה גוסס היה עומד להתבטל אעפ\"כ שייך בזה לומר כיון שהותרה הותרה וכדלקמן בסימן שע\"ד ס\"א ע\"ש ועיין בבה\"ל מה שכתבנו בשם עצי האלמוגים:","(לד) וכן קטן אוסר - עד שיערבו עליו [רמב\"ם]:"]}],"372":[{"s":"<b>דיני שותפי הדירות לעירוב. ובו יט סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>גגין וחצירו' וקרפיפו' כולן רשות א' הם <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>לכלים ששבתו בתוכה שמותר לטלטלם מזה לזה אפי' הם של בעלים הרב' <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>ולא עירבו יחד מותר לטלטל מחצר לחצר אחר' או לגג או לראש כותל שביניהם ומגג לגג אחר הסמוך לו אפי' גבוה ממנו הרבה ומהגג לקרפף <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>שאינו יותר מסאתים או שהוקף לדירה אפי' הוא יותר מסאתים <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>או למבוי שמתוקן בלחי או קורה אפי' לא עירבו בו <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>ואע\"פ שעירבו בני חצר לעצמן דשכיחי מאני דבתים בחצר מותר לטלטל כלים ששבתו בחצר זו לחצר אחר' ולא חיישינן שמא יטלטל גם כלים ששבתו בבית לחצר אחרת או לגג וקרפף:","m":["(א) גגין - היינו על הגג שאין עוד קירוי למעלה [דאלו על התקרה שהוא תחת הגג בכלל עלית הבית הוא וכבית דמיא] וגגין שלהן חלקין היו וראויין להשתמש עליהן, ומיירי כשלא היו בולטות חוץ למחיצת הבית ואם היו בולטות עיין לעיל בסימן שמ\"ה סט\"ז:","(ב) וקרפיפות - עיין לעיל בסימן שמ\"ו ס\"ג:","(ג) רשות אחד הן - דכל אלו אין תשמישן מיוחד ותדיר לפיכך אין בהם חילוק רשות ומותר לטלטל מאחד לחבירו בלי עירובי חצרות וכ\"ש שמותר לטלטל בגגין או בחצרות גופא מאחד לחבירו וכן מותר לטלטל בכל החצר [או בכל הגג] אף שלא עירבו הדיורין יחד ולא הצריכו חכמים ע\"ח אלא משום שיהיה מותר להוציא לתוכה כלי הבית ששבתו בבית מבעוד יום וכן מחצר לבית:","(ד) ששבתו בתוכן - היינו שהיו מונחים שם מבעוד יום ולאפוקי כששבתו בתוך הבית:","(ה) ולא עירבו יחד - היינו החצרות בהדי הדדי או הגגין והחצרות דאלו בחצר גופא יותר רבותא הוא כשעירבו בהדדי כמו שמסיים לבסוף:","(ו) או לגג - של חבירו:","(ז) שביניהם - שבין שתי חצרות ומבואר היטב לקמן בס\"ו:","(ח) אפילו גבוה וכו' - ולא אמרינן שעי\"ז יתחלק לשתי רשויות:","(ט) ומהגג לקרפף - וה\"ה מחצר לקרפף:","(י) שאינו יותר מסאתים - דאלו אם היה יותר מסאתים בכלל כרמלית הוא כיון שלא הוקף לדירה ואסור להוציא מרה\"י אליו וכמבואר לעיל בסימן שנ\"ח:","(יא) או למבוי וכו' - ר\"ל שמותר להוציא לו מחצרות וגגין וקרפיפות כלים ששבתו בתוכן והטעם דגם מבוי אין תשמישו מיוחד ותדיר לפיכך הוא רשות אחד עמהן ולא הצריכו שיתופי מבואות אלא לכלים ששבתו בתוך הבית שיהיה מותר להוציא למבוי:","(יב) אפילו לא עירבו בו - ר\"ל שלא נשתתפו החצרות יחד:","(יג) ואע\"פ שעירבו וכו' - ר\"ל ולא מיבעי אם לא עירבו בני חצר לעצמן דאז אין מצוי בחצר כלי הבית כלל דהלא אסור להוציאן שם בודאי מותר לטלטל מחצר לחצר כלים ששבתו בתוכן דהא לא שייך למיגזר אטו כלי הבית:","(יד) לחצר אחרת - וה\"ה לגג וקרפף וכנ\"ל:","(טו) ולא חיישינן כו' - דהוי גזירה לגזירה:","(טז) שמא יטלטל גם כלים וכו' - מזה מבואר דכלים ששבתו בבית אף שבאו בהיתר לחצר זה מפני שעירבו בה אעפ\"כ אסור להוליכן לחצר אחרת שלא עירבו עמהן וה\"ה אם הוציא מבתי החצר להחצר שלא עירבו בה והוציאן שם דרך היתר כגון דרך מלבוש ופשטן שם ג\"כ אסור לחזור ולהוציא משם לחצר אחרת אכן אינו מבואר בהדיא מה דין כלים אלו בטלטול חצר זה עצמו אם מותר או לא ועיין בבה\"ל שביארנו שיש בזה מחלוקת הפוסקים ועכ\"פ אם הביא משקין ע\"י נכרי לבית אחר שלא עירב עמה כיון שבית רשות יחיד הוא מותר לישראל לטלטל המשקין אח\"כ בכל הבית לכו\"ע:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>קרפף יתר על סאתים שלא הוקף לדירה הוי כרמלית ואסור לטלטל ממנו לקרפף אחר להכניס ולהוציא מזה לזה כי אם שתי אמות בזה ושתי אמות בזה:","m":["(יז) ואסור לטלטל ממנו וכו' - וה\"ה דבתוכו אסור לטלטל רק בתוך ד\"א כמבואר לעיל בסי' שמ\"ו ס\"ג:","(יח) לקרפף אחר - ר\"ל קרפף שהוא כמוהו שמחזיק יותר מב\"ס ולא הוקף לדירה דאלו אם אינו מחזיק רק בית סאתים או שהוא מחזיק יותר מב\"ס והוקף לדירה רה\"י גמור הוא ואסור להכניס ולהוציא אליו כלל מקרפף זה שהוא כרמלית [אחרונים]:","(יט) כ\"א שתי אמות וכו' - דמכרמלית לכרמלית מותר וכדלעיל בסימן שמ\"ו ס\"ג. וכ\"ז בכלים ששבתו בתוכן דאלו כלים ששבתו בתוך הבית והובאו לקרפף ע\"י עכו\"ם וכה\"ג אסור להוציאן לקרפף אחר:","(כ) יוליכנו אחד וכו' - דכיון שכבר עירבו יחד הרי הם כאיש אחד:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>שתי <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>חצרות שרוצים לערב יחד להתיר אף כלים ששבתו בבתים אין צריכו' עירוב אחר אלא העירוב שעשו כבר יוליכנו א' מבני החצר בשביל כולם ויתננו בא' מבתי חצר שניה ואם ירצה יוליך שם אפי' פת משלו וכולם מותרים: <small>הגה והוא שעירבו בני חצירו עמו תחלה [תשובת הרא\"ש סי\"ו] או שאין צריכים לערב כמו שנתבאר סימן ש\"ע [ב\"י] </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>והוא שעירבו בני חצר השנייה לעצמה ואין בני חצר שניה צריכים פת אחר אלא העירוב שעשו כבר מתירן:","m":["(כא) וכולם מותרים - משום דשליחותייהו קעביד כיון שכבר עירבו ביחד:","(כב) תחלה - דאל\"כ הא בעת שהוליך פת שלו עדיין לא היה מעורב עמהם ואף שאח\"כ עירבו יחד לא חל העירוב למפרע מיהו נראה דאם אחר שעירבו בני חצירו חזר וסמך בהדיא על אותו פת שהוליך קודם לעירובן ודאי מהני דהא קניית העירוב הוא בין השמשות ודי בזה דלא גרע מבני חבורה שסמכו על הפת שעל השולחן [כמ\"ש סימן שס\"ו סי\"א] ואע\"פ שאין עושים כלום וה\"ה הכא נמי מהני אף בפת שלו דכיון שעירבו כבר הוי עתה שליח דכולהו כשחזר וסמך בהדיא על אותו פת בשביל כולם:","(כג) שאין צריכים לערב - דהתם נמי אמרינן דכולהו כחד חשיבי ואחד מוליך הפת משלו וכולם מותרים:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>אין שתי חצרות יכולות לערב יחד אא\"כ יהא פתח ביניהם <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>או חלון שיש בו <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>ד' על ד' טפחים <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>ויהי' קצתו בתוך י\"ט הנמוכים לארץ ואז אם רצו מערבין יחד ואם רצו מערבין כל א' לעצמו <small> (ועיין לקמן סי' שפ\"ו סעיף ב' ישראלים הדרים בב' וג' מקומות כיצד יערבו):</small>","m":["(כד) סי' ש\"ע - סעיף ד' וה' ע\"ש:","(כה) והוא שעירבו וכו' - ר\"ל שגם בני החצר השניה עירבו מקודם לעצמם דאל\"ה אינו מועיל מה שמוליכין העירוב אצלם דלא עדיפי מבני בחצר גופא שאסורים לטלטל בחצרן:","(כו) מתירן - דעל ידו נתערבו בני חצר זו יחד וע\"י הבאת הפת מחצר שאצלה נעשו מעורבין שתי החצרות יחד ומותרין גם הם לטלטל כלים ששבתו בבתיהם לחצר שאצלן וכתב בפרישה דצריכין להניח שתי העירובין ביחד:","(כז) אין שתי חצרות וכו' - וכ\"ז מיירי כשלא נשתתפו החצרות יחד במבוי אבל אם נשתתפו החצרות יחד במבוי נעשו הכל כחצר אחד ומותרים לטלטל מזה לזה אפילו לא היה רק חור קטן ביניהם:","(כח) יכולות לערב יחד - ר\"ל לענין שיהא מותר לטלטל אפילו כלי הבית מזה לזה וכנ\"ל:","(כט) פתח ביניהם או חלון - ואז מותר לטלטל אפי' דרך פתחים קטנים או חור שביניהם או ע\"י גב הכותל למעלה דשניהם כאחד חשיבי:","(ל) ד' טפחים על ד' טפחים - ואפילו הפתח והחלון ארוך הרבה צריך שיהיה גם ברחבו ד' דלא חשיב פתחא בפחות מד' דלא חזי להכניס ולהוציא בו כיון שהוא צר וכמאן דליתא דמיא. ואם החלון עגול אם יש בו כדי לרבע בו ארבעה טפחים על ארבעה טפחים הרי הוא כמרובע:","(לא) ויהיה קצתו וכו' - ואם החלון עגול אינו מספיק במה שיהיה קצה העיגול למטה בתוך עשרה אלא צריך לצמצם שמקום שמתחיל החלון להיות ד' טפחים יהיה קצתו בתוך עשרה טפחים לארץ:","(לב) בתוך י' טפחים - דאם כל החלון או הפתח למעלה מי\"ט אינו מועיל כלום כיון שיש תחתיו מחיצה גמורה החולקת בין החצרות וא\"א להם לערב יחד:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>חלון <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>שבין <i data-commentator=\"Magen Avraham\" data-order=\"6\"></i>שני בתים אפילו הוא למעלה מעשרה אם רצו מערבין יחד וה\"ה לארובה שבין בית <i data-commentator=\"Magen Avraham\" data-order=\"7\"></i>לעלייה שאפילו היא למעלה מי' אם רצו מערבין יחד ואפילו אין שם סולם לעלות בו: <small>הגה ומכל מקום בעינן שיהא רחבו ארבעה על ארבעה (ב\"י) ואם עשו <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i>סריגה לפני החלון בטל ליה מתורת חלון: (המגיד פ\"ג):</small>","m":["(לג) שבין שני בתים - ומיירי שלא שיעור בהחצר אשר הבתים פתוחים לו דאי עירבו כל הבתים אשר בחצר רשות אחד הוא ממילא ואפילו דרך חלון שאין בו שיעור פתח או דרך חורים נמי יכולים לטלטל:","(לד) למעלה מעשרה - לפי שהבית כיון שהוא מקורה הרי הוא כמלא והרי זה כאלו אין החלון גבוה י\"ט כיון שהבית כולו ממולא:","(לה) וה\"ה לארובה - דדינה כדין חלון:","(לו) ואפילו אין שם וכו' - ג\"כ יכולין להתאחד הבית והעליה ע\"י עירוב:","(לז) ומ\"מ בעינן וכו' - אחלון וארובה קאי:","(לח) ארבעה על ארבעה - ואם יש לו דרך על התחתון מלבד הארובה אז אף שאין בארובה דע\"ד מערב דרך הפתח ויכול לטלטל אף דרך חור:","(לט) סריגה לפני החלון - שקורין גראטע\"ס בל\"א והטעם שצריך שיהא החלל ד\"ט במקום אחד ואין הנקבים מצטרפין לזה וה\"ה לענין ארובה:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>בית שבין שתי חצרו' והוא פתוח לשניהם ועירב עם שתיהם אבל החצרו' לא עירבו זה עם זה אין לטלטל כלים ששבתו בבתים מחצר לחצר ע\"י בית זה שביניהם <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>היה בין שתי חצרו' כותל גבוה י\"ט <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>או שהיה קרקעה של א' מהחצרו' גבוה מחבירו ה' טפחים <i data-commentator=\"Magen Avraham\" data-order=\"8\"></i>ועשה עליו מחיצה חמשה להשלימו לעשרה אין יכולים לערב יחד <i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>ואם היה הכותל גבוה לשניהם עשרה והיו בראשו פירו' בני שתי החצרו' <i data-commentator=\"Magen Avraham\" data-order=\"9\"></i>יכולים להורידם לחצרו' וכן להעלו' עליו מפירו' ששבתו בחצירו' ולהורידם ממנו לחצר אחר' <i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"15\"></i>בין שהכותל רחב ד' או אינו רחב ד' אבל פירות ששבתו בבית אם הכותל רחב ד' אסור להעלות <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"16\"></i>לו ולא להוריד ממנו <i data-commentator=\"Magen Avraham\" data-order=\"10\"></i>ואם אינו רחב ד' מותר <small> (ובלבד שלא יחליפו כדלעיל סי' שמ\"ו ס\"א) </small> ואם היה הכותל גבוה לאחת מהחצרות עשרה ולשניה אינו גבוה עשרה <i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"17\"></i>כגון שקרקעו של א' גבוה משל חבירו מי שאינו גבוה לו עשרה <i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"18\"></i>מותר להשתמש בו <i data-commentator=\"Magen Avraham\" data-order=\"11\"></i>אף בכלים ששבתו בבי' <i data-commentator=\"Turei Zahav\" data-order=\"4\"></i>והשני <i data-commentator=\"Magen Avraham\" data-order=\"12\"></i>אסור להשתמש בו אף בכלים ששבתו בחצר <i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"19\"></i>והוא שיהא הכותל רחב ד' אבל <i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"20\"></i>אם אינו רחב ד' <i data-commentator=\"Magen Avraham\" data-order=\"13\"></i>מותר לשתיהן להשתמש בו אף מן הבתים אפילו עירבו כל אחת לעצמה:","m":["(מ) אין לטלטל - ר\"ל אע\"ג דכלים ששבתו בבית אמצעי מותר לטלטל לשתי החצרות וכן מהבתים שבשתי החצרות אליו מ\"מ מהבתים שבחצר זה לחצר זה ע\"י בית האמצעי אסור דהא החצרות לא עירבו בהדדי. ודוקא שהעירובין שעשו לא היה מונח בבית האמצעי כ\"א בשארי בתים שבחצרות אבל אם הניחו שתי העירובין בבית האמצעי נעשו עי\"ז משותפין הכל יחד ומותר לטלטל גם מחצר זה לחצר זה וכעין ההיא דלקמן בסימן שע\"ח ס\"א עי\"ש [מחה\"ש]:","(מא) היה בין שתי חצרות כותל וכו' - ובזה אין נ\"מ אם הכותל רחב ד' או לא דאפילו מחיצה דקה מפסקת בין החצרות כיון שגבוה עשרה:","(מב) גבוה י\"ט - דפחות מזה לא חשיב הפסק והוי כחצר אחד ומערבין אחד ואין מערבין שנים:","(מג) ועשה עליו וכו' - דקי\"ל דהמחיצה מצטרף להתל להשלימן לעשרה:","(מד) אין יכולים וכו' - וה\"ה כשגבוה מחבירו עשרה בלא מחיצה:","(מה) יכולים להורידם לחצרות - כדקי\"ל בראש הסימן דגגין וחצרות רשות אחת הן וראש זה הכותל לא עדיף מגג ודוקא לחצרות אבל לא לבתים אם הוא רחב ארבע:","(מו) ולהורידם ממנו וכו' - בין שערבו כ\"א בפני עצמו או לא ערבו כלל דכל החצרות רשות אחת הן וכנ\"ל בס\"א:","(מז) הכותל רחב ארבע - פירוש ארבע טפחים והטעם דכיון דהוא רחב ארבע הוא מקום חשוב בפני עצמו ואינו בטל לגבי שני החצרות ולפיכך אסור להעלות עליו מן הבתים וגם לא להוריד מן הכותל לבתים:","(מח) ואם אינו רחב וכו' - דבפחות מד' מקום פטור הוא ומותר להעלות מן הבתים עליו ולהוריד ממנו לבתים:","(מט) שלא יחליפו - היינו להעלות מן הבתים על הכותל ולחזור ולהורידם לחצר השני משום דלמא אתי לאפוקי להדיא מן הבתים לחצר השני בלא הנחה בינתים ועיין לעיל בסימן שמ\"ו סוף סעיף א' דהמחבר הביא שם שתי דעות בזה ומלשון הרמ\"א כאן משמע דחשש להחמיר:","(נ) מותר וכו' אף בכלים - ומיירי כשעירבה לעצמה דאם לא עירבה אסור מבית לחצר וכש\"כ למחיצה:","(נא) ששבתו בבית - דלדידיה נחשב ראש הכותל כקרקע החצר כיון שאינו גבוה י\"ט וניחא ליה להשתמש שם:","(נב) אף בכלים וכו' - דהואיל שחבירו מותר מבית למחיצה דהוי ליה כחצרו אם ישמש גם השני על המחיצה ויהיה רשות שניהם שולטת במחיצה זו ממילא יאסר הראשון להוציא מבית למחיצה כיון שעירבו כל אחד ואחד לעצמו וע\"כ אי אפשר שיהיו שניהם יכולים להשתמש עליו ונותנין הרשות להשתמש לזה שהתשמיש ניחא לו ביותר ולהראשון מפני שהכותל נמוך אצלו ניחא ליה ביותר ובספר אבן העוזר בשם הרשב\"א מקיל לשני להשתמש בו בכלים ששבתו בחצר:","(נג) מותר לשתיהן להשתמש - דהוי מקום פטור:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"21\"></i>נפרץ הכותל עד עשר אמות הרי הוא כפתח <i data-commentator=\"Be'er HaGolah\" data-label=\"ת\" data-order=\"22\"></i>והוא <i data-commentator=\"Turei Zahav\" data-order=\"5\"></i>שלא יהא נפרץ <i data-commentator=\"Magen Avraham\" data-order=\"14\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"2\"></i>במילואו <i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"23\"></i>ואם נפרץ ביותר מעשר חשוב כחצר אחת וצריכים לערב יחד <small> (וכל שכן אם אין ביניהם מחיצה גבוה י' דצריכין לערב יחד) (הר\"ר יהונתן פרק חלון):</small>","m":["(נד) עד עשר וכו' - ועד בכלל:","(נה) הרי הוא כפתח - וע\"כ אם רצו מערבין שנים ואם רצו מערבין יחד וכנ\"ל בסעיף ד':","(נו) שלא יהא נפרץ - דאם נפרץ במלואה אפילו פחות מעשר אמות צריכות לערב יחד דוקא:","(נז) במילואו - וע\"כ בעינן שישתייר מכל צד משהו או מצד אחד פס ד\"ט רוחב בגובה עשרה דבלא\"ה הרי הוא כמו שנפרץ במלואו [מ\"א] ועיין לעיל בסימן שס\"ג סעיף ב' במ\"ב מה שכתבנו בזה:","(נח) ביותר מעשר וכו' - פי' ואז אפילו נשאר מן הכותל מכאן ומכאן כפלי כפלים ממה שנפל הכל חשוב כנפול ואין זה פתח אלא פרצה:","(נט) יחד - דאם עירבו כ\"א לעצמו אוסרים זה על זה. אכן אם עשו צורת הפתח במקום הפרצה חשוב כפתח ואם רצו מערבין שנים:","(ס) אם אין ביניהם וכו' - וה\"ה אם כל המחיצה גבוה י\"ט אלא שיש בתוכה מקום רחב יותר מעשר אמות שאין בגובהן י\"ט הרי הוא חשוב כפרצה גמורה וצריכות לערב יחד דוקא:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"24\"></i>כותל שבין ב' חצרו' גבוה עשרה לשניהם והעמיד אצל הכותל סולם רחב ד' וכן כנגדו בחצר השני' אפי' אין הסולמו' זה כנגד זה אם אין ביניהם שלשה חשיבי כפתח היו מופלגים זה מכנגד זה שלשה אם <i data-commentator=\"Magen Avraham\" data-order=\"15\"></i>הכותל רחב ד' עדיין חשובים כפתח ואם אינו רחב ד' לא חשיבי כפתח באיזה סולם אמרו כשיש בו ארבע שליבו' אבל פחו' מכאן לא אא\"כ זרועותיו ושליבותיו כבדות שאז כובדו קובעו <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"25\"></i>ואם אין הכותל גבוה אלא עשרה וזוקף סולם גבוה שבעה ומשהו במשך ד' אצל הכותל מתירו בין להשתמש עליו <i data-commentator=\"Turei Zahav\" data-order=\"6\"></i>בין לערב יחד כיון שלא נשאר שלשה עד ראש הכותל <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"26\"></i>עקר חוליא מראש הכותל למעטו מגובה עשרה אם יש בה <i data-commentator=\"Magen Avraham\" data-order=\"16\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"3\"></i>משך ארבע מהני בין לעשותו כפתח לערב יחד בין לענין שיכול להשתמש בכל הכותל ואם אין בו ארבע אינו חשוב כפתח לערב יחד וכן אינו מועיל להשתמש בכל הכותל שאינו משתמש אלא כנגד <i data-commentator=\"Ba'er Hetev\" data-order=\"4\"></i>המקום שנתמעט:","m":["(סא) לשניהם - ר\"ל משני הצדדין:","(סב) אם אין ביניהם ג' - דחשיבי זה כנגד זה:","(סג) חשיבי כפתח - ואם רצו מערבין יחד שהרי יכולין לעלות ולירד מחצר זה לחצר זה דרך הסולמות ומיירי שהסולמות מגיעין לראש הכותל או עכ\"פ בפחות משלשה טפחים סמוך לראשן וכדלקמיה:","(סד) שלשה - טפחים וה\"ה אפילו אם היה מופלג טובא [גמרא]:","(סה) עדיין חשובים כפתח - דכיון שהוא רחב ד' טפחים בעוביו נוח להשתמש עליו ויכול להוליך מסולם לסולם דרך הכותל:","(סו) ד' שליבות - דסולם כזה מסתמא הוא כבד ואינו נוטלן משם בשבת מחמת כבדו וע\"כ הוא חשוב כפתח:","(סז) פחות מכאן לא - דכיון שנוח ליטלו משם בשבת הוי כמי שאינו ופשוט דאם הוא קבוע במסמרים לכותל אפי' אין בו ארבע שליבות חשוב כפתח:","(סח) כבדות - יותר מכפי הרגיל ואינו נוח ליטלו משם:","(סט) ואם אין וכו' - בא להוסיף כאן דאף בסולם זקוף שקשה לעלות עליו אל ראש הכותל סגי:","(ע) אלא עשרה - דאם הוא גבוה יותר מעשרה טפחים לא סגי בשבעה ומשהו אלא בכדי שיהיה הסולם מגיע בתוך ג\"ט סמוך לראש הכותל:","(עא) שבעה ומשהו - ולא נשאר עד ראש הכותל רק פחות משלשה ואמרינן לבוד:","(עב) במשך ד' - אסולם קאי שיחזיק משך רחבו ד\"ט וכנ\"ל בריש הסעיף ומשום דזהו שיעור פתח והעמודים של הסולם שתקועין השליבות בהן ג\"כ מצטרפין לשיעור זה ועובי השליבות אין בהן שיעור:","(עג) אצל הכותל - אדלעיל קאי ור\"ל שזוקף אצל הכותל בשוה ושיחזיק במשך אורך הכותל רחב ד\"ט וכתב במאמר מרדכי דשיעור זה של שבעה ומשהו הוא דוקא שכעומד בזקיפה אבל אם מעמידו באלכסון צריך שיחזיק יותר לפי ערך האלכסון והעיקר שיהיה ראש הסולם בתוך ג\"ט סמוך לראש הכותל:","(עד) להשתמש עליו - מכלי הבית כשלא עשה אלא סולם מצד אחד ולערב יחד כשהעמידו סולם משני הצדדין:","(עה) משך ארבע - ר\"ל המקום שנתמעט מגובה י\"ט יש בו ארבעה טפחים במשך הכותל:","(עו) שיכול להשתמש בכל הכותל - לכאורה אם לא עירבו יחד אלא כ\"א בפ\"ע הלא אוסרין זה ע\"ז להשתמש על ראש הכותל מכלי הבית וי\"ל לצדדין קתני דמה שכתב לערב יחד מיירי שנתמעט כן כל עובי הכותל ונעשה כפתח לשניהם ומה שכתב שיכול להשתמש בכל הכותל מיירי שלא נתמעט בכל עביו אלא בצד אחד במשך ד\"ט ונעשה לזה תשמישו בנחת למי שנתמעט מצדו שנוח לו לעלות במקום המיעוט וממנו יעלה על ראש כל הכותל ולהשני תשמישו בקשה ועיין בבית מאיר שכתב דאינו מותר אף למי שתשמישו בנחת אא\"כ יש במקום שנפחת מעוביו ד\"ט על ד\"ט ע\"ש טעמו:","(עז) בכל הכותל - בכלי הבית ומיירי שהכותל היה רחב ד\"ט דבפחות מזה מותר בכל גווני להשתמש בכל הכותל וכדלעיל בסוף ס\"ו:","(עח) אלא כנגד וכו' - ששם הוא תשמישו בנחת שעומד בקרקע ומשתמש אבל אינו נוח לעלות דרך עליו לראש הכותל הואיל ואין בו ד' במשכו:","(עט) בנה איצטבא וכו' - אבל אם לא נתחבר להקרקע מע\"ש לא מהני דהוי דבר הניטל בשבת ואינו ממעטו:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"27\"></i>בנה אצטבא למטה אצל הכותל למעטו מגובה עשר' אם יש בה ד' אורך במשך הכותל <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"28\"></i>ובולטת ד' מועיל להשתמש בכל הכותל אבל אינו חשוב כפתח לערב יחד עד שיגיע לראש הכותל ואם אין בה ד' על ד' אינו מועיל אפילו להשתמש כנגדו:","m":["(פ) ובולטת ד' - דהיינו שהיא ד\"ט על ד\"ט ולענין גובה משמע דאפילו כל שהוא סגי כמו בסמוך סעיף יו\"ד כל שנתמעט עי\"ז הכותל מעשרה טפחים ממנה ולמעלה:","(פא) מועיל להשתמש בכל הכותל - להעלות עליה מכלי הבית שהרי נוח לעלות דרך עליה על ראש הכותל הואיל ואין ממנה לראשו גבוה עשרה וכ\"ז כשלא עשה איצטבא רק אחד בצדו אבל אם גם השני עשה כן מצד השני נעשה הכותל לשניהם תשמישו בנחת ושוב חוזרין ואוסרין זע\"ז להשתמש בכותל:","(פב) אבל וכו' לערב יחד - היינו אפילו עשה כן גם מצד השני:","(פג) לראש הכותל - וה\"ה אם היה נמוך מזה פחות מג\"ט ג\"כ דינא הכי וכנ\"ל בס\"ח לענין סולם:","(פד) כנגדו - וכ\"ש דבכל הכותל אסור והטעם לפי שאין נוח לעמוד עליה ולהשתמש וכמאן דליתא דמיא ואינו דומה להנ\"ל בס\"ח דמותר עכ\"פ כנגד אותו המקום שנתמעט דהתם עומד ע\"ג קרקע ומשמש משא\"כ הכא שצר לעמוד על מקום קצר כזה:","(פה) כפה ספסל וכו' - סמוך לכותל או בתוך ג\"ט וכן למעלה לענין איצטבא:","(פו) ד' על ד' וכו' - הכל דינו כמו למעלה לענין איצטבא וע\"כ הסכימו האחרונים דמה שכתב כנגד המיעוט ט\"ס הוא וצ\"ל אפילו שלא כנגד המיעוט:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"29\"></i>כפה ספל שיש בו ד' על ד' וגבוה כל שהוא ומיעט בו גבהו מעשרה <i data-commentator=\"Turei Zahav\" data-order=\"7\"></i>מותר להשתמש <i data-commentator=\"Magen Avraham\" data-order=\"17\"></i>כנגד המיעוט ובלבד <i data-commentator=\"Magen Avraham\" data-order=\"18\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"5\"></i>שיחברנו בטיט:","m":["(פז) שיחברנו בטיט - חבור יפה לארץ שא\"א לשמטו עד שיחפור בדקר שאז א\"א ליטלו משם בשבת [ואע\"פ שעתיד ליטלו אחר השבת מותר] אבל אם הטיט מונח כך על אוגניו הכפויים לארץ מותר ליטלו להספל בשבת ואע\"פ שניזוז ממילא הטיט דהוי טלטול מן הצד ולא שמיה טלטול וכל דבר הניטל בשבת אינו ממעט:","(פח) בנה וכו' - סמוך לכותל זו למעלה מזו ויש אויר ביניהם:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"30\"></i>בנה אצטבא על אצטבא אם יש בתחתונה ד' על ד' או אין בה ד' על ד' ויש בעליונה ד' על ד' ואין בין זו לזו ג\"ט <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"31\"></i>מהני להתיר להשתמש עליו אבל לא מהני למהוי פתח לערב יחד:","m":["(פט) בתחתונה ד' על ד' - דאז היא עצמה מתרת להשתמש על הכותל ואע\"פ שאין למעלה ממנה כלום וכדלעיל בס\"ט ודע דבעינן שיהא התחתונה עכ\"פ בתוך ג\"ט סמוך לארץ דאל\"ה הוי בכלל מיעוט באויר ולא שמיה מיעוט:","(צ) ואין בין זו לזו ג\"ט - דר\"ל דאז מצרפינן לה גם האיצטבא התחתונה דהוי כלבוד וכאיצטבא אחת דמיא המתחלת מן הארץ הצרה קצרה מלמטה ורחבה מלמעלה אבל אם היו רחוקין זה מזה ג\"ט אין העליונה לבד מתרת אף שרחבה ד' על ד' דהא עומדת באויר והתחתונה הסמוכה לארץ אין יכולה להתיר דהא לית בה ד' על ד':","(צא) להשתמש עליו - על הכותל שהרי אין הכותל למעלה מהאיצטבאות גבוה עשרה טפחים. ומיירי שעשה האיצטבאות רק מצד אחד וכמו שכתבנו לעיל בסקפ\"א:","(צב) לערב יחד - ר\"ל אפילו אם ירצה לעשות איצטבאות מצד השני ג\"כ:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"32\"></i>זיז היוצא מן הכותל ויש בו ד' על ד' והניח עליו סולם כל שהוא מועיל <i data-commentator=\"Magen Avraham\" data-order=\"19\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"6\"></i>להתיר לו תשמיש הכותל והוא שלא תהא שליבה התחתונ' גבוה מן הארץ שלשה ולא יהא בין שליבה לשליבה שלשה והוא שיניח הסולם <i data-commentator=\"Magen Avraham\" data-order=\"20\"></i>על גב הזיז <i data-commentator=\"Turei Zahav\" data-order=\"8\"></i><i data-commentator=\"Magen Avraham\" data-order=\"21\"></i>אבל <i data-commentator=\"Ba'er Hetev\" data-order=\"7\"></i>סומכו אצלו לא <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"33\"></i>וכל זמן שאין גבוה הכותל עשרים טפחים די בזיז אחד שמניחו באמצע שהרי אין גבוה עשרה עד הזיז ולא גבוה עשרה ממנו עד ראש הכותל ואם הוא גבוה עשרים צריך שני זיזין א' בתוך עשרה התחתונים וא' למעל' ממנו בתוך י' העליונים שאם היה הזיז גבוה עשרה לא סגי לי' בסולם כל שהוא והוא שלא יהו הזיזין זה כנגד זה שראוי להטיל סולם מזה לזה:","m":["(צג) היוצא מן הכותל - בתוך עשרה טפחים סמוך לארץ:","(צד) והניח עליו וכו' - ר\"ל שראשו העליון של הסולם סמוך על הזיז:","(צה) סולם כל שהוא - ר\"ל שהוא סולם צר שאין מחזיק ד\"ט בעובי השליבות ולא רחב ד\"ט במשך הכותל מ\"מ מהני כיון שראוי לעלות עליו להזיז הוי האי סולם דרגא לזיז ומצטרף עם הזיז דהוי כדבר אחד:","(צו) להתיר לו תשמיש הכותל - אבל לעשותו פתח לערב יחד אינו מועיל אא\"כ הזיז הוא בפחות מג\"ט לראש הכותל והשני עשה ג\"כ כזה מעבר השני:","(צז) שלא תהא וכו' - דאם רחוקה ג\"ט מן הארץ הוי מיעוט באויר:","(צח) ולא יהא וכו' - שאז נעשה הזיז עם כל השליבות הכל אחד וכאלו איצטבא אחת שיש בה ד' על ד' מלמעלה שמועלת אע\"פ שקצרה מלמטה וכנ\"ל בסי\"א:","(צט) על גב הזיז אבל וכו' - ר\"ל שיסמוך ראש העליון של הסולם בזיז ולא שיסמוך הסולם לכותל אצל הזיז בצדו אפילו אם הוא תוך שלש להזיז דא\"כ לא הוי הך סולם דרגא לזיז:","(ק) בתוך עשרה העליונים - ושיהיו בפחות מי\"ט לתחתון וגם צריך לזה שני סולמות אחד מן הארץ עד זיז התחתון ואחד מן התחתון עד העליון:","(קא) שאם היה הזיז וכו' - ר\"ל שאם יגביה זיז התחתון גבוה עשרה מן הארץ [וכן אם הזיז העליון ירחיקנו עשרה טפחים מהזיז התחתון] לא סגי ליה בסולם כל שהוא אלא שיהיה במשכו ד' טפחים:","(קב) והוא וכו' זה כנגד זה - אלא יהיו משוכים זה מזה כדי שיהיה ראוי להעמיד סולם על זיז התחתון ולסמכו בשפוע על זיז העליון:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"34\"></i>העמיד שני סולמות זה בצד זה ולא היה בשניהם משך ארבע' והרחיקם זה מזה כדי שיהא בשניהם ארבע' ומילא האויר שביניהם בקש אינו מועיל לא להתירו להשתמש עליו ולא לערב יחד שמקום מעמד הרגלים הוא באמצע הסולם ואין ראוי לעלות בקש ואם העמיד הסולם באמצע והקש מן הצד מהני בין להתירו להשתמש עליו <i data-commentator=\"Magen Avraham\" data-order=\"22\"></i>בין <i data-commentator=\"Ba'er Hetev\" data-order=\"8\"></i>לערב יחד:","m":["(קג) ומילא האויר שביניהם בקש - שעשאן כעין שליבות:","(קד) והקש מן הצד - ובזה נשלם השיעור משך רוחב ד\"ט להסולם:","(קה) מהני וכו' - לפי שכף הרגל עולה בסולם והקש שמן הצד ראוי להחזיק בו בידיו ולעלות:","(קו) בין לערב יחד - אם מגיע לפחות מג\"ט לראש הכותל ועשה כן גם בחצר השנית וכן בכל הסימן היכא שנזכר לערב יחד מיירי שעשה כן גם בחצר השנית:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"35\"></i>אין הסולם רחב ארבע' וחקק אצלו בכותל להשלימו לארבע' די לו שיחוק <i data-commentator=\"Magen Avraham\" data-order=\"23\"></i>בגובה עשרה ואם לא העמיד סולם כלל אלא חקק בכותל כמין שליבו' של סולם לעלות בו צריך שיחוק בכל גובה הכותל ומועיל בין להתיר תשמיש בין לערב יחד:","m":["(קז) וחקק אצלו בכותל - כגון שזקף הסולם ביושר וחקק מכאן ומכאן בכותל שהיה עב ועשה כמין שליבות להשלים השיעור של רוחב ארבעה טפחים:","(קח) די לו וכו' - פי' אבל הסולם בעצמו צריך שיעלה עד ראש הכותל עכ\"פ פחות מג\"ט וכנ\"ל בס\"ח:","(קט) שיחוק בגובה עשרה - שזהו שיעור גובה פתח ואע\"פ שהכותל גבוה הרבה ושם אין הסולם רחב ד\"ט אין בכך כלום שהרי יכול לעלות לראש הכותל בסולם אע\"פ שאין ברחבו ד':","(קי) צריך שיחוק - ברוחב ד' בכל גובה הכותל דבזה אין נוח כ\"כ לעלות כמו בשליבי סולם:","(קיא) בכל גובה הכותל - ואמנם אם נשאר מן הגובה רק פחות מג\"ט שלא חקקו מסתברא ג\"כ דמהני [פמ\"ג]:","(קיב) ומועיל וכו' - זה קאי גם ארישא:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"36\"></i><i data-commentator=\"Magen Avraham\" data-order=\"24\"></i>היה אילן בצד הכותל ועשהו סולם לכותל אם רצו מערבין א' אבל אם עשה אשרה סולם לכותל אין מערבין א' מפני שאסור לעלות עליה מן התורה שהרי אסורה בהנאה <i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"37\"></i>והרא\"ש ז\"ל כתב בהיפך <i data-commentator=\"Magen Avraham\" data-order=\"25\"></i>דאילן אינו מועיל ואשרה מועלת והוא שתהא <i data-commentator=\"Magen Avraham\" data-order=\"26\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"9\"></i>יבשה:","m":["(קיג) אם רצו מערבין אחד - שאין איסור לעלות על סתם אילן בשבת אלא מדברי סופרים ובבין השמשות שהוא שעת קניית העירוב לא גזרו על שבות של דבריהם:","(קיד) דאילן אינו מועיל - דכיון שאסור לעלות בו בשבת והאיסור בא מכח שבת ואיך יתיר דבר לשבת דהו\"ל כשני סותרין:","(קטו) ואשירה מועלת - הואיל ולית בה משום איסור שבת אע\"ג שיש בה איסור אחר שהוא איסור ע\"ג לא חיישינן לזה דמ\"מ פתחא הוא ואריה דרביע עלה:","(קטז) יבשה - שאין בו פירות ועלין וענפים דאז לא חיישינן שמא יתלוש ומותר לעלות עליו בשבת מדינא אי לאו משום איסור אשרה ועיין לעיל סימן של\"ו דיש ליזהר שלא לעלות אפילו באילן יבש התם רק משום סייג וגדר שלא יבואו להקל בשאר אילנות ועיין בא\"ר שמצדד להלכה כסברא הראשונה שהיא דעת הרבה פוסקים:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"38\"></i><i data-commentator=\"Turei Zahav\" data-order=\"9\"></i>חריץ שבין שתי חצירו' עמוק עשרה ורחב ארבעה אין יכולין לערב יחד אפילו מלא תבן וקש <i data-commentator=\"Be'er HaGolah\" data-label=\"פ\" data-order=\"39\"></i>כל זמן שלא בטלו ואם היה מלא עפר וצרורו' <i data-commentator=\"Be'er HaGolah\" data-label=\"צ\" data-order=\"40\"></i>אפילו <i data-commentator=\"Magen Avraham\" data-order=\"27\"></i>סתמא שלא בטלו צריכים לערב יחד <small> (וע\"ל סי' שנ\"ח סעיף ב'): הגה י\"א דאם מלאם בפרות <i data-commentator=\"Ba'er Hetev\" data-order=\"10\"></i>סתמא בטלו לה דדרכן לעשותו שם <i data-commentator=\"Magen Avraham\" data-order=\"28\"></i>אוצר (הגהות אשירי):</small>","m":["(קיז) חריץ שבין שתי חצרות - פי' שלא היה ביניהן שום מחיצה המפסקת רק חריץ בעלמא:","(קיח) עמוק עשרה וכו' - שכשם שמחיצה שגבוה עשרה מפסקת בין הרשויות כן חריץ שהוא עמוק שיעור זה ג\"כ מחלק הרשויות. ומיירי שהחריץ הולך בכל אורך החצרות מקצה אל קצה דאם נחסר ד' טפחים נחשב אותו מקום כפתח וכדלקמיה בסי\"ז:","(קיט) ורחב ארבעה - טפחים דפחות מכאן נוח לפסען משפתו אל שפתו ולא חשוב הפסק וגם זה מיירי שהיה כל שטח החריץ רוחב ד\"ט וכדמוכח לקמיה בסי\"ז:","(קכ) תבן וקש - שראוי למאכל בהמה דאם היה תבן וקש סרוח שאין ראוי למאכל בהמה דינו כעפר ואפילו סתמא נמי מבוטל:","(קכא) כ\"ז שלא ביטלו - בפירוש ואמר לא שקילנא מהכא וי\"א שאפילו לא אמר בפיו רק שהסכים בלבו לזה ג\"כ ממילא מתבטל:","(קכב) מלא עפר וכו' - היינו כל אורך החריץ או עכ\"פ ביותר מעשר אמות [דאל\"ה הוי כפתח ואם רצו מערבין שנים] ודע דמה שכתב מלא עפר הוא לאו דוקא דאם מיעט עומקו מעשרה ג\"כ דינא הכי:","(קכג) אפילו סתמא - דעפר וצרורות בחריץ מסתמא מבוטלין הן:","(קכד) וע\"ל סי' שנ\"ח ס\"ב - בהג\"ה דשם הביא שתי דיעות אם ביטלו לשבת אחת ודעתו לפנותו אח\"כ אם חשיב בטול די\"א דכיון דדעתו שלא ישאר שם לעולם לא חשיב בטול וגרע מסתמא ואין יכולין לערב יחד ולדינא נראה דכיון שהוא ד\"ס יש לסמוך להקל אם רצו מערבין יחד ואם רצו מערבין שנים:","(קכה) לעשותן שם אוצר - לאיזה זמן ולא להסתפק ממנו ועיין במ\"א שמפקפק על דין זה וכן בביאור הגר\"א הסכים לדבריו דדוקא בפירות טבלים שהוא דבר שאין ניטל בשבת ולכן סתמא מבוטל הא שאר פירות שמותר להסתפק מהם סתמא אינו מבוטל:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ק\" data-order=\"41\"></i>נתן עליו נסר כמין גשר <i data-commentator=\"Magen Avraham\" data-order=\"29\"></i>משפת החריץ אל שפתו אם הוא רחב ארבע חשוב כפתח ומערבין א' ואם רצו מערבין שנים: <small>הגה וה\"ה אם מלאו ברוחב ארבעה מדבר המבטלו שם: (ב\"י) </small> <i data-commentator=\"Ba'er Hetev\" data-order=\"11\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ר\" data-order=\"42\"></i>ואם נתן הנסר לאורך החריץ <i data-commentator=\"Be'er HaGolah\" data-label=\"ש\" data-order=\"43\"></i>במשך ארבעה אפי' אין בו אלא כל שהוא חשוב כפתח שהרי מיעטו מארבעה:","m":["(קכו) אם הוא רחב ארבעה - אבל אם הוא פחות מד\"ט כמאן דליתא דמיא ומערבין שנים דוקא:","(קכז) חשוב כפתח - דאף שהחריץ ארוך הרבה מאד מ\"מ הרי יכול לעבור דרך אותו הנסר מחצרו לחבירו כמו דרך פתח והוא מחברן לאחד כשירצו:","(קכח) ואם רצו מערבין שנים - ודע דלא חשבינן אותו כפתח אלא מד\"ט רוחב עד עשר אמות אבל ביותר מזה חשוב כפרצה וע\"כ אם סתם החריץ בנסרים עד יותר מעשרה אמות בארכו או שנתן נסר אחד לאורך החריץ ביותר מעשר אמות ומיעט שם החריץ מרוחב ארבעה טפחים חשוב כפרצה ביותר מעשר אמות ומערבין אחד ולא שנים:","(קכט) במשך ארבעה - ר\"ל אפילו אין הנסר מחזיק לארכו רק ארבעה טפחים די [דבעלמא שיעור פתח הוא בד\"ט] ויעמידנו ע\"ג יתדות:","(קל) כל שהוא - שהיה הנסר קצר מאוד ברחבו:","(קלא) חשוב כפתח - ואם רצו מערבין יחד:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ת\" data-order=\"44\"></i>אם החריץ עמוק לא' עשרה ולשני אינו עמוק עשרה או שהוא שוה לשניהם דינו ככותל:","m":["(קלב) דינו ככותל - המבואר כל פרטיו בס\"ו שמערבין שנים ואין מערבין אחד וכן לענין אם היה מונח פירות בחריץ שהוא עמוק עשרה ורחב ד' טפחים שאין יכולין להוציא משם לבית ולא מבית לתוכו אך אם לאחד עמוק עשרה ולשני אינו עמוק עשרה כגון שקרקעו של אחד היה נמוך מחבירו נותנין לזה להשתמש בו שלו ניחא תשמישתיה ביותר והכל כנ\"ל עי\"ש:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"45\"></i>גדיש של תבן שבין שתי חצרו' אם הוא גבוה עשרה כל א' מערב לעצמו נתמעט <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"46\"></i>בחול מי' צריכים לערב ביחד ובעוד שלא נתמעט <i data-commentator=\"Turei Zahav\" data-order=\"10\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"47\"></i>אסור לשום א' מהן ליתן מן התבן לתוך קופתו בשבת להאכילה לבהמתו <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"48\"></i>ואפי' להעמיד' שם שתאכל אסורה <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"49\"></i>אבל אם יוכל לעמוד בפניה כדי שלא יהא לה דרך לנטו' אלא לשם <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"50\"></i>ולהרא\"ש <i data-commentator=\"Magen Avraham\" data-order=\"30\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"12\"></i>אפי' בחול אסור ליתן ממנו לקופתו וכן להעמיד הבהמ' בידים במה דברים אמורים בגדיש שבין ב' חצרו' <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"51\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"13\"></i>אבל גדיש שבין <i data-commentator=\"Magen Avraham\" data-order=\"31\"></i>שני בתים מותר להאכיל בהמתו ממנו בידים:","m":["(קלג) שבין שתי חצרות - והיו לכל אחד דיורין בפ\"ע והיו פרוצין זה לזה ביותר מעשר אמות והתבן הזה סותם מקום הפרצה:","(קלד) כל אחד וכו' - דגם זה נחשב למחיצה אף שלא כוון בהנחתו לשם מחיצה:","(קלה) נתמעט בחול - אבל נתמעט בשבת כיון שהותרה בתחילת כניסת השבת הותרה:","(קלו) מי' - היינו מגובה עשרה ובמשך יותר מעשר אמות אבל בפחות מעשרה אם רצו מערבין שנים:","(קלז) לתוך קופתו בשבת - דחיישינן דלמא שקיל טובא וממעט ליה מי\"ט וקאתי לטלטל בחצר ואע\"ג דבשבת זו מותר מדינא דהואיל והותרה הותרה חיישינן שמא יבוא לטלטל גם בשבת הבאה וי\"א דהטעם הוא משום דהאי תבן מוקצה הוא מאתמול למחיצה זו ואסור לטלטלו:","(קלח) ואפילו להעמידה וכו' - דילמא שקיל בידו ונותן לה:","(קלט) אלא לשם - והתם לא חיישינן לדלמא נתמעט מעשרה דבהמה קלי קלי אכלה [רש\"י]:","(קמ) אפילו בחול אסור וכו' - שמא יפחת מעשרה בע\"ש סמוך לבין השמשות ולא ירגיש בדבר ויטלטלו בשבת באיסור ודוקא בנוטל מעט מעט חיישינן לזה אבל לא במסלק כולו בבת אחת. והעיקר כסברא ראשונה:","(קמא) שבין שני בתים - ששני הבתים פרוצים ביותר מעשר אמות למקום הגדיש והוא סותם הפרצה והבתים שייכים כל אחד לחצר אחרת מפני שפתוחים כל אחד לחצר אחרת ולא עירבו שני החצירות ביחד ולכן כשיתמעט הגדיש מגובה עשרה טפחים שני הבתים אסורין בטלטול כיון שלא עירבו החצירות יחד והן פרוצין זה לזה ביותר מעשר אמות וה\"ה בבית אחד גדול שנחלק לשנים ע\"י מחיצת התבן שבאמצע ויש לכל אחד פתח לחצר אחרת ולא עירבו החצירות יחד דכשנסתלק התבן אוסרין זה על זה:","(קמב) מותר להאכיל - דמיירי כשיש תקרה להגדיש (או שהתבן מונח ומפסיק באמצע הבית כנ\"ל) דאז אין לחוש שמא יתמעט מעשרה ולא ירגיש דכיון דאיכא תקרה כי מפחית מיו\"ד מנכרא מלתא ואפילו אם לא היתה המחיצה מגעת לתקרה אלא בסמוך לה פחות מג\"ט אמרינן לבוד [עו\"ש]:\n"]}],"373":[{"s":"<b>דין שתי גזוזטראות בשתי עליות. ובו סעיף אחד:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i><i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>שתי גזוזטראו' הבולטו' משני עליו' זו כנגד זו ונתן ביניהם <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i>נסר רחב ארבע' <i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>הרי הוא כפתח ומערבין יחד: <small>הגה ואם אין המרחק שביניהם ארבעה אפילו בלא נסר נמי <i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>דינא הכי (המגיד פ\"ג) </small> ואם רצו כל א' מערבת לעצמה אבל <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>אם היו זו שלא כנגד זו שאחת משוכה למזרח וא' למערב <i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>אינם יכולים לערב יחד וכן אם היתה אחת גבוה מחבירת' לא חשיב פתח <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>והני מילי כשמרוחקו' זו מזו ג\"ט אבל אם הם תוך ג' זו לזו בין בריחוק בין בגובה <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>חשיב שפיר <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>כפתח:","m":["(א) זו כנגד זו - ר\"ל שזה בולט מדרום לצפון וזה מצפון לדרום:","(ב) נסר - ובעינן שיקבע הנסר במסמרים שלא יוכל ליטלו בשבת:","(ג) הרי הוא כפתח - פי' ועי\"ז מותר לטלטל בשתי החצרות מזה לזה אם ירצו לערב יחד דכיון שיש נסר ביניהם רחב ארבע הרי יכול בקל לילך מפתח העליה זו להעליה שכנגדו ומצטרפים וכתב הפמ\"ג דוקא כמו שצייר המחבר שהיו הגזוזטראות בולטות מן העליות שיש בהן דיורין וקי\"ל לעיל בסימן שע\"ב ס\"ה דשני בתים יכולין לערב דרך פתח שביניהם אפילו הוא למעלה מי\"ט אבל אם היו כה\"ג בולטות משתי חצרות לא מהני כיון שהוא למעלה מי\"ט וכנ\"ל שם:","(ד) ואם אין המרחק וכו' - היינו שאין בין גזוזטרא לגזוזטרא הפסק אויר רק פחות מד\"ט וא\"כ יוכל לפסוע בקל מזה לזה:","(ה) דינא הכי - כמו בנסר שיכולין לערב יחד כשירצו ואם רצו מערבין שנים ודוקא שסמיכת הגזוזטראות זו לזו לא היה באורך כל הכותל דאלו אם היה סמיכתן באורך כל הכותל או שהיה נמשך הסמיכה זו לזו ביותר מעשר אמות אז מערבין אחד ולא שנים:","(ו) ואם רצו כל אחת וכו' - ודוקא כשאין הנסר מחזיק רק מארבעה טפחים עד עשר אמות אבל אם הוא מרוצף בנסרים יותר מעשר אמות מערבין אחד ולא שנים. ודע דמה שצריכין לערב יחד הוא רק להועיל שיהיו יכולין כ\"א לטלטל על הגזוזטרא וכן לחצר חבירו כלים ששבתו בבית אבל מ\"מ אפילו לא עירוב יחד יכולים כ\"א לערב לעצמו החצר עם בתיו ועליה שלו:","(ז) לעצמה - ובאופן זה יהיה מותר לכ\"א לטלטל מכלי ביתו בשטח גזוזטרא השייך לו אמנם על השטח שכנגד הנסר וגם על הנסר גופא מסתברא דאסור שהרי כ\"א פרוץ למקום חבירו ואוסרין זה על זה:","(ח) משוכה למזרח - ר\"ל משוכה ממקום חברתה לצד מזרח:","(ט) אינם יכולים לערב יחד - שכשיתנו הנסר מזו לזו יבא מקרן זוית של זו לזו ופתחא בקרן זוית לא עבדי אינשי וגם לפי שאין הגשר ישר אלא באלכסון עומד מתירא אדם לעבור בו:","(י) חשיב שפיר וכו' - פי' דהוי כאלו הנסר מונח בשוה:","(יא) כפתח - דע דמה שאמרו בין בריחוק בין בגובה היינו שמרוחק זה מזה יותר מד' טפחים באויר שבין זו לזו אלא שזו גבוה מזו בפחות מג' טפחים אז אמרינן דהוי כאלו הם שניהם זו כנגד זו ונותן נסר מזו לזו כיון שהמרחק שביניהם יותר מד' טפחים וה\"ה נמי כשמרוחק זו מזו בפחות מג' טפחים בריחוק שזו לצד מזרח וזו לצד מערב ואינם זה כנגד זה ממש רק שמרוחק פחות מג\"ט אמרינן לבוד והוי כאלו הם זו כנגד זו ואז אף שעדיין יש אויר רחוק בין זו לזו יותר מד\"ט מותר ע\"י נסר שנותן בין זו לזו:\n"]}],"374":[{"s":"<b>נסתם בשבת פתח או חלון במקום שעירב בו. ובו ד סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>ערבו דרך חלון או פתח שביניהם ונסתם בשבת <i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i>מותרים להשתמש דרך גובה הכותל וחוריו <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>ואפי' אם עירב לשנה ונסתם הפתח בחול ונפתח בשבת <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i><i data-commentator=\"Magen Avraham\" data-order=\"1\"></i><i data-commentator=\"Ba'er Hetev\" data-order=\"1\"></i><small> (ואפילו סתמה במזיד) (אגור) </small> חזר העירוב להתירו ולהרמב\"ם אין מותר לטלטל אלא <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i><i data-commentator=\"Magen Avraham\" data-order=\"2\"></i>כל אחת לעצמה אבל מזו לזו לא:","m":["(א) ונסתם בשבת - כגון שנפלה מפולת כנגדו [רש\"י]:","(ב) מותרים להשתמש - מזו לזו בשבת זו וכ\"ש כל אחת לעצמה דמותרת אף אותה שאין העירוב מונחת בתוכה:","(ג) דרך גובה הכותל וחוריו - ר\"ל אע\"ג דעכשיו שנסתם אין ראויין להתערב יחד דהלא אין בחורין שיעור חלון אפ\"ה לא נתבטל העירוב על שבת זו דכיון שהותר בתחלת השבת הותר לכל השבת:","(ד) ונפתח בשבת - ר\"ל לא מיבעי אם נפתח קודם השבת בודאי הוי עירוב דהא בעת כניסת השבת היו כבר פתוחין מזו לזו אלא אפילו אם נפתח בשבת גופא מ\"מ כיון שבעת הנחת העירוב שהניח לכמה שבתות או לשנה היה פתח מזו לזו וחל העירוב לכן אף שבשבת אחרת היה סתום מתחלת השבת ולא היה אז העירוב מועיל לכולם מ\"מ לא נתבטל ומיד שנפתח חזר העירוב להתירו הראשון:","(ה) ואפילו סתמה במזיד - היינו בכונה. ודע דמ\"א וכמה אחרונים צידדו לאסור בזה כשחזר ונפתח בשבת דכיון שסתם הפתח שבין שתי החצרות במזיד הוי כביטל העירוב בידים דהרי גלי דעתיה שאינו חפץ בעירוב וא\"כ כיון שביה\"ש שהוא זמן חלות העירוב היה עדיין סתום לא מהני כשנפתח אח\"כ בשבת גופא ואין להקל כשסתמו במזיד אלא כשנפתח קודם השבת דאז אמרינן אף שנתבטל מעיקרא כיון שחזר ונפתח הרי עכ\"פ הם שותפין בפת של עירוב וביה\"ש שהוא זמן קניית העירוב הרי יש פתח ביניהם שראוי לערב ועיין בבה\"ל שביארנו שכן ראוי לנהוג למעשה. אכן אם בעת שסתמו היה בדעתו רק לפי שעה ואח\"כ לחזור ולפתחו מסתברא דמותר אף כשחזר ונפתח בשבת:","(ו) ולהרמב\"ם וכו' - קאי אריש הסעיף היכא שנסתם הפתח בשבת דלדעה הראשונה מותר להשתמש מזו לזו דרך חורין ולדידיה אינו מותר אלא כל חצר לעצמה והרבותא הוא דאפילו אותה חצר שאין העירוב מונח בתוכה מותרת ומ\"מ אם חזר ונפתח לכו\"ע מותר לטלטל מזו לזו כמו מתחלה. ולענין הלכה העיקר כסברא הראשונה כ\"כ האחרונים:","(ז) כל אחד בחצירו - דאף דכל חצר נפרץ עתה לרשות אחרת שאין משותפין יחד והוי נפרץ למקום האסור לו מ\"מ כיון שבין השמשות היה מותר הותר לכל השבת:","(ח) ואפי' כלי הבית - דאלו כלי החצר מותר לטלטל אף מחצר לחצר גם כשנפרץ דכל החצרות רשות אחת וכדלעיל בריש סי' שע\"ב:","(ט) אבל וכו' - לכרמלית אסור. בזה לא אמרינן כיון שהותרה הותרה כמו דאמרינן מעיקרא דשם לא נפרץ אלא לחצר שהוא רה\"י כמוהו ואין ביניהם אלא שזה הוא של יחיד זה וזה הוא של אחר אבל זה שנפרץ לרשות אחרת ממש לא אמרינן ביה הואיל והותרה הותרה ועיין בבה\"ל:","(י) שנפרצה קודם שבת - דאלו בשבת אמרינן כיון שהותרה הותרה:","(יא) במילואה לגדולה - ר\"ל שהיו סמוכין זה לזה וכותל מפסיק ביניהן ונפרץ כל הכותל הזה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>היה כותל בין שתי חצרו' ועירבה כל אחת לעצמה ונפרץ הכותל בשבת <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>מותרים לטלטל כל א' בחצרו אפי' כלי הבי' אבל חצר שנפרצה בשבת לרשו' הרבים או <i data-commentator=\"Magen Avraham\" data-order=\"3\"></i>לכרמלית אסור:","m":[]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>חצר קטנה שנפרצ' <i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>קודם שבת במילוא' לגדול' <i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>ואין בפרצה יותר מי' אמו' גדול' מותרת להוציא כלי' ששבתו בבית לחצרה אם עירבה לעצמה <i data-commentator=\"Magen Avraham\" data-order=\"4\"></i>וקטנה אסור' להוציא כלים ששבתו בבית לחצירה אלא אם כן עירבו יחד והיינו <i data-commentator=\"Be'er HaGolah\" data-label=\"י\" data-order=\"10\"></i>כשנכנסין כותלי קטנה לגדולה <i data-commentator=\"Be'er HaGolah\" data-label=\"כ\" data-order=\"11\"></i>וכשכתלי קטנה מופלגים ג\"ט מכותלי אורך הגדולה דאם לא כן היתה קטנה ניתרת ע\"י <i data-commentator=\"Be'er HaGolah\" data-label=\"ל\" data-order=\"12\"></i>נראה מבחוץ ושוה מבפנים:","m":["(יב) ואין בפרצה יותר מי' אמות - דאלו יותר מעשרה לא שייך לומר דקטנה היא כפתחה של גדולה דפתחא יותר מעשר אמות לא עבדי אינשי:","(יג) גדולה מותרת וכו' - ואין הקטנה אוסרת עליה דהא הגדולה יש לה גיפופין ומקום פרצה הכותל של הקטנה הרי היא כפתחה:","(יד) להוציא כלים ששבתו בבית וכו' - דאלו כלים ששבתו בחצר מותר לכתחלה להוציא אף לחצר אחרת אפילו כשלא עירבו יחד:","(טו) אם עירבה לעצמה - אבל אם לא עירבה אף היא אסורה:","(טז) וקטנה אסורה וכו' - דהרי כותל שלה נפרצה במילואה לגדולה שהיא מקום האסור לה:","(יז) והיינו וכו' - ר\"ל אימתי הקטנה אסורה בשכותליה נכנסין ובולטין לתוך הגדולה בשתים וג' אמות כזה:","(יח) מופלגים ג' טפחים וכו' - דהיינו מקום כניסת מחיצות הקטנה מופלגות מכותלי אורך הגדולה שבצדה והא דבעינן שלשה טפחים דאל\"ה אמרינן לבוד לאורך הגדולה והוי כאלו לא היה מופלג כלל:","(יט) דאל\"כ היתה קטנה ניתרת וכו' - ר\"ל דאם לא היו נכנסין ובולטין כותלי קטנה לתוך הגדולה היתה גם קטנה מותרת דאע\"ג דשוה מבפנים שהעומד בתוכה רואה כל כותלי אורכה שוין שאין שם מכותל רחבה לפאותיה כלום והוי הפרצה בכל מלואה הרי מבחוץ בתוך הגדולה נראין לה שיורי כותל מכאן ומכאן [והיינו אותו עודף שהגדולה עודפת על הקטנה וניתרת בהם תשתרי גם הקטנה] משא\"כ כשבולטין כותלי קטנה לתוך הגדולה ניכר שאותן שיורי כותל של הגדולה העומדין מאחורי פרצת הקטנה אין שייך לה:"]},{"s":" <i data-commentator=\"Be'er HaGolah\" data-label=\"מ\" data-order=\"13\"></i>גג קטן שנפרץ קודם שבת <i data-commentator=\"Be'er HaGolah\" data-label=\"נ\" data-order=\"14\"></i>במילואו לגג גדול קטן <i data-commentator=\"Be'er HaGolah\" data-label=\"•\" data-order=\"15\"></i>אסור להעלות עליו כלים ששבתו בבית וגדול מותר <i data-commentator=\"Be'er HaGolah\" data-label=\"ס\" data-order=\"16\"></i>והוא שיהו מחיצות הבית ניכרות למי שעומד על הגג אבל אם אינם ניכרות כגון <i data-commentator=\"Magen Avraham\" data-order=\"5\"></i>שהגג בולט עליהם הוי כרמלית <i data-commentator=\"Be'er HaGolah\" data-label=\"ע\" data-order=\"17\"></i>אלא אם כן פתוח לו מהבית חלון ארבע על ארבע:","m":["(כ) גג קטן וכו' - אבל אם שני הגגין שוין אוסרין זה על זה אפילו אם אינם יותר מעשר אמות דהרי נפרצו במילואן זה לזה:","(כא) שנפרץ וכו' - לאו דוקא והכונה שהיה פתוח לגג הסמוך לו דבגג לא איירי בשהיה מתחלה מחיצה ונקט לשון נפרץ איידי דסעיף ג':","(כב) קודם שבת - דאי בשבת אמרינן כיון שהותרה הותרה וכנ\"ל:","(כג) במילואו לגג גדול - היינו שכל גג הקטן היה מכוון נגד גג הגדול הסמוך לו ומיירי נמי שלא עירבו בעליהם יחד וגם שאין גג הקטן מחזיק יותר מעשר אמות וכנ\"ל בס\"ג:","(כד) קטן אסור להעלות וכו' - דהרי נפרץ לרשות חבירו האסור לו:","(כה) ששבתו בבית - דאלו כלים ששבתו על הגג מותר לטלטלם אפילו לגג חבירו בלי עירוב כלל וכנ\"ל בסימן שע\"ב ס\"א:","(כו) וגדול מותר - להוציא כלי הבית על גגו דגג הקטן לגביה נחשב כפתח בעלמא כיון שאין בו יותר מעשר אמות:","(כז) מחיצות הבית ניכרות וכו' - שכל גגות שלהן חלקין היו ולא משופעין וכשאין בולט הגג מן הכתלים ולחוץ נראין מחיצות הבית לעומדין על שפת הגג כשמסתכלין תחת רגליהם ואז אמרינן גוד אסיק מחיצתא וכאלו מוקף מחיצות למעלה סביב הגג אבל כשהגג בולט מן הכתלים ולחוץ אין מחיצות הבית נראין ואין אומרין גוד אסיק מחיצתא והוי כרמלית ואסור לטלטל בכל אחד שאין לו שום מחיצות אפילו כלים ששבתו על הגג כ\"א בתוך ד' אמות:","(כח) שהגג בולט - דוקא כשבולט ד\"ט אבל אם אין בולט ארבעה טפחים הוי כמחיצות ניכרות [מ\"א וא\"ר ועיין במה שכתבנו לעיל בסימן שמ\"ה סט\"ז בבה\"ל]:","(כט) פתוח לו וכו' - דמשתמשין בו ונחשב כל הגג כחורי רה\"י. ומ\"מ לא מהני זה אלא להתיר להשתמש על גגו בכלים ששבתו בתוכו דיש עליו עי\"ז שם רה\"י אבל להעלות עליו כלים ששבתו בבית אסור כ\"ז שלא עירבו יחד כיון שאין המחיצות ניכרות עליו:\n"]}],"375":[{"s":"<b>מה הם הדברים השרוים בחצר שאינם אוסרים. ובו ד סעיפים:</b><br><i data-commentator=\"Be'er HaGolah\" data-label=\"א\" data-order=\"1\"></i>מרפסת שהוא דרך לעליות הפתוחים לה ועומדת בחצר ועולים לה בסולם ובני העליות יורדים ממנה לחצר ועוברים לרשות הרבים אינם אוסרים על בני החצר דסולם תורת פתח עליו והוי כשתי חצרות ופתח ביניהם שאם רצו מערבים יחד ואם רצו כל א' מערב לעצמו ובלבד שיערבו כל בני מרפסת לעצמן <i data-commentator=\"Turei Zahav\" data-order=\"1\"></i>כדי שתהא רגל המותרת במקומה:","m":["(א) אינן אוסרין על בני החצר - כשלא עירבו יחד אלא בני העליות לעצמן ובני החצר לעצמן ולא הוי כחצר אחד שעירבו בני חציה לעצמן ובני חציה לעצמן דאסרי אהדדי אלא הוי כשתי חצרות. ומיירי כשהמרפסת גבוה י\"ט מן החצר דאי לא היה גבוה י\"ט הוי ליה עם החצר כחצר אחת [אחרונים]:","(ב) לעצמו - ר\"ל ומותר לטלטל אפילו כלי הבית לחצר וכן כלי עליה למרפסת אבל כלי הבית למרפסת או כלי עליה לחצר אסור כיון שלא עירבו יחד:","(ג) ובלבד שיערבו וכו' - ר\"ל דאם לא עירבו בפני עצמן והיא אסורה במקומה אוסרת ג\"כ על החצר לטלטל בתוכה מכלי הבית דמרפסת כיון שאין לו דרך אחר לר\"ה כ\"א ע\"י חצר הו\"ל כחצר זה לפנים מזה שאין לו דרך אחר כ\"א ע\"י חצר החיצונה דקיי\"ל לקמן בסימן שע\"ח דאם בני חצר הפנימי לא עירבו לעצמן דהו\"ל רגל האסורה במקומה אוסרין על החיצונה:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ב\" data-order=\"2\"></i><i data-commentator=\"Turei Zahav\" data-order=\"2\"></i>אם לא עירבו יחד ויש בחצר תל או עמוד <i data-commentator=\"Be'er HaGolah\" data-label=\"ג\" data-order=\"3\"></i>שהוא משותף בין שניהם אם <i data-commentator=\"Magen Avraham\" data-order=\"1\"></i>אינם גבוהים י\"ט <i data-commentator=\"Be'er HaGolah\" data-label=\"ד\" data-order=\"4\"></i>הרי אלו נחשבי' בין החצר ובין המרפסת ושניהם אסורים <i data-commentator=\"Be'er HaGolah\" data-label=\"ה\" data-order=\"5\"></i>להוציא שם כלים שבבתים <i data-commentator=\"Be'er HaGolah\" data-label=\"ו\" data-order=\"6\"></i>ואם הם גבוהים מקרקעית החצר י\"ט <small> (ובתוך עשרה למרפסת  (טור) </small> <i data-commentator=\"Be'er HaGolah\" data-label=\"ז\" data-order=\"7\"></i>והם בתוך ד' טפחים למרפסת בני מרפסת מותרים לפי שתשמישו (להם) בנחת מלבני החצר ואם היו רחוקים מהמרפס' ד\"ט או יותר אע\"פ שגבוהים עשרה <small> (מן החצר לתוך עשרה למרפסת) (טור) </small> הרי אלו בכלל החצר והמרפס' לפי ששניהם אפשר להשתמש בהם על ידי זריקה לפיכך שניהם אסורים להוציא שם כלים ששבתו בבתים עד שיערבו:","m":["(ד) בין שניהם - דאם הוא של אחד מהם הרי הוא ברשותא דחד ואינם אוסרים עליו בכל גווני:","(ה) אם וכו' - הכלל בזה דכל שלאחד תשמישו בנחת [היינו בקל] ולהשני בקשה לא מקרי רק רשות לאותו שתשמישו בנחת ואין השני יכול לאסור עליו אבל אם שניהם שוים הן שהוא לשניהם בקל להשתמש על אותו מקום הן בקשה שייך לשניהם וממילא אוסרים זה ע\"ז להוציא לאותו מקום מכלי הבית כיון שלא עירבו יחד ואיזה מקרי בנחת ואיזה בקשה מתבאר בגמרא דכל שצריך לתשמישו זריקה דהיינו שהתל או העמוד גבוה ממנו עשרה טפחים וצריך לזרוק שם או שצריך שלשול דהיינו שהמקום ההוא נמוך ממנו י\"ט וכשרוצה להשתמש עליו צריך לשלשל ולהורידו לשם כ\"ז מקרי קשה ואם הוא פחות מי\"ט הן בזריקה והן בשלשול מקרי בנחת ולפעמים מקרי קשה אפילו אם הוא פחות מי\"ט כגון שאותו עמוד או התל מופלג בריחוק מקום ממנו ד\"ט וצריך לזרוק באויר:","(ו) אינם גבוהים י\"ט - מן הארץ וגם מן המרפסת שלמעלה מהם אין נמוך ממנה עשרה טפחים דאז נוח לשניהם להשתמש שם ולכן אוסרים זה על זה דאם היה נמוך מן המרפסת עשרה טפחים אז היו נותנים אותו לבני החצר דלהם תשמישו בנחת ולבני המרפסת [היינו אנשי העליה שבתיהם נפתחים להמרפסת ואיסקופת פתחיהם שוה לה] בקשה:","(ז) ושניהם אסורים וכו' - ודוקא כשהיה התל והעמוד סמוך להמרפסת בתוך ד\"ט דאם היו רחוקים ממנו ד\"ט א\"כ תשמיש המרפסת עליו בקשה והחצר בנחת ונותנים אותו לבני החצר:","(ח) ובתוך עשרה למרפסת - דאם היה מרוחק עשרה גם ממרפסת היה לשניהם בקשה ויד שניהן שוין בו לאסור זה על זה:","(ט) שתשמישו להם בנחת - שהם לה בתוך י\"ט וגם אינם מופלגים ממנה:","(י) אע\"פ שגבוהים וכו' ותוך עשרה למרפסת - ר\"ל וא\"כ היה שייך למרפסת וכמו שכתב מתחלה אפ\"ה כיון שמופלגין ממנה ד\"ט וכשרוצים בני מרפסת להשתמש שם הוא רק ע\"י זריקה מקרי תשמישו ג\"כ בקשה זה מחמת גובהו וזה מחמת רחקו:","(יא) ותוך עשרה למרפסת - ואם היו נמוכים עשרה טפחים גם מהמרפסת יש דעות בפוסקים יש אומרים דכיון שלבעל המרפסת יש שתי ריעותות שנמוכים מעשרה וגם מופלגים ד\"ט א\"כ תשמיש של אנשי החצר נוח יותר שם ונותנין אותו להם ויש אומרים דכיון שלהחצר נמי גבוה י\"ט מקרי לשניהם תשמישו בקשה ואוסרין זה ע\"ז בור שבחצר. [של בני המרפסת ובני החצר בשותפות] ומקיפתו חוליא גבוה י' טפחים וסמוכה למרפסת בתוך ד\"ט אוסרין זה על זה כשלא עירבו יחד למלאות מים בדלי ששבת בבית או בעליות וכן להכניס המים לבתיהם ואין נותנין אותו לבני מרפסת הואיל וגם להם תשמישו בקשה ע\"י שלשול י' טפחים לבור ואפילו אם הבור מלא מים עד גובה החוליא שסמוכה למרפסת אסור משום גזירה שמא יחסרו המים בשבת וישתמשו בו כבתחלה אבל אם היה הבור מלא בדבר שאין ניטל בשבת הרי הוא כעמוד או תל גבוה י' מחצר ותוך עשרה למרפסת שנותנין אותו לבני מרפסת [כשאינו מופלג מכנגדה ד\"ט וכנ\"ל] להשתמש על גבה:","(יב) ארבעה טפחים - בגובה שלה:"]},{"s":"<i data-commentator=\"Turei Zahav\" data-order=\"3\"></i><i data-commentator=\"Be'er HaGolah\" data-label=\"ח\" data-order=\"8\"></i>היתה מצבה ארבע' טפחים לפני המרפס' אין המרפסת אוסר' על בני החצר שהרי נחלקה מהם:","m":["(יג) אין המרפסת אוסרת וכו' - ר\"ל אפילו התל ועמוד הסמוכה לה בתוך ד\"ט וגבוה י\"ט שכיון שעשו הפסק לפני המרפסת גילו דעתם שסילקו עצמם מן החצר:"]},{"s":"<i data-commentator=\"Be'er HaGolah\" data-label=\"ט\" data-order=\"9\"></i>זיזים היוצאים מהכתלים כל שהוא למטה מעשרה טפחים הרי זה נחשב מהחצר ובני החצר משתמשין בו וכל שהוא בתוך י\"ט העליונים הסמוכים לעלייה אנשי עלייה משתמשין בו והנשאר בין י' התחתונים עד התחלת י' העליונים מן הזיזין היוצאים שניהם אסורים בו ואין משתמשין בהם בכלים ששבתו בבתים אלא אם כן עירבו:","m":["(יד) זיזים היוצאים וכו' - גם זה הסעיף מיירי שבני החצר ובני העליה עירבו כ\"א לעצמן ושהזיזים היו שייכין לבני החצר והעליה בשותפות וגם מיירי שהזיזין היו רחבים ד\"ט דאל\"ה הוי מקום פטור ובטיל להכא ולהכא [רש\"י]:","(טו) והנשאר וכו' - מיירי בשהיו יותר מעשרים טפחים מן העליה לקרקע החצר וה\"ה כשהיה פחות מעשרים טפחים והזיז עומד באמצע ואין ממנו עשרה טפחים לא לזה ולא לזה:\n"]}]};